(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-antiquities-6-e", [{"sp": "HDR", "t": "Ἰουδαϊκὴ Ἀρχαιολογία"}, {"sp": "HDR", "t": "Βιβλίον ΙΗʹ", "st": "18"}, {"sp": "N", "t": "Κυρίνιος δὲ τῶν εἰς τὴν βουλὴν συναγομένων ἀνὴρ τάς τε ἄλλας ἀρχὰς ἐπιτετελεκὼς καὶ διὰ πασῶν ὁδεύσας ὕπατος γενέσθαι τά τε ἄλλα ἀξιώματι μέγας σὺν ὀλίγοις ἐπὶ Συρίας παρῆν, ὑπὸ Καίσαρος δικαιοδότης τοῦ ἔθνους ἀπεσταλμένος καὶ τιμητὴς τῶν οὐσιῶν γενησόμενος, Κωπώνιός τε αὐτῷ συγκαταπέμπεται τάγματος τῶν ἱππέων, ἡγησόμενος Ἰουδαίων τῇ ἐπὶ πᾶσιν ἐξουσίᾳ. παρῆν δὲ καὶ Κυρίνιος εἰς τὴν Ἰουδαίαν προσθήκην τῆς Συρίας γενομένην ἀποτιμησόμενός τε αὐτῶν τὰς οὐσίας καὶ ἀποδωσόμενος τὰ Ἀρχελάου χρήματα. οἱ δὲ καίπερ τὸ κατ’ ἀρχὰς ἐν δεινῷ φέροντες τὴν ἐπὶ ταῖς ἀπογραφαῖς ἀκρόασιν ὑποκατέβησαν τοῦ μὴ εἰς πλέον ἐναντιοῦσθαι πείσαντος αὐτοὺς τοῦ ἀρχιερέως Ἰωαζάρου, Βοηθοῦ δὲ οὗτος υἱὸς ἦν. καὶ οἱ μὲν ἡττηθέντες τοῦ Ἰωαζάρου τῶν λόγων ἀπετίμων τὰ χρήματα μηδὲν ἐνδοιάσαντες· Ἰούδας δὲ Γαυλανίτης ἀνὴρ ἐκ πόλεως ὄνομα Γάμαλα Σάδδωκον Φαρισαῖον προσλαβόμενος ἠπείγετο ἐπὶ ἀποστάσει, τήν τε ἀποτίμησιν οὐδὲν ἄλλο ἢ ἄντικρυς δουλείαν ἐπιφέρειν λέγοντες καὶ τῆς ἐλευθερίας ἐπ’ ἀντιλήψει παρακαλοῦντες τὸ ἔθνος· ὡς παρασχὸν μὲν κατορθοῦν εἰς τὸ εὔδαιμον ἀνακειμένης τῆς κτήσεως, σφαλεῖσιν δὲ τοῦ ταύτης περιόντος ἀγαθοῦ τιμὴν καὶ κλέος ποιήσεσθαι τοῦ μεγαλόφρονος, καὶ τὸ θεῖον οὐκ ἄλλως ἢ ἐπὶ συμπράξει τῶν βουλευμάτων εἰς τὸ κατορθοῦν συμπροθυμεῖσθαι μᾶλλον, ἂν μεγάλων ἐρασταὶ τῇ διανοίᾳ καθιστάμενοι μὴ ἐξαφίωνται πόνου τοῦ ἐπ’ αὐτοῖς. καὶ ἡδονῇ γὰρ τὴν ἀκρόασιν ὧν λέγοιεν ἐδέχοντο οἱ ἄνθρωποι, προύκοπτεν ἐπὶ μέγα ἡ ἐπιβολὴ τοῦ τολμήματος, κακόν τε οὐκ ἔστιν, οὗ μὴ φυέντος ἐκ τῶνδε τῶν ἀνδρῶν καὶ περαιτέρω τοῦ εἰπεῖν ἀνεπλήσθη τὸ ἔθνος· πολέμων τε ἐπαγωγαῖς οὐχ οἷον τὸ ἄπαυστον τὴν βίαν ἔχειν, καὶ ἀποστέρησιν φίλων, οἳ καὶ ἐπελαφρύνοιεν τὸν πόνον, λῃστηρίων τε μεγάλων ἐπιθέσεσιν καὶ διαφθοραῖς ἀνδρῶν τῶν πρώτων, δόξα μὲν τοῦ ὀρθουμένου τῶν κοινῶν, ἔργῳ δὲ οἰκείων κερδῶν ἐλπίσιν. ἐξ ὧν στάσεις τε ἐφύησαν δι’ αὐτὰς καὶ φόνος πολιτικός, ὁ μὲν ἐμφυλίοις σφαγαῖς μανίᾳ τῶν ἀνθρώπων εἴς τε ἀλλήλους καὶ αὑτοὺς χρωμένων ἐπιθυμίᾳ τοῦ μὴ λείπεσθαι τῶν ἀντικαθεστηκότων, ὁ δὲ τῶν πολεμίων, λιμός τε εἰς ὑστάτην ἀνακείμενος ἀναισχυντίαν, καὶ πόλεων ἁλώσεις καὶ κατασκαφαί, μέχρι δὴ καὶ τὸ ἱερὸν τοῦ θεοῦ ἐνείματο πυρὶ τῶν πολεμίων ἥδε ἡ στάσις. οὕτως ἄρα ἡ τῶν πατρίων καίνισις καὶ μεταβολὴ μεγάλας ἔχει ῥοπὰς τοῦ ἀπολουμένου τοῖς συνελθοῦσιν, εἴ γε καὶ Ἰούδας καὶ Σάδδωκος τετάρτην φιλοσοφίαν ἐπείσακτον ἡμῖν ἐγείραντες καὶ ταύτης ἐραστῶν εὐπορηθέντες πρός τε τὸ παρὸν θορύβων τὴν πολιτείαν ἐνέπλησαν καὶ τῶν αὖθις κακῶν κατειληφότων ῥίζας ἐφυτεύσαντο τῷ ἀσυνήθει πρότερον φιλοσοφίας τοιᾶσδε· περὶ ἧς ὀλίγα βούλομαι διελθεῖν, ἄλλως τε ἐπεὶ καὶ τῷ κατ’ αὐτῶν σπουδασθέντι τοῖς νεωτέροις ὁ φθόρος τοῖς πράγμασι συνέτυχε.", "st": "18.1.1"}, {"sp": "N", "t": "Ἰουδαίοις φιλοσοφίαι τρεῖς ἦσαν ἐκ τοῦ πάνυ ἀρχαίου τῶν πατρίων, ἥ τε τῶν Ἐσσηνῶν καὶ ἡ τῶν Σαδδουκαίων, τρίτην δὲ ἐφιλοσόφουν οἱ Φαρισαῖοι λεγόμενοι. καὶ τυγχάνει μέντοι περὶ αὐτῶν ἡμῖν εἰρημένα ἐν τῇ δευτέρᾳ βίβλῳ τοῦ Ἰουδαϊκοῦ πολέμου, μνησθήσομαι δ’ ὅμως καὶ νῦν αὐτῶν ἐπ’ ὀλίγον.", "st": "18.1.2"}, {"sp": "N", "t": "Οἵ τε γὰρ Φαρισαῖοι τὴν δίαιταν ἐξευτελίζουσιν οὐδὲν ἐς τὸ μαλακώτερον ἐνδιδόντες, ὧν τε ὁ λόγος κρίνας παρέδωκεν ἀγαθῶν ἕπονται τῇ ἡγεμονίᾳ περιμάχητον ἡγούμενοι τὴν φυλακὴν ὧν ὑπαγορεύειν ἠθέλησεν. τιμῆς γε τοῖς ἡλικίᾳ προήκουσιν παραχωροῦσιν οὐδ’ ἐπ’ ἀντιλέξει τῶν εἰσηγηθέντων ταῦτα οἱ θράσει ἐπαιρόμενοι. πράσσεσθαί τε εἱμαρμένῃ τὰ πάντα ἀξιοῦντες οὐδὲ τοῦ ἀνθρωπείου τὸ βουλόμενον τῆς ἐπ’ αὐτοῖς ὁρμῆς ἀφαιροῦνται δοκῆσαν τῷ θεῷ κρίσιν γενέσθαι καὶ τῷ ἐκείνης βουλευτηρίῳ καὶ τῶν ἀνθρώπων τῷ ἐθελήσαντι προσχωρεῖν μετ’ ἀρετῆς ἢ κακίας. ἀθάνατόν τε ἰσχὺν ταῖς ψυχαῖς πίστις αὐτοῖς εἶναι καὶ ὑπὸ χθονὸς δικαιώσεις τε καὶ τιμὰς οἷς ἀρετῆς ἢ κακίας ἐπιτήδευσις ἐν τῷ βίῳ γέγονεν, καὶ ταῖς μὲν εἱργμὸν ἀίδιον προτίθεσθαι, ταῖς δὲ ῥᾳστώνην τοῦ ἀναβιοῦν. καὶ δι’ αὐτὰ τοῖς τε δήμοις πιθανώτατοι τυγχάνουσιν καὶ ὁπόσα θεῖα εὐχῶν τε ἔχεται καὶ ἱερῶν ποιήσεως ἐξηγήσει τῇ ἐκείνων τυγχάνουσιν πρασσόμενα. εἰς τοσόνδε ἀρετῆς αὐτοῖς αἱ πόλεις ἐμαρτύρησαν ἐπιτηδεύσει τοῦ ἐπὶ πᾶσι κρείσσονος ἔν τε τῇ διαίτῃ τοῦ βίου καὶ λόγοις.", "st": "18.1.3"}, {"sp": "N", "t": "Σαδδουκαίοις δὲ τὰς ψυχὰς ὁ λόγος συναφανίζει τοῖς σώμασι, φυλακῇ δὲ οὐδαμῶς τινων μεταποίησις αὐτοῖς ἢ τῶν νόμων· πρὸς γὰρ τοὺς διδασκάλους σοφίας, ἣν μετίασιν, ἀμφιλογεῖν ἀρετὴν ἀριθμοῦσιν. εἰς ὀλίγους δὲ ἄνδρας οὗτος ὁ λόγος ἀφίκετο, τοὺς μέντοι πρώτους τοῖς ἀξιώμασι, πράσσεταί τε ἀπ’ αὐτῶν οὐδὲν ὡς εἰπεῖν· ὁπότε γὰρ ἐπ’ ἀρχὰς παρέλθοιεν, ἀκουσίως μὲν καὶ κατ’ ἀνάγκας, προσχωροῦσι δ’ οὖν οἷς ὁ Φαρισαῖος λέγει διὰ τὸ μὴ ἄλλως ἀνεκτοὺς γενέσθαι τοῖς πλήθεσιν.", "st": "18.1.4"}, {"sp": "N", "t": "Ἐσσηνοῖς δὲ ἐπὶ μὲν θεῷ καταλείπειν φιλεῖ τὰ πάντα ὁ λόγος, ἀθανατίζουσιν δὲ τὰς ψυχὰς περιμάχητον ἡγούμενοι τοῦ δικαίου τὴν πρόσοδον. εἰς δὲ τὸ ἱερὸν ἀναθήματα στέλλοντες θυσίας ἐπιτελοῦσιν διαφορότητι ἁγνειῶν, ἃς νομίζοιεν, καὶ δι’ αὐτὸ εἰργόμενοι τοῦ κοινοῦ τεμενίσματος ἐφ’ αὑτῶν τὰς θυσίας ἐπιτελοῦσιν. βέλτιστοι δὲ ἄλλως [ἄνδρες] τὸν τρόπον καὶ τὸ πᾶν πονεῖν ἐπὶ γεωργίᾳ τετραμμένοι. ἄξιον δ’ αὐτῶν θαυμάσαι παρὰ πάντας τοὺς ἀρετῆς μεταποιουμένους τόδε διὰ τὸ μηδαμῶς ὑπάρξαν Ἑλλήνων ἢ βαρβάρων τισίν, ἀλλὰ μηδ’ εἰς ὀλίγον, ἐκείνοις ἐκ παλαιοῦ συνελθὸν ἐν τῷ ἐπιτηδεύεσθαι μὴ κεκωλῦσθαι· τὰ χρήματά τε κοινά ἐστιν αὐτοῖς, ἀπολαύει δὲ οὐδὲν ὁ πλούσιος τῶν οἰκείων μειζόνως ἢ ὁ μηδ’ ὁτιοῦν κεκτημένος· καὶ τάδε πράσσουσιν ἄνδρες ὑπὲρ τετρακισχίλιοι τὸν ἀριθμὸν ὄντες. καὶ οὔτε γαμετὰς εἰσάγονται οὔτε δούλων ἐπιτηδεύουσιν κτῆσιν, τὸ μὲν εἰς ἀδικίαν φέρειν ὑπειληφότες, τὸ δὲ στάσεως ἐνδιδόναι ποίησιν, αὐτοὶ δ’ ἐφ’ ἑαυτῶν ζῶντες διακονίᾳ τῇ ἐπ’ ἀλλήλοις ἐπιχρῶνται. ἀποδέκτας δὲ τῶν προσόδων χειροτονοῦντες καὶ ὁπόσα ἡ γῆ φέροι ἄνδρας ἀγαθούς, ἱερεῖς δὲ ἐπὶ ποιήσει σίτου τε καὶ βρωμάτων. ζῶσι δὲ οὐδὲν παρηλλαγμένως, ἀλλ’ ὅτι μάλιστα ἐμφέροντες Δακῶν τοῖς πλείστοις λεγομένοις.", "st": "18.1.5"}, {"sp": "N", "t": "Τῇ δὲ τετάρτῃ τῶν φιλοσοφιῶν ὁ Γαλιλαῖος Ἰούδας ἡγεμὼν κατέστη, τὰ μὲν λοιπὰ πάντα γνώμῃ τῶν Φαρισαίων ὁμολογούσῃ, δυσνίκητος δὲ τοῦ ἐλευθέρου ἔρως ἐστὶν αὐτοῖς μόνον ἡγεμόνα καὶ δεσπότην τὸν θεὸν ὑπειληφόσιν. θανάτων τε ἰδέας ὑπομένειν παρηλλαγμένας ἐν ὀλίγῳ τίθενται καὶ συγγενῶν τιμωρίας καὶ φίλων ὑπὲρ τοῦ μηδένα ἄνθρωπον προσαγορεύειν δεσπότην. ἑωρακόσιν δὲ τοῖς πολλοῖς τὸ ἀμετάλλακτον αὐτῶν τῆς ἐπὶ τοιούτοις ὑποστάσεως περαιτέρω διελθεῖν παρέλιπον· οὐ γὰρ δέδοικα μὴ εἰς ἀπιστίαν ὑποληφθῇ τι τῶν λεγομένων ἐπ’ αὐτοῖς, τοὐναντίον δὲ μὴ ἐλασσόνως τοῦ ἐκείνων καταφρονήματος δεχομένου τὴν ταλαιπωρίαν τῆς ἀλγηδόνος ὁ λόγος ἀφηγῆται. ἀνοίᾳ τε τῇ ἐντεῦθεν ἤρξατο νοσεῖν τὸ ἔθνος Γεσσίου Φλώρου, ὃς ἡγεμὼν ἦν, τῇ ἐξουσίᾳ τοῦ ὑβρίζειν ἀπονοήσαντος αὐτοὺς ἀποστῆναι Ῥωμαίων. καὶ φιλοσοφεῖται μὲν Ἰουδαίοις τοσάδε.", "st": "18.1.6"}, {"sp": "N", "t": "Κυρίνιος δὲ τὰ Ἀρχελάου χρήματα ἀποδόμενος ἤδη καὶ τῶν ἀποτιμήσεων πέρας ἐχουσῶν, αἳ ἐγένοντο τριακοστῷ καὶ ἑβδόμῳ ἔτει μετὰ τὴν Ἀντωνίου ἐν Ἀκτίῳ ἧτταν ὑπὸ Καίσαρος, Ἰωάζαρον τὸν ἀρχιερέα καταστασιασθέντα ὑπὸ τῆς πληθύος ἀφελόμενος τὸ ἀξίωμα τῆς τιμῆς Ἄνανον τὸν Σεθὶ καθίσταται ἀρχιερέα. Ἡρώδης δὲ καὶ Φίλιππος τετραρχίαν ἑκάτερος τὴν ἑαυτοῦ παρειληφότες καθίσταντο. καὶ Ἡρώδης Σέπφωριν τειχίσας πρόσχημα τοῦ Γαλιλαίου παντὸς ἠγόρευεν αὐτὴν Αὐτοκρατορίδα· Βηθαραμφθᾶ δέ, πόλις καὶ αὐτὴ τυγχάνει, τείχει περιλαβὼν Ἰουλιάδα ἀπὸ τοῦ αὐτοκράτορος προσαγορεύει τῆς γυναικός. Φίλιππος δὲ Πανεάδα τὴν πρὸς ταῖς πηγαῖς τοῦ Ἰορδάνου κατασκευάσας ὀνομάζει Καισάρειαν, κώμην δὲ Βηθσαϊδὰ πρὸς λίμνῃ τῇ Γεννησαρίτιδι πόλεως παρασχὼν ἀξίωμα πλήθει τε οἰκητόρων καὶ τῇ ἄλλῃ δυνάμει Ἰουλίᾳ θυγατρὶ τῇ Καίσαρος ὁμώνυμον ἐκάλεσεν.", "st": "18.2.1"}, {"sp": "N", "t": "Κωπωνίου δὲ τὴν Ἰουδαίαν διέποντος, ὃν ἔφην Κυρινίῳ συνεκπεμφθῆναι, τάδε πράσσεται. τῶν ἀζύμων τῆς ἑορτῆς ἀγομένης, ἣν πάσχα καλοῦμεν, ἐκ μέσης νυκτὸς ἐν ἔθει τοῖς ἱερεῦσιν ἦν ἀνοιγνύναι τοῦ ἱεροῦ τοὺς πυλῶνας. καὶ τότε οὖν ἐπεὶ τὸ πρῶτον γίνεται ἡ ἄνοιξις αὐτῶν, ἄνδρες Σαμαρεῖται κρύφα εἰς Ἱεροσόλυμα ἐλθόντες διάρριψιν ἀνθρωπείων ὀστῶν ἐν ταῖς στοαῖς καὶ διὰ παντὸς τοῦ ἱεροῦ ἤρξαντο μὴ πρότερον ἐπὶ τοιούτοις νομίζοντες τά τε ἄλλα διὰ φυλακῆς μείζονος ἦγον τὸ ἱερόν. καὶ Κωπώνιος μετ’ οὐ πολὺ εἰς Ῥώμην ἐπαναχωρεῖ, διάδοχος δ’ αὐτῷ τῆς ἀρχῆς παραγίνεται Μᾶρκος Ἀμβιβουχος, ἐφ’ οὗ καὶ Σαλώμη ἡ τοῦ βασιλέως Ἡρώδου ἀδελφὴ μεταστᾶσα Ἰουλίᾳ μὲν Ἰάμνειάν τε καταλείπει καὶ τὴν τοπαρχίαν πᾶσαν, τήν τ’ ἐν τῷ πεδίῳ Φασαηλίδα καὶ Ἀρχελαΐδα, ἔνθα φοινίκων πλείστη φύτευσις καὶ καρπὸς αὐτῶν ἄριστος. διαδέχεται δὲ καὶ τοῦτον Ἄννιος Ῥοῦφος, ἐφ’ οὗ δὴ καὶ τελευτᾷ Καῖσαρ, δεύτερος μὲν Ῥωμαίων αὐτοκράτωρ γενόμενος ἑπτὰ δὲ καὶ πεντήκοντα τῆς ἀρχῆς ἔτη, πρὸς οἷς μῆνες ἓξ ἡμέραι δυοῖν πλείονες, τούτου δὲ αὐτῷ τοῦ χρόνου δεκατέσσαρα ἔτη συνῆρξεν Ἀντώνιος, βιώσας ἔτη ἑβδομηκονταεπτά. διαδέχεται δὲ τῷ Καίσαρι τὴν ἡγεμονίαν Τιβέριος Νέρων γυναικὸς αὐτοῦ Ἰουλίας υἱὸς ὤν, τρίτος ἤδη οὗτος αὐτοκράτωρ, καὶ πεμπτὸς ὑπ’ αὐτοῦ παρῆν Ἰουδαίοις ἔπαρχος διάδοχος Ἀννίῳ Ῥούφῳ Οὐαλέριος Γρᾶτος· ὃς παύσας ἱερᾶσθαι Ἄνανον Ἰσμάηλον ἀρχιερέα ἀποφαίνει τὸν τοῦ Φαβί, καὶ τοῦτον δὲ μετ’ οὐ πολὺ μεταστήσας Ἐλεάζαρον τὸν Ἀνάνου τοῦ ἀρχιερέως υἱὸν ἀποδείκνυσιν ἀρχιερέα. ἐνιαυτοῦ δὲ διαγενομένου καὶ τόνδε παύσας Σίμωνι τῷ Καμίθου τὴν ἀρχιερωσύνην παραδίδωσιν. οὐ πλείων δὲ καὶ τῷδε ἐνιαυτοῦ τὴν τιμὴν ἔχοντι διεγένετο χρόνος, καὶ Ἰώσηπος ὁ καὶ Καϊάφας διάδοχος ἦν αὐτῷ. καὶ Γρᾶτος μὲν ταῦτα πράξας εἰς Ῥώμην ἐπανεχώρει ἕνδεκα ἔτη διατρίψας ἐν Ἰουδαίᾳ, Πόντιος δὲ Πιλᾶτος διάδοχος αὐτῷ ἧκεν.", "st": "18.2.2"}, {"sp": "N", "t": "Ἡρώδης δὲ ὁ τετράρχης, ἐπὶ μέγα γὰρ ἦν τῷ Τιβερίῳ φιλίας προελθών, οἰκοδομεῖται πόλιν ἐπώνυμον αὐτῷ Τιβεριάδα τοῖς κρατίστοις ἐπικτίσας αὐτὴν τῆς Γαλιλαίας ἐπὶ λίμνῃ τῇ Γεννησαρίτιδι. θερμά τε οὐκ ἄπωθέν ἐστιν ἐν κώμῃ, Ἀμμαθοὺς ὄνομα αὐτῇ. σύγκλυδες δὲ ᾤκισαν, οὐκ ὀλίγον δὲ καὶ τὸ Γαλιλαῖον ἦν, καὶ ὅσοι μὲν ἐκ τῆς ὑπ’ αὐτῷ γῆς ἀναγκαστοὶ καὶ πρὸς βίαν εἰς τὴν κατοικίαν ἀγόμενοι, τινὲς δὲ καὶ τῶν ἐν τέλει. ἐδέξατο δὲ αὐτοῖς συνοίκους καὶ τοὺς πανταχόθεν ἐπισυναγομένους ἄνδρας ἀπόρους, ἔστι δ’ οὓς μηδὲ σαφῶς ἐλευθέρους, πολλά τε αὐτοὺς κἀπὶ πολλοῖς ἠλευθέρωσεν καὶ εὐηργέτησεν ἀνάγκασμα τοῦ μὴ ἀπολείψειν τὴν πόλιν ἐπιθείς, κατασκευαῖς τε οἰκήσεων τέλεσι τοῖς αὐτοῦ καὶ γῆς ἐπιδόσει, εἰδὼς παράνομον τὸν οἰκισμὸν ὄντα καὶ ἀπὸ τοῦ Ἰουδαίοις πατρίου διὰ τὸ ἐπὶ μνήμασιν, ἃ πολλὰ τῇδε ἦν, ἀνῃρημένοις τὴν ἵδρυσιν τῇ Τιβεριάδι γενέσθαι· μιαροὺς δὲ ἐπὶ ἑπτὰ ἡμέρας εἶναι τοὺς οἰκήτορας ἀγορεύει ἡμῖν τὸ νόμιμον.", "st": "18.2.3"}, {"sp": "N", "t": "Τελευτᾷ δὲ καὶ Φραάτης ὁ Παρθυαίων βασιλεὺς κατὰ τοῦτον τὸν χρόνον ἐπιβουλῆς αὐτῷ γενομένης ὑπὸ Φραατάκου τοῦ υἱέος κατὰ τοιαύτην αἰτίαν. Φραάτης παίδων αὐτῷ γενομένων γνησίων Ἰταλικῆς παιδίσκης ὄνομα αὐτῇ Θεσμοῦσα. ταύτῃ ὑπὸ Ἰουλίου Καίσαρος μετ’ ἄλλων δωρεῶν ἀπεσταλμένῃ τὸ μὲν πρῶτον παλλακίδι ἐχρῆτο, καταπλαγεὶς δὲ τῷ πολλῷ τῆς εὐμορφίας προϊόντος τοῦ χρόνου καὶ παιδὸς αὐτῇ τοῦ Φραατάκου γενομένου γαμετήν τε τὴν ἄνθρωπον ἀποφαίνεται καὶ τιμίαν ἦγεν. ἐπὶ πᾶσιν οἷς εἴποι πιθανὴ τῷ βασιλεῖ γεγονυῖα καὶ σπεύδουσα τῷ παιδὶ τῷ αὐτῆς γενέσθαι τὴν Πάρθων ἡγεμονίαν ἑώρα μὴ ἄλλως γενησομένην μὴ ἀποσκευῆς αὐτῇ μηχανηθείσης τῶν γνησίων τοῦ Φραάτου παίδων. πείθει οὖν αὐτὸν ἐκπέμπειν εἰς Ῥώμην ἐφ’ ὁμηρείᾳ τοὺς γνησίους παῖδας. καὶ οὗτοι μέν, οὐ γὰρ ἀντειπεῖν εὔπορον Φραάτῃ τοῖς Θεσμούσης ἐπιτάγμασιν, ἐπὶ τῆς Ῥώμης ἐξεπέμποντο. Φραατάκης δὲ μόνος ἐπὶ τοῖς πράγμασι τρεφόμενος δεινὸν ἡγεῖτο καὶ ἅμα χρόνιον τοῦ πατρὸς διδόντος τὴν ἀρχὴν λαμβάνειν, ὥστε ἐπεβούλευε τῷ πατρὶ συμπράξει τῆς μητρός, ᾗ δὴ καὶ συνιέναι λόγος εἶχεν αὐτόν. καὶ δι’ ἀμφότερα μισηθεὶς οὐδὲν ἡσσόνως τῆς πατροκτονίας τὸ μῦσος τοῦ μητρὸς ἔρωτος τιθεμένων τῶν ὑπηκόων, στάσει περιελαθεὶς πρότερον ἢ φῦναι μέγας ἐξέπεσε τῶν πραγμάτων καὶ οὕτως θνήσκει. συμφρονήσαντες δὲ οἱ γενναιότατοι Πάρθων, ὡς ἀβασιλεύτοις μὲν ἀμήχανον πολιτεύεσθαι, οἱ δὲ τοῦ βασιλεύοντος ἐκ τοῦ γένους τῶν Ἀρσακιδῶν, οὐ γὰρ ἑτέροις ἄρχειν νόμιμον, ἀπέχρη δὲ πολλάκις καὶ μέχρι νῦν περιυβρίσθαι τὴν βασιλείαν ἔκ τε γάμων τῆς Ἰταλικῆς παλλακίδος καὶ γενέσεων, Ὀρώδην ἐκάλουν πρεσβεύσαντες εἰς δάν, ἄλλως μὲν ἐπίφθονον τῷ πλήθει καὶ ὑπαίτιον καθ’ ὑπερβολὰς ὠμότητος, πάνυ γὰρ ἦν σκαιὸς καὶ δυσδιάθετος εἰς ὀργήν, ἕνα δὲ τῶν ἐκ τοῦ γένους. τοῦτον μὲν δὴ συστάντες ἀποκτείνουσιν, ὡς μὲν ἔνιοί φασιν, ἐν σπονδαῖς καὶ τραπέζαις, μαχαιροφορεῖν γὰρ ἔθος ἅπασιν, ὡς δ’ ὁ πλείων κατέχει λόγος, εἰς θήραν προαγαγόντες. πρεσβεύσαντες δὲ εἰς Ῥώμην ᾐτοῦντο βασιλέα τῶν ὁμηρευόντων, καὶ πέμπεται Βονώνης προκριθεὶς τῶν ἀδελφῶν· ἐδόκει γὰρ χωρεῖν τὴν τύχην, ἣν αὐτῷ δύο μέγισται τῶν ὑπὸ τὸν ἥλιον ἡγεμονίαι προσέφερον, ἰδία καὶ ἀλλοτρία. ταχεῖα δ’ ἀνατροπὴ τοὺς βαρβάρους ὕπεισιν ἅτε καὶ φύσει σφαλεροὺς ὄντας πρός τε τὴν ἀναξιοπάθειαν, ἀνδραπόδῳ γὰρ ἀλλοτρίῳ ποιήσειν τὸ προστασσόμενον ἠξίουν, τὴν ὁμηρείαν ἀντὶ δουλείας ὀνομάζοντες, καὶ τῆς ἐπικλήσεως τὴν ἀδοξίαν· οὐ γὰρ [ἂν] πολέμου δικαίῳ δεδόσθαι τὸν βασιλεύσοντα Πάρθοις, ἀλλά, ὃ τῷ παντὶ χεῖρον, εἰρήνης ὕβρει. παραχρῆμα δ’ ἐκάλουν Ἀρτάβανον Μηδίας βασιλεύοντα γένος Ἀρσακίδην· πείθεται δ’ Ἀρτάβανος καὶ μετὰ στρατιᾶς ἔπεισιν. ὑπαντιάζει δ’ αὐτῷ Βονώνης· καὶ τὸ μὲν πρῶτον συμφρονήσαντος αὐτῷ τοῦ πλήθους τῶν Πάρθων παραταξάμενος νικᾷ, καὶ φεύγει πρὸς τοὺς ὅρους τῆς Μηδίας Ἀρτάβανος. μετ’ οὐ πολὺ δὲ συναγαγὼν συμβάλλει τε Βονώνῃ καὶ νικᾷ, καὶ Βονώνης εἰς Σελεύκειαν ἀφιππάζεται σὺν ὀλίγοις τοῖς περὶ αὐτόν. Ἀρτάβανος δὲ πολὺν τῇ τροπῇ φόνον ἐργασάμενος ὑπὲρ ἐκπλήξεως τῶν βαρβάρων πρὸς Κτησιφῶντα μετὰ τοῦ πλήθους ἀναχωρεῖ. κἀκεῖνος μὲν ἐβασίλευεν ἤδη Πάρθοις, Βονώνης δ’ εἰς Ἀρμενίαν διαπίπτει, καὶ κατ’ ἀρχὰς μὲν ἐφίετο τῆς χώρας καὶ πρὸς Ῥωμαίους ἐπρέσβευεν. ὡς δ’ αὐτῷ Τιβέριος μὲν ἀπεῖπεν πρός τε τὴν ἀνανδρίαν καὶ τοῦ Πάρθου τὰς ἀπειλάς, ἀναπρεσβεύει γὰρ δὴ πόλεμον ἀνατεινόμενος, μηχανὴ δ’ ἦν ἑτέρας βασιλείας οὐδεμία, καὶ γὰρ οἱ περὶ Νιφάτην δυνατοὶ τῶν Ἀρμενίων Ἀρταβάνῳ προστίθενται, παραδίδωσιν αὑτὸν Σιλανῷ τῷ τῆς Συρίας στρατηγῷ. κἀκεῖνος μὲν κατὰ αἰδῶ τῆς ἐν Ῥώμῃ κομιδῆς ἐν Συρίᾳ παρεφυλάσσετο· τὴν δὲ Ἀρμενίαν Ὀρώδῃ δίδωσιν Ἀρτάβανος ἑνὶ τῶν ἑαυτοῦ παίδων.", "st": "18.2.4"}, {"sp": "N", "t": "Ἐτελεύτησεν δὲ καὶ ὁ τῆς Κομμαγηνῆς βασιλεὺς Ἀντίοχος, διέστη δὲ τὸ πλῆθος πρὸς τοὺς γνωρίμους καὶ πρεσβεύουσιν ἀφ’ ἑκατέρου μέρους, οἱ μὲν δυνατοὶ μεταβάλλειν τὸ σχῆμα τῆς πολιτείας εἰς ἐπαρχίαν ἀξιοῦντες, τὸ πλῆθος δὲ βασιλεύεσθαι κατὰ τὰ πάτρια. καὶ ψηφίζεται ἡ σύγκλητος Γερμανικὸν πέμπειν διορθώσοντα τὰ κατὰ τὴν ἀνατολὴν πραγματευομένης αὐτῷ τῆς τύχης εὐκαιρίαν τοῦ θανάτου· καὶ γὰρ γενόμενος κατὰ τὴν ἀνατολὴν καὶ πάντα διορθώσας ἀνῃρέθη φαρμάκῳ ὑπὸ Πείσωνος, καθὼς ἐν ἄλλοις δεδήλωται.", "st": "18.2.5"}, {"sp": "N", "t": "Πιλᾶτος δὲ ὁ τῆς Ἰουδαίας ἡγεμὼν στρατιὰν ἐκ Καισαρείας ἀγαγὼν καὶ μεθιδρύσας χειμαδιοῦσαν ἐν Ἱεροσολύμοις ἐπὶ καταλύσει τῶν νομίμων τῶν Ἰουδαϊκῶν ἐφρόνησε, προτομὰς Καίσαρος, αἳ ταῖς σημαίαις προσῆσαν, εἰσαγόμενος εἰς τὴν πόλιν, εἰκόνων ποίησιν ἀπαγορεύοντος ἡμῖν τοῦ νόμου. καὶ διὰ τοῦτο οἱ πρότερον ἡγεμόνες ταῖς μὴ μετὰ τοιῶνδε κόσμων σημαίαις ἐποιοῦντο εἴσοδον τῇ πόλει. πρῶτος δὲ Πιλᾶτος ἀγνοίᾳ τῶν ἀνθρώπων διὰ τὸ νύκτωρ γενέσθαι τὴν εἴσοδον ἱδρύεται τὰς εἰκόνας φέρων εἰς τὰ Ἱεροσόλυμα. οἱ δ’ ἐπεὶ ἔγνωσαν κατὰ πληθὺν παρῆσαν εἰς Καισάρειαν ἱκετείαν ποιούμενοι ἐπὶ πολλὰς ἡμέρας ἐπὶ μεταθέσει τῶν εἰκόνων. καὶ μὴ συγχωροῦντος διὰ τὸ εἰς ὕβριν Καίσαρι φέρειν, ἐπείπερ οὐκ ἐξανεχώρουν λιπαρεῖν κατὰ ἕκτην ἡμέραν ἐν ὅπλοις ἀφανῶς ἐπικαθίσας τὸ στρατιωτικὸν αὐτὸς ἐπὶ τὸ βῆμα ἧκεν. τὸ δ’ ἐν τῷ σταδίῳ κατεσκεύαστο, ὅπερ ἀπέκρυπτε τὸν ἐφεδρεύοντα στρατόν. πάλιν δὲ τῶν Ἰουδαίων ἱκετείᾳ χρωμένων ἀπὸ συνθήματος περιστήσας τοὺς στρατιώτας ἠπείλει θάνατον ἐπιθήσειν ζημίαν ἐκ τοῦ ὀξέος, εἰ μὴ παυσάμενοι θορυβεῖν ἐπὶ τὰ οἰκεῖα ἀπίοιεν. οἱ δὲ πρηνεῖς ῥίψαντες ἑαυτοὺς καὶ γυμνοῦντες τὰς σφαγὰς ἡδονῇ δέξασθαι τὸν θάνατον ἔλεγον ἢ τολμήσειν τὴν σοφίαν παραβήσεσθαι τῶν νόμων. καὶ Πιλᾶτος θαυμάσας τὸ ἐχυρὸν αὐτῶν ἐπὶ φυλακῇ τῶν νόμων παραχρῆμα τὰς εἰκόνας ἐκ τῶν Ἱεροσολύμων ἐπανεκόμισεν εἰς Καισάρειαν.", "st": "18.3.1"}, {"sp": "N", "t": "Ὑδάτων δὲ ἐπαγωγὴν εἰς τὰ Ἱεροσόλυμα ἔπραξεν δαπάνῃ τῶν ἱερῶν χρημάτων ἐκλαβὼν τὴν ἀρχὴν τοῦ ῥεύματος ὅσον ἀπὸ σταδίων διακοσίων, οἱ δ’ οὐκ ἠγάπων τοῖς ἀμφὶ τὸ ὕδωρ δρωμένοις πολλαί τε μυριάδες ἀνθρώπων συνελθόντες κατεβόων αὐτοῦ παύσασθαι τοῦ ἐπὶ τοιούτοις προθυμουμένου, τινὲς δὲ καὶ λοιδορίᾳ χρώμενοι ὕβριζον εἰς τὸν ἄνδρα, οἷα δὴ φιλεῖ πράσσειν ὅμιλος. ὁ δὲ στολῇ τῇ ἐκείνων πολὺ πλῆθος στρατιωτῶν ἀμπεχόμενον, οἳ ἐφέροντο σκυτάλας ὑπὸ ταῖς στολαῖς, διαπέμψας εἰς ὃ περιέλθοιεν αὐτούς, αὐτὸς ἐκέλευσεν ἀναχωρεῖν. τῶν δὲ ὡρμηκότων εἰς τὸ λοιδορεῖν ἀποδίδωσι τοῖς στρατιώταις ὃ προσυνέκειτο σημεῖον. οἱ δὲ καὶ πολὺ μειζόνως ἤπερ ἐπέταξεν Πιλᾶτος ἐχρῶντο πληγαῖς τούς τε θορυβοῦντας ἐν ἴσῳ καὶ μὴ κολάζοντες οἱ δ’ εἰσεφέροντο μαλακὸν οὐδέν, ὥστε ἄοπλοι ληφθέντες ὑπ’ ἀνδρῶν ἐκ παρασκευῆς ἐπιφερομένων πολλοὶ μὲν αὐτῶν ταύτῃ καὶ ἀπέθνησκον, οἱ δὲ καὶ τραυματίαι ἀνεχώρησαν. καὶ οὕτω παύεται ἡ στάσις.", "st": "18.3.2"}, {"sp": "N", "t": "[Γίνεται δὲ κατὰ τοῦτον τὸν χρόνον Ἰησοῦς σοφὸς ἀνήρ, εἴγε ἄνδρα αὐτὸν λέγειν χρή· ἦν γὰρ παραδόξων ἔργων ποιητής, διδάσκαλος ἀνθρώπων τῶν ἡδονῇ τἀληθῆ δεχομένων, καὶ πολλοὺς μὲν Ἰουδαίους, πολλοὺς δὲ καὶ τοῦ Ἑλληνικοῦ ἐπηγάγετο· ὁ χριστὸς οὗτος ἦν.] [καὶ αὐτὸν ἐνδείξει τῶν πρώτων ἀνδρῶν παρ’ ἡμῖν σταυρῷ ἐπιτετιμηκότος Πιλάτου οὐκ ἐπαύσαντο οἱ τὸ πρῶτον ἀγαπήσαντες· ἐφάνη γὰρ αὐτοῖς τρίτην ἔχων ἡμέραν πάλιν ζῶν τῶν θείων προφητῶν ταῦτά τε καὶ ἄλλα μυρία περὶ αὐτοῦ θαυμάσια εἰρηκότων. εἰς ἔτι τε νῦν τῶν Χριστιανῶν ἀπὸ τοῦδε ὠνομασμένον οὐκ ἐπέλιπε τὸ φῦλον.]", "st": "18.3.3"}, {"sp": "N", "t": "Καὶ ὑπὸ τοὺς αὐτοὺς χρόνους ἕτερόν τι δεινὸν ἐθορύβει τοὺς Ἰουδαίους καὶ περὶ τὸ ἱερὸν τῆς Ἴσιδος τὸ ἐν Ῥώμῃ πράξεις αἰσχυνῶν οὐκ ἀπηλλαγμέναι συντυγχάνουσιν. καὶ πρότερον τοῦ τῶν Ἰσιακῶν τολμήματος μνήμην ποιησάμενος οὕτω μεταβιβῶ τὸν λόγον ἐπὶ τὰ ἐν τοῖς Ἰουδαίοις γεγονότα. Παυλῖνα ἦν τῶν ἐπὶ Ῥώμης προγόνων τε ἀξιώματι τῶν καθ’ ἑαυτὴν ἐπιτηδεύοντι κόσμον ἀρετῆς ἐπὶ μέγα προϊοῦσα τῷ ὀνόματι, δύναμίς τε αὐτῇ χρημάτων ἦν καὶ γεγονυῖα τὴν ὄψιν εὐπρεπὴς καὶ τῆς ὥρας ἐν ᾗ μάλιστα ἀγάλλονται αἱ γυναῖκες εἰς τὸ σωφρονεῖν ἀνέκειτο ἡ ἐπιτήδευσις τοῦ βίου. ἐγεγάμητο δὲ Σατορνίνῳ τῶν εἰς τὰ πάντα ἀντισουμένων τῷ περὶ αὐτὴν ἀξιολόγῳ. ταύτης ἐρᾷ Δέκιος Μοῦνδος τῶν τότε ἱππέων ἐν ἀξιώματι μεγάλῳ, καὶ μείζονα οὖσαν ἁλῶναι δώροις διὰ τὸ καὶ πεμφθέντων εἰς πλῆθος περιιδεῖν ἐξῆπτο μᾶλλον, ὥστε καὶ εἴκοσι μυριάδας δραχμῶν Ἀτθίδων ὑπισχνεῖτο εὐνῆς μιᾶς. καὶ μηδ’ ὣς ἐπικλωμένης, οὐ φέρων τὴν ἀτυχίαν τοῦ ἔρωτος ἐνδείᾳ σιτίων θάνατον ἐπιτιμᾶν αὑτῷ καλῶς ἔχειν ἐνόμισεν ἐπὶ παύλῃ κακοῦ τοῦ κατειληφότος. καὶ ὁ μὲν ἐπεψήφιζέν τε τῇ οὕτω τελευτῇ καὶ πράσσειν οὐκ ἀπηλλάσσετο. καὶ ἦν γὰρ ὄνομα Ἴδη πατρῷος ἀπελευθέρα τῷ Μούνδῳ παντοίων ἴδρις κακῶν, δεινῶς φέρουσα τοῦ νεανίσκου τῷ ψηφίσματι τοῦ θανεῖν, οὐ γὰρ ἀφανὴς ἦν ἀπολούμενος, ἀνεγείρει τε αὐτὸν ἀφικομένη διὰ λόγου πιθανή τε ἦν ἐλπίδων τινῶν ὑποσχέσεσιν, ὡς διαπραχθησομένων ὁμιλιῶν πρὸς τὴν Παυλῖναν αὐτῷ. καὶ δεχομένου τὴν ἱκετείαν ἡδονῇ πέντε μυριάδων δεήσειν αὐτῇ μόνων ἔλεγεν ἐπὶ ἁλώσει τῆς γυναικός. καὶ ἡ μὲν ἐπὶ τούτοις ἀνεγείρασα τὸν νεανίσκον καὶ τὸ αἰτηθὲν λαβοῦσα ἀργύριον οὐ τὰς αὐτὰς ὁδοὺς ἐστέλλετο τοῖς προδεδιακονημένοις ὁρῶσα τῆς γυναικὸς τὸ μηδαμῶς χρημάτων ἁλισκόμενον, εἰδυῖα δὲ αὐτὴν θεραπείᾳ τῆς Ἴσιδος σφόδρα ὑπηγμένην τεχνᾶταί τι τοιόνδε. τῶν ἱερέων τισὶν ἀφικομένη διὰ λόγων ἐπὶ πίστεσιν μεγάλαις τὸ δὲ μέγιστον δόσει χρημάτων τὸ μὲν παρὸν μυριάδων δυοῖν καὶ ἡμίσει, λαβόντος δ’ ἔκβασιν τοῦ πράγματος ἑτέρῳ τοσῷδε, διασαφεῖ τοῦ νεανίσκου τὸν ἔρωτα αὐτοῖς, κελεύουσα παντοίως ἐπὶ τῷ ληψομένῳ τὴν ἄνθρωπον σπουδάσαι. οἱ δ’ ἐπὶ πληγῇ τοῦ χρυσίου παραχθέντες ὑπισχνοῦντο. καὶ αὐτῶν ὁ γεραίτατος ὡς τὴν Παυλῖναν ὠσάμενος γενομένων εἰσόδων καταμόνας διὰ λόγων ἐλθεῖν ἠξίου. καὶ συγχωρηθὲν πεμπτὸς ἔλεγεν ἥκειν ὑπὸ τοῦ Ἀνούβιδος ἔρωτι αὐτῆς ἡσσημένου τοῦ θεοῦ κελεύοντός τε ὡς αὐτὸν ἐλθεῖν. τῇ δὲ εὐκτὸς ὁ λόγος ἦν καὶ ταῖς τε φίλαις ἐνεκαλλωπίζετο τῇ ἐπὶ τοιούτοις ἀξιώσει τοῦ Ἀνούβιδος καὶ φράζει πρὸς τὸν ἄνδρα, δεῖπνόν τε αὐτῇ καὶ εὐνὴν τοῦ Ἀνούβιδος εἰσηγγέλθαι, συνεχώρει δ’ ἐκεῖνος τὴν σωφροσύνην τῆς γυναικὸς ἐξεπιστάμενος. χωρεῖ οὖν εἰς τὸ τέμενος, καὶ δειπνήσασα, ὡς ὕπνου καιρὸς ἦν, κλεισθεισῶν τῶν θυρῶν ὑπὸ τοῦ ἱερέως ἔνδον ἐν τῷ νεῷ καὶ τὰ λύχνα ἐκποδὼν ἦν καὶ ὁ Μοῦνδος, προεκέκρυπτο γὰρ τῇδε, οὐχ ἡμάρτανεν ὁμιλιῶν τῶν πρὸς αὐτήν, παννύχιόν τε αὐτῷ διηκονήσατο ὑπειληφυῖα θεὸν εἶναι. καὶ ἀπελθόντος πρότερον ἢ κίνησιν ἄρξασθαι τῶν ἱερέων, οἳ τὴν ἐπιβουλὴν ᾔδεσαν, ἡ Παυλῖνα πρωῒ ὡς τὸν ἄνδρα ἐλθοῦσα τὴν ἐπιφάνειαν ἐκδιηγεῖται τοῦ Ἀνούβιδος καὶ πρὸς τὰς φίλας ἐνελαμπρύνετο λόγοις τοῖς ἐπ’ αὐτῷ. οἱ δὲ τὰ μὲν ἠπίστουν εἰς τὴν φύσιν τοῦ πράγματος ὁρῶντες, τὰ δ’ ἐν θαύματι καθίσταντο οὐκ ἔχοντες, ὡς χρὴ ἄπιστα αὐτὰ κρίνειν, ὁπότε εἴς τε τὴν σωφροσύνην καὶ τὸ ἀξίωμα ἀπίδοιεν αὐτῆς. τρίτῃ δὲ ἡμέρᾳ μετὰ τὴν πρᾶξιν ὑπαντιάσας αὐτὴν ὁ Μοῦνδος Παυλῖνα, φησίν, ἀλλά μοι καὶ εἴκοσι μυριάδας διεσώσω δυναμένη οἴκῳ προσθέσθαι τῷ σαυτῆς διακονεῖσθαί τε ἐφ’ οἷς προεκαλούμην οὐκ ἐνέλιπες. ἃ μέντοι εἰς Μοῦνδον ὑβρίζειν ἐπειρῶ, μηδέν μοι μελῆσαν τῶν ὀνομάτων, ἀλλὰ τῆς ἐκ τοῦ πράγματος ἡδονῆς, Ἀνούβιον ὄνομα ἐθέμην αὐτῷ. καὶ ὁ μὲν ἀπῄει ταῦτα εἰπών, ἡ δὲ εἰς ἔννοιαν τότε πρῶτον ἐλθοῦσα τοῦ τολμήματος περιρρήγνυταί τε τὴν στολὴν καὶ τἀνδρὶ δηλώσασα τοῦ παντὸς ἐπιβουλεύματος τὸ μέγεθος ἐδεῖτο μὴ περιῶφθαι βοηθείας τυγχάνειν· ὁ δὲ τῷ αὐτοκράτορι ἐπεσήμηνε τὴν πρᾶξιν. καὶ ὁ Τιβέριος μαθήσεως ἀκριβοῦς αὐτῷ γενομένης ἐξετάσει τῶν ἱερέων ἐκείνους τε ἀνεσταύρωσεν καὶ τὴν Ἴδην ὀλέθρου γενομένην αἰτίαν καὶ τὰ πάντα ἐφ’ ὕβρει συνθεῖσαν τῆς γυναικός, τόν τε ναὸν καθεῖλεν καὶ τὸ ἄγαλμα τῆς Ἴσιδος εἰς τὸν Θύβριν ποταμὸν ἐκέλευσεν ἐμβαλεῖν. Μοῦνδον δὲ φυγῆς ἐτίμησε, κώλυμα τοῦ μὴ μειζόνως κολάζειν τὸ μετὰ ἔρωτος αὐτῷ ἡμαρτῆσθαι τὰ ἡμαρτημένα ἡγησάμενος. καὶ τὰ μὲν περὶ τὸ ἱερὸν τῆς Ἴσιδος τοῖς ἱερεῦσιν ὑβρισμένα τοιαῦτα ἦν. ἐπάνειμι δὲ ἐπὶ τὴν ἀφήγησιν τῶν ἐν Ῥώμῃ Ἰουδαίοις κατὰ τοῦτον τὸν χρόνον συντυχόντων, ὥς μοι καὶ προαπεσήμηνεν ὁ λόγος.", "st": "18.3.4"}, {"sp": "N", "t": "Ἦν ἀνὴρ Ἰουδαῖος, φυγὰς μὲν τῆς αὐτοῦ κατηγορίᾳ τε παραβάσεων νόμων τινῶν καὶ δέει τιμωρίας τῆς ἐπ’ αὐτοῖς, πονηρὸς δὲ εἰς τὰ πάντα. καὶ δὴ τότε ἐν τῇ Ῥώμῃ διαιτώμενος προσεποιεῖτο μὲν ἐξηγεῖσθαι σοφίαν νόμων τῶν Μωυσέως, προσποιησάμενος δὲ τρεῖς ἄνδρας εἰς τὰ πάντα ὁμοιοτρόπους τούτοις ἐπιφοιτήσασαν Φουλβίαν τῶν ἐν ἀξιώματι γυναικῶν καὶ νομίμοις προσεληλυθυῖαν τοῖς Ἰουδαϊκοῖς πείθουσι πορφύραν καὶ χρυσὸν εἰς τὸ ἐν Ἱεροσολύμοις ἱερὸν διαπέμψασθαι, καὶ λαβόντες ἐπὶ χρείας τοῖς ἰδίοις ἀναλώμασιν αὐτὰ ποιοῦνται, ἐφ’ ὅπερ καὶ τὸ πρῶτον ἡ αἴτησις ἐπράσσετο. καὶ ὁ Τιβέριος, ἀποσημαίνει γὰρ πρὸς αὐτὸν φίλος ὢν Σατορνῖνος τῆς Φουλβίας ἀνὴρ ἐπισκήψει τῆς γυναικός, κελεύει πᾶν τὸ Ἰουδαϊκὸν τῆς Ῥώμης ἀπελθεῖν. οἱ δὲ ὕπατοι τετρακισχιλίους ἀνθρώπους ἐξ αὐτῶν στρατολογήσαντες ἔπεμψαν εἰς Σαρδὼ τὴν νῆσον, πλείστους δὲ ἐκόλασαν μὴ θέλοντας στρατεύεσθαι διὰ φυλακὴν τῶν πατρίων νόμων. καὶ οἱ μὲν δὴ διὰ κακίαν τεσσάρων ἀνδρῶν ἠλαύνοντο τῆς πόλεως.", "st": "18.3.5"}, {"sp": "N", "t": "Οὐκ ἀπήλλακτο δὲ θορύβου καὶ τὸ Σαμαρέων ἔθνος· συστρέφει γὰρ αὐτοὺς ἀνὴρ ἐν ὀλίγῳ τὸ ψεῦδος τιθέμενος κἀφ’ ἡδονῇ τῆς πληθύος τεχνάζων τὰ πάντα, κελεύων ἐπὶ τὸ Γαριζεὶν ὄρος αὐτῷ συνελθεῖν, ὃ ἁγνότατον αὐτοῖς ὀρῶν ὑπείληπται, ἰσχυρίζετό τε παραγενομένοις δείξειν τὰ ἱερὰ σκεύη τῇδε κατορωρυγμένα Μωυσέως τῇδε αὐτῶν ποιησαμένου κατάθεσιν. οἱ δὲ ἐν ὅπλοις τε ἦσαν πιθανὸν ἡγούμενοι τὸν λόγον, καὶ καθίσαντες ἔν τινι κώμῃ, Τιραθανὰ λέγεται, παρελάμβανον τοὺς ἐπισυλλεγομένους ὡς μεγάλῳ πλήθει τὴν ἀνάβασιν εἰς τὸ ὄρος ποιησόμενοι. φθάνει δὲ Πιλᾶτος τὴν ἄνοδον αὐτῶν προκαταλαβόμενος ἱππέων τε πομπῇ καὶ ὁπλιτῶν, οἳ συμβαλόντες τοῖς ἐν τῇ κώμῃ προσυνηθροισμένοις παρατάξεως γενομένης τοὺς μὲν ἔκτειναν, τοὺς δ’ εἰς φυγὴν τρέπονται ζωγρίᾳ τε πολλοὺς ἦγον, ὧν τοὺς κορυφαιοτάτους καὶ τοὺς ἐν τοῖς φυγοῦσι δυνατωτάτους ἔκτεινε Πιλᾶτος.", "st": "18.4.1"}, {"sp": "N", "t": "Καταστάντος δὲ τοῦ θορύβου Σαμαρέων ἡ βουλὴ παρὰ Οὐιτέλλιον ὑπατικὸν ἴασιν ἄνδρα Συρίας τὴν ἡγεμονίαν ἔχοντα καὶ Πιλάτου κατηγόρουν ἐπὶ τῇ σφαγῇ τῶν ἀπολωλότων· οὐ γὰρ ἐπὶ ἀποστάσει τῶν Ῥωμαίων, ἀλλ’ ἐπὶ διαφυγῇ τῆς Πιλάτου ὕβρεως εἰς τὴν Τιραθανὰ παραγενέσθαι. καὶ Οὐιτέλλιος Μάρκελλον τῶν αὐτοῦ φίλων ἐκπέμψας ἐπιμελητὴν τοῖς Ἰουδαίοις γενησόμενον Πιλᾶτον ἐκέλευσεν ἐπὶ Ῥώμης ἀπιέναι πρὸς ἃ κατηγοροῖεν οἱ Σαμαρεῖται διδάξοντα τὸν αὐτοκράτορα. καὶ Πιλᾶτος δέκα ἔτεσιν διατρίψας ἐπὶ Ἰουδαίας εἰς Ῥώμην ἠπείγετο ταῖς Οὐιτελλίου πειθόμενος ἐντολαῖς οὐκ ὂν ἀντειπεῖν. πρὶν δ’ ἐν τῇ Ῥώμῃ ἴσχειν αὐτὸν φθάνει Τιβέριος μεταστάς.", "st": "18.4.2"}, {"sp": "N", "t": "Οὐιτέλλιος δὲ εἰς τὴν Ἰουδαίαν ἀφικόμενος ἐπὶ Ἱεροσολύμων ἀνῄει, καὶ ἦν γὰρ αὐτοῖς ἑορτὴ πάτριος, πάσχα δὲ καλεῖται, δεχθεὶς μεγαλοπρεπῶς Οὐιτέλλιος τὰ τέλη τῶν ὠνουμένων καρπῶν ἀνίησιν εἰς τὸ πᾶν τοῖς ταύτῃ κατοικοῦσιν καὶ τὴν στολὴν τοῦ ἀρχιερέως καὶ τὸν πάντα αὐτοῦ κόσμον συνεχώρησεν ἐν τῷ ἱερῷ κειμένην ὑπὸ τοῖς ἱερεῦσιν ἔχειν τὴν ἐπιμέλειαν, καθότι καὶ πρότερον ἦν αὐτοῖς ἐξουσία. τότε δὲ ἐν τῇ Ἀντωνίᾳ, φρούριον δ’ ἐστὶν οὕτως λεγόμενον, ἡ ἀπόθεσις αὐτῆς ἦν διὰ τοιαύτην αἰτίαν· τῶν ἱερέων τις Ὑρκανός, πολλῶν δὲ ὄντων οἳ τόδε ἐκαλοῦντο τὸ ὄνομα ὁ πρῶτος, ἐπεὶ πλησίον τῷ ἱερῷ βᾶριν κατασκευασάμενος ταύτῃ τὰ πολλὰ τὴν δίαιταν εἶχεν καὶ τὴν στολήν, φύλαξ γὰρ ἦν αὐτῆς διὰ τὸ καὶ μόνῳ συγκεχωρῆσθαι τοῦ ἐνδύεσθαι τὴν ἐξουσίαν, ταύτην εἶχεν ἀποκειμένην, ὁπότε εἰς τὴν πόλιν κατιὼν ἀναλαμβάνοι τὴν ἰδιωτικήν. καὶ οἵ τε υἱεῖς αὐτοῦ ταῦτα πράσσειν ἐπετήδευσαν καὶ τέκνα ἐκείνων. Ἡρώδης δὲ βασιλεύσας τήν τε βᾶριν ταύτην ἐν ἐπιτηδείῳ κειμένην κατασκευάσας πολυτελῶς Ἀντωνίαν καλεῖ ὀνόματι Ἀντωνίου φίλος ὤν, καὶ τὴν στολὴν ὥσπερ καὶ λαμβάνει τῇδε κειμένην κατεῖχεν, πιστεύων οὐδὲν νεωτεριεῖν ἐπ’ αὐτῷ τὸν λαὸν διὰ τάδε. ἔπρασσε δὲ ὅμοια τῷ Ἡρώδῃ καὶ ὁ ἐπικατασταθεὶς αὐτῷ βασιλεὺς Ἀρχέλαος υἱὸς ὤν, οὗ Ῥωμαῖοι παραδεξάμενοι τὴν ἀρχὴν ἐκράτουν τῆς στολῆς τοῦ ἀρχιερέως ἀποκειμένης ἐν οἴκῳ λίθοις οἰκοδομηθέντι ὑπὸ σφραγῖδι τῶν τε ἱερέων καὶ τῶν γαζοφυλάκων τοῦ φρουράρχου τὸ ἐφ’ ἡμέραν ἑκάστην λύχνον ἅπτοντος. ἑπτὰ δ’ ἡμέραις πρὸ τῆς ἑορτῆς ἀπεδίδοτο αὐτοῖς ὑπὸ τοῦ φρουράρχου, καὶ ἁγνισθείσῃ χρησάμενος ὁ ἀρχιερεὺς μετὰ μίαν τῆς ἑορτῆς ἡμέραν ἀπετίθετο αὖθις εἰς τὸν οἶκον, ᾗπερ ἔκειτο καὶ πρότερον. τοῦτο ἐπράττετο τρισὶν ἑορταῖς ἑκάστου ἔτους καὶ τὴν νηστείαν. Οὐιτέλλιος δὲ ἐπὶ τῷ ἡμετέρῳ πατρίῳ ποιεῖται τὴν στολήν, ᾗ τε κείσοιτο μὴ πολυπραγμονεῖν ἐπισκήψας τῷ φρουράρχῳ καὶ ὁπότε δέοι χρῆσθαι. καὶ ταῦτα πράξας ἐπὶ εὐεργεσίᾳ τοῦ ἔθνους καὶ τὸν ἀρχιερέα Ἰώσηπον τὸν Καϊάφαν ἐπικαλούμενον ἀπαλλάξας τῆς ἱερωσύνης Ἰωνάθην καθίστησιν Ἀνάνου τοῦ ἀρχιερέως υἱόν. ἐπ’ Ἀντιοχείας δ’ αὖθις ἐποιεῖτο τὴν ὁδόν.", "st": "18.4.3"}, {"sp": "N", "t": "Πέμπει δὲ καὶ Τιβέριος ὡς Οὐιτέλλιον γράμματα, κελεύων αὐτῷ πράσσειν φιλίαν πρὸς Ἀρτάβανον τὸν Πάρθων βασιλέα· ἐφόβει γὰρ αὐτὸν ἐχθρὸς ὢν καὶ Ἀρμενίαν παρεσπασμένος μὴ ἐπὶ πλέον κακουργῇ· πιστεύειν δὲ τῇ φιλίᾳ μόνως ὁμήρων αὐτῷ διδομένων, μάλιστα δὲ τοῦ Ἀρταβάνου υἱέος. ταῦτα δὲ γράφων Τιβέριος πρὸς τὸν Οὐιτέλλιον μεγάλαις δόσεσι χρημάτων πείθει καὶ τὸν Ἰβήρων καὶ τὸν Ἀλβανῶν βασιλέα πολεμεῖν Ἀρταβάνῳ μηδὲν ἐνδοιάσαι. οἱ δὲ αὐτοὶ μὲν ἀντεῖχον, Ἀλανοὶ δὲ δίοδον αὐτοῖς διδόντες διὰ τῆς αὐτῶν καὶ τὰς θύρας τὰς Κασπίας ἀνοίξαντες ἐπάγουσι τῷ Ἀρταβάνῳ. καὶ ἥ τε Ἀρμενία ἀφῄρητο αὖθις καὶ πλησθείσης πολέμων τῆς Παρθυαίων γῆς οἵ τε πρῶτοι τῶν τῇδε ἐκτείνοντο ἀνδρῶν ἀνάστατά τε ἦν αὐτοῖς τὰ πάντα καὶ τοῦ βασιλέως ὁ υἱὸς ἐκ τουτωνὶ τῶν μαχῶν ἔπεσε μετὰ πολλῶν στρατοῦ μυριάδων. καὶ αὐτοῦ τὸν πατέρα Ἀρτάβανον Οὐιτέλλιος πομπῇ χρημάτων εἴς τε συγγενεῖς καὶ φίλους τοὺς ἐκείνου γενομένῃ ἐμέλλησε μὲν κτιννύειν διὰ τῶν τὰ δῶρα εἰληφότων, αἰσθόμενος δὲ τὴν ἐπιβουλὴν ὁ Ἀρτάβανος ἄφυκτον οὖσαν διὰ τὸ ὑπὸ πολλῶν καὶ τῶν πρώτων ἀνδρῶν συντεθεῖσαν μὴ ἀνεῖσθαι τοῦ ἐπὶ πέρας ἐλθεῖν, καὶ νομίζων καὶ ὁπόσον αὐτῷ καθαρῶς συνειστήκει καὶ τόδε ἤτοι ἐφθαρμένον ἐπὶ δόλῳ τὴν εὔνοιαν προσποιεῖσθαι ἢ πείρας αὐτῷ γενομένης μετατάξεσθαι πρὸς τοὺς προαφεστηκότας, εἴς τι τῶν ἄνω σατραπειῶν ἔσωζεν αὑτόν. καὶ πολλὴν μετὰ ταῦτα στρατιὰν ἀθροίσας Δαῶν τε καὶ Σακῶν καὶ πολεμήσας τοὺς ἀνθεστηκότας κατέσχε τὴν ἀρχήν.", "st": "18.4.4"}, {"sp": "N", "t": "Ταῦτα ἀκούσας ὁ Τιβέριος ἠξίου φιλίαν αὐτῷ γενέσθαι πρὸς τὸν Ἀρτάβανον, ἐπεὶ δὲ κἀκεῖνος προκληθεὶς ἄσμενος ἐδέχετο τὸν περὶ αὐτῶν λόγον, ἐπὶ τὸν Εὐφράτην παρῆσαν ὅ τε Ἀρτάβανος καὶ Οὐιτέλλιος. καὶ ζεύξεως τοῦ ποταμοῦ γενομένης κατὰ τὸ μεσαίτατον τῆς γεφύρας ἀλλήλους ὑπηντίαζον μετὰ φυλακῆς ἑκάτερος τῆς περὶ αὐτόν. καὶ λόγων αὐτοῖς συμβατικῶν γενομένων Ἡρώδης ὁ τετράρχης εἱστίασεν αὐτοὺς κατὰ μέσον τὸν πόρον σκηνίδα ἐπισκηψάμενος τῷ πόρῳ πολυτελῆ. καὶ Ἀρτάβανος πέμπει Τιβερίῳ ὅμηρον Δαρεῖον τὸν υἱὸν μετὰ πολλῶν δώρων, ἐν οἷς καὶ ἄνδρα ἑπτάπηχυν τὸ μέγεθος Ἰουδαῖον τὸ γένος Ἐλεάζαρον ὄνομα· διὰ μέντοι τὸ μέγεθος Γίγας ἐκαλεῖτο. ἐπὶ τούτοις Οὐιτέλλιος μὲν ἐπ’ Ἀντιοχείας ᾔει, Ἀρτάβανος δὲ ἐπὶ τῆς Βαβυλωνίας. Ἡρώδης δὲ βουλόμενος δι’ αὐτοῦ πρώτου γενέσθαι πύστιν Καίσαρι τῶν ὁμήρων τῆς λήψεως ἐκπέμπει γραμματοφόρους τὰ πάντα ἀκριβῶς γράψας εἰς ἐπιστολὴν καὶ μηδὲν ὑπολιπόμενος ἐπὶ μηνύσει τῷ ὑπατικῷ. πρὸς Οὐιτελλίου δὲ ἐπιπεμφθεισῶν ἐπιστολῶν καὶ τοῦ Καίσαρος ἐπισημήναντος πρὸς αὐτόν, ὡς δῆλα αὐτῷ γένοιτο πρότερον πύστιν περὶ αὐτῶν Ἡρώδου προτεθεικότος, ταραχθεὶς ὁ Οὐιτέλλιος μεγάλως καὶ πεπονθέναι μειζόνως ἢ ἐπέπρακτο ὑπολαμβάνων ἄδηλον τὴν ἐπ’ αὐτοῖς ἔκρυπτεν ὀργήν, μέχρι δὴ καὶ μετῆλθε Γαΐου τὴν Ῥωμαίων ἀρχὴν παρειληφότος.", "st": "18.4.5"}, {"sp": "N", "t": "Τότε δὲ καὶ Φίλιππος, Ἡρώδου δὲ ἦν ἀδελφός, τελευτᾷ τὸν βίον εἰκοστῷ μὲν ἐνιαυτῷ τῆς Τιβερίου ἀρχῆς, ἡγησάμενος δὲ αὐτὸς ἑπτὰ καὶ τριάκοντα τῆς Τραχωνίτιδος καὶ Γαυλανίτιδος καὶ τοῦ Βατανέων ἔθνους πρὸς αὐταῖς, μέτριον δὲ ἐν οἷς ἦρχεν παρασχὼν τὸν τρόπον καὶ ἀπράγμονα· δίαιταν μὲν γὰρ τὸ πᾶν ἐν γῇ τῇ ὑποτελεῖ ἐποιεῖτο, πρόοδοι δ’ ἦσαν αὐτῷ σὺν ὀλίγοις τῶν ἐπιλέκτων, καὶ τοῦ θρόνου εἰς ὃν ἔκρινεν καθεζόμενος ἐν ταῖς ὁδοῖς ἑπομένου, ὁπότε τις ὑπαντιάσας ἐν χρείᾳ γένοιτο αὐτῷ ἐπιβοηθεῖν, οὐδὲν εἰς ἀναβολὰς ἀλλ’ ἐκ τοῦ ὀξέος ἱδρύσεως τοῦ θρόνου ᾗ καὶ τύχοι γενομένης καθεζόμενος ἠκροᾶτο καὶ τιμωρίας τε ἐπετίμα τοῖς ἁλοῦσι καὶ ἠφίει τοὺς ἀδίκως ἐν ἐγκλήμασι γενομένους. τελευτᾷ δ’ ἐν Ἰουλιάδι καὶ αὐτοῦ κομισθέντος ἐπὶ τὸ μνημεῖον, ὃ ἔτι πρότερον ᾠκοδόμησεν αὐτός, ταφαὶ γίνονται πολυτελεῖς. τὴν δ’ ἀρχήν, οὐ γὰρ κατελίπετο παῖδας, Τιβέριος παραλαβὼν προσθήκην ἐπαρχίας ποιεῖται τῆς Σύρων, τοὺς μέντοι φόρους ἐκέλευσε συλλεγομένους ἐν τῇ τετραρχίᾳ τῇ ἐκείνου γενομένῃ κατατίθεσθαι.", "st": "18.4.6"}, {"sp": "N", "t": "Ἐν τούτῳ δὲ στασιάζουσιν Ἀρέτας τε ὁ Πετραῖος βασιλεὺς καὶ Ἡρώδης διὰ τοιαύτην αἰτίαν· Ἡρώδης ὁ τετράρχης γαμεῖ τὴν Ἀρέτα θυγατέρα καὶ συνῆν χρόνον ἤδη πολύν. στελλόμενος δὲ ἐπὶ Ῥώμης κατάγεται ἐν Ἡρώδου ἀδελφοῦ ὄντος οὐχ ὁμομητρίου· ἐκ γὰρ τῆς Σίμωνος τοῦ ἀρχιερέως θυγατρὸς Ἡρώδης ἐγεγόνει. ἐρασθεὶς δὲ Ἡρωδιάδος τῆς τούτου γυναικός, θυγάτηρ δὲ ἦν Ἀριστοβούλου καὶ οὗτος ἀδελφὸς αὐτῶν, Ἀγρίππου δὲ ἀδελφὴ τοῦ μεγάλου, τολμᾷ λόγων ἅπτεσθαι περὶ γάμου. καὶ δεξαμένης συνθῆκαι γίνονται μετοικίσασθαι παρ’ αὐτόν, ὁπότε ἀπὸ Ῥώμης παραγένοιτο. ἦν δὲ ἐν ταῖς συνθήκαις ὥστε καὶ τοῦ Ἀρέτα τὴν θυγατέρα ἐκβαλεῖν. καὶ ὁ μὲν εἰς τὴν Ῥώμην ἔπλει ταῦτα συνθέμενος. ἐπεὶ δὲ ἐπανεχώρει διαπραξάμενος ἐν τῇ Ῥώμῃ ἐφ’ ἅπερ ἔσταλτο, ἡ γυνὴ πύστεως αὐτῇ τῶν πρὸς τὴν Ἡρωδιάδα συνθηκῶν γενομένης πρὶν ἔκπυστος αὐτῷ γενέσθαι τὰ πάντα ἐκμαθοῦσα κελεύει πέμπειν αὐτὴν ἐπὶ Μαχαιροῦντος, μεθόριον δ’ ἐστὶ τῆς τε Ἀρέτα καὶ Ἡρώδου ἀρχῆς, γνώμην οὐκ ἐκφαίνουσα τὴν αὐτῆς. καὶ ὁ Ἡρώδης ἐξέπεμψεν μηδὲν ᾐσθῆσθαι τὴν ἄνθρωπον προσδοκῶν. ἡ δέ, προαπεστάλκει γὰρ ἐκ πλείονος εἰς τὸν Μαχαιροῦντα τῷ τε πατρὶ αὐτῆς ὑποτελεῖ, πάντων εἰς τὴν ὁδοιπορίαν ἡτοιμασμένων ὑπὸ τοῦ στρατηγοῦ ἅμα τε παρῆν καὶ ἀφωρμᾶτο εἰς τὴν Ἀραβίαν κομιδῇ τῶν στρατηγῶν ἐκ διαδοχῆς παρῆν τε ὡς τὸν πατέρα ᾗ τάχος καὶ αὐτῷ τὴν Ἡρώδου διάνοιαν ἔφραζεν. ὁ δὲ ἀρχὴν ἔχθρας ταύτην ποιησάμενος περί τε ὅρων ἐν γῇ τῇ Γαμαλικῇ, καὶ δυνάμεως ἑκατέρῳ συλλεγείσης εἰς πόλεμον καθίσταντο στρατηγοὺς ἀπεσταλκότες ἀνθ’ ἑαυτῶν. καὶ μάχης γενομένης διεφθάρη πᾶς ὁ Ἡρώδου στρατὸς προδοσίας αὐτῷ γενομένης ὑπ’ ἀνδρῶν φυγάδων, οἳ ὄντες ἐκ τῆς Φιλίππου τετραρχίας Ἡρώδῃ συνεστράτευον. ταῦτα Ἡρώδης γράφει πρὸς Τιβέριον. ὁ δὲ ὀργῇ φέρων τὴν Ἀρέτα ἐπιχείρησιν γράφει πρὸς Οὐιτέλλιον πόλεμον ἐξενεγκεῖν καὶ ἤτοι ζωὸν ἑλόντα ἀναγαγεῖν δεδεμένον ἢ κτεινομένου πέμπειν τὴν κεφαλὴν ἐπ’ αὐτόν. καὶ Τιβέριος μὲν ταῦτα πράσσειν ἐπέστελλεν τῷ κατὰ Συρίαν στρατηγῷ.", "st": "18.5.1"}, {"sp": "N", "t": "Τισὶ δὲ τῶν Ἰουδαίων ἐδόκει ὀλωλέναι τὸν Ἡρώδου στρατὸν ὑπὸ τοῦ θεοῦ καὶ μάλα δικαίως τινυμένου κατὰ ποινὴν Ἰωάννου τοῦ ἐπικαλουμένου βαπτιστοῦ. κτείνει γὰρ δὴ τοῦτον Ἡρώδης ἀγαθὸν ἄνδρα καὶ τοῖς Ἰουδαίοις κελεύοντα ἀρετὴν ἐπασκοῦσιν καὶ τὰ πρὸς ἀλλήλους δικαιοσύνῃ καὶ πρὸς τὸν θεὸν εὐσεβείᾳ χρωμένοις βαπτισμῷ συνιέναι· οὕτω γὰρ δὴ καὶ τὴν βάπτισιν ἀποδεκτὴν αὐτῷ φανεῖσθαι μὴ ἐπί τινων ἁμαρτάδων παραιτήσει χρωμένων, ἀλλ’ ἐφ’ ἁγνείᾳ τοῦ σώματος, ἅτε δὴ καὶ τῆς ψυχῆς δικαιοσύνῃ προεκκεκαθαρμένης. καὶ τῶν ἄλλων συστρεφομένων, καὶ γὰρ ἥσθησαν ἐπὶ πλεῖστον τῇ ἀκροάσει τῶν λόγων, δείσας Ἡρώδης τὸ ἐπὶ τοσόνδε πιθανὸν αὐτοῦ τοῖς ἀνθρώποις μὴ ἐπὶ ἀποστάσει τινὶ φέροι, πάντα γὰρ ἐῴκεσαν συμβουλῇ τῇ ἐκείνου πράξοντες, πολὺ κρεῖττον ἡγεῖται πρίν τι νεώτερον ἐξ αὐτοῦ γενέσθαι προλαβὼν ἀνελεῖν τοῦ μεταβολῆς γενομένης [μὴ] εἰς πράγματα ἐμπεσὼν μετανοεῖν. καὶ ὁ μὲν ὑποψίᾳ τῇ Ἡρώδου δέσμιος εἰς τὸν Μαχαιροῦντα πεμφθεὶς τὸ προειρημένον φρούριον ταύτῃ κτίννυται. τοῖς δὲ Ἰουδαίοις δόξαν ἐπὶ τιμωρίᾳ τῇ ἐκείνου τὸν ὄλεθρον ἐπὶ τῷ στρατεύματι γενέσθαι τοῦ θεοῦ κακῶσαι Ἡρώδην θέλοντος.", "st": "18.5.2"}, {"sp": "N", "t": "Οὐιτέλλιος δὲ παρασκευασάμενος ὡς εἰς πόλεμον τὸν πρὸς Ἀρέταν δυσὶ τάγμασιν ὁπλιτῶν ὅσοι τε περὶ αὐτὰ ψιλοὶ καὶ ἱππεῖς συμμαχοῦντες ἐκ τῶν ὑπὸ Ῥωμαίοις βασιλειῶν ἀγόμενος, ἐπὶ τῆς Πέτρας ἠπείγετο καὶ ἔσχε Πτολεμαΐδα. ὡρμημένῳ δ’ αὐτῷ διὰ τῆς Ἰουδαίων ἄγειν τὸν στρατὸν ὑπαντιάσαντες ἄνδρες οἱ πρῶτοι παρῃτοῦντο τὴν διὰ τῆς χώρας ὁδόν· οὐ γὰρ αὐτοῖς εἶναι πάτριον περιορᾶν εἰκόνας εἰς αὐτὴν φερομένας, πολλὰς δ’ εἶναι σημαίαις ἐπικειμένας. καὶ πεισθεὶς μετέβαλέν τε τῆς γνώμης τὸ ἐπὶ τοιούτοις προβουλεῦσαν καὶ διὰ τοῦ μεγάλου πεδίου κελεύσας χωρεῖν τὸ στρατόπεδον αὐτὸς μετὰ Ἡρώδου τοῦ τετράρχου καὶ τῶν φίλων εἰς Ἱεροσόλυμα ἀνῄει θύσων τῷ θεῷ ἑορτῆς πατρίου τοῖς Ἰουδαίοις ἐνεστηκυίας. εἰς ἣν ἀπαντήσας καὶ δεχθεὶς ὑπὸ τοῦ τῶν Ἰουδαίων πλήθους ἐκπρεπῶς τρεῖς μὲν ἡμέρας ταύτῃ διατριβὴν ποιεῖται, ἐν αἷς Ἰωνάθην τὴν ἱερωσύνην ἀφελόμενος ἐγχειρίζει τῷ ἀδελφῷ αὐτοῦ Θεοφίλῳ, τῇ τετάρτῃ δὲ γραμμάτων αὐτῷ παραγενομένων, ἃ ἐδήλου τὴν Τιβερίου τελευτήν, ὥρκισεν τὴν πληθὺν ἐπ’ εὐνοίᾳ τῇ Γαΐου. ἀνεκάλει δὲ καὶ τὸ στράτευμα ἐπὶ τὰ οἰκεῖα ἑκάστου χειμαδιᾶν πόλεμον ἐκφέρειν οὐκέθ’ ὁμοίως δυνάμενος διὰ τὸ εἰς Γάιον μεταπεπτωκέναι τὰ πράγματα. ἐλέγετο δὲ καὶ τὸν Ἀρέταν οἰωνοσκοπησάμενον πρὸς τὴν ἀγγελίαν τῶν Οὐιτελλίου στρατιωτῶν φάναι μηχανὴν οὐκ εἶναι τῷ στρατῷ τῆς ἐπὶ Πετραίους ὁδοῦ· τεθνήξεσθαι γὰρ τῶν ἡγεμόνων ἢ τὸν πολεμεῖν κελεύσαντα ἢ τὸν γνώμῃ τῇ ἐκείνου ὡρμημένον διακονεῖσθαι ἢ ἐφ’ ὃν γένοιτο ἡ παρασκευὴ τοῦ στρατεύματος. καὶ Οὐιτέλλιος μὲν ἐπ’ Ἀντιοχείας ἀνεχώρησεν. Ἀγρίππας δὲ ὁ Ἀριστοβούλου υἱὸς ἐνιαυτῷ πρότερον ἢ τελευτῆσαι Τιβέριον ἐπὶ Ῥώμης ἄνεισι πράξων τι παρὰ τῷ αὐτοκράτορι δυνάμεώς τινος αὐτῷ παραγενομένης. βούλομαι οὖν εἰπεῖν ἐπὶ μακρότερον περί τε Ἡρώδου καὶ γένους αὐτοῦ ὡς ἐγένετο, ἅμα μὲν καὶ διὰ τὸ ἀνήκειν τῇ ἱστορίᾳ τὸν περὶ αὐτῶν λόγον, ἅμα δὲ καὶ παράστασιν ἔχειν τοῦ θείου, ὡς οὐδὲν ὠφελεῖ πλῆθος οὐδ’ ἄλλη τις ἀλκὴ τῶν ἐν ἀνθρώποις ἐπιτετευγμένων δίχα τῶν πρὸς τὸ θεῖον εὐσεβειῶν, εἴ γε ἐντὸς ἑκατὸν ἐτῶν ἐξόδου συνέβη πλὴν ὀλίγων, πολλοὶ δ’ ἦσαν, διαφθαρῆναι τοὺς Ἡρώδου ἀπογόνους· φέροι δ’ ἄν τι κἀπὶ σωφρονισμῷ τοῦ ἀνθρωπείου γένους τὸ τὴν δυστυχίαν αὐτῶν μαθεῖν, ἅμα δὲ καὶ τὸν Ἀγρίππαν διηγήσασθαι θαύματος ἀξιώτατον γεγενημένον, ὃς ἐκ πάνυ ἰδιώτου καὶ παρὰ πᾶσαν δόξαν τῶν εἰδότων αὐτὸν ἐπὶ τοσόνδε ηὐξήθη δυνάμεως. εἴρηται μὲν οὖν μοι καὶ πρότερον περὶ αὐτῶν, λεχθήσεται δὲ καὶ νῦν ἀκριβῶς.", "st": "18.5.3"}, {"sp": "N", "t": "Ἡρώδῃ τῷ μεγάλῳ θυγατέρες ἐκ Μαριάμμης τῆς Ὑρκανοῦ θυγατρὸς γίνονται δύο, Σαλαμψιὼ μὲν ἡ ἑτέρα, ἣ γαμεῖται Φασαήλῳ τῷ αὐτῆς ἀνεψιῷ Φασαήλου παιδὶ ὄντι τοῦ Ἡρώδου ἀδελφοῦ δεδωκότος τοῦ πατρὸς αὐτήν, Κύπρος δὲ Ἀντιπάτρῳ καὶ αὐτὴ ἀνεψιῷ Ἡρώδου παιδὶ τῆς ἀδελφῆς Σαλώμης. καὶ Φασαήλῳ μὲν ἐκ Σαλαμψιοῦς γίνονται πέντε παῖδες Ἀντίπατρος Ἀλέξανδρος Ἡρώδης θυγατέρες τε Ἀλεξάνδρα καὶ Κύπρος, ἣν Ἀγρίππας γαμεῖ ὁ Ἀριστοβούλου. Ἀλεξάνδραν δὲ γαμεῖ μὲν Τίμιος Κύπριος ἀνὴρ τῶν ἀξιολόγων, παρ’ ᾧ δὴ ἄτεκνος τελευτᾷ. Κύπρῳ δ’ ἐξ Ἀγρίππου μὲν ἄρρενες γίνονται δύο, θυγατέρες δὲ τρεῖς Βερενίκη Μαριάμμη Δρούσιλλα, Ἀγρίππας δὲ καὶ Δροῦσος τοῖς ἄρσεσιν ὀνόματα, ὧν ὁ Δροῦσος πρὶν ἡβῆσαι τελευτᾷ. τῷ δὲ πατρὶ τούτων Ἀγρίππας ἐτρέφετο μετὰ καὶ ἑτέρων ἀδελφῶν Ἡρώδης καὶ Ἀριστόβουλος· καὶ Βερενίκη καὶ οἵδε παῖδες Ἡρώδου τοῦ υἱέος τοῦ μεγάλου· ἡ δὲ Βερενίκη Κοστοβάρου καὶ Σαλώμης παῖς τῆς Ἡρώδου ἀδελφῆς. τούτους Ἀριστόβουλος νηπίους λείπεται θνήσκων ὑπὸ τοῦ πατρὸς σὺν Ἀλεξάνδρῷ τῷ ἀδελφῷ, καθὰ προειρήκαμεν. ἡβήσαντες δ’ ἄγονται Ἡρώδης μὲν οὗτος ὁ τοῦ Ἀγρίππου ἀδελφὸς Μαριάμμην θυγατέρα Ὀλυμπιάδος τῆς Ἡρώδου βασιλέως θυγατρὸς καὶ Ἰωσήπου τοῦ Ἰωσήπου, ἀδελφὸς δὲ οὗτος Ἡρώδου τοῦ βασιλέως· ἴσχει τε ἐξ αὐτῆς υἱὸν Ἀριστόβουλον. ὁ δὲ τρίτος τοῦ Ἀγρίππου ἀδελφὸς Ἀριστόβουλος γαμεῖ Ἰωτάπην Σαμψιγεράμου θυγατέρα τοῦ Ἐμεσῶν βασιλέως, θυγάτηρ τε αὐτοῖς γίνεται κωφή· ὄνομα καὶ τῇδε Ἰωτάπη. καὶ τάδε μὲν τῶν ἀρσένων τέκνα. Ἡρωδιὰς δὲ αὐτῶν ἡ ἀδελφὴ γίνεται Ἡρώδῃ Ἡρώδου τοῦ μεγάλου παιδὶ γεγονότι ἐκ Μαριάμμης τῆς τοῦ Σίμωνος τοῦ ἀρχιερέως, καὶ αὐτοῖς Σαλώμη γίνεται, μεθ’ ἧς τὰς γονὰς Ἡρωδιὰς ἐπὶ συγχύσει φρονήσασα τῶν πατρίων Ἡρώδῃ γαμεῖται τοῦ ἀνδρὸς τῷ ὁμοπατρίῳ ἀδελφῷ διαστᾶσα ζῶντος. τὴν δὲ Γαλιλαίων τετραρχίαν οὗτος εἶχεν. ἡ δὲ θυγάτηρ αὐτῆς Σαλώμη Φιλίππῳ γαμεῖται Ἡρώδου παιδὶ τῷ τετράρχῃ τῆς Τραχωνίτιδος, καὶ ἄπαιδος τελευτήσαντος Ἀριστόβουλος αὐτὴν ἄγεται Ἡρώδου παῖς τοῦ Ἀγρίππου ἀδελφοῦ. παῖδες δὲ ἐγένοντο αὐτοῖς τρεῖς Ἡρώδης Ἀγρίππας Ἀριστόβουλος. τοῦτο μὲν δὴ τὸ Φασαήλου καὶ Σαλαμψιοῦς ἐστι γένος. Κύπρῳ δ’ ἐξ Ἀντιπάτρου θυγάτηρ γίνεται Κύπρος, καὶ αὐτὴν Ἀλεξᾶς ὁ Ἐλκίας γαμεῖ τοῦ Ἀλεξᾶ, καὶ αὐτῆς θυγάτηρ ἦν Κύπρος. Ἡρώδης δὲ καὶ Ἀλέξανδρος, οὓς ἀδελφοὺς ἔφην Ἀντιπάτρου, ἄτεκνοι τελευτῶσιν. Ἀλεξάνδρῳ δὲ τῷ Ἡρώδου παιδὶ τοῦ βασιλέως τῷ ὑπὸ τοῦ πατρὸς ἀνῃρημένῳ Ἀλέξανδρος καὶ Τιγράνης ἐγεγόνεισαν υἱεῖς ἐκ τῆς Ἀρχελάου τοῦ Καππαδόκων βασιλέως θυγατρός. καὶ Τιγράνης μὲν βασιλεύων Ἀρμενίας κατηγοριῶν αὐτοῦ ἐπὶ Ῥώμης γενομένων ἄπαις τελευτᾷ. Ἀλεξάνδρῳ δὲ Τιγράνης ὁμώνυμος τῷ ἀδελφῷ γίνεται παῖς καὶ βασιλεὺς Ἀρμενίας ὑπὸ Νέρωνος ἐκπέμπεται υἱός τε Ἀλέξανδρος αὐτῷ γίνεται. γαμεῖ δ’ οὗτος Ἀντιόχου τοῦ Κομμαγηνῶν βασιλέως θυγατέρα Ἰωτάπην, ἡσίοδός τε τῆς ἐν Κιλικίᾳ Οὐεσπασιανὸς αὐτὸν ἵσταται βασιλέα. καὶ τὸ μὲν Ἀλεξάνδρου γένος εὐθὺς ἅμα τῷ φυῆναι τὴν θεραπείαν ἐξέλιπεν τῶν Ἰουδαίοις ἐπιχωρίων μεταταξάμενοι πρὸς τὰ Ἕλλησι πάτρια· ταῖς δὲ λοιπαῖς θυγατράσιν Ἡρώδου τοῦ βασιλέως ἀτέκνοις τελευτᾶν συνέπεσεν. τῶν δὲ γενομένων Ἡρώδου ἀπογόνων οὓς κατέλεξα ἔμενον ἐν ᾧ χρόνῳ Ἀγρίππας ὁ μέγας τὴν βασιλείαν παρέλαβεν. τούτων δέ μοι τοῦ γένους προδεδηλωμένων διέξειμι λοιπόν, ὁπόσαι Ἀγρίππᾳ τύχαι συνέλθοιεν, ὥς τε αὐτῶν διάδρασιν ποιησάμενος ἐπὶ μέγιστον ἀξιώματός τε ἅμα προκόψειεν καὶ δυνάμεως.", "st": "18.5.4"}, {"sp": "N", "t": "Ἡρώδου τοῦ βασιλέως ὀλίγον πρὸ τῆς τελευτῆς Ἀγρίππας ἐν Ῥώμῃ διαιτώμενος καὶ ὁμοτροφίας καὶ συνηθείας αὐτῷ πολλῆς γενομένης πρὸς Δροῦσον τὸν Τιβερίου τοῦ αὐτοκράτορος υἱὸν καὶ Ἀντωνίᾳ τῇ Δρούσου τοῦ μεγάλου γυναικὶ εἰς φιλίαν ἀφίκετο, Βερενίκης τῆς μητρὸς τιμωμένης παρ’ αὐτῇ καὶ προαγωγῶν ἠξιωκυίας τὸν υἱόν. φύσει δὲ μέγας ὢν ὁ Ἀγρίππας καὶ δωρεῖσθαι πολυτελὴς ζώσης μὲν τῆς μητρὸς οὐκ ἐξέφαινε τῆς ψυχῆς τὸ θέλον διαδιδράσκειν αὐτῆς ἠξιωκὼς τὴν ἐπὶ τοῖς τοιούτοις γενομένην ὀργήν, ἐπεὶ δὲ Βερενίκη τελευτᾷ, γενόμενος ἐπὶ τῷ αὐτοῦ τρόπῳ, τὰ μὲν εἰς πολυτέλειαν τῆς καθ’ ἡμέραν διαίτης, τὰ δ’ εἰς τῶν δωρεῶν τὸ μὴ μέτρῳ προϊέμενον ἀνάλωσε τῶν χρημάτων, τὰ πλεῖστα δ’ εἰς τοὺς Καίσαρος ἀπελευθέρους ἐτετέλεστο ἐλπίδι πράξεως τῆς αὐτῶν, πενία τε ἐν ὀλίγῳ περὶ αὐτὸν ἦν. καὶ τοῦτο ἦν κώλυμα τῆς ἐν Ῥώμῃ διαίτης, καὶ ὁ Τιβέριος τοῖς φίλοις τοῦ υἱέος τετελευτηκότος ἀπειπὼν φοιτᾶν εἰς ὄψιν αὐτῷ, διὰ τὸ ἀνερεθίζεσθαι πρὸς τὸ λυπεῖσθαι μνημονεύων τοῦ παιδὸς θεωρίᾳ τῇ ἐκείνων.", "st": "18.6.1"}, {"sp": "N", "t": "Διὰ μὲν δὴ ταῦτα ἐπὶ τῆς Ἰουδαίας πλέων ᾤχετο κακοπραγῶν καὶ τεταπεινωμένος ὀλέθρῳ τε ὧν εἶχεν χρημάτων καὶ ἀπορίᾳ τοῦ ἐκτίσοντος τὰ χρέα τοῖς δανεισταῖς πολλοῖς τε οὖσιν καὶ ἀλεωρὰν οὐδ’ ἡντινοῦν ἐνδιδοῦσιν, ὥστε ἀπορίᾳ τῶν ποιητέων καὶ αἰσχύνῃ τῇ ἐπ’ αὐτοῖς ὑποχωρήσας εἴς τινα πύργον ἐν Μαλάθοις τῆς Ἰδουμαίας ἐν περινοίᾳ τοῦ μεταστήσοντος αὑτὸν ἦν. αἰσθάνεται δ’ αὐτοῦ τὴν διάνοιαν Κύπρος ἡ γυνὴ παντοία τε ἦν ἀπείργουσα τῶν ἐπὶ τοιούτοις βουλευμάτων. διαπέμπεται δὲ καὶ ὡς τὴν ἀδελφὴν αὐτοῦ Ἡρωδιάδα Ἡρώδῃ τῷ τετράρχῃ συνοικοῦσαν γράμματα, δηλοῦσα τό τε ἐπὶ τοιούτοις τοῦ Ἀγρίππα προβουλεῦσαν καὶ τὴν ἀνάγκην, ἣ ἐπ’ αὐτὰ ἐξήγαγεν· ἐκέλευέν τε συγγενῆ οὖσαν βοηθεῖν θεωροῦσαν, ὡς αὐτὴ παντοίως ὡς κουφίζοι τὸν ἄνδρα καὶ ταῦτα ἐξ ὁμοίων ἀφορμῶν. οἱ δὲ μεταπέμψαντες αὐτὸν οἰκητήριον ἀπέδειξαν Τιβεριάδα καί τι καὶ ἀργύριον ὥρισαν εἰς τὴν δίαιταν, ἀγορανομίᾳ τε τῆς Τιβεριάδος ἐτίμησαν. οὐ μὴν ἐπὶ πλεῖόν γε Ἡρώδης ἐνέμεινε τοῖς δεδογμένοις, καίτοι γε οὐδ’ ὣς ἀρκοῦντα ἦν· ἐν γὰρ Τύρῳ παρὰ συνουσίαν ὑπὸ οἴνου γενομένων αὐτοῖς λοιδοριῶν, ἀνεκτὸν οὐχ ἡγησάμενος Ἀγρίππας τοῦ Ἡρώδου τε ἐπονειδίσαντος εἰς ἀπορίαν καὶ τροφῆς ἀναγκαίας μετάδοσιν, ὡς Φλάκκον τὸν ὑπατικὸν εἴσεισιν φίλον ἐπὶ Ῥώμης τὰ μάλιστα αὐτῷ γεγονότα πρότερον· Συρίαν δὲ ἐν τῷ τότε διεῖπεν.", "st": "18.6.2"}, {"sp": "N", "t": "Καὶ δεξαμένου Φλάκκου παρὰ τούτῳ διῆγεν παρακατεσχηκότος αὐτὸν ἐκεῖ Ἀριστοβούλου, ὃς ἀδελφὸς ὢν Ἀγρίππου διάφορός τ’ ἦν. οὐ μὴν ἐβλάπτοντο ἔχθρᾳ τῇ ἀλλήλων, ὥστε μὴ φιλίᾳ τοῦ ὑπατικοῦ τὰ εἰκότα τιμὴν φέρεσθαι. οὐ μὴν ὅ γε Ἀριστόβουλος ἀνίει τι τοῦ πρὸς τὸν Ἀγρίππαν δυσμενοῦς μέχρι καὶ εἰς ἔχθραν αὐτὸν Φλάκκῳ καθίστησιν, αἰτίαν τοιαύτην ἐπὶ τῇ δυσμενείᾳ παραλαβών. Δαμασκηνοὶ Σιδωνίοις περὶ ὅρων διάφοροι καθεστῶτες, μέλλοντος Φλάκκου περὶ τούτων ἀκροᾶσθαι μαθόντες τὸν Ἀγρίππαν ὡς παρ’ αὐτῷ μέγα δύναιτ’ ἂν ἠξίουν μερίδος τῆς αὐτῶν γενέσθαι, ἀργύριόν τε πλεῖστον ὡμολογεῖτο αὐτῷ. καὶ ὁ μὲν πάντα ἐπὶ τῇ βοηθείᾳ τῶν Δαμασκηνῶν ὥρμητο πράσσειν. Ἀριστόβουλος δέ, οὐ γὰρ ἐλάνθανεν αὐτὸν ἡ ὁμολογία τῶν χρημάτων, καταγορεύει πρὸς τὸν Φλάκκον. καὶ βασανιζομένου τοῦ πράγματος ἐπεὶ φανερὰ ἦν, ἐξωθεῖ τὸν Ἀγρίππαν φιλίας τῆς πρὸς αὐτόν. ὁ δὲ εἰς ὑστάτην περιωσμένος ἀπορίαν εἰς Πτολεμαΐδα παρῆν, καὶ κατὰ τὸ ἄπορον τῆς ἀλλαχόθι διαίτης γνώμην ἐποιεῖτο ἐπὶ τῆς Ἰταλίας πλεῖν. εἰργόμενος δὲ χρημάτων ἀπορίᾳ ἠξίου Μαρσύαν ὄντα αὐτοῦ ἀπελεύθερον ποριστὴν γενέσθαι τῶν ἐπὶ τοιούτοις μηχανῶν δανεισάμενον παρά τινος. καὶ ὁ Μαρσύας Πρῶτον κελεύει Βερενίκης ὄντα ἀπελεύθερον τῆς Ἀγρίππου μητρός, διαθήκης δὲ τῆς ἐκείνου δικαίῳ ὑποτελοῦντα τῆς Ἀντωνίας, αὐτῷ γοῦν παρασχεῖν ἐπὶ γράμματι καὶ πίστει τῇ αὐτοῦ. ὁ δέ, ἐπεκάλει γὰρ τῷ Ἀγρίππᾳ χρημάτων τινῶν ἀποστέρησιν, ἀναγκάζει τὸν Μαρσύαν δύο μυριάδων Ἀτθίδων συμβόλαιον ποιησάμενον πεντακοσίαις καὶ δισχιλίαις ἔλασσον λαμβάνειν. συνεχώρει δ’ ἐκεῖνος κατὰ τὸ μὴ εἶναι ἄλλως ποιεῖν. εἰλημμένου δὲ τοῦ χρήματος τούτου Ἀγρίππας εἰς Ἀνθηδόνα παραγενόμενος καὶ λαβὼν ναῦν ἐν ἀναγωγαῖς ἦν. καὶ γνοὺς Ἐρέννιος Καπίτων ὁ τῆς Ἰαμνείας ἐπίτροπος πέμπει στρατιώτας, οἳ εἰσπράξονται αὐτὸν ἀργυρίου τριάκοντα μυριάδας θησαυρῷ τῷ Καίσαρος ὀφειλομένας ἐπὶ Ῥώμης ὑπ’ αὐτοῦ, ἀνάγκας τε ἐπετίθεσαν τοῦ μενοῦντος. καὶ τότε μὲν πείσεσθαι τοῖς κεκελευσμένοις προσποιητὸς ἦν, νυκτὸς δ’ ἐπιγενομένης κόψας τὰ ἀπόγεια ᾤχετο ἐπ’ Ἀλεξανδρείας πλέων. ἔνθα Ἀλεξάνδρου δεῖται τοῦ ἀλαβάρχου μυριάδας εἴκοσι δάνειον αὐτῷ δοῦναι. ὁ δ’ ἐκείνῳ μὲν οὐκ ἂν ἔφη παρασχεῖν, Κύπρῳ δὲ οὐκ ἠρνεῖτο τήν τε φιλανδρίαν αὐτῆς καταπεπληγμένος καὶ τὴν λοιπὴν ἅπασαν ἀρετήν. ἡ δὲ ὑπισχνεῖτο, καὶ ὁ Ἀλέξανδρος πέντε τάλαντα αὐτοῖς ἐν τῇ Ἀλεξανδρείᾳ δοὺς τὸ λοιπὸν ἐν Δικαιαρχείᾳ γενομένοις παρέξειν ἐπηγγέλλετο, δεδιὼς τοῦ Ἀγρίππου τὸ εἰς τὰ ἀναλώματα ἕτοιμον. καὶ Κύπρος μὲν ἀπαλλάξασα τὸν ἄνδρα ἐπὶ τῆς Ἰταλίας πλευσούμενον αὐτὴ μετὰ τῶν τέκνων ἐπὶ Ἰουδαίας ἀνέζευξεν.", "st": "18.6.3"}, {"sp": "N", "t": "Ἀγρίππας δὲ εἰς Ποτιόλους παραβαλὼν ἐπιστολὴν ὡς Τιβέριον τὸν Καίσαρα γράφει διαιτώμενον ἐν Καπρέαις, παρουσίαν τε τὴν αὐτοῦ δηλῶν ἐπὶ θεραπείᾳ καὶ ὄψει τῇ ἐκείνου, καὶ ἀξιῶν ἔφεσιν αὐτῷ γενέσθαι εἰς Καπρέας παραβαλεῖν. Τιβέριος δὲ οὐδὲν ἐνδοιάσας τά τε ἄλλα αὐτῷ γράφει φιλανθρωπίᾳ χρώμενος, ἐκτίνει τε χάριν ἀποσημαίνων ἐπὶ τῷ σῶν ἐπανήκειν εἰς τὰς Καπρέας, ἐπεὶ δ’ ἀφικνεῖται μηδὲν ὑφελὼν τοῦ ἐν τοῖς γράμμασι προθύμου ἠσπάζετό τε καὶ ἐξένιζεν. τῇ δ’ ἑξῆς Καίσαρι γραμμάτων αὐτῷ παρὰ Ἐρεννίου Καπίτωνος ἀφικομένων, ὅτι Ἀγρίππας μυριάδας τριάκοντα δάνεισμα ποιήσας καὶ πρὸς τὰς καταβολὰς ἐκλιπὼν χρόνον τὸν συγκείμενον ἀπαιτήσεως γενομένης οἴχοιτο φυγὰς ἐκ τῶν ὑπ’ αὐτῷ χωρίων ἄκυρον αὐτὸν καθιστὰς τῆς ἐπὶ τῷ εἰσπραξομένῳ ἐξουσίας, ταύτην ἀναγνοὺς τὴν ἐπιστολὴν περιαλγεῖ τε ὁ Καῖσαρ καὶ διάκλεισιν γενέσθαι τῷ Ἀγρίππᾳ κελεύει εἰσόδων τῶν πρὸς αὐτὸν ἄχρι δὴ καταβολῆς τοῦ χρέους. ὁ δὲ μηδὲν τῇ ὀργῇ τοῦ Καίσαρος καταπλαγεὶς Ἀντωνίας δεῖται Γερμανικοῦ μητρὸς καὶ Κλαυδίου τοῦ ὕστερον γενομένου Καίσαρος, δάνεισμα αὐτῷ δοθῆναι τῶν τριάκοντα μυριάδων, ὡς φιλίας μὴ ἁμάρτοι τῆς πρὸς Τιβέριον. ἡ δὲ Βερενίκης τε μνήμῃ τῆς μητρὸς αὐτοῦ, σφόδρα γὰρ ἀλλήλαις ἐχρῶντο αἵδε αἱ γυναῖκες, καὶ αὐτῷ ὁμοτροφίας πρὸς τοὺς ἀμφὶ Κλαύδιον γεγενημένης, δίδωσι τὸ ἀργύριον, καὶ αὐτῷ ἀποτίσαντι τὸ χρέος ἀνεπικώλυτος ἦν ἡ φιλία τοῦ Τιβερίου. αὖθις δὲ αὐτῷ Τιβέριος ὁ Καῖσαρ συνίστησιν υἱωνὸν τὸν αὐτοῦ κελεύων τὰ πάντα αὐτῷ ταῖς ἐξόδοις παρατυγχάνειν. Ἀγρίππας δὲ φιλίᾳ δεχθεὶς ὑπὸ τῆς Ἀντωνίας κατὰ θεραπείαν τρέπεται τὴν Γαΐου υἱωνοῦ τε ὄντος αὐτῇ καὶ εὐνοίᾳ τοῦ πατρὸς εἰς τὰ πρῶτα τιμωμένου. καὶ γὰρ ἦν ἄλλος Σαμαρεὺς γένος Καίσαρος δὲ ἀπελεύθερος· παρὰ τούτου δάνεισμα μυριάδας ἑκατὸν εὑρόμενος τῇ τε Ἀντωνίᾳ καταβάλλει τὸ ὀφειληθὲν χρέος καὶ τῶν λοιπῶν τῷ ἀναλώματι θεραπεύων τὸν Γάιον μειζόνως ἐν ἀξιώματι ἦν παρ’ αὐτῷ.", "st": "18.6.4"}, {"sp": "N", "t": "Προϊούσης δὲ ἐπὶ μέγα τῷ Ἀγρίππᾳ τῆς πρὸς Γάιον φιλίας αἰωρουμένοις ποτὲ λόγος περὶ τοῦ Τιβερίου γίνεται, καὶ τοῦ Ἀγρίππου κατ’ εὐχὰς τραπομένου, μόνω δ’ ἤστην, ᾗ τάχος Τιβέριον ὑπεκστάντα τῆς ἀρχῆς Γαΐῳ παραχωρεῖν ἀξιωτέρῳ τὰ πάντα ὄντι, τούτων ἀκροᾶται τῶν λόγων Εὔτυχος, Ἀγρίππου δ’ ἦν ἀπελεύθερος ἡνίοχος, καὶ παραχρῆμα μὲν σιγῇ παρεδίδου. κλοπῆς δὲ ἱματίων αὐτῷ τοῦ Ἀγρίππου ἐπικαλουμένης, καὶ ἀκριβῶς δὲ ἐκεκλόφει, φυγὼν καὶ ληφθεὶς ἀγωγῆς αὐτοῦ ἐπὶ Πείσωνα γενομένης, ὃς ἦν φύλαξ τῆς πόλεως, ἐρομένου τὴν αἰτίαν τῆς φυγῆς Καίσαρί φησιν ἀπορρήτους ἔχειν λόγους εἰπεῖν ἐπ’ ἀσφαλείᾳ τῆς σωτηρίας αὐτοῦ φέροντας, ὥστε δήσας αὐτὸν ἔστελλεν εἰς τὰς Καπρέας, καὶ Τιβέριος τῷ αὑτοῦ τρόπῳ χρώμενος εἶχεν αὐτὸν δέσμιον, μελλητὴς εἰ καί τις ἕτερος βασιλέων ἢ τυράννων γενόμενος. οὔτε γὰρ πρεσβειῶν ὑποδοχὰς ἐκ τοῦ ὀξέος ἐποιεῖτο ἡγεμόσι τε ἢ ἐπιτρόποις ὑπ’ αὐτοῦ σταλεῖσιν οὐδεμία ἦν διαδοχή, ὁπότε μὴ φθαῖεν τετελευτηκότες· ὅθεν καὶ δεσμωτῶν ἀκροάσεως ἀπερίοπτος ἦν. ὥστε καὶ τῶν φίλων ἐρομένων τὴν αἰτίαν τοῦ ἐπὶ τοιούτοις ὁλκῇ χρωμένου, ἔφη τὰς μὲν πρεσβείας τρίβειν, ὅπως μὴ ἀπαλλαγῆς αὐταῖς ἐκ τοῦ ὀξέος γενομένης ἕτεροι πρέσβεις ἐπιχειροτονηθέντες ἐπανίοιεν ὄχλος τε αὐτῷ γίγνοιτο ἐπιδοχαῖς αὐτῶν καὶ πομπαῖς προσκειμένῳ. τὰς δ’ ἀρχὰς συγχωρεῖν τοῖς ἅπαξ εἰς αὐτὰς ὑπ’ αὐτοῦ καταστᾶσιν αἰδοῦς προμηθείᾳ τῶν ὑποτελῶν· φύσει μὲν γὰρ εἶναι πᾶσαν ἡγεμονίαν οἰκείαν τοῦ πλεονεκτεῖν· τὰς δὲ μὴ πατρίους, ἀλλ’ εἰς ὀλίγον καὶ ἄδηλον ὁπότε ἀφαιρεθεῖεν καὶ μειζόνως ἐξοτρύνειν ἐπὶ κλοπαῖς τοὺς ἔχοντας. εἰ μὲν οὖν ἐφεστήκασιν εἰς πλέον, αὐτοὺς ἄδην τῶν κλοπῶν ἕξειν ὑπὸ τοῦ πολλοῦ τῶν κεκερδημένων ἀμβλυτέρως τὸ λοιπὸν αὐταῖς χρωμένους. διαδοχῆς δ’ ἐπιπαραγενομένης ἐκ τοῦ ὀξέος μηδαμῶς ἂν ἀρκέσαι τοὺς ἆθλα τοῖς ἄρχουσι προκειμένους ἀναστροφῆς αὐτοῖς οὐ διδομένης καιρῶν, ἐν οἷς πλήρεις οἱ προειληφότες γενόμενοι ὑποδιδοῖέν τε σπουδῆς τῆς ἐπὶ τῷ λαμβάνειν, διὰ τὸ πρὶν ἐν καιρῷ γενέσθαι μεταστῆναι. παράδειγμά τε αὐτοῖς φησι τοῦτον τὸν λόγον· τραυματίᾳ τινὶ κειμένῳ μυῖαι κατὰ πλῆθος τὰς ὠτειλὰς περιέστασαν. καί τις τῶν παρατυχόντων οἰκτείρας αὐτοῦ τὴν δυστυχίαν καὶ νομίσας ἀδυναμίᾳ μὴ βοηθεῖν οἷός τ’ ἦν ἀποσοβεῖν αὐτὰς παραστάς. καὶ δεομένου παύσασθαι τῶν ἐπὶ τοιοῖσδε, ὑπολαβὼν ἤρετο τὴν αἰτίαν τοῦ ἀπρομηθοῦς εἰς τὴν διαφυγὴν κακοῦ τοῦ ἐφεστηκότος. μειζόνως γὰρ ἂν ἀδικοῖς με, εἶπε, ταύτας ἀπαγαγών. ταῖς μέν γε ἤδη πληρωθείσαις τοῦ αἵματος οὐκέθ’ ὁμοίως ἔπειξις ὄχλον μοι παρασχεῖν, ἀλλά πῃ καὶ ἀνίσχουσιν. αἱ δ’ ἀκραιφνεῖ τῷ κατ’ αὐτὰς λιμῷ συνελθοῦσαι καὶ τετρυμένον ἤδη παραλαμβάνουσαι κἂν ὀλέθρῳ παραδοῖεν. διὰ τάδε οὖν καὐτὸς ὑπὸ πολλῶν τῶν κλοπῶν διεφθαρμένοις τοῖς ὑποτελέσιν προμηθὲς εἶναι μὴ συνεχὲς ἐξαποστέλλειν τοὺς ἡγησομένους, οἳ ἐν τρόπῳ μυιῶν ἐκπολεμοῖεν αὐτούς, φύσει πρὸς κέρδος ὀρωρεγμένοις σύμμαχον παραλαμβάνοντες τὴν ἐλπίδα τοῦ ταχέως ἀφαιρεθησομένου τὴν ἐνθένδε ἡδονήν. μαρτυρήσει δέ μου τῷ λόγῳ περὶ τῆς ἐπὶ τοιούτοις φύσεως Τιβερίου τὸ ἔργον αὐτό· ἔτη γὰρ δύο πρὸς τοῖς εἴκοσιν αὐτοκράτωρ γενόμενος δύο τοὺς πάντας Ἰουδαίοις ἐξέπεμψεν διοικήσοντας τὸ ἔθνος, Γρᾶτον τε καὶ Πιλᾶτον, ὃς αὐτῷ διεδέξατο τὴν ἡγεμονίαν. καὶ οὐκ ἐπὶ μὲν Ἰουδαίων τοιοῦτος ἦν, ἑτεροῖος δὲ ἐπὶ τῶν λοιπῶν ὑπηκόων. ἀλλὰ καὶ τῶν δεσμωτῶν τὴν ὑπερβολὴν τῆς ἀκροάσεως ἀπεσήμαινεν ὑπὸ τοῦ δικαιωθεῖσι μὲν θανάτῳ κούφισιν γενέσθαι τῶν ἐνεστηκότων κακῶν, διὰ τὸ μὴ ἐπ’ ἀρετῇ τῶν ἐπὶ τοιούτοις τύχῃ συνελθεῖν, τριβομένοις δὲ ἀχθηδόνι τῇ ἐπικειμένῃ μείζονα προσρέπειν τὴν δυστυχίαν.", "st": "18.6.5"}, {"sp": "N", "t": "Διὰ μὲν δὴ τάδε καὶ Εὔτυχος ἀκροάσεώς τε οὐκ ἐτύγχανε· καὶ δεσμοῖς ἐνείχετο. χρόνου δὲ ἐγγενομένου Τιβέριός τε ἐκ τῶν Καπρεῶν εἰς Τουσκουλανὸν παραγίνεται ὅσον ἀπὸ σταδίων ἑκατὸν τῆς Ῥώμης, καὶ ὁ Ἀγρίππας ἀξιοῖ τὴν Ἀντωνίαν διαπράξασθαι γενέσθαι τῷ Εὐτύχῳ τὴν ἀκρόασιν ἐφ’ οἷστισι τὴν κατηγορίαν ποιοῖτο αὐτοῦ. τιμία δὲ ἦν Ἀντωνία Τιβερίῳ εἰς τὰ πάντα συγγενείας τε ἀξιώματι, Δρούσου γὰρ ἦν ἀδελφοῦ αὐτοῦ γυνή, καὶ ἀρετῇ τοῦ σώφρονος· νέα γὰρ χηρεύειν παρέμεινεν γάμῳ τε ἀπεῖπεν τῷ πρὸς ἕτερον καίπερ τοῦ Σεβαστοῦ κελεύοντός τινι γαμεῖσθαι, καὶ λοιδοριῶν ἀπηλλαγμένον διεσώσατο αὐτῆς τὸν βίον. ἰδίᾳ τε εὐεργέτις ἦν εἰς τὰ μέγιστα τοῦ Τιβερίου· ἐπιβουλῆς γὰρ μεγάλης συστάσης ἐπ’ αὐτὸν ὑπὸ Σηιάνου φίλου τε ἀνδρὸς καὶ δύναμιν ἐν τῷ τότε μεγίστην ἔχοντος διὰ τὸ τῶν στρατευμάτων εἶναι ἡγεμονίαν αὐτῷ, καὶ τῆς τε βουλῆς οἱ πολλοὶ καὶ τῶν ἀπελευθέρων προσέθεντο καὶ τὸ στρατιωτικὸν διέφθαρτο, προυκοπτέν τε ἡ ἐπιβουλὴ ἐπὶ μέγα κἂν ἐπέπρακτο Σηιάνῳ τὸ ἔργον μὴ τῆς Ἀντωνίας τόλμῃ χρησαμένης σοφωτέρᾳ τῆς Σηιάνου κακουργίας. ἐπεὶ γὰρ μανθάνει τὰ ἐπὶ τῷ Τιβερίῳ συντεθειμένα, γράφει πρὸς αὐτὸν τὰ πάντα ἀκριβῶς καὶ Πάλλαντι ἐπιδοῦσα τὰ γράμματα τῷ πιστοτάτῳ τῶν δούλων αὐτῆς ἐκπέμπει πρὸς Τιβέριον εἰς τὰς Καπρέας. ὁ δὲ μαθὼν τόν τε Σηιᾶνον κτείνει καὶ τοὺς συνεπιβούλους, τήν τε Ἀντωνίαν καὶ πρὶν ἀξιολόγως ἄγων τιμιωτέραν τε ὑπελάμβανεν κἀπὶ τοῖς πᾶσι πιθανήν. ὑπὸ δὴ ταύτης τῆς Ἀντωνίας ὁ Τιβέριος παρακαλούμενος ἐξετάσαι τὸν Εὔτυχον, ἀλλ’ εἰ μὲν καταψεύσειε, φησὶν ὁ Τιβέριος, [ἔτι δε] Ἀγρίππου τὰ εἰρημένα Εὔτυχος, ἀρκοῦσαν κομίζεται παρ’ αὐτοῦ τιμωρίαν, ἣν ἐπιτετίμηκα αὐτός· εἰ δὲ βασανιζομένου ἀληθῆ φανείη τὰ εἰρημένα, μήπου κολάζειν ποθῶν τὸν ἀπελεύθερον ἐπ’ αὐτὸν μᾶλλον καλοίη τὴν δίκην. καὶ ὁ Ἀγρίππας ταῦτα φαμένης πρὸς αὐτὸν Ἀντωνίας πολλῷ μᾶλλον ἐπέκειτο ἀξιῶν ἐξέτασιν γενέσθαι τοῦ πράγματος, καὶ ἡ Ἀντωνία, οὐ γὰρ ἀνίει πολὺς ὢν ὁ Ἀγρίππας ἐπὶ τοῖσδε δεῖσθαι, καιρὸν παραλαβοῦσα τοιοῦτον· αἰωρεῖτο μὲν Τιβέριος ἐπὶ φορείου κείμενος, προϊόντων Γαΐου τε τοῦ ἐκείνης υἱωνοῦ καὶ Ἀγρίππα, ἀπ’ ἀρίστου δ’ ἦσαν, παραπεριπατοῦσα τῷ φορείῳ παρεκάλει καλεῖσθαί τε τὸν Εὔτυχον καὶ ἐξετάζεσθαι. ὁ δέ ἀλλ’ ἴστων μὲν Ἀντωνία, εἶπεν, οἱ θεοί, ὅτι μὴ τῇ ἐμαυτοῦ γνώμῃ ἀνάγκῃ δὲ τῆς σῆς παρακλήσεως ἐξαγόμενος πράξω τὰ πραξόμενα. ταῦτα εἰπὼν κελεύει Μάκρωνα, ὃς Σηιανοῦ διάδοχος ἦν, τὸν Εὔτυχον ἀγαγεῖν. καὶ ὁ μὲν οὐδὲν εἰς ἀναβολὰς παρῆν. Τιβέριος δ’ αὐτὸν ἤρετο, τί καὶ ἔχοι λέγειν κατ’ ἀνδρὸς ἐλευθερίαν αὐτῷ παρεσχηκότος. ὁ δέ φησιν, ὦ δέσποτα, αἰωροῦντο μὲν ἐφ’ ἁμάξης Γάιός τε οὗτος καὶ Ἀγρίππας σὺν αὐτῷ καί σφων ἑζόμην παρὰ τοῖν ποδοῖν, λόγων δὲ πολλῶν ἀνακυκλουμένων Ἀγρίππας φησὶ πρὸς Γάιον· εἰ γὰρ ἀφίκοιτό ποτε ἡμέρα, ᾗ μεταστὰς ὁ γέρων οὗτος χειροτονοίη σε ἡγεμόνα τῆς οἰκουμένης· οὐδὲν γὰρ ἡμῖν Τιβέριος ὁ υἱωνὸς αὐτοῦ γένοιτ’ ἂν ἐμποδὼν ὑπὸ σοῦ τελευτῶν, καὶ ἥ τε οἰκουμένη γένοιτ’ ἂν μακαρία κἀγὼ πρὸ αὐτῆς. Τιβέριος δὲ πιστὰ ἡγησάμενος τὰ εἰρημένα καὶ ἅμα μῆνιν ἀναφέρων τῷ Ἀγρίππᾳ παλαιάν, διότι κελεύσαντος αὐτοῦ θεραπεύειν Τιβέριον υἱωνόν τε αὐτοῦ γεγονότα καὶ Δρούσου παῖδα ὄντα, ὁ Ἀγρίππας ἀτίμως ἦγεν παρακροασάμενος τὰς ἐπιστολὰς καὶ πᾶς ὡς τὸν Γάιον μετεκάθιζεν, τοῦτον μὲν δή, φησί, Μάκρων, δῆσον. Μάκρων δὲ τὰ μὲν οὐ σαφῶς ὅντινα προστάξειεν ἐξεπιστάμενος, τὰ δὲ οὐκ ἂν προσδοκῶν περὶ τῷ Ἀγρίππᾳ αὐτὸν κελεῦσαί τι τοιοῦτον, ἐπανεῖχεν ἀκριβωσόμενος τὰ εἰρημένα. ἐπεὶ δ’ ὁ Καῖσαρ περιοδεύσας τὸν ἱππόδρομον λαμβάνει τὸν Ἀγρίππαν ἑστηκότα, καὶ μὴν δή, φησίν, Μάκρων, τοῦτον εἶπον δεθῆναι. τοῦ δὲ ἐπανερομένου ὅντινα, Ἀγρίππαν γε εἶπεν. καὶ ὁ Ἀγρίππας τρέπεται μὲν κατὰ δεήσεις, τοῦ τε παιδὸς ᾧ συνετέθραπτο μνημονεύων καὶ τοῦ Τιβερίου τῆς ἐκτροφῆς, οὐ μὴν ἤνυέν γέ τι, ἀλλ’ ἦγον αὐτὸν ἐν πορφυρίσι δέσμιον. καὶ καῦμά τε γὰρ σφοδρὸν ἦν καὶ ὑπὸ οἴνου τοῦ ἐπὶ σιτίοις μὴ πολλοῦ γεγονότος δίψος ἐξέκαιεν αὐτόν, καί τι καὶ ἠγωνία καὶ τὸ παρ’ ἀξίαν προσελάμβανεν, θεασάμενός τινα τῶν Γαΐου παίδων Θαυμαστὸν ὄνομα ὕδωρ ἐν ἀγγείῳ κομίζοντα ᾔτησε πιεῖν. καὶ ὀρέξαντος προθύμως πιών, ἀλλ’ εἴπερ ἐπ’ ἀγαθοῖς, φησίν, ὦ παῖ, τὰ τῆσδέ σου τῆς διακονίας γέγονεν, διαφυγῆς μοι γενομένης τῶνδε τῶν δεσμῶν οὐκ ἂν βραδύνοιμι ἐλευθερίαν εἰσπρασσόμενός σοι παρὰ Γαΐου, ὃς καὶ δεσμώτῃ μοι γενομένῳ διακονεῖσθαι καθάπερ ἐν τῷ πρότερον καθεστηκότι σχήματι τῆς περὶ ἐμὲ ἀξιώσεως οὐκ ἐνέλιπες. καὶ οὐκ ἐψεύσατο [ταῦτα εἰπών, ἀλλὰ δὴ ἠμείψατο]· ἐν ὑστέρῳ γὰρ βασιλεύσας τὸν Θαυμαστὸν μειζόνως ἐλεύθερόν τε ἀφῆκε παρὰ Γαΐου Καίσαρος γεγονότος λαβὼν καὶ τῆς οὐσίας ἐπίτροπον καθίστησι, τελευτῶν τε τῷ υἱεῖ Ἀγρίππᾳ καὶ Βερενίκῃ τῇ θυγατρὶ ἐπὶ τοῖς ὁμοίοις διακονησόμενον κατέλιπεν, ἐν τιμῇ τε ὢν ταύτῃ γηραιὸς τελευτᾷ. καὶ ταῦτα μὲν ὕστερον.", "st": "18.6.6"}, {"sp": "N", "t": "Ἀγρίππας δὲ τότε δεθεὶς εἱστήκει πρὸ τοῦ βασιλείου πρός τινι δένδρῳ κλιθεὶς ὑπὸ ἀθυμίας μετὰ πολλῶν οἳ ἐδέδεντο. καί τινος ὀρνέου καθίσαντος ἐπὶ τοῦ δένδρου, ᾧ Ἀγρίππας προσεκέκλιτο, βουβῶνα δὲ οἱ Ῥωμαῖοι τὸν ὄρνιν τοῦτον καλοῦσιν, τῶν δεσμωτῶν τις Γερμανὸς θεασάμενος ἤρετο τὸν στρατιώτην, ὅστις εἴη ὁ ἐν τῇ πορφυρίδι. καὶ μαθὼν μὲν Ἀγρίππαν ὄνομα αὐτῷ, Ἰουδαῖον δὲ τὸ γένος καὶ τῶν ἐκείνῃ ἀξιολογωτάτων, ἠξίωσεν τὸν συνδεδεμένον αὐτῷ στρατιώτην πλησίον ἐλθεῖν διὰ λόγων· βούλεσθαι γάρ τινα ἀμφὶ τῶν πατρίων ἔρεσθαι αὐτόν. καὶ τυχών, ἐπεὶ πλησίον ἵσταται, δι’ ἑρμηνέως ὦ νεανία, φησίν, καταχθεῖ μέν σε τὸ αἰφνίδιον τῆς μεταβολῆς πολλήν τε οὕτως καὶ ἀθρόαν ἐπαγαγὸν τὴν τύχην, ἀπιστία δέ σοι λόγων, οἳ ἐπὶ διαφυγῇ κακοῦ τοῦ ἐφεστηκότος διαιροῖντο τοῦ θείου τὴν πρόνοιαν. ἴσθι γε μήν, θεοὺς τοὺς ἐμοὶ πατρῴους καὶ τοὺς τοῖσδε ἐγχωρίους, οἳ τόνδε ἐπρυτάνευσαν ἡμῖν τὸν σίδηρον, ἐπομνύμενος λέξω τὰ πάντα οὔτε ἡδονῇ γλωσσάργῳ διδοὺς τὸν ἐπ’ αὐτοῖς λόγον οὔτε διακενῆς εὐθυμεῖν σε ἐσπουδακώς. αἱ γὰρ ἐπὶ τοιοῖσδε προαγορεύσεις ὑστερηκότος τοῦ ἀποδείξοντος ἔργου χαλεπωτέραν προστίθενται τὴν ἀχθηδόνα τοῦ μηδ’ εἰ τὴν ἀρχὴν ἀκροάσαιτο αὐτῶν. ἀλλὰ καὶ τὸ ἐμὸν κινδύνοις παραβαλλόμενος δίκαιον ἡγησάμην σοι διασαφῆσαι τὴν προαγόρευσιν τῶν θεῶν. οὐκ ἔσθ’ ὅπως οὐκ εὐθέως ἀπαλλαγή τέ σοι τῶνδε τῶν δεσμῶν παρέσται καὶ πρόοδος ἐπὶ μήκιστον ἀξιώματός τε καὶ δυνάμεως, ζηλωτός τε ἂν γένοιο πᾶσιν, οἳ νῦν δι’ οἴκτου τὰς τύχας σου λαμβάνουσιν, εὐδαίμονά τε ἂν ποιοῖο τὴν τελευτὴν παισίν, οἷς ἔσῃ τὸν βίον καταλειπόμενος. μνημονεύειν δέ, ὁπότε εἰσαῦθις τὸν ὄρνιν θεάσαιο τοῦτον, πέντε ἡμέραις σοι τὴν τελευτὴν ἐσομένην. ταῦτα πεπράξεται μὲν ᾗπερ ἀποσημαίνει τοῦ θεοῦ τὸ ἐξαποστεῖλαν τουτονὶ τὸν ὄρνιν. προγνώσει τε αὐτῶν σύνεσιν τὴν παραγενομένην ἀποστερεῖν σε ἄδικον ἡγησάμην, ὅπως ἐπιστάμενος ἀγαθοῦ μέλλοντος λυσιτελεῖν ἐν ὀλίγῳ τὴν ἀχθηδόνα τοῦ παρόντος τιθοῖο. μνήμην δὲ ποιεῖσθαι εἰς χεῖράς σου παραγενομένου τοῦ εὐδαίμονος καὶ τοῦ καθ’ ἡμᾶς διαφευξομένου δυστυχίαν, ᾗ τανῦν σύνεσμεν. καὶ ὁ μὲν Γερμανὸς τοσάδε προειπὼν εἰς τοσόνδε ὦφλεν τῷ Ἀγρίππᾳ γέλωτα, ἐφ’ ὅσον ἐν τοῖς ὕστερον κατεφάνη τεθαυμάσθαι ἄξιος. ἡ δὲ Ἀντωνία χαλεπῶς φέρουσα τοῦ Ἀγρίππου τὴν δυστυχίαν τὸ μὲν Τιβερίῳ περὶ αὐτοῦ διαλέγεσθαι ἐργωδέστερον ἑώρα καὶ ἄλλως ἐπ’ ἀπράκτοις γενησόμενον, εὑρίσκετο δ’ αὐτῷ παρὰ τοῦ Μάκρωνος στρατιωτῶν τε μετρίων ἀνδρῶν οἳ παραφυλάξειαν αὐτὸν ἐν φροντίσιν καὶ ἑκατοντάρχου τοῦ ἐφεστηξομένου τε ἐκείνοις καὶ συνδέτου ἐσομένου, λουτρά τε καθ’ ἡμέραν συγκεχωρῆσθαι καὶ ἀπελευθέρων καὶ φίλων εἰσόδους τήν τε ἄλλην ῥᾳστώνην, ἣ τῷ σώματι γένοιτ’ ἄν. εἰσῄεσάν τε ὡς αὐτὸν φίλος τε Σίλας καὶ τῶν ἀπελευθέρων Μαρσύας καὶ Στοιχεὺς τροφὰς εἰσκομίζοντες αἷς ἔχαιρεν καὶ δι’ ἐπιμελείας πάσης ἔχοντες, ἱμάτιά τε κομίζοντες ἐπὶ προσποιήσει πράσεως ὁπότε νὺξ γένοιτο ὑπεστρώνυσαν αὐτῷ συμπράξει τῶν στρατιωτῶν Μάκρωνος προειρηκότος· καὶ ταῦτα ἐπράσσετο ἐπὶ μῆνας ἕξ. καὶ τὰ μὲν κατὰ Ἀγρίππαν ἐν τούτοις ἦν.", "st": "18.6.7"}, {"sp": "N", "t": "Τιβέριος δ’ ἐπανελθὼν εἰς τὰς Καπρέας ἐμαλακίζετο τὰ μὲν πρῶτα μετρίως, ἐπιδούσης δ’ εἰς τὸ μᾶλλον τῆς νόσου πονηρὰς ἔχων περὶ αὐτῷ τὰς ἐλπίδας Εὔοδον, ὃς ἦν αὐτῷ τιμιώτατος τῶν ἀπελευθέρων, κελεύει τὰ τέκνα προσαγαγεῖν πρὸς αὐτόν· χρῄζειν γὰρ ἀφικέσθαι σφίσι διὰ λόγων πρὶν ἢ τελευτᾶν. ἦσαν δ’ αὐτῷ παῖδες γνήσιοι μὲν οὐκέτι· Δροῦσος γὰρ δὴ ὁ μόνος αὐτῷ γεγονὼς ἐτύγχανεν τεθνεώς· υἱὸς δὲ τούτου κατελείπετο Τιβέριος ἐπικαλούμενος Γέμελλος, Γάιός τε Γερμανικοῦ παῖς, ἀδελφοῦ υἱὸς γεγονώς, νεανίας τε ἤδη καὶ παιδείαν ἐκπεπονηκὼς ἐπὶ πλεῖστον εὐνοίᾳ τε τοῦ δήμου τιμώμενος διὰ τὴν Γερμανικοῦ τοῦ πατρὸς ἀρετήν· ἐπὶ μέγιστον γὰρ δὴ οὗτος προῆλθεν παρὰ τοῖς πλήθεσι τιμῆς εὐσταθείᾳ τρόπου καὶ δεξιότητι τοῦ ὁμιλεῖν ἀνεπαχθὴς ὢν καὶ τὴν ἀξίωσιν κτώμενος τῷ βούλεσθαι ἴσος πᾶσιν εἶναι. ἐξ ὧν οὐ μόνον ὁ δῆμος καὶ ἡ βουλὴ μειζόνως ἦγον αὐτόν, ἀλλὰ καὶ τῶν ὑποτελῶν ἕκαστον ἐθνῶν, οἱ μὲν ὡμιληκότες ἁλισκόμενοι τῇ χάριτι τῆς ἐντεύξεως, οἱ δὲ πύστει τῆς ἐκείνων ἀφηγήσεως παραλαμβάνοντες. πένθος τε αὐτοῦ τελευτήσαντος προυτέθη πᾶσιν οὐ θεραπείᾳ τῆς ἀρχῆς ἐπιψευδομένων τὴν συμφοράν, λύπῃ δὲ ἀληθεῖ οἰκειουμένων διὰ τὸ ἴδιον τυχεῖν ἑκάστοις τὴν μετάστασιν αὐτοῦ ὑπειλῆφθαι· οὕτως ἀνεπαχθῶς ὡμίλησε τοῖς ἀνθρώποις. ἐξ ὧν μέγα ὄφελος καὶ τῷ παιδὶ αὐτοῦ παρὰ πᾶσιν κατελέλειπτο τοῖς τε ἄλλοις καὶ μάλιστα τὸ στρατιωτικὸν ἦρτο, ἀρετὴν ἀριθμοῦντες τὸ περὶ τῆς ἀρχῆς ἐκείνῳ περιγενησομένης, εἰ δεήσει, καὶ τελευτᾶν.", "st": "18.6.8"}, {"sp": "N", "t": "Ὁ δὲ Τιβέριος Εὐόδῳ πρόσταγμα ποιησάμενος κατὰ τὴν ὑστεραίαν ὑπὸ τὴν ἕω εἰσαγαγεῖν τοὺς παῖδας εὔχεται τοῖς πατρίοις θεοῖς σημεῖόν τι πρόφαντον αὐτῷ δεῖξαι περὶ τοῦ τὴν ἡγεμονίαν διαδεξομένου, σπεύδων μὲν τῷ υἱεῖ τοῦ παιδὸς αὐτὴν καταλιπεῖν, μεῖζον δὲ δόξης τε καὶ βουλήσεως τῆς αὐτοῦ πεπιστευκὼς τοῦ θεοῦ τὸ ἐπ’ αὐτοῖς ἀποφανούμενον. οἰώνισμα δ’ οὖν αὐτῷ προύκειτο, εἰς ἐκεῖνον ἥξειν τὴν ἡγεμονίαν, ὃς ἂν κατὰ τὴν ἐπιοῦσαν ἀφίκοιτο πρότερος πρὸς αὐτόν. ταῦτα διανοηθεὶς πέμπει παρὰ τοῦ υἱωνοῦ τὸν παιδαγωγὸν κελεύων ὑπὸ πρώτην ὥραν ἄγειν τὸν παῖδα ὡς αὐτόν, καταμελήσεσθαι στρατηγίας τὸν θεὸν ὑπολαμβάνων· ὁ δ’ ἀντεψήφιζεν αὐτοῦ τὴν χειροτονίαν. ὁ μὲν δὴ ταῦτ’ ἐνθυμησάμενος, ἐπεὶ τάχιστα ἡμέρα ἦν, κελεύει τὸν Εὔοδον εἰσκαλεῖν τῶν παίδων τὸν παρόντα πρότερον. ἐξελθὼν δ’ ἐκεῖνος καὶ τὸν Γάιον πρὸ τοῦ δωματίου καταλαβών, ὁ γὰρ Τιβέριος οὐ παρῆν μετεώρου τῆς τροφῆς αὐτῷ γενομένης, ᾔδει δὲ οὐδὲν ὧν ἐβούλετο ὁ δεσπότης, καλεῖ σε, φησίν, ὁ πατήρ, καὶ εἰσήγαγεν αὐτόν. Τιβέριος δὲ ὡς θεᾶται Γάιον, τότε πρῶτον εἰς ἐπίνοιαν ἐλθὼν τοῦ θείου τῆς ἐξουσίας καὶ τὴν κατ’ αὐτὸν ἡγεμονίαν παντελῶς ἀφῃρημένην ἐπικυροῦν οἷς ψηφίσαιτο δυνάμεως ἐκεῖθεν αὐτῷ μὴ παραγενομένης, πολλὰ δὴ κατολοφυράμενος αὑτὸν μὲν τοῦ ἐφ’ οἷς προβουλεύσειε κυροῦν ἀφῃρημένου τὸ κράτος, Τιβέριον δὲ τὸν υἱωνόν, ὡς τῆς τε Ῥωμαίων ἀρχῆς ὁμοῦ διαμάρτοι καὶ τῆς σωτηρίας κεχρημένον διὰ τὸ ἐπ’ ἄλλων κρειττόνων οὐκ ἀνεκτὸν εἰσηγησαμένω τὴν συναναστροφὴν κείσεσθαι τὴν σωτηρίαν αὐτῷ τοῦ συγγενοῦς μὴ ὠφελεῖν δυναμένου, φόβῳ τε καὶ μίσει τοῦ ἐφεστηκότος χρησομένου πρὸς αὐτόν, τὰ μὲν ὡς προσεδρεύοντα τῇ ἀρχῇ, τὰ δὲ ὡς ἀντεπιβουλεύειν ὑπέρ τε τῆς σωτηρίας καὶ τῆς ἀντιλήψεως τῶν πραγμάτων μὴ ἀφησόμενον. ἦν δὲ καὶ γενεθλιαλογίᾳ Τιβέριος μάλιστα προσκείμενος καὶ κατορθούμενα αὐτῇ μειζόνως τῶν εἰς τόδε ἀνακειμένων ἑκόντων τὸν βίον ἐξηγμένος. Γάλβαν οὖν ποτε θεασάμενος ὡς αὐτὸν εἰσιόντα φησὶ πρὸς τοὺς ἐπιτηδειοτάτους αὐτῷ, ὡς παραγίνοιτο ἀνὴρ τῇ Ῥωμαίων προτιμησόμενος ἡγεμονίᾳ. τά τε πάντα μαντειῶν ὁπόσα ἐχόμενα πιθανὰ ἡγούμενος ἡγεμόνων μάλιστα ἀνὴρ οὗτος ὑπὸ τοῦ ἐπαληθείοντος αὐτῶν ἐπὶ τοῖς πράγμασιν ἐχρῆτο αὐταῖς. καὶ τότε ἐν χαλεποῖς ἦν συντυχίᾳ τοῦ γεγονότος, ὡς ἐπ’ ἀπολωλότι τῷ υἱεῖ τοῦ παιδὸς ἀχθεινῶς διατιθέμενος καὶ κατάμεμψιν αὐτοῦ ποιούμενος τοῦ κατὰ τὴν οἰώνισιν προμηθοῦς· παρὸν γὰρ [ἂν] αὐτῷ λύπης ἀπηλλαγμένῳ τελευτᾶν ἀμαθίᾳ τῶν ἐσομένων, διατρίβεσθαι τῷ προεγνωκὼς τὴν ἐσομένην δυστυχίαν τῶν φιλτάτων τελευτᾶν. καίπερ δὲ συντεταραγμένος τῇ παρὰ δόξαν τῆς ἀρχῆς εἰς οὓς οὐκ ἤθελεν περιόδῳ, ἄκων δὲ καὶ μὴ βουλόμενος φησὶ γοῦν πρὸς τὸν Γάιον· ὦ παῖ, καίπερ μοι συγγενεστέρου Τιβερίου ἢ κατὰ σὲ ὄντος δόξῃ τε τῇ ἐμαυτοῦ καὶ τῷ ὁμοψήφῳ ἐπ’ αὐτῇ τῶν θεῶν σοὶ φέρων ἐγχειρίζω τὴν Ῥωμαίων ἡγεμονίαν. ἀξιῶ δέ σε μηδὲν ἀμνημονεῖν ὁμιλήσαντα αὐτῇ μήτ’ εὐνοίας τῆς ἐμῆς, ὃς εἰς τοσόνδε ἀξιώματος καθίστημι μέγεθος, μήτε τοῦ πρὸς Τιβέριον συγγενοῦς, ἀλλ’ ἐπιστάμενον, ὡς σύν τε τοῖς θεοῖς καὶ μετ’ αὐτοὺς τοιῶνδέ σοι κατασταίην ἀγαθῶν ποριστής, ἀμείβεσθαί μου τὸ ἐπ’ αὐτοῖς πρόθυμον καὶ ἅμα Τιβερίου φροντίζειν διὰ τὴν συγγένειαν, ἄλλως τε γινώσκειν, ὡς τεῖχός σοι καὶ τῆς ἀρχῆς ὁμοῦ καὶ τῆς σωτηρίας περιὼν γίνοιτο ἂν Τιβέριος, φροίμιον δὲ τοῦ δυστυχοῦς μεθιστάμενος. αἵ τε γὰρ μονώσεις ἐπικίνδυνοι τοῖς εἰς τηλικούτων πραγμάτων ὄγκον καταστᾶσιν καὶ θεοῖς οὐκ ἀτιμώρητα ὁπόσα παρὰ δίκην πρασσόμενα ἀφανίζοι τοῦ νόμου τὸ ἑτέρως πράσσειν παρακαλοῦν. ταῦτα μὲν ὁ Τιβέριος ἔλεγεν, οὐ μὴν πιθανὸς ἦν Γαΐῳ καίπερ ὑπισχνουμένῳ, ἀλλὰ καταστὰς εἰς τὴν ἀρχὴν τόν τε Τιβέριον μαντείαις ἀναιρεῖ ταῖς ἐκείνου καὐτὸς ἐπιβουλῶν ἐπ’ αὐτὸν συντεθεισῶν μετ’ οὐ πολὺ τελευτᾷ.", "st": "18.6.9"}, {"sp": "N", "t": "Τιβέριος δὲ τὸν Γάιον ἀποδείξας διάδοχον τῆς ἡγεμονίας ὀλίγας ἐπιβιοὺς ἡμέρας ἔθανεν σχὼν αὐτὸς τὴν ἀρχὴν ἡμέρας τρεῖς καὶ πέντε μῆνας πρὸς ἐνιαυτοῖν δυοῖν καὶ εἴκοσι. Γάιος δὲ ἦν αὐτοκράτωρ τέταρτος. Ῥωμαίοις δ’ ἦν μὲν πύστις τῆς Τιβερίου τελευτῆς εὐφραίνοντό τε τῷ ἀγαθῷ τῆς ἀγγελίας, οὐ μὴν πιστεύειν γε θάρσος ἦν αὐτοῖς, οὐ τῷ μὴ βούλεσθαι, πρὸ πολλῶν γὰρ ἂν ἐτίμησαν χρημάτων τὸ ἐπαληθεῦσαν τῶν λόγων, δέει δὲ μὴ ψευδοῦς τῆς ἀγγελίας γενομένης προεξαναστάντες ἐπὶ δηλώσει τοῦ αὐτῶν χάρματος εἶτ’ ἀπολλύοιντο διαβολῆς αὐτῶν γενομένης· πλεῖστα γὰρ ἀνὴρ εἷς οὗτος Ῥωμαίων τοὺς εὐπατρίδας εἰργάσατο δεινὰ δυσόργητος ἐπὶ πᾶσιν ὢν καὶ ἀνήκεστος εἰς τὸ ἐργάζεσθαι καταστάς, εἰ καὶ χωρὶς λόγου τὴν αἰτίαν ἐπανέλοιτο τοῦ μισεῖν, καὶ ἐπὶ πᾶσι μὲν οἷς κρίνοιεν ἐξαγριοῦν φύσιν ἔχων, εἰς θάνατον δὲ καὶ τῶν κουφοτάτων ἀνατιθεὶς τὴν ζημίαν. ὥστε ἡδονῇ τοῦ ἐπ’ αὐτῷ λόγου φέροντος τὴν ἀκρόασιν εἰς ὅσον ἐβούλοντο ἀπολαύσματι χρῆσθαι ἐπεκεκώλυντο δείμασι κακῶν, ἃ προεωρᾶτο ψευσθεῖσι τῆς ἐλπίδος. Μαρσύας δὲ τοῦ Ἀγρίππου ὁ ἀπελεύθερος πυθόμενος τοῦ Τιβερίου τὴν τελευτὴν ὠθεῖτο δρομαῖος τὸν Ἀγρίππαν εὐαγγελιούμενος, καὶ καταλαβὼν ἐν ἐξόδοις ὄντα εἰς τὸ βαλανεῖον συννεύσας πρὸς αὐτὸν γλώσσῃ τῇ Ἑβραίων τέθνηκεν ὁ λέων φησίν. ὁ δὲ σύνεσίν τε τοῦ λόγου ποιησάμενος καὶ χάρματι τῷ ἐπ’ αὐτῷ περιενεχθείς ἀλλά σοι τῶν ἁπάντων καὶ τῆς ἐπὶ τῷδε εὐαγγελίας χάριτες ἐν ἐμοὶ παντοῖαι γίνοιντο, μόνον ἀληθῆ τὰ λεγόμενα εἴη. καὶ ὁ ἑκατοντάρχης, ὅσπερ τῇ φυλακῇ ἐφειστήκει τοῦ Ἀγρίππου, θεώμενος τήν τε σπουδὴν μεθ’ οἵας ὁ Μαρσύας ἀφίκετο καὶ τὸ ἐκ τῶν λόγων χάρμα τῷ Ἀγρίππᾳ συνελθόν, ὑποτοπήσας καίνωσίν τινα γεγονέναι τῶν λόγων ἤρετό σφας περὶ τοῦ λόγου τοῦ ἐφεστηκότος. οἱ δὲ τέως μὲν παρέτρεπον, ἐγκειμένῳ δὲ ἀποσημαίνει ὁ Ἀγρίππας, ἤδη γὰρ φίλος ἦν, μηδὲν ἐνδοιάσας. ὁ δὲ ἐκοινοῦτό τε τὴν ἡδονὴν τοῦ λόγου διὰ τὸ εἰς ἀγαθὰ τῷ Ἀγρίππᾳ φέρειν προυτίθει τε αὐτῷ δεῖπνον. εὐωχουμένων δ’ αὐτῶν καὶ τοῦ πότου προϊόντος παρῆν τις λέγων ζῆν τε τὸν Τιβέριον καὶ ὀλίγων ἡμερῶν ἐπανήξειν εἰς τὴν πόλιν. καὶ ὁ ἑκατοντάρχης δεινῶς θορυβηθεὶς τῷ λόγῳ διὰ τὸ εἰς θάνατον ἀνακείμενα πεπραχέναι δεσμώτῃ τε καὶ ἐπ’ ἀγγελίᾳ θανάτου αὐτοκράτορος συνδιῃτῆσθαι μετὰ χάρματος, ἀπωθεῖταί τε τὸν Ἀγρίππαν τοῦ κλινιδίου καί ἦπου, φησίν, λήσειν με ὑπονοεῖς θάνατον τοῦ αὐτοκράτορος κατεψευσμένος, ἀλλ’ οὐ κεφαλῇ τῇ σῇ τοῦτον ἀναμαξόμενος τὸν λόγον; ταῦτα εἰπὼν κελεύει δῆσαι τὸν Ἀγρίππαν λελυκὼς πρότερον αὐτὸν φυλακήν τε ἀκριβεστέραν αὐτοῦ ἢ πρότερον καθίσταται. καὶ νύκτα μὲν ἐκείνην ὁ Ἀγρίππας ἐν τοιούτοις ἦν τοῖς κακοῖς. τῇ δὲ ὑστεραίᾳ λόγος τε πλείων ἦν κατὰ τὴν πόλιν ἰσχυριζόμενος ἐπὶ τῇ τελευτῇ τοῦ Τιβερίου, ἐθάρρουν τε οἱ ἄνθρωποι φανερῶς ἤδη θροεῖν καί τινες καὶ θυσίας ἐπετέλουν, ἐπιστολαί τε ἀφίκοντο παρὰ τοῦ Γαΐου, ἡ μὲν πρὸς τὴν σύγκλητον τοῦ Τιβερίου διασαφοῦσα τὴν τελευτὴν καὶ τὴν αὐτοῦ παράληψιν τῆς ἡγεμονίας γενομένην, ἡ δὲ πρὸς Πείσωνα τὸν φύλακα τῆς πόλεως τοῦτό τε ἀγορεύουσα, καὶ τὸν Ἀγρίππαν ἐκέλευεν ἐκ τοῦ στρατοπέδου μεταστῆσαι εἰς τὴν οἰκίαν, ἐν ᾗ πρότερον ἢ δεθῆναι δίαιταν εἶχεν. τότε ἐν θάρσει λοιπὸν ἦγεν τὰ περὶ αὐτῆς· φυλακὴ μὲν γὰρ καὶ τήρησις ἦν, μετὰ μέντοι ἀνέσεως τῆς εἰς τὴν δίαιταν. Γάιος δὲ ὡς ἐπὶ Ῥώμης παρῆν ἄγων τοῦ Τιβερίου τὸ σῶμα, ταφάς τε αὐτοῦ ποιεῖται πολυτελεῖς νόμοις τοῖς πατρίοις, Ἀγρίππαν τε αὐθημερὸν λύειν ὄντα πρόθυμον κώλυμα Ἀντωνία ἦν οὔ τι μίσει τῷ πρὸς τὸν δεδεμένον προμηθείᾳ δὲ τοῦ Γαΐου εὐπρεποῦς, μὴ δόξαν ἀπάγοιτο ἡδονῇ δεχομένου τὴν Τιβερίου τελευτὴν ἄνδρα ὑπ’ ἐκείνου δεδεμένον λύων ἐκ τοῦ ὀξέος. διελθουσῶν μέντοι οὐ πολλῶν ἡμερῶν μεταπεμψάμενος αὐτὸν εἰς τὸν οἶκον ἀποκείρει τε αὐτὸν καὶ μεταμφιέννυσιν, εἶτα δὲ τὸ διάδημα περιτίθησιν τῇ κεφαλῇ καὶ βασιλέα καθίστησιν αὐτὸν τῆς Φιλίππου τετραρχίας δωρησάμενος αὐτῷ καὶ τὴν Λυσανίου τετραρχίαν, ἀλλάττει τε σιδηρᾷ ἁλύσει χρυσῆν ἰσόσταθμον. ἱππάρχην δὲ ἐπὶ τῆς Ἰουδαίας ἐκπέμπει Μάρυλλον.", "st": "18.6.10"}, {"sp": "N", "t": "Δευτέρῳ δὲ ἔτει τῆς Γαΐου Καίσαρος ἡγεμονίας Ἀγρίππας ἠξίου συγχώρησιν αὐτῷ γενέσθαι πλεύσαντι τήν τε ἀρχὴν καταστήσασθαι καὶ τὰ ἄλλα εἰς δέον οἰκονομησαμένῳ ἐπανιέναι. καὶ συγχωροῦντος τοῦ αὐτοκράτορος παρῆν παρ’ ἐλπίδας τε ὤφθη πᾶσι βασιλεὺς πολλήν τε τῆς τύχης ἐπεδείκνυεν ἐπὶ τοῖς ἀνθρώποις τὴν ἐξουσίαν τοῖς θεωροῦσιν ἐκ λογισμῶν ἀπορίας τε τῆς πρότερον καὶ τοῦ ἐν τῷ παρόντι εὐδαίμονος. καὶ οἱ μὲν ἐμακάριζον τοῦ μὴ διαμαρτίᾳ χρησαμένου τῶν ἐλπίδων, οἱ δ’ ἐν ἀπιστίᾳ περὶ τῶν γεγονότων ἦσαν.", "st": "18.6.11"}, {"sp": "N", "t": "Ἡρωδιὰς δὲ ἡ ἀδελφὴ τοῦ Ἀγρίππου συνοικοῦσα Ἡρώδῃ, τετράρχης δὲ οὗτος ἦν Γαλιλαίας καὶ Περαίας, φθόνῳ τἀδελφοῦ τὴν ἐξουσίαν ἐδέχετο ὁρῶσα ἐν πολὺ μείζονι ἀξιώματι γεγενημένον ἀνδρὸς τοῦ αὐτῆς, διὰ τὸ φυγῇ μὲν ποιήσασθαι τὴν ἔξοδον διαλῦσαι τὰ χρέα μὴ δυνάμενον, κάθοδον δὲ μετ’ ἀξιώματος καὶ οὕτως πολλοῦ τοῦ εὐδαίμονος. ἐλυπεῖτο οὖν καὶ βαρέως ἔφερεν τῇ ἐπὶ τοσοῦτον αὐτοῦ μεταβολῇ, καὶ μάλιστα ὁπότε θεάσαιτο μετὰ τῶν εἰωθότων παρασήμων τῆς βασιλείας ἐπιφοιτῶντά τε τοῖς πλήθεσιν, ἐπικρύπτεσθαι οὐκ ἠνείχετο τὴν δυστυχίαν τοῦ φθόνου, ἀλλὰ τὸν ἄνδρα ἐξῆρεν κελεύουσα ἐπὶ τῆς Ῥώμης πλεῖν ἐπὶ μνηστείᾳ τῶν ἴσων· οὐδὲ γὰρ ἀνεκτὸν εἶναι σφίσι τὸ ζῆν, εἰ Ἀγρίππας Ἀριστοβούλου μὲν υἱὸς ὢν θανεῖν ὑπὸ τοῦ πατρὸς κατεγνωσμένου, πενίᾳ δὲ ἀπόρῳ συνιών, ὡς τελέως αὐτῷ ἐπικουφίζεσθαι τἀναγκαῖα τοῦ ἐφ’ ἡμέρας, φυγῇ δὲ τῶν δεδανεικότων τὸν πλοῦν πεποιημένος ἐπανεληλύθοι βασιλεύς, αὐτὸς δέ γε ὢν παῖς βασιλέως καὶ τοῦ συγγενοῦς τῆς ἀρχῆς καλοῦντος αὐτὸν ἐπὶ μεταποιήσει τῶν ἴσων καθέζοιτο ἀγαπῶν ἐν ἰδιωτείᾳ διαβιοῦν. ἀλλ’ εἰ καὶ πρότερόν γε, Ἡρώδη, μηδὲν ἐλύπει σε τὸ ἐν ἐλάσσονι τιμῇ πατρὸς οὗ γέγονας εἶναι, νῦν γοῦν ὀρέχθητι συγγενοῦς ἀξιώματος μηδὲ ὑπόμενε ἡσσᾶσθαι προύχοντι τιμῆς ἀνδρὶ πλοῦτον τεθεραπευκότι τὸν σόν, μηδὲ πενίαν ἀποφήνῃς τὴν ἐκείνου τῆς ἡμετέρας εὐπορίας ἀρετῇ μᾶλλον χρῆσθαι δυναμένην, μηδὲ δευτερεύειν ἀνεπαίσχυντον ἡγοῦ τῶν χθές τε καὶ πρῴην ἐλέῳ τῷ σῷ διαβεβιωκότων. ἀλλ’ ἐπὶ τῆς Ῥώμης ἴωμεν, καὶ μήτε πόνου φειδώ τις ἔστω μήτε ἀργυρίου δαπάνης καὶ χρυσίου, διὰ τὸ μὴ ἐπ’ οὐδαμινοῖς ἐν βελτίοσιν γενέσθαι τὴν τήρησιν αὐτῶν ἀναλώσεως τῆς ἐπὶ κτήσει βασιλείας ἐσομένης.", "st": "18.7.1"}, {"sp": "N", "t": "Ὁ δὲ τέως μὲν ἀπεμάχετο ἀγαπῶν τὴν ἡσυχίαν καὶ τῆς Ῥώμης τὸν ὄχλον δι’ ὑποψίας λαμβάνων ἀναδιδάσκειν τε αὐτὴν ἐπειρᾶτο, ἡ δ’ ἐφ’ ὅσον ἐξαναχωροῦντα ἑώρα μειζόνως ἐπέκειτο κελεύουσα μὴ ἀνιέναι πάντα πράσσειν ἐπὶ τῇ βασιλείᾳ. καὶ πέρας οὐκ ἀνῆκεν ἕως ἐξενίκησεν αὐτὸν ὁμογνώμονα αὐτῇ ἀκουσίως γενέσθαι διὰ τὸ μὴ εἶναι ἄλλως ἀποφυγεῖν αὐτῆς τὸ ἐπὶ τοιούτοις ψηφισάμενον, παρασκευασάμενός τε ὡς ἐνῆν πολυτελῶς καὶ φειδοῖ μηδενὸς χρώμενος ἀνήγετο ἐπὶ τῆς Ῥώμης ἅμα καὶ τὴν Ἡρωδιάδα ἀγόμενος. Ἀγρίππας δὲ τήν τε διάνοιαν αὐτῶν καὶ τὴν παρασκευὴν αἰσθόμενος καὶ αὐτὸς παρεσκευάζετο, ἐπεί τε ἐκπεπλευκότας ἀκούει, πέμπει καὶ αὐτὸς ἐπὶ τῆς Ῥώμης Φορτουνᾶτον αὐτοῦ τῶν ἀπελευθέρων δῶρά τε κομίζοντα τῷ αὐτοκράτορι καὶ ἐπιστολὰς κατὰ τοῦ Ἡρώδου τὰ δὲ καὶ αὐτὸν διδάξοντα ᾗ καιρὸς τὸν Γάιον. ὁ δὲ ἐπαναχθεὶς τοῖς ἀμφὶ τὸν Ἡρώδην καὶ δεξιῷ χρησάμενος τῷ πλῷ τοσόνδε ἀπελίπετο τοῦ Ἡρώδου, ὥστε τὸν μὲν ἐντυχεῖν Γαΐῳ, ὁ δὲ ἐπικατάγεται καὶ τὰς ἐπιστολὰς ἀπεδίδου. καὶ προσέπλευσαν ἀμφότεροι Δικαιαρχείᾳ καὶ τὸν Γάιον ἐν Βαΐαις λαμβάνουσιν. πολύδριον δ’ ἐστὶ καὶ τοῦτο τῆς Καμπανίας ὅσον ἀπὸ σταδίων πέντε τῆς Δικαιαρχείας κείμενον, βασίλειοί τέ εἰσιν οἰκήσεις αὐτόθι πολυτελέσι κεχρημέναι κατασκευαῖς φιλοτιμηθέντος τῶν αὐτοκρατόρων ἑκάστου τοὺς προγεγονότας ὑπερβάλλεσθαι, λουτρά τε παρέχεται τὸ χωρίον θερμὰ γῆθεν αὐτόματα ἀνιέντα ἀγαθὰ ἐπί τε ἰάσει τοῖς χρωμένοις καὶ ἄλλως τῷ ἀνειμένῳ τῆς διαίτης συμφέροντα. Γάιος δὲ ἅμα τε προσαγορεύων τὸν Ἡρώδην, πρῶτον δὲ αὐτῷ ἐνετύγχανεν, ἅμα τε τοῦ Ἀγρίππου τὰς ἐπιστολὰς ἐπιὼν ἐπὶ κατηγορίᾳ τῇ ἐκείνου συγκειμένας, κατηγόρει δὲ αὐτοῦ ὁμολογίαν πρὸς Σηιανὸν κατὰ τῆς Τιβερίου ἀρχῆς καὶ πρὸς Ἀρτάβανον τὸν Πάρθον ἐπὶ τοῦ παρόντος κατὰ τῆς Γαΐου ἀρχῆς, παράδειγμά τε ἦν αὐτῷ τοῦ λόγου μυριάσιν ἑπτὰ ὁπλιτῶν ἀρκέσουσα κατασκευὴ ἐν ταῖς Ἡρώδου ὁπλοθήκαις ἀποκειμένη, ἐκινεῖτό τε ὑπὸ τῶν εἰρημένων καὶ ἤρετο τὸν Ἡρώδην, εἰ ἀληθὴς ὁ περὶ τῶν ὅπλων λόγος. τοῦ δέ, οὐ γὰρ ἦν ἕτερα εἰπεῖν διὰ τὸ ἀντιφθέγξασθαι τὴν ἀλήθειαν, εἰπόντος εἶναι τὰ ὅπλα, πιστὰ ἡγούμενος εἶναι τὰ ἐπὶ τῇ ἀποστάσει κατηγορούμενα, τὴν τετραρχίαν ἀφελόμενος αὐτὸν προσθήκην τῇ Ἀγρίππου βασιλείᾳ ποιεῖται καὶ τὰ χρήματα ὁμοίως τῷ Ἀγρίππᾳ δίδωσιν, αὐτὸν δὲ φυγῇ ἀιδίῳ ἐζημίωσεν ἀποδείξας οἰκητήριον αὐτοῦ Λούγδουνον πόλιν τῆς Γαλλίας. Ἡρωδιάδα δὲ μαθὼν Ἀγρίππου ἀδελφὴν οὖσαν τά τε χρήματα ἐδίδου ὁπόσα ἐκείνῃ ἰδίᾳ ἦν καὶ τοῦ μὴ κοινωνεῖν νομίσας τῷ ἀνδρὶ τῆς συμφορᾶς τεῖχος αὐτῇ τὸν ἀδελφὸν ἔλεγεν. ἡ δέ ἀλλὰ σὺ μέν, αὐτόκρατορ, εἶπεν, μεγαλοφρόνως τε καὶ ἀξιώματι τῷ σαυτοῦ πρεπόντως τάδε λέγεις, κώλυμα δέ μοί ἐστιν χρῆσθαί σου τῇ χάριτι τῆς δωρεᾶς εὔνοια ἡ πρὸς τὸν γεγαμηκότα, οὗ κοινωνόν με τῆς εὐδαιμονίας γενομένην οὐ δίκαιον ἐγκαταλιπεῖν τὸ ἐπὶ ταῖς τύχαις καθεσταμένον. ὁ δὲ ὀργῇ τοῦ μεγαλόφρονος αὐτὴν ποιησάμενος συνήλαυνεν καὶ αὐτὴν τῷ Ἡρώδῃ καὶ τὴν οὐσίαν αὐτῆς τῷ Ἀγρίππᾳ δίδωσιν. Ἡρωδιάδι μὲν δὴ φθόνου τοῦ πρὸς τὸν ἀδελφὸν καὶ Ἡρώδῃ γυναικείων ἀκροασαμένῳ κουφολογιῶν δίκην ταύτην ἐπετίμησεν ὁ θεός. Γάιος δὲ τὸν μὲν πρῶτον ἐνιαυτὸν καὶ τὸν ἑξῆς πάνυ μεγαλοφρόνως ἐχρῆτο τοῖς πράγμασιν καὶ μέτριον παρέχων αὑτὸν εἰς εὔνοιαν πολλὴν προυχώρει παρά τε Ῥωμαίοις αὐτοῖς καὶ τοῖς ὑπηκόοις. προϊὼν δ’ ἐξίστατο τοῦ ἀνθρωπίνως φρονεῖν ὑπὸ μεγέθους τῆς ἀρχῆς ἐκθειάζων ἑαυτὸν καὶ τὰ πάντα ἐπ’ ἀτιμίᾳ τοῦ θείου πολιτεύειν ἦρτο.", "st": "18.7.2"}, {"sp": "N", "t": "Καὶ δὴ στάσεως ἐν Ἀλεξανδρείᾳ γενομένης Ἰουδαίων τε οἳ ἐνοικοῦσι καὶ Ἑλλήνων τρεῖς ἀφ’ ἑκατέρας τῆς στάσεως πρεσβευταὶ αἱρεθέντες παρῆσαν ὡς τὸν Γάιον. καὶ ἦν γὰρ τῶν Ἀλεξανδρέων πρέσβεων εἷς Ἀπίων, ὃς πολλὰ εἰς τοὺς Ἰουδαίους ἐβλασφήμησεν ἄλλα τε λέγων καὶ ὡς τῶν Καίσαρος τιμῶν περιορῷεν· πάντων γοῦν ὁπόσοι τῇ Ῥωμαίων ἀρχῇ ὑποτελεῖς εἶεν βωμοὺς τῷ Γαΐῳ καὶ νεὼς ἱδρυμένων τά τε ἄλλα πᾶσιν αὐτὸν ὥσπερ τοὺς θεοὺς δεχομένων, μόνους τούσδε ἄδοξον ἡγεῖσθαι ἀνδριᾶσι τιμᾶν καὶ ὅρκιον αὐτοῦ τὸ ὄνομα ποιεῖσθαι. πολλὰ δὲ καὶ χαλεπὰ Ἀπίωνος εἰρηκότος, ὑφ’ ὧν ἀρθῆναι ἤλπιζεν τὸν Γάιον καὶ εἰκὸς ἦν, Φίλων ὁ προεστὼς τῶν Ἰουδαίων τῆς πρεσβείας, ἀνὴρ τὰ πάντα ἔνδοξος Ἀλεξάνδρου τε τοῦ ἀλαβάρχου ἀδελφὸς ὢν καὶ φιλοσοφίας οὐκ ἄπειρος, οἷός τε ἦν ἐπ’ ἀπολογίᾳ χωρεῖν τῶν κατηγορημένων. διακλείει δ’ αὐτὸν Γάιος κελεύσας ἐκποδὼν ἀπελθεῖν, περιοργής τε ὢν φανερὸς ἦν ἐργασόμενός τι δεινὸν αὐτούς. ὁ δὲ Φίλων ἔξεισι περιυβρισμένος καί φησι πρὸς τοὺς Ἰουδαίους, οἳ περὶ αὐτὸν ἦσαν, ὡς χρὴ θαρρεῖν, Γαΐου λόγῳ μὲν αὐτοῖς ὠργισμένου, ἔργῳ δὲ ἤδη τὸν θεὸν ἀντιπαρεξάγοντος.", "st": "18.8.1"}, {"sp": "N", "t": "Γάιος δὲ ἐν δεινῷ φέρων εἰς τοσόνδε ὑπὸ Ἰουδαίων περιῶφθαι μόνων πρεσβευτὴν ἐπὶ Συρίας ἐκπέμπει Πετρώνιον διάδοχον Οὐιτελλίῳ τῆς ἀρχῆς, κελεύων χειρὶ πολλῇ εἰσβαλόντι εἰς τὴν Ἰουδαίαν, εἰ μὲν ἑκόντες δέχοιντο, ἱστᾶν αὐτοῦ ἀνδριάντα ἐν τῷ ναῷ τοῦ θεοῦ, εἰ δ’ ἀγνωμοσύνῃ χρῷντο, πολέμῳ κρατήσαντα τοῦτο ποιεῖν. καὶ Πετρώνιος Συρίαν παραλαβὼν ἠπείγετο διακονεῖσθαι ταῖς ἐπιστολαῖς τοῦ Καίσαρος, συμμαχίαν τε πλείστην ὅσην ἠδύνατο ἀθροίσας καὶ τάγματα δύο τῆς Ῥωμαίων δυνάμεως ἄγων ἐπὶ Πτολεμαΐδος παρῆν αὐτόθι χειμάσων ὡς πρὸς ἔαρ τοῦ πολεμεῖν οὐκ ἀφεξόμενος, καὶ πρὸς τὸν Γάιον ἔγραφεν περὶ τῶν ἐπεγνωσμένων. ὁ δὲ ἐπῄνει τῆς προθυμίας αὐτὸν καὶ ἐκέλευεν μὴ ἀνιέναι πολεμεῖν δὲ μὴ πειθομένοις ἐντεταμένως. Ἰουδαίων δὲ πολλαὶ μυριάδες παρῆσαν ὡς τὸν Πετρώνιον εἰς Πτολεμαΐδα κατὰ δεήσεις μηδὲν ἐπὶ παρανομίᾳ σφᾶς ἐπαναγκάζειν καὶ παραβάσει τοῦ πατρίου νόμου. εἰ δέ σοι πάντως πρόκειται τὸν ἀνδριάντα φέρειν καὶ ἱστᾶν, ἡμᾶς αὐτοὺς πρότερον μεταχειρισάμενος πρᾶσσε τὰ δεδογμένα· οὐδὲ γὰρ δυνάμεθα περιόντες θεωρεῖν πράγματα ἡμῖν ἀπηγορευμένα ἀξιώματί τε τοῦ νομοθέτου καὶ προπατόρων τῶν ἡμετέρων τῶν εἰς ἀρετὴν ἀνήκειν αὐτὰ κεχειροτονηκότων. Πετρώνιος δὲ ὀργὴν λαβὼν εἶπεν· ἀλλ’ εἰ μὲν αὐτοκράτωρ ὢν βουλεύμασι χρῆσθαι τοῖς ἐμαυτοῦ τάδε πράσσειν ἐπενόουν, κἂν δίκαιος ἦν ὑμῖν πρός με οὗτος ὁ λόγος. νυνὶ δέ μοι Καίσαρος ἐπεσταλκότος πᾶσα ἀνάγκη διακονεῖσθαι τοῖς ἐκείνῳ προανεψηφισμένοις διὰ τὸ εἰς ἀνηκεστοτέραν φέρειν ζημίαν τὴν παρακρόασιν αὐτῶν. ἐπεὶ τοίνυν οὕτως φρονεῖς, ὦ Πετρώνιε, φασὶν οἱ Ἰουδαῖοι, ὡς μὴ ἂν ἐπιστολὰς τὰς Γαΐου παρελθεῖν, οὐδ’ ἂν αὐτοὶ παραβαίημεν τοῦ νόμου τὴν προαγόρευσιν θεοῦ πεισθέντες ἀρετῇ καὶ προγόνων πόνοις τῶν ἡμετέρων εἰς νῦν ἀπαράβατοι μεμενηκότες, οὐδ’ ἂν τολμήσαιμεν ἐπὶ τοσοῦτον κακοὶ γενέσθαι, ὥστε ὁπόσα ἐκείνῳ δόξειεν μὴ πρασσόμενα ἀγαθοῦ ῥοπὴν ἡμῖν φέρειν αὐτοὶ παραβαίνειν ποτ’ ἂν θάνατον φοβηθέντες. ὑπομενοῦμεν δὲ εἰς τύχας ἰόντες ἐπὶ φυλακῇ τε πατρίων καὶ κινδυνεύειν προθεμένοις ἐλπίδα οὖσαν ἐξεπιστάμενοι κἂν περιγενέσθαι διά τε τοῦ θεοῦ τὸ στησόμενον μεθ’ ἡμῶν ἐπὶ τιμῇ τε τῇ ἐκείνου τὰ δεινὰ ὑποδεχομένων καὶ τῆς τύχης τὸ ἐπ’ ἀμφότερα φιλοῦν τοῖς πράγμασι παρατυγχάνειν, ἐκ δὲ τοῦ σοὶ πείθεσθαι πολλὴν μὲν λοιδορίαν τοῦ ἀνάνδρου προσκεισομένην ὡς δι’ αὐτὸ παράβασιν τοῦ νομίμου προσποιουμένοις, καὶ ἅμα πολλὴν ὀργὴν τοῦ θεοῦ, ὃς καὶ παρὰ σοὶ δικαστῇ γένοιτ’ ἂν βελτίων Γαΐου.", "st": "18.8.2"}, {"sp": "N", "t": "Καὶ ὁ Πετρώνιος ἐκ τῶν λόγων θεασάμενος δυσνίκητον αὐτῶν τὸ φρονοῦν καὶ μὴ ἂν ἀμαχεὶ δύναμιν αὐτῷ γενέσθαι διακονήσασθαι Γαΐῳ τὴν ἀνάθεσιν τοῦ ἀνδριάντος πολὺν δὲ ἔσεσθαι φόνον, τούς τε φίλους ἀναλαβὼν καὶ θεραπείαν, ἣ περὶ αὐτὸν ἦν, ἐπὶ Τιβεριάδος ἠπείγετο χρῄζων κατανοῆσαι τῶν Ἰουδαίων τὰ πράγματα ὡς ἔχοι. καὶ Ἰουδαῖοι μέγαν ἡγούμενοι τὸν ἐκ τοῦ πρὸς Ῥωμαίους πολέμου κίνδυνον, πολὺ μείζονα δὲ κρίνοντες τὸν ἐκ τοῦ παρανομεῖν, αὖθις πολλαὶ μυριάδες ὑπηντίαζον Πετρώνιον εἰς τὴν Τιβεριάδα γενόμενον, καὶ ἱκετείᾳ χρώμενοι μηδαμῶς εἰς ἀνάγκας τοιαύτας αὐτοὺς καθιστᾶν μηδὲ μιαίνειν ἀνδριάντος ἀναθέσει τὴν πόλιν, πολεμήσετε ἄρα Καίσαρι, Πετρώνιος ἔφη, μήτε τὴν ἐκείνου παρασκευὴν λογιζόμενοι μήτε τὴν ὑμετέραν ἀσθένειαν; οἱ δ’ οὐδαμῶς πολεμήσαιμεν, ἔφασαν, τεθνηξόμεθα δὲ πρότερον ἢ παραβῆναι τοὺς νόμους. ἐπί τε τὰ πρόσωπα κείμενοι καὶ τὰς σφαγὰς προδεικνύντες ἕτοιμοι κτιννύεσθαι ἔλεγον εἶναι. καὶ ταῦτ’ ἐπράσσετο ἐπὶ ἡμέρας τεσσαράκοντα, καὶ τοῦ γεωργεῖν ἀπερίοπτοι τὸ λοιπὸν ἦσαν καὶ ταῦτα τῆς ὥρας οὔσης πρὸς σπόρῳ, πολλή τε ἦν προαίρεσις αὐτοῖς καὶ τοῦ θνήσκειν ἐπιθυμίας πρόθεσις, ἢ τὴν ἀνάθεσιν θεάσασθαι τοῦ ἀνδριάντος.", "st": "18.8.3"}, {"sp": "N", "t": "Ἐν τούτοις ὄντων τῶν πραγμάτων Ἀριστόβουλος ὁ Ἀγρίππου τοῦ βασιλέως ἀδελφὸς καὶ Ἑλκίας ὁ μέγας ἄλλοι τε οἱ κράτιστοι τῆσδε τῆς οἰκίας καὶ οἱ πρῶτοι σὺν αὐτοῖς εἰσίασιν ὡς τὸν Πετρώνιον παρακαλοῦντες αὐτόν, ἐπειδὴ τὴν προθυμίαν ὁρᾷ τῆς πληθύος, μηδὲν εἰς ἀπόνοιαν αὐτῆς παρακινεῖν, ἀλλὰ γράφειν πρὸς Γάιον τὸ ἀνήκεστον αὐτῶν πρὸς τὴν ἀποδοχὴν τοῦ ἀνδριάντος, πῶς τε ἀποστάντες τοῦ γεωργεῖν ἀντικαθέζονται, πολεμεῖν μὲν οὐ βουλόμενοι διὰ τὸ μηδ’ ἂν δύνασθαι, θανεῖν δ’ ἔχοντες ἡδονὴν πρὶν παραβῆναι τὰ νόμιμα αὐτοῖς, ὥστε ἀσπόρου τῆς γῆς γενομένης λῃστεῖαι ἂν φύοιντο ἀδυναμίᾳ καταβολῆς τῶν φόρων. ἴσως γὰρ ἂν ἐπικλασθέντα τὸν Γάιον μηδὲν ὠμὸν διανοηθῆναι μηδὲ ἐπ’ ἀναστάσει φρονῆσαι τοῦ ἔθνους· ἐμμένοντος δὲ τῇ τότε βουλῇ τοῦ πολεμεῖν τότε δὴ καὐτὸν ἅπτεσθαι τοῦ πράγματος. καὶ οἱ μὲν ἀμφὶ τὸν Ἀριστόβουλον ἐπὶ τούτοις τὸν Πετρώνιον παρεκάλουν. Πετρώνιος δὲ τοῦτο μὲν τῶν περὶ τὸν Ἀριστόβουλον παντοίως ἐπικειμένων διὰ τὸ ὑπὲρ μεγάλων ποιεῖσθαι τὴν δέησιν καὶ πάσῃ μηχανῇ χρησαμένων εἰς τὰς ἱκετείας, τοῦτο δὲ τῶν Ἰουδαίων θεώμενος τὴν ἀντιπαράταξιν τῆς γνώμης καὶ δεινὸν ἡγούμενος τοσαῖσδε ἀνθρώπων μυριάσιν μανίᾳ τῇ Γαΐου διακονούμενος ἐπαγαγὼν θάνατον ἐν αἰτίᾳ τὸ πρὸς θεὸν σεβάσμιον ἔχειν καὶ μετὰ πονηρᾶς τὸν μετὰ ταῦτα βίον ἐλπίδος διαιτᾶσθαι, πολὺ κρεῖσσον ἡγεῖτο ἐπιστείλας τῷ Γαΐῳ τὸ ἀνήκεστον αὐτῶν ὀργὴν φέροντος μὴ ἐκ τοῦ ὀξέος δεδιακονημένου αὐτοῦ ταῖς ἐπιστολαῖς· τάχα μὲν γὰρ καὶ πείσειν· καὶ τῇ τὸ πρῶτον μανίᾳ τῆς γνώμης ἐπιμένοντος ἅψεσθαι πολέμου τοῦ πρὸς αὐτούς, εἰ δ’ ἄρα τι καὶ κατ’ αὐτοῦ τρέποι τῆς ὀργῆς, καλῶς ἔχειν τοῖς ἀρετῆς μεταποιουμένοις ὑπὲρ τοσῆσδε ἀνθρώπων πληθύος τελευτᾶν, ἔκρινε πιθανὸν ἡγεῖσθαι τῶν δεομένων τὸν λόγον.", "st": "18.8.4"}, {"sp": "N", "t": "Συγκαλέσας δὲ εἰς τὴν Τιβεριάδα τοὺς Ἰουδαίους, οἱ δὲ ἀφίκοντο πολλαὶ μυριάδες, καταστὰς ἐπ’ αὐτῶν τήν τε ἐν τῷ παρόντι στρατείαν οὐ γνώμης ἀπέφαινε τῆς αὐτοῦ τοῦ δὲ αὐτοκράτορος τῶν προσταγμάτων, τὴν ὀργὴν οὐδὲν εἰς ἀναβολάς, ἀλλ’ ἐκ τοῦ παραχρῆμα ἐπιφέρεσθαι τοῖς πράγμασιν τοῖς παρακροᾶσθαι θάρσος εἰσφερομένοις· ᾧ καλῶς ἔχον ἐστὶν τόν γε τιμῆς τοσαύτης ἐπιτετευχότα συγχωρήσει τῇ ἐκείνου οὐδὲν ἐναντίον πράσσειν· οὐ μὴν δίκαιον ἡγοῦμαι ἀσφάλειάν τε καὶ τιμὴν τὴν ἐμαυτοῦ μὴ οὐχ ὑπὲρ τοῦ ὑμετέρου μὴ ἀπολουμένου τοσούτων ὄντων ἀναλοῦν διακονούμενον τῇ ἀρετῇ τοῦ νόμου, ὃν πάτριον ὄντα περιμάχητον ἡγεῖσθε, καὶ τῇ ἐπὶ πᾶσιν ἀξιώσει καὶ δυνάμει τοῦ θεοῦ, οὗ τὸν ναὸν οὐκ ἂν περιιδεῖν τολμήσαιμι ὕβρει πεσεῖν τῆς τῶν ἡγεμονευόντων ἐξουσίας. στέλλω δὲ ὡς Γάιον γνώμας τε τὰς ὑμετέρας διασαφῶν καί πῃ καὶ συνηγορίᾳ χρώμενος ὑπὲρ τοῦ καθ’ ἡμᾶς παρὰ γνώμην πεισομένην οἷς προύθεσθε ἀγαθοῖς. καὶ συμπράσσοι μὲν ὁ θεός, βελτίων γὰρ ἀνθρωπίνης μηχανῆς καὶ δυνάμεως ἡ κατ’ ἐκεῖνον ἐξουσία, πρυτανεύων ὑμῖν τε τὴν τήρησιν τῶν πατρίων καὶ αὐτῷ τὸ μηδὲν ἀνθρωπείαις παρὰ γνώμην βουλεύσεσι τιμῶν τῶν εἰωθυιῶν ἁμαρτεῖν. εἰ δ’ ἐκπικρανθεὶς Γάιος εἰς ἐμὲ τρέψει τὸ ἀνήκεστον τῆς ὀργῆς, τλήσομαι πάντα κίνδυνον καὶ πᾶσαν ταλαιπωρίαν συνιοῦσαν τῷ σώματι καὶ τῇ τύχῃ ὑπὲρ τοῦ μὴ ὑμᾶς τοσούσδε ὄντας ἐπὶ οὕτως ἀγαθαῖς ταῖς πράξεσι διολλυμένους θεωρεῖν. ἄπιτε οὖν ἐπὶ ἔργα τὰ αὐτῶν ἕκαστοι καὶ τῇ γῇ ἐπιπονεῖτε. πέμψω δ’ αὐτὸς ἐπὶ Ῥώμης καὶ τὰ πάντα ὑπὲρ ὑμῶν δι’ ἐμαυτοῦ καὶ τῶν φίλων οὐκ ἀποτραπήσομαι διακονεῖν.", "st": "18.8.5"}, {"sp": "N", "t": "Ταῦτα εἰπὼν καὶ διαλύσας τῶν Ἰουδαίων τὸν σύλλογον προμηθεῖσθαι τῶν εἰς τὴν γεωργίαν ἠξίου τοὺς ἐν τέλει καὶ καθομιλεῖν τὸν λαὸν ἐλπίσι χρησταῖς. καὶ ὁ μὲν εὐθυμεῖν τὸ πλῆθος ἔσπευδεν. ὁ θεὸς δὲ παρρησίαν ἐπεδείκνυτο τὴν αὐτοῦ Πετρωνίῳ καὶ τὴν ἐπὶ τοῖς ὅλοις σύλληψιν· ἅμα τε γὰρ ἐπαύετο τοῦ λόγου, ὃν πρὸς τοὺς Ἰουδαίους εἶπεν, καὶ αὐτίκα ὑετὸν ἠφίει μέγαν παρ’ ἐλπίδα τοῖς ἀνθρώποις γενόμενον διὰ τὸ ἐκείνην τὴν ἡμέραν αἴθριον ἕωθεν οὖσαν οὐδὲν ὄμβριον ἀποσημαίνειν ἐκ τῶν περὶ τὸν οὐρανὸν καὶ τὸ πᾶν ἔτος αὐχμῷ μεγάλῳ κατεσχημένον ἐπ’ ἀπογνώσει ποιεῖν τοὺς ἀνθρώπους ὕδατος τοῦ ἄνωθεν, εἰ καὶ σύννεφόν ποτε θεάσαιντο τὸν οὐρανόν. ὥστε δὴ τότε πολλοῦ καὶ παρὰ τὸ εἰωθὸς καὶ παρὰ τὸ ἑτέρῳ δόξαν ἀφιγμένου ὕδατος τοῖς τε Ἰουδαίοις ἐλπὶς ἦν ἐπ’ οὐδαμοῖς ἀτυχήσειν Πετρώνιον ὑπὲρ αὐτῶν δεόμενον, ὅ τε Πετρώνιος κατεπέπληκτο μειζόνως ὁρῶν ἐναργῶς τὸν θεὸν τῶν Ἰουδαίων προμηθούμενον καὶ πολλὴν ἀποσημήναντα τὴν ἐπιφάνειαν, ὡς μηδ’ ἂν τοῖς ἔργῳ προθεμένοις τἀναντία φρονεῖν ἰσχὺν ἀντιλέξεως καταλελεῖφθαι. ὡς δὲ καὶ πρὸς τὸν Γάιον σὺν τοῖς λοιποῖς ὁπόσα ἔγραφεν, ἐπαγωγὰ δὲ ἦν τὰ πάντα καὶ παντοίως παρακαλοῦντα μὴ τοσαύτας μυριάδας ἀνθρώπων ἀπονοεῖν, ἃς εἰ κτείνοι, οὐ γὰρ δίχα γε πολέμου παραχωρήσειν τοῦ νομίμου τῆς θρησκείας, προσόδου τε τῆς ἀπ’ αὐτῶν ἀποστερεῖσθαι καὶ τῷ τροπαίῳ τῆς ἀρᾶς ὑποτίθεσθαι τὸν μέλλοντα αἰῶνα. κἄλλως θείου τοῦ προεστηκότος αὐτῶν τὴν δύναμιν ὡς ἀκραιφνῆ ἀπέφαινεν καὶ μηδὲν ἐνδοίαστον ἐπὶ δυνάμει τῇ αὐτῆς ἐπιδείκνυσθαι καταλείπουσαν. καὶ Πετρώνιος μὲν ἐν τούτοις ἦν.", "st": "18.8.6"}, {"sp": "N", "t": "Ἀγρίππας δὲ ὁ βασιλεύς, ἐτύγχανεν γὰρ ἐπὶ Ῥώμης διαιτώμενος, προύκοπτε φιλίᾳ τῇ πρὸς τὸν Γάιον μειζόνως. καί ποτε προθεὶς δεῖπνον αὐτῷ καὶ πρόνοιαν ἔχων πάντας ὑπερβαλέσθαι τέλεσί τε τοῖς εἰς τὸ δεῖπνον καὶ παρασκευῇ τοῦ εἰς ἡδονὴν φέροντος, ὡς μὴ ὅπως ἄν τινα τῶν λοιπῶν, ἀλλὰ μηδ’ αὐτὸν Γάιον πιστεύειν ποτε ἰσωθῆναι θελήσοντα οὐχ ὅπως ὑπερβαλέσθαι· τοσοῦτον ὁ ἀνὴρ τῇ παρασκευῇ πάντας ὑπερῆρεν καὶ τῷ τὰ πάντα ἢ Καίσαρος ἐκφροντίσας παρασχεῖν. καὶ ὁ Γάιος ἐκθαυμάσας τήν τε διάνοιαν αὐτοῦ καὶ τὴν μεγαλοπρέπειαν, ὡς ἐπ’ ἀρεσκείᾳ τῇ αὐτοῦ βιάζοιτο καὶ ὑπὲρ δύναμιν τῶν χρημάτων εὐπορίᾳ χρήσασθαι, βουλόμενός τε μιμήσασθαι τὴν Ἀγρίππου φιλοτιμίαν ἐφ’ ἡδονῇ τῇ αὐτοῦ πρασσομένην, ἀνειμένος ὑπὸ οἴνου καὶ τὴν διάνοιαν εἰς τὸ ἱλαρώτερον ἐκτετραμμένος, φησὶν ἐν συμποσίῳ παρακαλοῦντος εἰς πότον· Ἀγρίππα, καὶ πρότερον μέν σοι τιμὴν συνῄδειν ᾗ ἐχρῶ τὰ πρὸς ἐμὲ καὶ πολλὴν εὔνοιαν μετὰ κινδύνων ἀποδειχθεῖσαν, οἷς ὑπὸ Τιβερίου περιέστης δι’ αὐτήν, ἐπιλείπεις τε οὐδὲν καὶ ὑπὲρ δύναμιν ἀρετῇ χρῆσθαι τῇ πρὸς ἡμᾶς. ὅθεν, αἰσχρὸν γὰρ ἡσσᾶσθαί με ὑπὸ τῆς σῆς σπουδῆς, ἀναλαβεῖν βούλομαι τὰ ἐλλελειμμένα πρότερον· ὀλίγον γὰρ πᾶν ὁπόσον σοι δωρεῶν ἐχόμενον ἀπεμοιρασάμην. τὸ πᾶν, ὅπερ σοι ῥοπὴν ἂν προσθείη τοῦ εὐδαίμονος, δεδιακονήσεται γάρ σοι προθυμίᾳ τε καὶ ἰσχύι τῇ ἐμῇ. καὶ ὁ μὲν ταῦτα ἔλεγεν οἰόμενος γῆν τε πολλὴν τῆς προσόδου αἰτήσεσθαι ἢ καί τινων προσόδους πόλεων, ὁ δὲ καίπερ τὰ πάντα ἐφ’ οἷς αἰτήσαι παρασκευασάμενος οὐκ ἐφανέρου τὴν διάνοιαν, ἀλλ’ ἐκ τοῦ ὀξέος ἀμείβεται τὸν Γάιον, ὅτι μήτε πρότερον κέρδος τὸ ἀπ’ αὐτοῦ καραδοκῶν παρὰ τὰς Τιβερίου ἐπιστολὰς θεραπεύσειεν αὐτὸν οὔτε νῦν πράσσειν τι τῶν εἰς χάριν τὴν ἐκείνου κερδῶν οἰκείων ἔν τισι λήψεσι. μεγάλα δὲ εἶναι τὰ προδεδωρημένα καὶ περαιτέρω τοῦ θράσει χρωμένου τῶν ἐλπίδων· καὶ γὰρ εἰ τῆς σῆς ἐλάττονα γέγονεν δυνάμεως, τῆς γ’ ἐμοῦ τοῦ εἰληφότος διανοίας τε καὶ ἀξιώσεως μείζονα. καὶ ὁ Γάιος ἐκπλαγεὶς τὴν ἀρετὴν αὐτοῦ πλειόνως ἐνέκειτο εἰπεῖν, ὅ τι χαρίζοιτ’ ἂν αὐτῷ παρασχόμενος. ὁ δέ, ἐπεί περ, ὦ δέσποτα, προθυμίᾳ τῇ σῇ δωρεῶν ἄξιον ἀποφαίνεις, αἰτήσομαι τῶν μὲν εἰς ὄλβον φερόντων οὐδὲν διὰ τὸ μεγάλως με ἐνδιαπρέπειν οἷς ἤδη παρέσχες· ὅ τι δ’ ἂν σοὶ δόξαν προσποιοῖ τοῦ εὐσεβοῦς καὶ τὸ θεῖον σύμμαχον ἐφ’ οἷς θελήσειας παρακαλοῖ κἀμοὶ πρὸς εὐκλείας γένοιτο παρὰ τοῖς πυνθανομένοις, ὡς μηθενὸς ὧν χρησαίμην ὑπὸ τῆς σῆς ἐξουσίας ἀτυχεῖν πώποτε γνόντι· ἀξιῶ γάρ σοι τοῦ ἀνδριάντος τὴν ἀνάθεσιν, ἣν ποιήσασθαι κελεύεις Πετρώνιον εἰς τὸ Ἰουδαίων ἱερόν, μηκέτι πράσσειν διανοεῖσθαι.", "st": "18.8.7"}, {"sp": "N", "t": "Καὶ ὁ μὲν καίπερ ἐπικίνδυνον τοῦτο ἡγούμενος, εἰ γὰρ μὴ πιθανὰ ἔκρινε Γάιος, οὐδὲν ἄλλο ἢ ἐς θάνατον ἔφερεν, διὰ τὸ μεγάλα νομίζειν τε καὶ εἶναι κύβον ἀναρριπτεῖν τὸν ἐπ’ αὐτοῖς ἡγεῖτο. Γάιος δὲ [καὶ] ἅμα τε τῇ θεραπείᾳ τοῦ Ἀγρίππου ἀνειλημμένος καὶ ἄλλως ἀπρεπὲς ὑπολαμβάνων ἐπὶ τοσῶνδε μαρτύρων ψευδὴς γενέσθαι περὶ ὧν προθύμως ἐβιάζετο αἰτεῖσθαι τὸν Ἀγρίππαν μετὰ τοῦ ὀξέος μεταμέλῳ χρώμενος, ἅμα δὲ καὶ τοῦ Ἀγρίππου τὴν ἀρετὴν θαυμάσας, ἐν ὀλίγῳ αὔξειν τὴν οἰκείαν ἀρχὴν ἤτοι προσόδοις χρημάτων ἢ ἄλλῃ δυνάμει τοῦ κοινοῦ δὲ τῆς εὐθυμίας ἐπιμελοῖτο πρεσβεύων τοὺς νόμους καὶ τὸ θεῖον, συνεχώρει καὶ γράφει πρὸς τὸν Πετρώνιον, ἐκεῖνον τῆς τε ἀθροίσεως τοῦ στρατεύματος ἐπαινῶν καὶ τοῦ πρὸς αὐτὸν περὶ αὐτῶν ἐπεσταλκότος· νῦν οὖν εἰ μὲν φθάνεις τὸν ἀνδριάντα ἑστακώς, ἑστάτω· εἰ δὲ μήπω πεποίησαι τὴν ἀνάθεσιν, μηδὲν περαιτέρω κακοπαθεῖν, ἀλλὰ τόν τε στρατὸν διάλυε καὶ αὐτὸς ἐφ’ ἃ τὸ πρῶτόν σε ἔστειλα ἄπιθι· οὐδὲν γὰρ ἔτι δέομαι τῆς ἀναστάσεως τοῦ ἀνδριάντος Ἀγρίππᾳ χαριζόμενος ἀνδρὶ παρ’ ἐμοὶ τιμωμένῳ μειζόνως ἢ ὥστε με χρείᾳ τῇ ἐκείνου καὶ οἷς κελεύσειεν ἀντειπεῖν. Γάιος μὲν δὴ ταῦτα γράφει πρὸς τὸν Πετρώνιον πρότερον ἢ ἐντυχεῖν ἐπὶ ἀποστάσει καταδόξας αὐτοὺς ἐπείγεσθαι, μηδὲν γὰρ ἕτερον ἀποσημαίνειν τὴν διάνοιαν αὐτῶν, ἀλλὰ πόλεμον ἄντικρυς Ῥωμαίοις ἀπειλεῖν. καὶ περιαλγήσας ὡς ἐπὶ πείρᾳ τῆς ἡγεμονίας αὐτοῦ τετολμηκότων, ἀνὴρ ἐπὶ πᾶσιν ἥσσων μὲν τοῦ αἰσχροῦ, κρείσσων δὲ τοῦ βελτίστου καὶ ἐφ’ οἷστισι κρίνειεν ὀργῇ χρῆσθαι παρ’ ὁντινοῦν ἐπειγόμενος παίδευσιν αὐτῆς οὐδ’ ἡντινοῦν προστιθείς, ἀλλ’ ἐφ’ ἡδονῇ τιθεὶς τῇ ἐκείνης τὴν κρίσιν τοῦ εὐδαίμονος, γράφει πρὸς τὸν Πετρώνιον· ἐπειδὴ δῶρα ὁπόσα σοι οἱ Ἰουδαῖοι παρέσχον ἐν μείζονι λόγῳ τῶν ἐμῶν πεποίησαι ἐντολῶν διακονεῖσθαι τὰ πάντα ἡδονῇ τῇ ἐκείνων ἀρθεὶς ἐπὶ παραβάσει τῶν ἐμῶν ἐντολῶν, κελεύω σε σαυτῷ. κριτὴν γενόμενον λογίσασθαι περὶ τοῦ ποιητέου σοι ὑποστάντα ὀργῇ τῇ ἐμῇ, ἐπεί τοι παράδειγμα ποιοῖντό σε οἵ τε νῦν πάντες καὶ ὁπόσοι ὕστεροι γένοιντ’ ἄν, μηδαμῶς ἀκυροῦν αὐτοκράτορος ἀνδρὸς ἐντολάς.", "st": "18.8.8"}, {"sp": "N", "t": "Ταύτην μὲν γράφει Πετρωνίῳ τὴν ἐπιστολήν, οὐ μὴν φθάνει γε ζῶντος Πετρώνιος δεξάμενος αὐτὴν βραδυνθέντος τοῦ πλοῦ τοῖς φέρουσιν εἰς τοσόνδε, ὥστε Πετρωνίῳ γράμματα πρὸ αὐτῆς ἀφικέσθαι, δι’ ὧν μανθάνει τὴν Γαΐου τελευτήν. θεὸς γὰρ οὐκ ἄρ’ ἀμνημονήσειν ἔμελλε Πετρωνίῳ κινδύνων, οὓς ἀνειλήφει ἐπὶ τῇ τῶν Ἰουδαίων χάριτι καὶ τιμῇ τῇ αὐτοῦ, ἀλλὰ τὸν Γάιον ἀποσκευασάμενος ὀργῆς ὧν ἐπὶ σεβασμῷ τῷ αὐτοῦ πράσσειν ἐτόλμησε, τὸν μισθὸν χρεολυτεῖν συνευεργετεῖν τῷ Πετρωνίῳ ἥ τε Ῥώμη καὶ πᾶσα ἡ ἀρχή, μάλιστα δ’ ὁπόσοι τῆς βουλῆς προύχοιεν ἀξιώματι, διὰ τὸ εἰς ἐκείνους ἀκράτῳ τῇ ὀργῇ χρῆσθαι τὸν Γάιον. καὶ τελευτᾷ μὲν οὐ μετὰ πολὺν χρόνον ἢ γράψαι τῷ Πετρωνίῳ τὴν ἐπὶ τῷ θανεῖν ἀνακειμένην ἐπιστολήν, τὴν δ’ αἰτίαν, ἐξ ἧς τελευτᾷ, καὶ τῆς ἐπιβουλῆς τὸν τρόπον ἀφηγήσομαι προϊόντος τοῦ λόγου. Πετρωνίῳ δὲ προτέρα μὲν παρῆν ἡ διασαφοῦσα τοῦ Γαΐου τὴν τελευτὴν ἐπιστολή, μετ’ οὐ πολὺ δὲ ἡ κελεύουσα αὐτὸν τελευτᾶν αὐτόχειρα, καὶ ἥσθη τε τῇ συντυχίᾳ τοῦ ὀλέθρου, ὃς τὸν Γάιον κατέλαβεν, καὶ τοῦ θεοῦ τὴν πρόνοιαν ἐξεθαύμασεν οὐδὲν εἰς ἀναβολὰς ἀλλ’ ἐκ τοῦ ὀξέος μισθὸν αὐτῷ τιμῆς τε τῆς εἰς τὸν ναὸς καὶ βοηθείας τῆς Ἰουδαίων σωτηρίας παρασχομένου. καὶ Πετρωνίῳ μὲν οὕτως μὴ ἂν τοπασθεὶς διεφεύχθη ῥᾳδίως ὁ κίνδυνος τοῦ θανεῖν.", "st": "18.8.9"}, {"sp": "N", "t": "Γίνεται δὲ καὶ περὶ τοὺς ἐν τῇ Μεσοποταμίᾳ καὶ μάλιστα τὴν Βαβυλωνίαν οἰκοῦντας Ἰουδαίους συμφορὰ δεινὴ καὶ οὐδεμιᾶς ἧστινος ἐλάσσων φόνος τε αὐτῶν πολὺς καὶ ὁπόσος οὐχ ἱστορημένος πρότερον. περὶ ὧν δὴ τὰ πάντα ἐπ’ ἀκριβὲς διηγησάμενος ἐκθήσομαι καὶ τὰς αἰτίας, ἀφ’ ὧν αὐτοῖς τὸ πάθος συνέτυχεν. Νέερδα τῆς Βαβυλωνίας ἐστὶ πόλις ἄλλως τε πολυανδροῦσα καὶ χώραν ἀγαθὴν καὶ πολλὴν ἔχουσα καὶ σὺν ἄλλοις ἀγαθοῖς καὶ ἀνθρώπων ἀνάπλεως. ἔστιν δὲ καὶ πολεμίοις οὐκ εὐέμβολος περιόδῳ τε τοῦ Εὐφράτου πᾶσαν ἐντὸς αὐτὴν ἀπολαμβάνοντος καὶ κατασκευαῖς τειχῶν. ἔστιν δὲ καὶ Νίσιβις πόλις κατὰ τὸν αὐτὸν τοῦ ποταμοῦ περίρρουν, ὅθεν Ἰουδαῖοι τῇ φύσει τῶν χωρίων πεπιστευκότες τό τε δίδραχμον, ὃ τῷ θεῷ καταβάλλειν ἑκάστοις πάτριον, ταύτῃ κατετίθεντο καὶ ὁπόσα δὲ ἄλλα ἀναθήματα, ἐχρῶντό τε ὥσπερ ταμιείῳ ταῖσδε ταῖς πόλεσιν. ἐντεῦθεν δὲ ἐπὶ Ἱεροσολύμων ἀνεπέμπετο ᾗ καιρός, πολλαί τε ἀνθρώπων μυριάδες τὴν κομιδὴν τῶν χρημάτων παρελάμβανον δεδιότες τὰς Παρθυαίων ἁρπαγὰς ὑποτελούσης ἐκείνοις τῆς Βαβυλωνίας. καὶ ἦσαν γὰρ Ἀσιναῖος καὶ Ἀνιλαῖος Νεερδᾶται μὲν τὸ γένος, ἀλλήλων δὲ ἀδελφοί. καὶ αὐτούς, πατρὸς δ’ ἦσαν ὀρφανοί, ἡ μήτηρ προσέταξεν ἱστῶν μαθήσει ποιήσεως, οὐκ ὄντος ἀπρεποῦς τοῖς ἐπιχωρίοις ὥστε τοὺς ἄνδρας ταλασιουργεῖν παρ’ αὐτοῖς. τούτοις ὁ τοῖς ἔργοις ἐφεστώς, καὶ γὰρ ἐμεμαθήκεσαν παρ’ αὐτῷ, βραδυτῆτα ἐπικαλέσας τῆς ἀφίξεως ἐκόλασε πληγαῖς. οἱ δὲ ἐφ’ ὕβρει τὴν δικαίωσιν λογιζόμενοι, κατασπάσαντες τῶν ὅπλων πολλὰ ὁπόσα ἦν ἐπὶ τῆς οἰκίας φυλασσόμενα ᾤχοντο εἴς τι χωρίον, διάρρηξιν μὲν ποταμῶν λεγόμενον, νομὰς δὲ ἀγαθὰς παρασχεῖν πεφυκὸς καὶ χιλὸν ὁπόσοι εἰς τὸν χειμῶνα ἀποτιθοῖντο. συνῄεσάν τε ὡς αὐτοὺς τῶν νέων οἱ ἀπορώτατοι, καὶ τούτους τοῖς ὅπλοις φραγνύντες στρατηγοί τε ἦσαν καὶ τῶν κακῶν ἡγεμόνες οὐκ ἐκωλύοντο εἶναι. προελθόντες γὰρ ἐπὶ τὸ ἄμαχον καὶ κατασκευάσαντες ἀκρόπολιν διέπεμπον πρὸς τοὺς νέμοντας φόρον αὐτοῖς κελεύοντες καταβάλλειν τῶν βοσκημάτων, ἣ ἀρκοῦσα ἐπιτροφὴ γίνοιτ’ ἄν, προστιθέντες φιλίαν τε πειθομένοις καὶ ἄμυναν τῶν ἀλλαχόθεν ποθὲν πολεμίων, σφαγὰς δὲ τῶν ποιμνίων ἀπειθοῦσιν. οἱ δέ, οὐ γὰρ ἦν ἕτερα παρ’ αὐτὰ ποιεῖν, ἠκροῶντο καὶ τῶν προβάτων ἔστελλον ὁπόσα κελευσθεῖεν, ὥστε δὴ καὶ πλείων αὐτοῖς συνελέγετο ἰσχὺς κύριοί τε ἦσαν ἐφ’ οἷς βουλεύσειαν ἐκ τοῦ ὀξέος ἐλαύνοντες κακουργεῖν. θεραπεύειν τε αὐτοὺς ἦρκτο πᾶς προστυγχάνων, καὶ ἦσαν φοβεροὶ καὶ τοῖς πειρασομένοις, ὥστ’ ἤδη προύκοπτε λόγος περὶ αὐτῶν κἀπὶ τοῦ Πάρθων βασιλέως.", "st": "18.9.1"}, {"sp": "N", "t": "Ὁ δὲ τῆς Βαβυλωνίας σατράπης μαθὼν ταῦτα καὶ βουληθεὶς ἔτι φυομένους κωλῦσαι πρίν τι μεῖζον κακὸν ἐξ αὐτῶν ἀναστῆναι, συλλέξας στρατὸν ὅσον ἐδύνατο πλεῖστον καὶ τῶν Παρθυαίων καὶ τῶν Βαβυλωνίων ἤλασε πρὸς αὐτοὺς, φθῆναι θέλων προσβαλὼν ἐξελεῖν πρὶν ἐξάγγελτος γενέσθαι κατασκευάζων τὸν στρατόν. περικαθίσας δὲ τὸ ἕλος ἡσύχαζεν, καὶ κατὰ τὴν ἐπιοῦσαν, ἦν δὲ σάββατον ἀργίας παντὸς χρήματος Ἰουδαίοις ἡμέρα, οἰόμενος οὐ τολμήσειν ἀντιστατήσειν αὐτῷ τοὺς πολεμίους, ἀλλὰ ἀμαχεὶ λαβὼν ἄξειν δεδεμένους, κατὰ βραχὺ δὲ προσῄει χρῄζων αἰφνίδιον ποιεῖσθαι τὴν ἐπίπτωσιν. Ἀσιναῖος δὲ ἐτύγχανε σὺν τοῖς ἑταίροις καθεζόμενος καὶ τὰ ὅπλα παρέκειτο αὐτοῖς ἄνδρες, φησί, χρεμετισμός μοι ἵππων προσέπεσεν οὐ φορβάδων, ἀλλ’ οἷος γένοιτ’ ἂν ἀνδρῶν αὐτοῖς ἐπιβεβηκότων, ἐπεὶ καί τινος ἀνακρούσεως αἰσθάνομαι χαλινῶν· δέδια, μὴ λελήθασιν ἡμᾶς οἱ πολέμιοι περιστάντες. ἀλλά τις προΐτω κατόπτης ἀπαγγελίαν ἡμῖν σαφῆ τῶν ἐνεστηκότων ποιησόμενος. εἴη δὲ ἐπὶ ψευδέσι μοι λελέχθαι τὰ εἰρημένα. καὶ ὁ μὲν τάδε εἶπεν, καὶ ᾤχοντό τινες προσκοποῦντες τὸ γινόμενον καὶ ᾗ τάχος παρελθόντες, καὶ οὔτε αὐτὸς ψεύδῃ σαφὴς εἰκαστὴς εἶναι τῶν πρασσομένων τοῖς πολεμίοις οὔτε ἐκεῖνοι πλειόνως ἐπιτρέψειν ἤμελλον ἡμῖν ὑβριεῖν. περιειλήμμεθα δόλῳ μηδὲν βοσκημάτων διαφέροντες· τοσῆσδε ἵππου πλῆθος ἐπελαύνουσιν ἡμῖν ἐν ἀπορίᾳ χειρῶν κειμένοις διὰ τὸ κατείργεσθαι προαγορεύσει τῶν πατρίων εἰς τὸ ἀργεῖν. Ἀσιναῖος δὲ οὐκ ἄρα γνώμῃ τοῦ κατασκόπου κρίνειν ἔμελλεν ἐπὶ τοῖς ποιητέοις, ἀλλὰ νομιμώτερον ἡγησάμενος τοῦ ἐπ’ ἀπράκτοις τελευτῶντας εὐφραίνειν τοὺς πολεμίους τὸ ἀλκῆς δεξάμενος αὐτοὺς ὑπὲρ τῆς ἀνάγκης εἰς ἣν ἐνεπεπτώκει παρανομεῖν τιμωρίαν ἀπολαμβάνοι, εἰ δέοι τελευτᾶν, αὐτός τε ἀναλαμβάνει τὰ ὅπλα καὶ τοῖς σὺν αὐτῷ θάρσος ἐνεποίει τῆς ἐπὶ τὰ ὅμοια ἀρετῆς. ὁμόσε ἴασι τοῖς πολεμίοις, καὶ πολλοὺς κτείναντες αὐτῶν διὰ τὸ καταφρονοῦντας ὡς ἐπὶ τὰ ἕτοιμα χωρεῖν εἰς φυγὴν τρέπονται τὸ λοιπόν.", "st": "18.9.2"}, {"sp": "N", "t": "Ὁ δὲ τῶν Πάρθων βασιλεύς, ἐπεὶ ἀφίκετο αὐτῷ ἡ ἀγγελία τῆς μάχης, ἐκπλαγεὶς τῷ τολμήματι τῶν ἀδελφῶν ἐπεθύμησεν αὐτοῖς ἐλθεῖν δι’ ὄψεως καὶ λόγων, καὶ πέμπει τὸν πιστότατον τῶν σωματοφυλάκων λέγοντα, ὅτι βασιλεὺς Ἀρτάβανος καίπερ ἠδικημένος ὑφ’ ὑμῶν ἐπιχειρήσεως αὐτοῦ τῇ ἀρχῇ γενομένης ἐν ἐλάσσονι τὴν καθ’ αὑτὸν ὀργὴν τῆς ὑμετέρας ἀρετῆς ποιησάμενος ἀπέστειλέν με δεξιάς τε καὶ πίστιν δώσοντα ὑμῖν, συγχωρῶν ἄδειάν τε καὶ ἀσυλίαν ὁδῶν, χρῄζων ἐπὶ φιλίᾳ προσχωρεῖν πρὸς αὐτὸν δόλου τε καὶ ἀπάτης χωρίς, δῶρά τε δώσειν ὑπισχνεῖται καὶ τιμήν, ἥτις ὑμῖν πρὸς τῇ νῦν οὔσῃ ἀρετῇ μελλήσει δυνάμει τῇ ἐκείνου ὠφελεῖν. Ἀσιναῖος δὲ αὐτὸς μὲν ὑπερβάλλεται ὁδοὺς τὰς ἐκεῖ, τὸν ἀδελφὸν δὲ Ἀνιλαῖον ἐκπέμπει μετὰ δώρων ὁπόσα πορίσαι ἦν. καὶ ὁ μὲν ᾤχετο καὶ εἴσοδος αὐτῷ γίνεται παρὰ βασιλέα. Ἀρτάβανος δὲ ἐπεὶ θεᾶται τὸν Ἀνιλαῖον καταμόνας ἥκοντα, ἤρετο τὴν αἰτίαν τοῦ καὶ τὸν Ἀσιναῖον ἐφυστερηκότος. ἐπεὶ δὲ πυνθάνεται αὐτὸν δείσαντα ἐν τῷ ἕλει ὑπομένειν, ὁ δὲ τούς τε πατρῴους θεοὺς ἐπώμνυτο μηδὲν κακὸν δράσειν αὐτοὺς πίστει τῇ αὐτοῦ προσκεχωρηκότας, καὶ τὴν δεξιὰν ἐδίδου, ὅπερ μέγιστον παρὰ πᾶσιν τοῖς ἐκείνῃ βαρβάροις παράδειγμα τοῦ θαρσεῖν γίνεται τοῖς ὁμιλοῦσιν· οὐ γὰρ ἂν ψεύσαιτό τις δεξιῶν ὑπ’ αὐτοῦ δόσεων γενομένων οὐδὲ πιστεύειν ἐνδοιάσειεν, εἰ τοιᾶσδε ἀσφαλείας δόσις γίνοιτο παρὰ τῶν ἐν ὑποψίᾳ ἀδικήσειν καθεστηκότων. καὶ Ἀρτάβανος μὲν ταῦτα πράξας ἐκπέμπει τὸν Ἀνιλαῖον πείσοντα τὸν ἀδελφὸν ἐπανελθεῖν, ἔπρασσεν δὲ ταῦτα βασιλεὺς χρῄζων ἐνστομισμάτων τῇ ἀρετῇ τῶν Ἰουδαίων ἀδελφῶν εἰς φιλίαν κτήσασθαι τῶν ἐκείνου σατραπειῶν ἐν ἀποστάσει τε οὐσῶν καὶ διανοίᾳ τοῦ ἀποστησομένου μέλλων ἐλάσειν ἐπ’ αὐτούς. ἐδεδίει γάρ, μὴ καὶ περιεχομένου πολέμῳ τῷ ἐκείνῃ κατὰ χείρωσιν τῶν ἀφεστηκότων αὐξηθῶσιν ἐπὶ μέγα οἱ περὶ τὸν Ἀσιναῖον καὶ τὴν Βαβυλωνίαν ἤτοι γε συστήσονται ἐπ’ ἀκροάσει τῇ αὐτῶν ἢ καὶ τούτου γε ἀποτυχόντες τοῦ κακῶσαι μειζόνως οὐ διαμάρτοιεν.", "st": "18.9.3"}, {"sp": "N", "t": "Ὁ μὲν δὴ ταῦτα διανοηθεὶς ἐκπέμπει τὸν Ἀνιλαῖον, ὁ δὲ πιθανὸς ἦν τῷ ἀδελφῷ τήν τε ἄλλην προθυμίαν εἰσηγούμενος τοῦ βασιλέως καὶ ὅρκιον τὸ γεγενημένον, ὥστε δὴ ἠπείγοντο ὡς τὸν Ἀρτάβανον. ὁ δὲ ἡδονῇ αὐτοὺς δέχεται παραγενομένους ἐθαύμαζεν τε τὸν Ἀσιναῖον τοῦ ἐν ταῖς πράξεσιν εὐψύχου, θεωρῶν παντελῶς ὄντα ὀφθῆναι βραχύν τε καὶ τοῖς τὸ πρῶτον ὄψει συνελθοῦσιν ἐνδοῦναι καταφρονήματος ἀφορμὰς ὡς οὐδενὶ κρίνοιεν αὐτόν, φησί τε πρὸς τοὺς φίλους, ὡς μείζονα ἐν τῇ παραθέσει παρέχοιτο τὴν ψυχὴν τοῦ σώματος, παρά τε πότον δεικνὺς τὸν Ἀσιναῖον Ἀβδαγάσῃ τῷ αὐτοῦ στρατοπεδάρχῃ τό τε ὄνομα διασαφεῖ καὶ τὴν πᾶσαν ἀρετήν, ᾗ χρῷτο εἰς πόλεμον. τοῦ δὲ Ἀβδαγάσου κελεύοντος συγχώρημα αὐτῷ γενέσθαι κτείναντα αὐτὸν ἄποινα ἀπολαβεῖν ὑπὲρ ὧν ὑβρίσειεν εἰς τὴν Παρθυαίων ἀρχήν ἀλλ’ οὐκ ἄν, εἶπεν ὁ βασιλεύς, συγχώρημα διδοίην ἐπ’ ἀνδρὶ πίστει τῇ εἰς ἐμὲ τεθαρρηκότι καὶ προσέτι δεξιάν τε πέμψας καὶ θεῶν ὅρκοις πιθανὸς γενέσθαι σπουδάσας. εἰ δὲ ἀνὴρ τυγχάνεις τὰ πολέμια ἀγαθός, μηδὲν ἐπιορκίας χρῄζων τῆς ἐμῆς Παρθυαίων ἐκδίκει τὴν ἀρχὴν περιυβρισμένην· ἐπαναχωροῦντι γὰρ ἐπιθέμενος περιγίνου κράτει τῷ περὶ σὲ καὶ μετ’ ἀγνοίας τῆς ἐμῆς. ἕωθεν δὲ μετακαλέσας τὸν Ἀσιναῖον ὥρα σοι, φησίν, ὦ νεανία, χωρεῖν ἐπὶ τὰ σαυτοῦ, μὴ καὶ πλείοσιν τῶν ἐνθάδε στρατηγῶν τὴν ὀργὴν ἐρεθίσειας ἐπιχειρεῖν σου τῇ σφαγῇ καὶ δίχα γνώμης τῆς ἐμῆς. παρακαταθήκην δέ σοι δίδωμι τὴν Βαβυλωνίαν γῆν ἀλῄστευτόν τε καὶ ἀπαθῆ κακῶν ἐσομένην ὑπὸ τῶν σῶν φροντίδων. ἄξιον δέ μοι τυγχάνειν σου χρηστοῦ ἀνεπίκλητόν σοι παρασχόμενος τὴν ἐμαυτοῦ πίστιν, οὐκ ἐπὶ κούφοις ἀλλ’ ἐπὶ τοῖς εἰς σωτηρίαν ἀνακειμένοις. ταῦτα εἰπὼν καὶ δῶρα δοὺς τοτηνίκα ἐκπέμπει τὸν Ἀσιναῖον. ὁ δὲ εἰς τὴν οἰκείαν παραγενόμενος φρούρια κατασκευάζει καὶ ὁπόσα πρότερον ὠχύρου, μέγας τε ἐν ὀλίγῳ γεγόνει καὶ οἷος οὐκ ἄλλος τῶν πρότερον ἐκ τοιαύτης ἀφορμῆς ἅψασθαι πραγμάτων ἐν τόλμῃ γεγονότων, Παρθυαίων τε αὐτὸν ἐθεράπευον οἱ ταύτῃ καταπεμπόμενοι στρατηγοί· μικρὸν γὰρ ἐδόκει καὶ τῆς κατ’ αὐτὸν ἧσσον ἀρετῆς ἡ ἐκ Βαβυλωνίων προϊοῦσα τιμή. ἦν τε ἐν ἀξιώματι καὶ δυνάμει, πάντα τε ἤδη τὰ ἐπὶ τῆς Μεσοποταμίας πρὸς αὐτὸν ἦρτο πράγματα, προύκοπτέν τε αὐτῶν ἡ εὐδαιμονία ἐπὶ ἔτη πεντεκαίδεκα.", "st": "18.9.4"}, {"sp": "N", "t": "Ἀκμαζόντων δὲ αὐτοῖς τῶν ἀγαθῶν ἀρχὴ αὐτοὺς ἐπικαταλαμβάνει κακῶν ἐκ τοιᾶσδε αἰτίας, ἐπειδὴ τὴν ἀρετήν, ᾗ προύκοψαν ἐπὶ μέγα δυνάμεως, ἐκτρέπουσιν εἰς ὕβριν ἐπὶ παραβάσει τῶν πατρίων ὑπὸ ἐπιθυμιῶν καὶ ἡδονῆς ἐμπεσόντες τῶν Πάρθων τινί, στρατηγὸς δὲ ἀφίκετο τῶν ταύτῃ χωρίων, ᾧ δὴ καὶ εἵπετο γαμετὴ τά τε ἄλλα καὶ εἰς τὸ ἐπαινεῖσθαι προειληφυῖα πασῶν καὶ μείζονα ῥοπὴν ἐπ’ αὐτῷ λαμβάνουσα θαύματι τοῦ εὐπρεποῦς. ταύτης εἴτε ἀκοῇ τῆς εὐπρεπείας ἐκμαθὼν εἴτε καὶ ἄλλως αὐτόπτης γενόμενος Ἀνιλαῖος ὁ τοῦ Ἀσιναίου ἀδελφὸς ἐραστής τε ἐγεγόνει καὶ πολέμιος, τὸ μὲν ὑπὸ τοῦ μὴ ἄλλως ἐλπίζειν ἐκπράσσεσθαι τὴν σύνοδον τῆς γυναικὸς μὴ τὴν ἐξουσίαν ὡς ἐπ’ αὐτῇ κτηθείσῃ παραλαβών, τὸ δὲ ὑπὸ τοῦ δυσαντίλεκτον κρίνειν τὴν ἐπιθυμίαν. ἅμα τε οὖν πολέμιος ἐπ’ αὐτῆς ἀνὴρ κεχειροτόνητο κτείνων κιτιῶν καὶ μάχης ἐπάκτου γενομένης πεσόντος ἀνῃρημένου ἁλοῦσα ἐγεγάμητο τῷ ἐραστῇ. οὐ μὴν δίχα γε μεγάλων δυστυχιῶν Ἀνιλαίῳ τε ἅμα αὐτῷ καὶ Ἀσιναίῳ ἡ γυνὴ ἀφίκετο εἰς τὸν οἶκον αὐτῶν, ἀλλὰ σύν τινι μεγάλῳ κακῷ διὰ τοιαύτην αἰτίαν· ἐπεὶ γὰρ τἀνδρὸς τεθνηκότος αἰχμάλωτος ἤγετο, τὰ ἀφιδρύματα τῶν θεῶν, ἅπερ τῷ ἀνδρὶ καὶ αὐτῇ πατρῷα ἦν, ἐπιχώριον δὲ τοῖς ἐκείνῃ πᾶσίν ἐστιν ἐπί τε τῆς οἰκίας ἔχειν σεβάσματα καὶ ἰοῦσιν ἐπὶ ξένης συνεπάγεσθαι, περιστέλλουσα καὶ ταύτῃ τοῦ πατρίου τὸ ἐπ’ αὐτοῖς ἔθος συναπήγετο, καὶ τὸ μὲν πρῶτον λεληθότως αὐτῶν θρησκείαν ἐποιεῖτο, γαμετὴ δὲ ἀποδειχθεῖσα ἤδη τρόπῳ τῷ αὐτῆς εἰωθότι καὶ μεθ’ οἵων νομίμων ἐπὶ τοῦ προτέρου ἀνδρὸς ἐθεράπευεν αὐτούς. καὶ τῶν ἑταίρων οἱ μάλιστα τιμώμενοι παρ’ αὐτοῖς τὸ μὲν πρῶτον οὐδαμῶς πράσσοι Ἑβραϊκὰ οὐδὲ ὁπόσα νόμοις τοῖς αὐτῶν πρόσφορα γυναῖκα ἠγμένος ἀλλόφυλον καὶ παραβαίνουσαν θυσιῶν καὶ σεβασμῶν τῶν αὐτοῖς εἰωθότων τὴν ἀκρίβειαν· ὁρᾶν οὖν, μὴ τὰ πολλὰ τῇ ἡδονῇ τοῦ σώματος συγχωρῶν ἀπολέσειε τὴν ἀρχὴν τοῦ εὐπρεποῦς καὶ τὴν εἰς νῦν ὑπὸ τοῦ θείου προελθοῦσαν ἐξουσίαν. ἐπεὶ δὲ οὐδὲν ἐπέραινον, ἀλλὰ καί τινα αὐτῶν τὸν μάλιστα τιμώμενον ὅτι πλέονι παρρησίᾳ χρήσαιτο ἀπέκτεινε, καὶ ὃς θεώμενος εὐνοίας τε τῶν νόμων καὶ τοῦ κτείνοντος αὐτὸν τιμωρίαν ἐπηράσατο αὐτῷ τε Ἀνιλαίῳ καὶ Ἀσιναίῳ καὶ πᾶσιν ἑταίροις ὁμοίαν ὑπὸ τῶν ἐχθρῶν ἐπαχθεῖσαν γενέσθαι τελευτήν, τοῖς μὲν ὡς ἡγεμόσι παρανομιῶν γεγονόσι, τοῖς δέ, ὅτι μὴ βοηθοῖεν αὐτῷ τοιάδε πάσχοντι διὰ τὸ ἐκδικεῖν τοῖς νόμοις, οἱ δὲ ἐβαρύνοντο μέν, ἠνείχοντο δέ, μνημονεύοντες οὐκ ἐξ ἄλλης αἰτίας ἀλλ’ ἰσχύι τῇ ἐκείνων τῇ εὐδαιμονίᾳ συνελθόντες. ἐπεὶ δὲ καὶ τὴν θεραπείαν ἀκροῶνται τῶν θεῶν τῶν Παρθυαίοις τιμωμένων, οὐκέτι ἀνεκτὸν ἡγούμενοι τοῦ Ἀνιλαίου τὸ ὑβρίζον εἰς τοὺς νόμους ἐπὶ τὸν Ἀσιναῖον ἐλθόντες καὶ πλέονες ἤδη κατεβόων τοῦ Ἀνιλαίου, φάμενοι καλῶς ἔχειν, εἰ μὴ πρότερον κατ’ αὐτὸν ἑώρα τὸ ὠφελοῦν ἀλλὰ νῦν γοῦν ἐπιστροφὴν ποιεῖσθαι τοῦ γεγονότος πρὶν ἢ τὴν ἁμαρτίαν ἐκείνῳ τε καὶ πᾶσι τοῖς ἄλλοις γενέσθαι εἰς ὄλεθρον ἀνακειμένην, τόν τε γάμον τῆς ἀνθρώπου λέγοντες οὐ μετ’ αὐτῶν οὐδ’ αὐτοῖς εἰωθότων τεθεῖσθαι νόμων καὶ τὴν θρησκείαν ἣν ἐπιτηδεύοι ἡ γυνὴ ἐπ’ ἀτιμώσει θεοῦ τοῦ αὐτοῖς σεβασμίου πράσσεσθαι. ὁ δὲ καὐτὸς ᾔδει μὲν τὴν ἁμαρτάδα τοῦ ἀδελφοῦ μεγάλων αἰτίαν οὖσαν κακῶν καὶ ἐσομένην, οὐ μὴν ἀπείχετό γε εὐνοίᾳ τοῦ συγγενοῦς νικώμενος καὶ συγγνώμην νέμων ὡς ὑπὸ κρείσσονος κακοῦ τῆς ἐπιθυμίας νικωμένου. ἐπεὶ δὲ πλείους τε ὁσημέραι συνεστρέφοντο καὶ πλείους ἦσαν αἱ καταβοαί, τηνικαῦτα δή φησιν περὶ αὐτῶν πρὸς Ἀνιλαῖον τοῖς τε πρῶτον γεγονόσιν ἐπιτιμῶν καὶ παύσασθαι τὸ λοιπὸν κελεύων τὴν ἄνθρωπον ἀποπεμψάμενον εἰς τοὺς συγγενεῖς. ἐπράσσετο δὲ οὐδὲν ἐκ τῶν λόγων· καὶ ἡ γυνὴ δὲ αἰσθανομένη μὲν τοῦ θροῦ τοῦ κατέχοντος τοὺς λαοὺς δι’ αὐτήν, δεδοικυῖα δὲ περὶ τοῦ Ἀνιλαίου, μὴ καί τι πάθοι ἔρωτι τῷ πρὸς αὐτήν, φάρμακον τῷ Ἀσιναίῳ δοῦσα ἐν τοῖς σιτίοις μεθίστατο τὸν ἄνθρωπον ἀδεής τε ἦν ἐπὶ κριτῇ τῶν περὶ αὐτὴν πραχθησομένων τῷ ἐραστῇ γενομένη.", "st": "18.9.5"}, {"sp": "N", "t": "Ἀνιλαῖος δὲ καταμόνας ἤδη τὴν ἡγεμονίαν παραλαβὼν ἐξάγει στρατιὰν ἐπὶ τὰς Μιθριδάτου κώμας ἀνδρὸς πρώτου ἐν τῇ Παρθυηνῇ καὶ βασιλέως Ἀρταβάνου τὴν θυγατέρα γεγαμηκότος, διὰ λείας τε ἦγεν αὐτάς, καὶ πολλὰ μὲν χρήματα καὶ ἀνδράποδα εὑρίσκεται, πολλὰ δὲ πρόβατα ἄλλα τε πολλὰ ὁπόσα ἐπὶ προσλήψει τοῦ εὐδαίμονος ὠφελεῖ τοῖς ἔχουσιν. Μιθριδάτης δέ, ἐτύγχανε γὰρ τῇδε ὤν, ἐπειδὴ ἀκούει τῶν κωμῶν τὴν ἅλωσιν ἐν δεινῷ φέρων, ὁπότε μὴ προάρξαντος ἀδικεῖν Ἀνιλαῖος ἄρξαιτο καὶ παρόντος τοῦ ἀξιώματος ὑπεριδών, ἱππέας συναγαγὼν πλείστους ὅσους ἐδύνατο καὶ τῶν πλείστων τοὺς ἐν ἡλικίᾳ παρῆν ὡς προσμίξων τοῖς περὶ τὸν Ἀνιλαῖον καὶ ἔν τινι κώμῃ τῶν αὐτοῦ σχὼν ἡσύχαζεν, ὡς τῇ ἐπιούσῃ μαχησόμενος διὰ τὸ εἶναι σαββάτων ἡμέραν τοῖς Ἰουδαίοις ἐν ἀργίᾳ διαγομένην. Ἀνιλαῖος δὲ ταῦτα πυθόμενος παρὰ ἀνδρὸς Σύρου ἀλλοφύλου ἐξ ἑτέρας κώμης τέ τε ἄλλα φράζοντος ἀκριβῶς καὶ τὸ χωρίον, ἔνθα Μιθριδάτης ἤμελλεν δαίνυσθαι, δειπνοποιησάμενος καθ’ ὥραν ἤλαυνε νυκτὸς ἀμαθέσι τῶν ποιουμένων χρῄζων τοῖς Παρθυαίοις ἐπιπεσεῖν. καὶ περὶ τετάρτην φυλακὴν ἐπιπεσὼν τοὺς μὲν ἔτι κοιμωμένους ἀναιρεῖ τοὺς δὲ εἰς φυγὴν τρέπει, Μιθριδάτην δὲ ζωγρίᾳ λαβὼν ἦγεν ὡς αὐτὸν ἐπὶ ὄνον γυμνὸν ἀναθέμενος, ἥπερ ἀτιμιῶν μεγίστη νομίζεται παρὰ Παρθυαίοις. καταγαγὼν δὲ εἰς τὴν ὕλην μετὰ τοιοῦδε ὁρίσματος, [καὶ] κελευόντων τῶν φίλων ἀναιρεῖν τὸν Μιθριδάτην ἀνεδίδασκεν αὐτοὺς σπεύδων αὐτὸς ἐναντία· μὴ γὰρ καλῶς ἔχειν ἀναιρεῖν ἄνδρα γένους τε ὄντα τοῦ πρώτου παρὰ Παρθυαίοις καὶ ἐπιγαμίᾳ τῇ πρὸς τὸν βασιλέα μειζόνως τιμώμενον· νῦν μὲν γὰρ ἀνεκτὰ εἶναι τὰ πεπραγμένα· καὶ γὰρ εἰ περιύβρισται Μιθριδάτης, ἀλλ’ οὖν σωτηρίᾳ τῆς ψυχῆς εὐεργετούμενον χάριτος μνήσεσθαι τοῖς τὰ τοιάδε παρασχοῦσιν, παθόντος δέ τι ἀνήκεστον οὐκ ἀτρεμήσειν βασιλέα μὴ οὐ μεγάλην σφαγὴν Ἰουδαίων τῶν ἐν Βαβυλῶνι ποιησάμενον, ὧν φείδεσθαι καλῶς ἔχειν διά τε τὴν συγγένειαν καὶ διὰ τὸ μὴ ἀναστροφὴν εἶναι ἂν αὐτοῖς πταίσματός τινος γενομένου τὸ κατ’ ἐκείνους ἀκμῆς πληθύι χρώμενον. καὶ ὁ μὲν ταῦτα διανοηθεὶς καὶ φράσας ἐν τῷ συλλόγῳ πιθανὸς ἦν ἀφίεταί τε Μιθριδάτης, ἐλθόντα δὲ αὐτὸν ὠνείδιζεν ἡ γυνή, εἰ μὴ προμηθήσεται βασιλέως τε γαμβρὸς ὢν καὶ ταύτῃ τιμωρῶν τιμωρηθήσεσθαι τοὺς ὑβρίσαντας εἰς αὐτὸν περιορώμενος, ἀγαπῶν δὲ τὴν σωτηρίαν μετὰ αἰχμαλωσίαν ὑπὸ Ἰουδαίων ἀνδρῶν γενομένην· καὶ νῦν ἐπανάδραμε τὴν ἀρετήν, ἢ θεοὺς ἐπόμνυμι τοὺς βασιλείους ἦ μὴν παραλυθήσεσθαι τῆς πρὸς σὲ ἐπὶ γάμῳ κοινωνίας. ὁ δὲ αὖ τοῦτο μὲν τῶν ὀνειδῶν τὴν καθ’ ἡμέραν ἀχθηδόνα μὴ φέρων, τοῦτο δὲ τῆς γυναικὸς τὴν μεγαλοφροσύνην δεδιώς, μὴ παραλύοιτο αὐτοῦ τῶν γάμων, ἄκων μὲν καὶ μὴ βουλόμενος συνάγει δ’ οὖν στρατὸν ὅσον ἐδύνατο πλεῖστον καὶ ἤλαυνεν οὐκ ἀνασχετὸν ὑπολαμβάνων ἔτι καὶ αὐτὸς τὴν σωτηρίαν, εἰ Παρθυαῖος ὢν ὑπὸ Ἰουδαίου περιωθοῖτο ἀντιπολεμοῦντος.", "st": "18.9.6"}, {"sp": "N", "t": "Ἀνιλαῖος δὲ ὡς μανθάνει προσελαύνοντα δυνάμει πολλῇ τὸν Μιθριδάτην ἄδοξον ἡγησάμενος τὸ μένειν ἐν τοῖς ἕλεσιν, ἀλλὰ μὴ φθάσας ὑπαντιάζειν τοὺς πολεμίους, εὐτυχίᾳ τε τῇ πρότερον ἐλπίζων ὅμοια πράξειν καὶ τήν τε ἀρετὴν τοῖς τολμῶσι καὶ εἰωθόσιν θαρρεῖν παρατυγχάνειν, ἐξῆγε τὴν δύναμιν. πολλοί τε πρὸς τῷ οἰκείῳ στρατῷ προσεγεγόνεσαν αὐτῷ καθ’ ἁρπαγὴν τῶν ἀλλοτρίων τραπησόμενοι καὶ ὄψει πᾶν προεκπλήξοντες τοὺς πολεμίους. προϊοῦσι δὲ αὐτοῖς εἰς σταδίους ἐνενήκοντα καὶ διὰ τῆς ἀνύδρου τῆς πορείας γενομένης καὶ μεσημβρίας τά τε ἄλλα περιῆν τότε τὸ δίψος καὶ Μιθριδάτης ἐπιφανεὶς προσέβαλε τεταλαιπωρημένοις ἀπορίᾳ τοῦ πιεῖν καὶ δι’ αὐτὸ καὶ τὴν ὥραν φέρειν τὰ ὅπλα μὴ δυναμένοις. τροπή τε οὖν γίνεται τῶν περὶ τὸν Ἀνιλαῖον διὰ τὸ ἀπηγορευκότας ἀκραιφνέσι προσφέρεσθαι καὶ φόνος πολὺς πολλαί τε μυριάδες ἔπεσον ἀνδρῶν, Ἀνιλαῖος δὲ καὶ ὅσον περὶ αὐτὸν ἦν συνεστηκὸς ἐπὶ τῆς ὕλης ἐπανεχώρουν φυγῇ μεγάλην νίκης τῆς ἐπ’ αὐτοῖς χαρὰν Μιθριδάτῃ παρεσχηκότες. Ἀνιλαίῳ δὲ προσῄει πλῆθος ἄπορον ἀνδρῶν πονηρῶν ἐν ὀλίγῳ τὴν σωτηρίαν ποιουμένων ῥᾳστώνης χάριτι τῆς εἰς τὸ παρόν, ὥστε ἀντανίσωμα τὴν τούτων πρόσοδον γενέσθαι πλῆθος τῶν ἀπολωλότων· οὐ μὴν ὅμοιοί γε ἦσαν τοῖς πεπτωκόσι διὰ τὸ ἀμελέτητον. οὐ μὴν ἀλλὰ καὶ ταύταις ἐπιφοιτᾷ ταῖς κώμαις τῶν Βαβυλωνίων ἀνάστατά τε ἦν πάντα ταῦτα ὑπὸ τῆς Ἀνιλαίου ὕβρεως. καὶ οἱ Βαβυλώνιοι καὶ οἱ ὄντες ἐν τῷ πολέμῳ πέμπουσιν ἐς τὰ Νέερδα πρὸς τοὺς ἐν αὐτῇ Ἰουδαίους Ἀνιλαῖον ἐξαιτούμενοι, καὶ μὴ δεξομένοις τὸν λόγον τοῦτον, οὐδὲ γὰρ βουλομένοις ἔκδοτον παρασχεῖν δυνηθῆναι, εἰρήνην προυκαλοῦντο· οἱ δὲ καὐτοὶ χρῄζειν ἔλεγον τῶν ἐπὶ τῆς εἰρήνης συμβάσεων καὶ πέμπουσι μετὰ τῶν Βαβυλωνίων ἄνδρας, οἳ διαλέξοιντο πρὸς τὸν Ἀνιλαῖον. οἱ δὲ Βαβυλώνιοι κατοπτίας αὐτοῖς γενομένης μαθόντες τὸ χωρίον, ἐν ᾧ ἱδρυμένος ὁ Ἀνιλαῖος ἦν, ἐπιπεσόντες κρύφα νυκτὸς μεθύουσι καὶ καθ’ ὕπνον τετραμμένοις κτείνουσιν ἀδεῶς πάντας ὅσους ἐγκατέλαβον καὶ Ἀνιλαῖον αὐτόν.", "st": "18.9.7"}, {"sp": "N", "t": "Βαβυλώνιοι δὲ ἀπαλλαγέντες τῆς Ἀνιλαίου βαρύτητος, ἐπιστόμισμα γὰρ ἦν αὐτῶν μίσει τῷ πρὸς τοὺς Ἰουδαίους, ἀεὶ γὰρ ὡς ἐπὶ πολὺ διάφοροι καθεστήκεσαν αἰτίᾳ τῆς ἐναντιώσεως τῶν νόμων καὶ ὁποτέροις παραγένοιτο θαρρεῖν πρότεροι ἀλλήλων ἥπτοντο εἰ μὴ καὶ τότε οὖν ἀπολωλότων τῶν περὶ τὸν Ἀνιλαῖον ἐπετίθεντο τοῖς Ἰουδαίοις οἱ Βαβυλώνιοι. οἱ δ’ ἐν δεινῷ τιθέμενοι τὴν ὕβριν τὴν ἐκ τῶν Βαβυλωνίων καὶ μήτε ἀντιτάξασθαι μάχῃ δυνάμενοι μήτε ἀνεκτὸν ἡγούμενοι τὴν συνοικίαν ᾤχοντο εἰς Σελεύκειαν τῶν ἐκείνῃ πόλιν ἀξιολογωτάτην Σελεύκου κτίσαντος αὐτὴν τοῦ Νικάτορος. οἰκοῦσιν δ’ αὐτὴν πολλοὶ μὲν Μακεδόνων, πλεῖστοι δὲ Ἕλληνες, ἔστιν δὲ καὶ Σύρων οὐκ ὀλίγον τὸ ἐμπολιτευόμενον. εἰς μὲν δὴ ταύτην καταφεύγουσιν οἱ Ἰουδαῖοι καὶ ἐπὶ μὲν πέντε ἔτη ἀπαθεῖς κακῶν ἦσαν, τῷ δὲ ἕκτῳ ἔτει μετὰ τὸ πρῶτον φθορὰ ἐν Βαβυλῶνι ἐγένετο αὐτῶν καὶ καιναὶ κτίσεις ἐκ τῆς πόλεως καὶ δι’ αὐτὴν ἄφιξις εἰς τὴν Σελεύκειαν ἐκδέχεται μείζων αὐτοὺς συμφορὰ δι’ αἰτίαν, ἣν ἀφηγήσομαι.", "st": "18.9.8"}, {"sp": "N", "t": "Σελευκέων τοῖς Ἕλλησι πρὸς τοὺς Σύρους ὡς ἐπὶ πολὺ ἐν στάσει καὶ διχονοίᾳ ἐστὶν ὁ βίος καὶ κρατοῦσιν οἱ Ἕλληνες. τότε οὖν συνοικούντων αὐτοῖς Ἰουδαίων γενομένων ἐστασίαζον, καὶ οἱ Σύροι καθυπέρτεροι ἦσαν ὁμολογίᾳ τῇ Ἰουδαίων πρὸς αὐτοὺς φιλοκινδύνων τε ἀνδρῶν καὶ πολεμεῖν προθύμως ἐντεταγμένων. καὶ οἱ Ἕλληνες περιωθούμενοι τῇ στάσει καὶ μίαν ὁρῶντες αὐτοῖς ἀφορμὴν τοῦ ἀνασώσασθαι τὸ πρότερον ἀξίωμα, εἰ δυνηθεῖεν παῦσαι ταὐτὸν λέγοντας Ἰουδαίους καὶ Σύρους, διελέγοντο ἕκαστοι πρὸς τῶν Σύρων τοὺς αὐτοῖς συνήθεις πρὸ τοῦ γεγονότας εἰρήνην τε καὶ φιλίαν ὑπισχνούμενοι. οἱ δὲ ἐπείθοντο ἄσμενοι. ἐγίνοντο οὖν ἀφ’ ἑκατέρων λόγοι καὶ τῶν πρώτων παρ’ ἑκατέροις ἀνδρῶν προασσόντων ἐπιδιαλλαγὰς τάχιστα ἡ σύμβασις ἐγένετο, ὁμονοήσαντές τε μέγα τεκμήριον ἑκάτεροι εὐνοίας [παρ’] ἀλλήλοις ἠξίουν παρασχεῖν τὸ πρὸς τοὺς Ἰουδαίους ἔχθος, ἐπιπεσόντες τε αἰφνίδιον αὐτοῖς κτείνουσι μυριάδας ὑπὲρ πέντε ἀνδρῶν, ἀπώλοντό τε πάντες πλὴν εἴ τινες ἐλέῳ φίλων ἢ γειτόνων ἐπιχωρηθὲν αὐτοῖς ἔφυγον. τούτοις δὲ ἦν εἰς Κτησιφῶντα ἀποχώρησις πόλιν Ἑλληνίδα καὶ τῆς Σελευκείας πλησίον κειμένην, ἔνθα χειμάζει τε ὁ βασιλεὺς κατὰ πᾶν ἔτος καὶ πλείστη τῆς ἀποσκευῆς αὐτοῦ τῇδε ἀποκειμένη τυγχάνει. ἀσύνετα δὲ ἦν αὐτοῖς τὴν ἵδρυσιν πεποιημένοις τιμῇ τῆς βασιλείας Σελευκέων πεφροντικότων. ἐφοβήθη δὲ καὶ πᾶν τὸ τῇδε Ἰουδαίων ἔθνος τούς τε Βαβυλωνίους καὶ τοὺς Σελευκεῖς, ἐπειδὴ καὶ ὁπόσον ἦν Σύρων ἐμπολιτεῦον τοῖς τόποις ταὐτὸν ἔλεγον τοῖς Σελευκεῦσιν ἐπὶ πολέμῳ τῷ πρὸς τοὺς Ἰουδαίους. καὶ συνελέγησαν ὥστε πολὺ εἴς τε τὰ Νέερδα καὶ τὴν Νίσιβιν ὀχυρότητι τῶν πόλεων κτώμενοι τὴν ἀσφάλειαν, καὶ ἄλλως πληθὺς ἅπασα μαχίμων ἀνδρῶν κατοικεῖται. καὶ τὰ μὲν κατὰ Ἰουδαίους τοὺς ἐν τῇ Βαβυλωνίᾳ κατῳκημένους τοιαῦτα ἦν.", "st": "18.9.9"}, {"sp": "HDR", "t": "Βιβλίον ΙΘʹ", "st": "19"}, {"sp": "N", "t": "Γάιος δὲ οὐκ εἰς μόνους Ἰουδαίους τοὺς ἐν Ἱεροσολύμοις καὶ τοὺς ὁπόσοι τῇδε οἰκοῦσιν ἐπεδείκνυτο τῆς ὕβρεως τὴν μανίαν, ἀλλὰ διὰ πάσης ἐσομένην γῆς καὶ θαλάσσης ἔστελλεν αὐτήν, ὁπόση Ῥωμαίοις ὑπακούει, μυρίων τε ἀνέπλησεν αὐτὴν κακῶν ὁπόσα μὴ ἱστόρητο πρότερον. μάλιστα δὲ ᾐσθάνετο τοῦ δεινοῦ τῶν πρασσομένων ἡ Ῥώμη κατ’ οὐδὲν αὐτὴν τιμιωτέραν τῶν λοιπῶν πόλεων ἡγουμένου, ἀλλὰ τούς τε ἄλλους ἄγοντος καὶ φέροντος καὶ μάλιστα τὴν σύγκλητον καὶ ὁπόσοι τούτων εὐπατρίδαι καὶ προγόνων ἐπιφανείαις τιμώμενοι. μυρία τε εὑρίσκετο καὶ κατὰ τῶν ἱππέων μὲν καλουμένων, ἀξιώματι δὲ καὶ δυνάμει χρημάτων ὅμοια τοῖς συγκλητικοῖς ὑπὸ τῆς πόλεως ἀγομένων διὰ τὸ ἐκ τούτων εἰς τὴν βουλὴν εἶναι κατακλήσεις· ὧν ἀτίμωσις ἦν καὶ μετανάστασις κτεινομένων τε καὶ τὰ χρήματα συλωμένων διὰ τὸ καὶ τὰς σφαγὰς ὡς τὸ πολὺ ἐπ’ ἀφαιρέσει τῶν χρημάτων αὐτοῖς συντυγχάνειν. ἐξεθείαζέν τε ἑαυτὸν καὶ τὰς τιμὰς οὐκέτ’ ἀνθρωπίνως ἠξίου γίνεσθαι παρὰ τῶν ὑπηκόων αὐτῷ· εἴς τε τοῦ Διὸς φοιτῶν τὸ ἱερόν, ὃ Καπετώλιον μὲν καλοῦσιν τιμιώτατον δ’ ἄρα αὐτοῖς ἐστιν ἱερῶν, ἀδελφὸν ἐτόλμησε προσαγορεύειν τὸν Δία· καὶ τἆλλα ἔπρασσεν μανίας οὐδὲν ἀπολελειμμένα, ἐπεὶ καὶ ἀπὸ Δικαιαρχείας τῆς πόλεως ἐν Καμπανίᾳ κειμένης εἰς Μισηνοὺς ἑτέραν πόλιν ἐπιθαλάσσιον, καὶ τὴν διάβασιν δεινὸν ἡγούμενος τριήρει περατοῦν, καὶ ἄλλως ἐπιβάλλειν ἡγούμενος αὐτῷ δεσπότῃ ὄντι τῆς θαλάσσης ταῦτα καὶ ὁποῖα καὶ παρὰ γῆς ἀπαιτεῖν, ἀπ’ ἄκρων ἐπ’ ἄκρα σταδίους τριάκοντα μέτρον τῆς θαλάσσης [ζεύξας] καὶ εἴσω τὸν κόλπον ἀπολαβὼν πάντα ἤλαυνεν ἐπὶ τῇ γεφύρᾳ τὸ ἅρμα· θεῷ γὰρ ὄντι τοιαύτας ποιεῖσθαι καλῶς ἔχειν τὰς ὁδούς. τῶν τε ἱερῶν τῶν Ἑλληνικῶν οὐδὲν ἔτι ἀσύλητον κατέλιπεν, ὁπόσα γραφῆς ἢ γλυφῆς ἐχόμενα καὶ τὰς λοιπὰς κατασκευὰς ἀνδριάντων καὶ ἀναθημάτων ἄγεσθαι κελεύσας παρ’ αὐτόν· οὐ γὰρ ἐν ἑτέρῳ τὰ καλὰ κεῖσθαι καλῶς ἔχειν ἢ ἐν τῷ καλλίστῳ, τυγχάνειν δὲ τοῦτο οὖσαν τὴν Ῥωμαίων πόλιν. ἐκόσμει τε τοῖς ἐνθένδε ἀγομένοις τήν τε οἰκίαν καὶ τοὺς κήπους ὁπόσαι τε αὐτῷ καταγωγαὶ διὰ γῆς τῆς τῶν Ἰταλῶν. ἐπεὶ καὶ τὸν Ὀλύμπιον τιμώμενον Δία ὑπὸ τῶν Ἑλλήνων καὶ οὕτως ὠνομασμένον Ὀλύμπιον Φειδίου τοῦ Ἀθηναίου πεποιηκότος ἐτόλμησε κελεῦσαι εἰς τὴν Ῥώμην μεταφέρειν. οὐ μὴν ἔπραξέν γε τῶν ἀρχιτεκτόνων φαμένων πρὸς Μέμμιον Ῥῆγλον, ὃς ἐπετέτακτο τῇ κινήσει τοῦ Διός, ἀπολεῖσθαι τοὖργον κινήσεως αὐτοῦ γενομένης. λέγεται δὲ Μέμμιον διὰ ταῦτα καὶ σημείων μειζόνων γενομένων, ἢ ὡς ἄν τινα μὴ πιστὰ ἡγεῖσθαι, ὑπερβαλέσθαι τὴν ἀναίρεσιν. καὶ γράφει τάδε πρὸς τὸν Γάιον ἐπ’ ἀπολογίᾳ τοῦ ἐκλιπεῖν ἀδιακόνητον τὴν ἐπιστολήν, ἀπολέσθαι τε ἐκ τούτων αὐτῷ κινδύνου γενομένου σώζεται φθάνοντος ἤδη Γαΐου τελευτῆσαι.", "st": "19.1.1"}, {"sp": "N", "t": "Εἰς τοῦτο δὲ προύβη τὸ μανικὸν αὐτῷ, ὥστε δὴ καὶ θυγατρὸς αὐτῷ γενομένης ἀνακομίσας ἐπὶ τὸ Καπετώλιον ἐπὶ τοῖς γόνασι κατατίθεται τοῦ ἀγάλματος, κοινὸν αὐτῷ τε καὶ τῷ Διὶ γεγονέναι τὸ τέκνον καὶ δύο χειροτονεῖν αὐτῆς πατέρας, ὁπότερον μείζονα φάμενος ἐν μέσῳ τε καταλιμπάνειν. καὶ τάδε ἠνείχοντο πράσσοντα αὐτὸν οἱ ἄνθρωποι. ἐπεχείρησε δὲ καὶ τοῖς οἰκέταις κατηγορίας ποιεῖσθαι τῶν δεσποτῶν ἐφ’ οἷστισιν ἐθελήσειαν ἐγκλήμασιν· δεινὰ γὰρ πάντα ἦν, ὁπόσα μέλλοι λέγεσθαι, διὰ τὸ χάριτί τε καὶ ὑπαγορεύσει τῇ ἐκείνου τὰ πολλὰ γίνεσθαι, ὥστε ἤδη καὶ Κλαυδίου ἐτόλμα ποιήσασθαι Πολυδεύκης ὁ δοῦλος κατηγορίαν, καὶ Γάιος ἠνείχετο κατὰ πατρῴου τοῦ αὐτοῦ δίκης θανάτου λεγομένης ἐπ’ ἀκροάσει συνελθεῖν ἐλπίδι τοῦ παραλαβεῖν δύναμιν ἀνελεῖν αὐτόν. οὐ μὴν ἐξεγένετό γε αὐτῷ. ἀναπεπληρωκότι δὲ αὐτῷ συκοφαντιῶν καὶ κακῶν πᾶσαν τὴν οἰκουμένην, ἧς ἐπῆρχεν, καὶ πολλὴν τὴν δουλοκρατίαν ἐπῃρμένου τοῖς δεσπόταις ἐπιβουλαὶ τὰ πολλὰ ἤδη συνίσταντο, τῶν μὲν ἐπ’ ἀμύνῃ ὧν πάθοιεν ὀργὴν ποιουμένων, τῶν δὲ πρὶν ἐμπεσόντες κακῶν τυχεῖν μεγάλων τιθεμένων τὸ μεταχειρίσασθαι τὸν ἄνθρωπον. ὅθεν, ἐπειδὴ τοῖς τε ἁπάντων νόμοις καὶ τῷ ἀσφαλεῖ μεγάλην συνήνεγκεν εὐδαιμονίας ῥοπὴν ὁ θάνατος αὐτοῦ ἔθνει τε τῷ ἡμετέρῳ οὐδὲ εἰς ὀλίγον ἐξεγεγόνει μὴ οὐκ ἀπολωλέναι μὴ ταχείας αὐτῷ τελευτῆς παραγενομένης, βούλομαι [δὲ] δι’ ἀκριβείας τὸν πάντα περὶ αὐτοῦ λόγον διελθεῖν, ἄλλως τε ἐπειδὴ καὶ πολλὴν ἔχει πίστιν τοῦ θεοῦ τῆς δυνάμεως καὶ παραμυθίαν τοῖς ἐν τύχαις κειμένοις καὶ σωφρονισμὸν τοῖς οἰομένοις ἀίδιον τὴν εὐτυχίαν, ἀλλὰ μὴ ἐπιμεταφέρειν κακῶς ἀρετῆς αὐτῇ μὴ παραγενομένης.", "st": "19.1.2"}, {"sp": "N", "t": "Ὁδοὺς μὲν δὴ τρεῖς ὁ θάνατος αὐτοῦ παρεσκευάζετο καὶ τούτων ἑκάστης ἄνδρες ἀγαθοὶ τὴν ἡγεμονίαν εἶχον. Αἰμίλιός τε γὰρ Ῥῆγλος ἐκ Κορδύβης τῆς ἐν Ἰβηρίᾳ γένος συνεῖχέν τινας ἢ δι’ ἐκείνων ἢ δι’ αὐτοῦ πρόθυμος ὢν ἄρασθαι Γάιον. ἑτέρα δὲ αὐτοῖς συνεκροτεῖτο, ἧς Χαιρέας Κάσσιος χιλίαρχος ἡγεμὼν ἦν. Μινουκιανὸς δὲ Ἄννιος οὐκ ὀλίγη μοῖρα τῶν ἐπὶ τὴν τυραννίδα παρεσκευασμένων ἦν. αἰτία δ’ αὐτοῖς μίσους τοῦ πρὸς Γάιον συνελθεῖν, Ῥήγλῳ μὲν τὸ ἐπὶ πᾶσιν ὀργίλον καὶ μίσει χρώμενον πρὸς τὰ μετ’ ἀδικίας ἐξαγόμενα· καὶ γὰρ ἔχει τι θυμοειδὲς ἐν τῇ διανοίᾳ καὶ ἐλευθέριον, ὑφ’ οὗ μηδὲ στέγειν προστίθεσθαι τῶν βουλευμάτων· πολλοῖς γοῦν ἀνεκοινώσατο καὶ φίλοις καὶ ἄλλοις δοκοῦσιν αὐτῷ δραστηρίοις. Μινουκιανὸς δὲ τὰ μὲν Λεπίδου τε ἐκδικία, φίλον γὰρ αὐτῷ τὰ μάλιστα ὄντα τοῦτον καὶ τῶν πολιτῶν σὺν ὀλίγοις ἀναιρεῖ Γάιος, καὶ ἄλλως φοβηθεὶς τὰ περὶ αὐτὸν διὰ τὸ πᾶσιν ὁμοίως τὸν Γάιον ἐπὶ θάνατον ἀνακειμένην ἐπαφιέναι τὴν ὀργὴν ἐπὶ τὴν ἐγχείρησιν ἐλθεῖν. Χαιρέαν δὲ αἰσχύνην φέροντα ὀνείδη τε εἰς τὴν ἀνανδρίαν ὑπὸ τοῦ Γαΐου προφερομένου, καὶ ἄλλως τὸ ἐφ’ ἡμέρᾳ κινδυνεύειν φιλίᾳ καὶ θεραπείᾳ τὴν Γαΐου τελευτὴν οὐ πάντ’ ἐλεύθερον ὑπολαμβάνων. οἱ δὲ καὶ πᾶσι κοινῇ προτεθῆναι τὴν ἐπὶ τῷ πράγματι σκέψιν τήν τε ὕβριν θεωμένοις καὶ ἐπιθυμοῦσιν ἀκμὴν ἐπ’ ἀλλήλων ἀκμάζουσαν διαφυγεῖν ἀραμένοις τὸν Γάιον· ἴσως μὲν γὰρ ἂν κατορθῶσαι, καλῶς δὲ κατορθοῦσι τηλικούτων ἀγαθῶν σχεῖν ἐπὶ σωτηρίᾳ τῆς τε πόλεως καὶ τῆς ἡγεμονίας πονοῦσι καὶ μετὰ ὀλέθρου ἅπτεσθαι τοῦ πράγματος. παρὰ πάντα δὲ Χαιρέαν ἐπείγεσθαι ὀνόματός τε ἐπιθυμίᾳ μείζονος καὶ ἄλλως ὑπὸ τοῦ ἀδεέστερον προσιέναι τῷ Γαΐῳ διὰ τὴν χιλιαρχίαν ῥᾳστώνης αὐτῷ κτείνειν ἐσομένης.", "st": "19.1.3"}, {"sp": "N", "t": "Ἐν τούτῳ δ’ ἱπποδρομίαι ἦσαν· καὶ σπουδάζεται γὰρ Ῥωμαίοις ἥδε ἡ θεωρία δεινῶς, συνίασίν τε προθύμως εἰς τὸν ἱππόδρομον καὶ ἐφ’ οἷς χρῄζοιεν δέονται τῶν αὐτοκρατόρων κατὰ πλῆθος συνελθόντες, οἱ δὲ ἀναντιλέκτους τὰς δεήσεις κρίνοντες οὐδαμῶς ἀχαριστοῦσιν. ἐκέλευον δὴ καὶ τὸν Γάιον ἐκθύμῳ τῇ ἱκετείᾳ χρώμενοι τῶν τε τελῶν ἐπανιέναι καὶ τῶν φόρων ἐπικουφίζειν τι τοῦ ἐπαχθοῦς. ὁ δ’ οὐκ ἠνείχετο, καὶ πλέον τι τῇ βοῇ χρωμένων ἄλλους ἄλλῃ διαπέμψας κελεύει τοὺς βοῶντας λαβεῖν τε καὶ μηδὲν εἰς ἀναβολὰς ἀνελεῖν προαγαγόντας. καὶ ὁ μὲν ἐκέλευε ταῦτα καὶ οἷς προσετέτακτο ἔπρασσον, πλεῖστοί τε ἦσαν οἱ ἐπὶ τοιούτοις ἀποθανόντες. καὶ ὁ δῆμος ἑώρα μέν, ἠνείχετο δὲ παυσάμενος τῆς βοῆς, ἐν ὀλίγῳ ἕνεκα τῶν χρημάτων ὀφθαλμοῖς ὁρῶντες τὴν ἐπὶ τοιούτοις παραίτησιν εἰς θάνατον αὐτοῖς φέρουσαν. ταῦτα Χαιρέαν ἐνήγαγεν μειζόνως ἅπτεσθαί τε τῆς ἐπιβουλῆς καὶ παύειν κατὰ τῶν ἀνθρώπων ἐξηγριωκότα τὸν Γάιον, καὶ πολλάκις μὲν καὶ παρὰ τὰς ἑστιάσεις ἐμέλλησεν ἐπιχειρεῖν, οὐ μὴν ἀλλ’ ἐπείχετο λογισμῷ, τὸ μὲν κτείνειν οὐκέτ’ ἐνδοιαστὸν κεκρικώς, τὸν δὲ καιρὸν περισκοπῶν, ὅπως μὴ εἰς κενόν, ἀλλ’ ἐπὶ καταπράξει τῶν βεβουλευμένων ταῖς χερσὶ χρῷτο.", "st": "19.1.4"}, {"sp": "N", "t": "Ἐστρατεύετο δὲ πολὺν ἤδη χρόνον οὐχ ἡδονῇ φέρων Γαΐου τὴν ἀναστροφήν. ἐπεὶ δὲ αὐτὸν ἵσταται Γάιος εἰσπραξόμενον τούς τε φόρους καὶ ὅσα ἄλλα καταβαλλόμενα εἰς τὸν Καίσαρος θησαυρὸν ἐφυστερήκει τοῖς καιροῖς διὰ τὸ ἐπιδιπλασιάζεσθαι τὴν δύναμιν αὐτῶν, χρόνον ἐκεῖ ποιεῖται τῇ εἰσπράξει τρόπῳ τῷ αὐτοῦ χρώμενος μᾶλλον ἢ τῇ Γαΐου προστάξει, διὰ τὸ φειδοῖ χρῆσθαι τὰς τύχας οἴκτῳ λαμβάνων τῶν ὑπὸ τὴν εἴσπραξιν εἰς ὀργὴν προυκαλεῖτο τὸν Γάιον μαλακίαν ἐπικαλοῦντα αὐτῷ τοῦ σχολῇ συνάγεσθαι αὐτῷ τὰ χρήματα. καὶ δὴ τά τε ἄλλα ὕβριζεν εἰς αὐτὸν καὶ ὁπότε τὸ σημεῖον αὐτῷ τὸ τῆς ἡμέρας καθηκούσης εἰς αὐτόν, θήλεά τε ἐδίδου τὰ ὀνόματα, καὶ ταῦτα αἰσχύνης ἀνάπλεα καὶ ταῦτα ἔπρασσεν αὐτὸς οὐκ ἀπηλλαγμένος ἔν τινων τελεταῖς μυστηρίων, ἃς αὐτὸς συνίστατο, στολάς τε ἐνδυόμενος γυναικείους καί τινων περιθέσεις πλοκαμίδων ἐπινοῶν ἄλλα τε ὁπόσα ἐπικαταψεύσασθαι θηλύτητα τῆς ὄψεως ἔμελλεν, αὐτὸς τὴν ἐπὶ τοιούτοις αἰσχύνην ἐτόλμα Χαιρέᾳ προσκαλεῖν. Χαιρέᾳ δὲ καὶ ὁπότε μὲν παραλαμβάνοι τὸ σημεῖον ὀργὴ παρίστατο, μειζόνως δ’ ὁπότε παραδιδοίη, γελώμενος ὑπὸ τῶν παραλαμβανόντων, ὥστε καὶ οἱ συγχιλίαρχοι παιδιὰν ἐποιοῦντο αὐτόν· ὁπότε γὰρ αὐτὸς μέλλοι τὸ σημεῖον παρ’ αὐτοῦ Καίσαρος κομίζειν, προύλεγόν τινα τῶν εἰωθότων φέρειν εἰς παιδιάν. διὰ ταῦτα δὲ αὐτῷ καὶ θάρσος παρίστατο κοινωνούς τινας παραλαμβάνειν, ὡς οὐκ ἐπ’ ὀλίγοις ὀργῇ χρώμενος. καὶ ἦν γὰρ Πομπήδιος συγκλητικὸς μέν, τὰς ἀρχὰς δὲ διεληλυθὼς σχεδὸν ἁπάσας, Ἐπικούρειος δ’ ἄλλως καὶ δι’ αὐτὸ ἀπράγμονος ἐπιτηδευτὴς βίου. τοῦτον ἐνδείκνυσιν Τιμίδιος ἐχθρὸς ὢν ὡς λοιδορίᾳ χρησάμενον ἀπρεπεῖ κατὰ τοῦ Γαΐου μάρτυρα παραλαμβάνων Κυιντιλίαν γυναῖκα τῶν ἐπὶ τῆς σκηνῆς ἐπιφανείᾳ τοῦ ὡραίου περισπούδαστον πολλοῖς τε οὖσαν καὶ τῷ Πομπηδίῳ. καὶ τῆς ἀνθρώπου, ψεῦδος γὰρ ἦν, δεινὸν ἡγουμένης μαρτυρίαν ἐπὶ θανάτῳ τοῦ ἐραστοῦ παρασχεῖν, βασάνων ἔχρῃζεν ὁ Τιμίδιος, καὶ Γάιος παρωξυμμένος κελεύει τὸν Χαιρέαν μηδὲν εἰς ἀναβολὰς ἀλλ’ εὐθέως βασανίζειν τὴν Κυιντιλίαν, χρώμενος τῷ Χαιρέᾳ πρός τε τὰ φονικὰ καὶ ὁπόσα στρεβλώσεως δέοιτο ὑπὸ τοῦ νομίζειν ὠμότερον διακονήσεσθαι τὴν λοιδορίαν φεύγοντα τῆς μαλακίας. Κυιντιλία δ’ ἐπὶ τὴν βάσανον ἀγομένη τῶν συνιστόρων τινὸς ἐπιβαίνει τῷ ποδὶ ἀποσημαίνουσα θαρσεῖν καὶ μὴ τὰς βασάνους αὐτῆς δεδιέναι· διοίσειν γὰρ μετ’ ἀνδραγαθίας. βασανίζει δ’ αὐτὴν ὠμῶς ὁ Χαιρέας, ἄκων μέν, κατ’ ἀνάγκας δὲ τὰς ὑπὲρ αὐτοῦ, καὶ μηδὲν ἐνδοῦσαν ἦγεν εἰς τὴν ὄψιν τὴν Γαΐου διακειμένην οὐκ ἐν ἡδονῇ τοῖς θεωροῦσι. καὶ ὁ Γάιος παθών τι πρὸς τὴν ὄψιν τῆς Κυιντιλίας δεινῶς ὑπὸ τῶν ἀλγηδόνων διακειμένης τοῦ τε ἐγκλήματος ἠφίει καὶ αὐτὴν καὶ τὸν Πομπήδιον, ἐκείνην δὲ καὶ χρημάτων δόσει τιμᾷ παραμυθίας ἐσομένων λώβης τε ἣν ἐλελώβητο εἰς τὴν εὐπρέπειαν τοῦ ἀφορήτου τῶν ἀλγηδόνων.", "st": "19.1.5"}, {"sp": "N", "t": "Ταῦτα δεινῶς ἠνίασεν τὸν Χαιρέαν ὡς αἴτιον ἀνθρώποις καὶ ὑπὸ Γαΐου παρηγορίας ἀξίοις ἐν αἰτίᾳ κακῶν τὸ ὅσον ἐπ’ αὐτοῖς γεγενημένοις, φησίν τε πρὸς Κλήμεντά τε καὶ Παπίνιον, ὧν Κλήμης μὲν ἦν ἐπὶ τῶν στρατοπέδων, Παπίνιος δὲ καὶ αὐτὸς ἦν χιλιαρχῶν, ἀλλ’ ἐπὶ φυλακῇ γε, ὦ Κλήμης, τὰ πάντα τοῦ αὐτοκράτορος ἡμῖν πράσσειν οὐκ ἐλλέλειπται· τῶν γὰρ συνομωμοκότων αὐτοῦ κατὰ τῆς ἡγεμονίας προνοίᾳ καὶ πόνοις τοὺς μὲν ἀπεκτείναμεν, τοὺς δὲ ἐστρεβλώσαμεν ἐπὶ τοσοῦτον, ὡς ἐλεεινοὺς κἀκείνῳ γενέσθαι, μετὰ πόσης τε ἀρετῆς ἡμῖν ἐξάγεται τῶν στρατιῶν; σιγήσαντος δὲ τοῦ Κλήμεντος καὶ τὸ μὲν αἰσχύνῃ φέρειν τὰ προστασσόμενα καὶ τῷ βλέμματι καὶ τῷ ἐρυθήματι παριστάντος, λόγῳ δὲ αὐτοῖς τὴν μανίαν τοῦ αὐτοκράτορος προσκαλεῖν ἄδικον ἡγουμένου προνοίᾳ τοῦ ἀσφαλοῦς, Χαιρέας ἤδη θάρσει χρώμενος ἐν λόγοις ἦν κινδύνων ἀνειμένοις πρὸς αὐτὸν τὰ κατέχοντα δεινὰ τὴν πόλιν καὶ τὴν ἀρχὴν ἐπεξιών, καὶ ὅτι λόγῳ μὲν εἴη Γάιος ὁ τὴν ἐπὶ τοιούτοις αἰτίαν προτιθέμενος, τοῖς δὲ τἀληθὲς ἐξετάζειν πειρωμένοις ἐγώ τε, ὦ Κλήμης, καὶ οὑτοσὶ ὁ Παπίνιος καὶ πρὸ ἡμῶν σύ, ταύτας Ῥωμαίοις τε καὶ τῷ παντὶ ἀνθρωπείῳ τὰς στρέβλας προσφερόμενοι, οὐκ ἐπιτάγμασιν τοῖς Γαΐου διακονούμενοι, γνώμῃ δὲ τῇ αὐτῶν, εἰ παρὸν παῦσαι τοσαύτῃ ἤδη χρώμενον ὕβρει εἴς τε τοὺς πολίτας καὶ τοὺς ὑπηκόους διακονούμεθα, δορυφόροι καὶ δήμιοι καθεστηκότες ἀντὶ στρατιωτῶν καὶ τὰ ὅπλα ταυτὶ φέροντες οὐχ ὑπὲρ ἐλευθερίας οὐδ’ ἀρχῆς τῶν Ῥωμαίων, ἀλλ’ ἐπὶ σωτηρίᾳ τοῦ δουλουμένου τά τε σώματα αὐτῶν καὶ τὰ φρονήματα, μιαινόμενοι τῷ καθ’ ἡμέραν αἵματι σφαγῆς καὶ βασάνου τῆς ἐκείνων, μέχρι δή τις καὶ καθ’ ἡμῶν διακονήσεται τοιαῦτα Γαΐῳ. οὐ γὰρ εὐνοίᾳ γε πολιτεύσει διὰ τάδε πρὸς ἡμᾶς, δι’ ὑφοράσεως δὲ μᾶλλον καὶ ἄλλως τοῦ πολλοῦ τῶν ἀπολλυμένων ἀποδεδωκότος· οὐ γὰρ δὴ στήσεταί ποτε Γαΐῳ τὰ τῆς ὀργῆς διὰ τὸ μὴ δίκην ἀλλ’ ἡδονὴν πέρας αὐτῆς τυγχάνειν· σκοποὶ δὲ προσκεισόμεθα καὐτοί, δέον καὶ τοῖς πᾶσιν τὸ ἀνεπιβούλευτόν τε καὶ ἐλεύθερον βεβαιοῦν καὶ ἡμῖν κινδύνων ἀπαλλαγὰς ψηφίσασθαι.", "st": "19.1.6"}, {"sp": "N", "t": "Κλήμης δὲ τὴν μὲν διάνοιαν τὴν Χαιρέου φανερὸς ἦν ἐπαινῶν, σιγᾶν δ’ ἐκέλευε, μὴ καὶ φοιτῶντος εἰς πλείονας τοῦ λόγου καὶ διαχεομένων ὁπόσα κρύπτεσθαι καλῶς ἔχοι πρὶν τυχεῖν πράξαντας ἐκπύστου τοῦ ἐπιβουλεύματος γενομένου κολασθεῖεν, χρόνῳ δὲ τῷ αὖθις καὶ τῇ ἀπ’ αὐτοῦ ἐλπίδι παραδιδόναι τὰ πάντα ὡς παραγενησομένης τινὸς αὐτοῖς ἐπικουρίας τυχαίου· αὐτὸν μὲν γὰρ ὑπὸ γήρως ἀφῃρῆσθαι τὴν ἐπὶ τοιοῖσδε τόλμαν, τῶν μέντοι γε ὑπὸ σοῦ, Χαιρέα, συντεθέντων τε καὶ ῥηθέντων ἀσφαλέστερα μὲν ἴσως ἂν ὑποθοίμην, εὐπρεπέστερα δὲ πῶς ἄν τις καὶ δύναιτο; καὶ Κλήμης μὲν ὡς αὑτὸν ἀναλύει διὰ λογισμῶν τῶν τε ἀκροαθέντων καὶ ὁπόσων αὐτὸς εἰρήκει περιφερόμενος. Χαιρέας δὲ δείσας ὡς Κορνήλιον Σαβῖνον ἠπείγετο καὶ αὐτὸν μὲν χιλίαρχον ὄντα, ἀξιόλογον δ’ ἄλλως ἐξεπιστάμενος αὐτὸν καὶ τοῦ ἐλευθέρου ἐραστὴν καὶ δι’ αὐτὸ τῇ καταστάσει τῶν πραγμάτων πολεμίως διακείμενον, χρῄζων ἐκ τοῦ ὀξέος ἔχεσθαι τῶν ἐγνωσμένων τῆς ἐγχειρήσεως ὑπ’ αὐτοῦ καλὰ νομίσας εἶναι προσθέσθαι καὶ δέει, μὴ ὑπὸ Κλήμεντος ἐκφοίτησις γένοιτο αὐτῶν, ἄλλως τε τὰς μελλήσεις καὶ τῶν καιρῶν τὰς ὑπερβολὰς πρὸς τῶν ὑπερβαλλομένων τιθέμενος.", "st": "19.1.7"}, {"sp": "N", "t": "Ἐπεὶ δὲ ἀσμένῳ καὶ τῷ Σαβίνῳ τὰ πάντα ἦν, ἅτε καὶ αὐτῷ γνώμης μὲν οὐχ ὑστεροῦντι τῆς ἴσης, ἀπορίᾳ δὲ πρὸς ὅντινα εἰπὼν ἀσφαλὴς εἴη τὰ πρὸς ἐκείνους σιγῇ παραδιδόντος, ἐπεί τε ἀνδρὸς ηὐπόρητο οὐ μόνον στέγειν ὧν πύθοιτο προσθησομένου, ἀλλὰ καὶ γνώμην φανεροῦντος τὴν αὐτοῦ, πολλῷ μᾶλλον ἦρτο, καὶ μηδὲν εἰς ἀναβολὰς ἐδεῖτο τοῦ Χαιρέου. τρέπονταί τε ὡς Μινουκιανόν, αὐτοῖς μὲν ἐπιτηδεύσει ἀρετῆς καὶ τῷ ὁμοζήλῳ τοῦ μεγαλόφρονος συγγενῆ, Γαΐῳ δ’ ὕποπτον τῆς Λεπίδου τελευτῆς, πάνυ γὰρ δὴ φίλοι ἐγένοντο Μινουκιανός τε καὶ Λέπιδος, καὶ δείματι κινδύνων τῶν καθ’ αὑτόν. πᾶσι γὰρ τοῖς ἐν τέλει φοβερὸς ἦν Γάιος, ὡς ἐπ’ αὐτὸν ἕκαστον καὶ πρὸς οὕστινας τῇ μανίᾳ χρῆσθαι μὴ ἀφησόμενος, φανεροί τε ἀλλήλοις ἦσαν τῆς ἐπὶ πράγμασιν ἀχθηδόνος, διασαφεῖν μὲν ἀλλήλοις ἄντικρυς τὴν διάνοιαν καὶ μῖσος τὸ πρὸς Γάιον φόβῳ τε κινδύνων ἀφέμενοι ἄλλως τε αἰσθανόμενοι τοῦ ἀλλήλων μίσους πρὸς τὸν Γάιον καὶ δι’ αὐτὸ εὐνοίᾳ χρῆσθαι τὰ πρὸς ἀλλήλους μὴ ἀπηλλαγμένοι.", "st": "19.1.8"}, {"sp": "N", "t": "Γενομένων δ’ αὐτοῖς ἀξιώσεων ἐπείπερ συνέβαλον, εἰωθότες καὶ πρότερον ὁπότε συνέλθοιεν τίμιον ἡγεῖσθαι τὸν Μινουκιανὸν ὑπεροχῇ τε ἀξιώματος, γενναιότατος γὰρ ἦν τῶν πολιτῶν, καὶ τῷ ἐπὶ πᾶσιν ἐπαινουμένῳ, μᾶλλον ὡς ἅπτοιτό τινος λόγου φθάσαι κἀκεῖνος εἴ ποτε Χαιρέαν, ὅ τι καὶ παραλάβοι σημεῖον τῆς ἡμέρας ἐκείνης· ἀοίδιμος γὰρ διὰ τῆς πόλεως ἦν ἡ εἰς τὸν Χαιρέαν διὰ τῶν σημείων τῆς δόσεως πρασσομένη ὕβρις. ὁ δὲ χάρματι τοῦ λόγου μηδὲν μελλήσας ἠμείβετο τοῦ Μινουκιανοῦ τὸ ἐπὶ τοιοῖσδε πιστεῦσαν ὁμιλίᾳ χρήσασθαι πρὸς αὐτόν, καί σύ μοι δίδως, εἶπεν, σημεῖον ἐλευθερίας, χάρις δέ σοι τοῦ ἀνεγείραντός με μειζόνως ἤπερ εἴωθα ἐμαυτὸν ὁρμᾶν, οὐδέν μοι χρεία πλειόνων ἔτι λόγων, οἵ με θαρσοῖεν, εἰ δὴ καὶ σοὶ ταῦτα δοκεῖ, γνώμης τε τῆς αὐτῆς κοινωνοὶ καὶ πρότερον ἢ συνελθεῖν γεγόναμεν. καὶ ἓν μὲν ὑπέζωμαι ξίφος, ἀμφοῖν δ’ ἂν ἀρκέσειεν. ὥστε ἴθι καὶ ἔργων ἐχώμεθα, ἡγεμών τ’ ἴσθι, ᾗ βούλοιο αὐτὸς κελεύων με χωρεῖν, ᾗ καὶ προσοίσομαι, ἐπικουρίᾳ τῇ σῇ συμπράσσοντος τε πίσυνος. οὐδὲ ἀπορία σιδήρου τοῖς τὴν ψυχὴν εἰς τὰ ἔργα προσφερομένοις, δι’ ἣν καὶ ὁ σίδηρος δραστήριος εἴωθεν εἶναι. ὥρμηκά τε εἰς τὴν πρᾶξιν οὐχ ὧν ἂν αὐτὸς πάθοιμι ἐλπίδι περιφερόμενος· οὐ γὰρ σχολὴ κινδύνους μοι κατανοεῖν τοὺς ἐμαυτοῦ δουλώσει τε πατρίδος ἐλευθερωτάτης ἐπαλγοῦντι τῶν νόμων τῆς ἀρετῆς ἀφῃρημένης τούς τε πάντας ἀνθρώπους ὀλέθρου διὰ Γάιον κατειληφότος. ἄξιος δ’ ἂν εἴην παρὰ σοὶ δικαστῇ πίστεως ἐπὶ τοιούτοις τυγχάνειν ὑπὸ τοῦ ὅμοια φρονεῖν αὐτοῖς καὶ σὲ μὴ ἀπηλλάχθαι.", "st": "19.1.9"}, {"sp": "N", "t": "Μινουκιανὸς δὲ τὴν ὁρμὴν τῶν λόγων θεασάμενος ἠσπάζετό τε ἀσμένως καὶ προσπαρίστατο τὴν τόλμαν αὐτοῦ ἐπαινέσας τε καὶ ἀσπασάμενος μετ’ εὐχῶν καὶ ἱκετείας ἀπελύοντο. καὶ ἰσχυρίζοντό τινες ὡς βεβαιοῦν τὰ εἰρημένα εἰσιόντος γὰρ εἰς τὸ βουλευτήριον Χαιρέου φωνὴν ἐκ τοῦ πλήθους γενέσθαι τινὸς ἐπ’ ἐξορμήσει κελεύοντος περαίνειν μὲν δὴ τὸ πρακτέον καὶ προσλαμβάνειν τὸ δαιμόνιον. καὶ τὸν Χαιρέαν τὸ μὲν πρῶτον ὑπιδέσθαι, μὴ καί τινος τῶν συνωμοτῶν προδότου γεγονότος ἁλίσκοιτο, καὶ τέλος συνέντα ἐπὶ προτροπῇ φέρειν πρῶτον εἴτε παραινέσει τῶν συνεγνωκότων ἀντισημαίνοντός τινος, εἴτε δὴ καὶ τοῦ θεοῦ, ὃς ἐφορᾷ τὰ ἀνθρώπινα, αἴροντος αὐτόν. διεληλύθει δὲ διὰ πολλῶν τὸ ἐπιβούλευμα καὶ πάντες ἐν ὅπλοις παρῆσαν, οἱ μὲν τῶν βουλευτῶν ὄντες οἱ δὲ ἱππεῖς καὶ ὁπόσοι τοῦ στρατιωτικοῦ συνῄδεσαν· οὐδεὶς γὰρ ἦν, ὃς μὴ ἐν εὐδαιμονίᾳ ἂν ἠρίθμει τὴν Γαΐου μετάστασιν· καὶ δι’ αὐτὸ πάντες ἠπείγοντο ὁποίῳ δύναιτό τις τρόπῳ μηδὲ ἑκὼν εἶναι τῆς ἐπὶ τοιούτοις ἀρετῆς ὑστερεῖν, ἀλλ’ ὡς ἔχοι προθυμίας ἢ δυνάμεως καὶ λόγοις καὶ δι’ ἔργων ἦρτο ἐπὶ τῇ τυραννοκτονίᾳ, ἐπεὶ καὶ Κάλλιστος, ἀπελεύθερος δ’ ἦν Γαΐου πλεῖστά τε ἀνὴρ εἷς οὗτος ἐπὶ μέγιστον δυνάμεως ἀφίκετο καὶ οὐδὲν ἄλλο ἢ ἰσοτύραννον εἶχε τὴν δύναμιν φόβῳ τε τῶν πάντων καὶ μεγέθει χρημάτων, ἅπερ ἐγένετο αὐτῷ· δωροδοκώτατος γὰρ ἦν καὶ ὑβριστότατος παρ’ ὁντινοῦν γίνεται, ἐξουσίᾳ χρησάμενος παρὰ τὸ εἰκός· καὶ ἄλλως τε τοῦ Γαΐου τὴν φύσιν ἐξεπιστάμενος ἀνήκεστον οὖσαν καὶ ἐφ’ οἷστισι κρίνειεν οὐδαμῶς ἀντισπάσματι χρωμένην, αὐτῷ τε πολλὰς μὲν καὶ ἄλλας αἰτίας τοῦ κινδυνεύειν, οὐχ ἥκιστα δὲ τὸ μέγεθος τῶν χρημάτων· ὥστε δὴ καὶ Κλαύδιον ἐθεράπευε κρυπτῶς μετακαθίζων πρὸς αὐτὸν ἐλπίδι τοῦ κἂν εἰς ἐκεῖνον ἥξειν τὴν ἡγεμονίαν Γαΐου μεταστάντος, αὐτῷ τὴν ὑπόθεσιν τῆς τιμῆς τὴν ἐφ’ ὁμοίοις ἰσχὺν προκαταθέμενος χάριν καὶ φιλανθρωπίας λόγον. ἐτόλμησεν γοῦν εἰπεῖν, ὡς κελευσθεὶς διαχρήσασθαι φαρμάκῳ τὸν Κλαύδιον μυρίας εὕροιτο τοῦ χρήματος τὰς ὑπερβολάς. δοκεῖν δὲ προσεποιεῖτο Κάλλιστος ἐπὶ θήρᾳ τῇ Κλαυδίου τὸν λόγον τοῦτον, ἔπειτα οὔτε Γάιος ὡρμηκὼς μεταχειρίσασθαι Κλαύδιον ἠνείχετο τῶν Καλλίστου προφάσεων οὔτε Κάλλιστος κελευσθείς που τὴν πρᾶξιν εὐκτὸν ὑπελάμβανεν ἢ κακουργῶν εἰς τοῦ δεσπότου τὰς ἐπιστολὰς οὐκ ἂν ἐκ τοῦ παραχρῆμα τὸν μισθὸν ἐκομίζετο. ἀλλὰ δὴ Κλαυδίῳ μὲν ἔκ τινος θείας δυνάμεως χρήσασθαι μανιῶν τῶν Γαΐου, Κάλλιστος προσποιήσασθαι χάριτος κατάθεσιν μηδαμῶς ὑπ’ αὐτοῦ γενομένης.", "st": "19.1.10"}, {"sp": "N", "t": "Τοῖς ἀμφὶ τὸν Χαιρέαν ὑπερβολαὶ τὸ καθ’ ἡμέραν ἦσαν ὀκνούντων πολλῶν οὐ γὰρ Χαιρέας ἔσται ἑκὼν εἶναι τοῦ πράσσειν ἀναβολὴν ἐποιεῖτο, πάντα καιρὸν ἐπιτήδειον τῇ πράξει νομίζων. καὶ γὰρ εἰς τὸ Καπετώλιον ἀνιόντα καὶ τὰς θυσίας ὑπὲρ τῆς θυγατρὸς ἐπιτελουμένας ὑπὸ τοῦ Γαΐου παρῆν πολλάκις καιρός, καὶ ὑπὲρ τῆς βασιλικῆς ἱστάμενον καὶ τῷ δήμῳ χρυσίου καὶ ἀργυρίου χρήματα διαρριπτοῦντα ὦσαι κατὰ κεφαλῆς, ὑψηλὸν δ’ ἐστὶ τὸ τέγος εἰς τὴν ἀγορὰν φέρον, ἐπί τε τῶν μυστηρίων ταῖς ποιήσεσιν ἃ συνίστατο· πάντων γὰρ αὐτὸν ἀπερίοπτον εἶναι προνοίᾳ τοῦ ἐν αὐτοῖς εὐπρεπῶς ἀναστραφησομένου καὶ ἀπογνώσει τοῦ ἐν ἐπιχειρήσει τινὶ γενέσθαι πιστεύοντα εἰ δὲ μηδὲν τίμιον ὡς τῶν θεῶν αὐτῷ δύναμιν τοῦ θανάτου παρατυγχάνειν, αὐτῷ δ’ ἂν ἰσχὺν ἐγγενέσθαι καὶ μὴ σιδηροφορουμένῳ διαχρήσασθαι τότε Γάιον. οὕτως εὐχῆς εἶχε τοὺς συνωμότας ὁ Χαιρέας δεδιὼς τοὺς καιροὺς μὴ διαρρυεῖεν. οἱ δὲ ἑώρων μὲν νομίμων τε χρῄζοντα καὶ ἐπ’ ἀγαθοῖς τοῖς αὐτῶν ἐπειγόμενον, οὐ μὴν ἀλλ’ ἠξίουν εἰς ὀλίγον γοῦν ὑπερβολῇ χρήσασθαι, μὴ καί πῃ σφάλματος τῇ ἐπιχειρήσει συνελθόντος ταράξαιεν τὴν πόλιν ζητήσεων τῶν συνεγνωκότων τὴν πρᾶξιν γινομένων καὶ τοῖς αὐτοῖς μελλήσουσιν ἐπιχειρεῖν ἄπορον τὴν ἀνδραγαθίαν φραξαμένου Γαΐου πρὸς αὐτοὺς μειζόνως. καλῶς οὖν ἔχειν θεωριῶν ἐν τῷ Παλατίῳ ἐπιτελουμένων ἅπτεσθαι τοῦ χρήματος· ἄγονται δὲ ἐπὶ τιμῇ τοῦ πρώτου μεταστησαμένου τὴν ἀρχὴν τοῦ δήμου Καίσαρος εἰς αὐτὸν μικρόν τε πρὸ τοῦ βασιλείου καλύβης πηκτοῦ γενομένης, καὶ Ῥωμαίων τε οἱ εὐπατρίδαι θεωροῦσιν ὁμοῦ παισὶν καὶ γυναιξὶν καὶ ὁ Καῖσαρ· ῥᾳστώνην τε αὐτοῖς ἔσεσθαι πολλῶν μυριάδων ἀνθρώπων εἰς ὀλίγον χωρίον καθειργνυμένων ὥστε εἰσιόντι τὴν ἐπιχείρησιν ποιήσασθαι δυνάμεως τοῖς ὑπασπισταῖς, εἰ καί τινες προθυμοῖντο, μὴ παρατευξομένης αὐτῷ βοηθεῖν.", "st": "19.1.11"}, {"sp": "N", "t": "Εἴχετο δὲ Χαιρέας, καὶ τῶν θεωριῶν ἐπελθουσῶν τῇ πρώτῃ δεδογμένον ἅπτεσθαι τῆς πράξεως ἰσχυρότερον ἦν τοῦ κατ’ ἐκείνους προβεβουλευκότος τὸ τῆς τύχης συγχωροῦν ὑπερβολάς, καὶ τὰς τρεῖς ὑπερβαλλομένου ταῖς νομίμοις ἡμέραις μόλις κατὰ τὴν τελευταίαν αὐτοῖς ἐπράχθη τὸ ἔργον. Χαιρέας δὲ συγκαλέσας τοὺς συνωμότας πολὺς μέν, εἶπεν, καὶ ὁ παρεληλυθὼς χρόνος ὀνειδίσαι τὸ ἐπιμέλλον ἡμῶν ἐπὶ τοῖς οὕτω βουλευθεῖσιν μετ’ ἀρετῆς, δεινὸν δέ, εἰ καὶ μηνύματος γενομένου διαπεσεῖται ἡ πρᾶξις καὶ Γάιος ὑβριεῖ μειζόνως. ἢ οὐχ ὁρῶμεν, ὡς τῆς ἐλευθερίας ἀφαιροῦμεν ὁπόσας τῶν ἡμερῶν προσθήκην τῇ Γαΐου τυραννίδι χαριζόμεθα, δέον αὐτούς τ’ ἀδεεῖς τὸ λοιπὸν εἶναι καὶ τοῖς ἄλλοις αἰτίαν τοῦ εὐδαίμονος παρασχόντας δι’ αἰῶνος τοῦ ἅπαντος τοῖς αὖθις ἐν θαύματι μεγάλῳ καὶ τιμῇ καταστῆναι; τῶν δὲ οὔτε ἀντειπεῖν ὡς οὐ πάνυ καλοῖς δυναμένων οὔτε τὴν πρᾶξιν ἄντικρυς δεχομένων σιγῇ δὲ καταπεπληγότων τί, φησίν, ὦ γενναῖοι, διαμέλλομεν; ἢ οὐχ ὁρᾶτε τὴν σήμερον τῶν θεωριῶν ἡμέραν ὑστάτην οὖσαν καὶ Γάιον ἐκπλευσούμενον; ἐπὶ γὰρ Ἀλεξανδρείας παρεσκεύαστο πλεῖν κατὰ θεωρίαν τῆς Αἰγύπτου. καλὸν δὲ ἡμῖν προέσθαι τῶν χειρῶν τὸ ὄνειδος τῇ Ῥωμαίων μεγαλαυχίᾳ πομπεῦσον διά τε γῆς καὶ θαλάσσης. πῶς δ’ οὐκ ἂν δικαίως κρίνοιμεν αὐτοὺς αἰσχύνῃ τῶν γενησομένων, εἴ τις αὐτὸν Αἰγύπτιος κτείνειεν τὴν ὕβριν οὐχ ἡγησάμενος ἀνασχετὸν τοῖς ἐλευθέροις γεγονόσιν; ἐγὼ μὲν οὖν οὐκέτι εἰς πλείονα ἀνέξομαι τὰς σκήψεις ὑμῶν, χωρήσω δὲ τοῖς κινδύνοις ὁμοῦ σήμερον ἡδονῇ φέρων πᾶν ὅ τι καὶ γένοιτο ἐξ αὐτῶν, οὐδ’ ἂν ὑπερβαλλοίμην εἴπερ εἴη· τί γὰρ δὴ καὶ γένοιτ’ ἂν ἀνδρὶ φρόνημα ἔχοντι τούτου σχετλιώτερον, ἕτερον Γάιον ἀναιρεῖν ἐμοῦ ζῶντος ἐμὲ τὴν ἐπὶ τῷδε ἀρετὴν ἀφῃρημένον;", "st": "19.1.12"}, {"sp": "N", "t": "Καὶ ὁ μὲν ταῦτα εἰπὼν αὐτός τε ὡρμήκει πράξων τὸ ἔργον καὶ τοῖς λοιποῖς ἐνεποίησε θάρσος πᾶσίν τε ἦν ἔρως ἅπτεσθαι τοῦ ἐγχειρήματος μηδὲν ὑπερβαλλομένοις, ἕωθέν τε ἐπὶ τοῦ Παλατίου εἰώθει τὸ ξίφος ὑπεζωσμένος τῶν ἱππικῶν· ἔθος γὰρ δὴ τοῖς χιλιάρχοις τοῦτο ἐζωσμένοις αἰτεῖν παρὰ τοῦ αὐτοκράτορος τὸ σημεῖον, ἦν τε ἡ ἡμέρα καθήκουσα εἰς αὐτὸν τῆς παραλήψεως τοῦ σημείου. ἄρτι τε συνῄει πληθὺς εἰς τὸ Παλάτιον ἐπὶ προκαταλήψει θέας πολλῷ θορύβῳ καὶ ὠθισμῷ, χαρᾷ φέροντος Γαΐου τὴν ἐπὶ τοιοῖσδε τῶν πολλῶν σπουδήν, παρὸ καὶ διακέκριτο οὐδὲν οὔτε τῇ συγκλήτῳ χωρίον οὔτε τοῖς ἱππεῦσιν, φύρδην δὲ ἕζοντο καὶ τοῖς ἀνδράσιν ὁμοῦ αἱ γυναῖκες καὶ τῷ δούλῳ ἀναμεμιγμένον τὸ ἐλεύθερον. Γάιος δὲ προόδων αὐτῷ γενομένων ἔθυσε τῷ Σεβαστῷ Καίσαρι, ᾧ δὴ καὶ τὰ τῆς θεωρίας ἤγετο, καὶ πίπτοντος τῶν ἱερείων τινὸς συνέβη αἵματι τὴν Ἀσπρήνα στολὴν ἑνὸς τῶν συγκλητικῶν ἀνάπλεων γενέσθαι. τοῦτο Γαΐῳ γέλωτα μὲν παρέσχεν, ἦν δ’ ἄρα εἰς οἰωνὸν τῷ Ἀσπρήνᾳ φανερόν· ἐπικατασφάζεται γὰρ τῷ Γαΐῳ. Γάιον δ’ ἱστορεῖται παρὰ φύσιν τὴν ἑαυτοῦ εὐπροσηγορώτατον γενέσθαι κατ’ ἐκείνην τὴν ἡμέραν καὶ δεξιότητι χρώμενον ὁμιλίας πάνθ’ ὁντινοῦν ἐκπλῆξαι τῶν παρατυγχανόντων. μετὰ δὲ τὴν θυσίαν ἐπὶ τὴν θεωρίαν τραπεὶς ἐκαθέζετο καὶ περὶ αὐτὸν τῶν ἑταίρων οἱ ἀξιολογώτατοι. κατεσκεύαστο δὲ τὸ θέατρον, πηκτὸν δὲ ἐγίνετο κατὰ ἕκαστον ἐνιαυτόν, τοιόνδε τρόπον· θύρας ἔχει δύο φερούσας τὴν μὲν εἰς αἴθριον, τὴν δ’ εἰς στοὰν εἰσόδοις καὶ ἀποχωρήσεσιν, ὅπως μὴ ταράσσοιντο οἱ ἔνδον ἀπειλημμένοι, ἐκ δ’ αὐτῆς τῆς καλύβης ἐνδοτέρω διαφράγμασιν ἑτέραν ἀπειληφυίαις ἐπ’ ἀναστροφῇ τοῖς ἀνταγωνισταῖς καὶ ὁπόσα ἀκροάματα. συγκαθημένης δὲ τῆς πληθύος καὶ τοῦ Χαιρέου σὺν τοῖς χιλιάρχοις οὐκ ἄπωθεν τοῦ Γαΐου, δεξιὸν δὲ τοῦ θεάτρου κέρας ὁ Καῖσαρ εἶχεν, Βαθύβιός τις τῶν συγκλητικῶν ἀνὴρ ἐστρατηγηκὼς ἤρετο Κλούιον παρακαθεζόμενον αὐτῷ καὶ τοῦτον ὑπατικόν, εἰ δή τις αὐτῷ νεωτέρων πραγμάτων πέρι ἀφίκοιτο πύστις, προμηθὴς γενόμενος τοῦ μὴ ἐξάκουστος εἶναι τάδε λέγων. τοῦ δὲ φαμένου μηδὲν πεπύσθαι σημεῖον τοιγαροῦν, ὦ Κλούιε, τυραννοκτονίας ἀγὼν πρόκειται. καὶ ὁ Κλούιος ὦ γενναῖε, φησίν, σίγα, μή τις τ’ ἄλλος Ἀχαιῶν μῦθον ἀκούσῃ. πολλῆς δ’ ὀπώρας ἐπιχεομένης τοῖς θεωροῖς καὶ πολλῶν ὀρνέων ὁπόσα τῷ σπανίῳ τίμια τοῖς κτωμένοις, ὁ Γάιος ἡδονῇ τὰς περὶ αὐτοῖς ἐθεώρει μάχας καὶ διαρπαγὰς οἰκειουμένων αὐτὰ τῶν θεωρῶν. ἔνθα δὲ καὶ σημεῖα μανθάνει δύο γενέσθαι· καὶ γὰρ μῖμος εἰσάγεται, καθ’ ὃν σταυροῦται ληφθεὶς ἡγεμών, ὅ τε ὀρχηστὴς δρᾶμα εἰσάγει Κινύραν, ἐν ᾧ αὐτός τε ἐκτείνετο καὶ ἡ θυγάτηρ Μύρρα, αἷμά τε ἦν τεχνητὸν πολὺ καὶ περὶ τὸν σταυρωθέντα ἐκκεχυμένον καὶ τῶν περὶ τὸν Κινύραν. ὁμολογεῖται δὲ καὶ τὴν ἡμέραν ἐκείνην γενέσθαι, ἐν ᾗ Φίλιππον τὸν Ἀμύντου Μακεδόνων βασιλέα κτείνει Παυσανίας εἷς τῶν ἑταίρων εἰς τὸ θέατρον εἰσιόντα. Γαΐου δ’ ἐνδοιάζοντος, εἴτε παραμείνειεν εἰς τέλος τῇ θεωρίᾳ διὰ τὸ τελευταίαν εἶναι τὴν ἡμέραν εἴτε λουτρῷ χρησάμενος καὶ σίτῳ εἶτα ἐπανίοι καθὰ καὶ οἱ πρότερον, Μινουκιανὸς ὑπὲρ τοῦ Γαΐου καθεζόμενος καὶ δεδιώς, μὴ διαλυθείη τὰ τῶν καιρῶν εἰς κενόν, ἐξαναστὰς ἐπειδὴ καὶ Χαιρέαν ἑώρα προεξεληλυθότα, ἠπείγετο θαρσύνειν αὐτὸν προελθών. λαμβάνεται δ’ αὐτοῦ τῆς στολῆς Γάιος κατὰ φιλοφροσύνην δῆθεν καί ποῖ δή, φησίν, ὦ μακάριε; καὶ ὁ μὲν αἰδοῖ δοκεῖν τοῦ Καίσαρος καθίζει, κρείσσων δ’ ὁ φόβος ἦν ὀλίγον τε διαλιπὼν εἶτα διανίσταται. καὶ ὁ Γάιος οὐδὲν ἐμποδὼν ἦν ἐξιόντι δοκῶν ἐπί τινι τῶν ἀναγκαίων ποιεῖσθαι τὴν ἔξοδον. Ἀμβρώνας δὲ καὶ αὐτὸς παρῄνει τῷ Γαΐῳ καθὸ πρότερον ὑπεξελθόντι πρός τε λουτρῷ καὶ ἀρίστῳ γενέσθαι καὶ ἔπειτα δὲ εἰσελθεῖν, χρῄζων ἐπὶ πέρας ἀχθῆναι τὰ ἐγνωσμένα.", "st": "19.1.13"}, {"sp": "N", "t": "Καὶ οἱ περὶ τὸν Χαιρέαν ἔτασσον μὲν ἀλλήλους ᾗ καιρός τε καὶ ἐχρῆν ἕκαστον στάντα ᾗ προσταχθείη μὴ ἀπολιμπάνεσθαι ἐπιπονοῦντες. ἤχθοντο δὲ τῇ διατριβῇ καὶ τῷ μέλλεσθαι τὰ ἐν χερσίν, ἐπεὶ καὶ περὶ ἐνάτην ὥραν ἤδη τὰ τῆς ἡμέρας ἦν. καὶ Χαιρέας βραδύνοντος Γαΐου πρόθυμος ἦν ἐπεισελθεῖν ἐν τῇ καθέδρᾳ προσπεσὼν μέντοι προῄδει τοῦτο σὺν πολλῷ φόνῳ τῶν τε βουλευτῶν καὶ ὁπόσοι τῶν ἱππέων παρῆσαν καίπερ δεδιὼς πρόθυμος ἦν, καλῶς ἔχειν ἡγούμενος πᾶσιν ἀσφάλειαν καὶ ἐλευθερίαν ὠνούμενος ἐν ὀλίγῳ τίθεσθαι τὰ κατὰ τοὺς ἀπολουμένους. καὶ δὴ τετραμμένων εἰς τὸ θέατρον εἰσόδῳ σημαίνεται Γάιος ἐξαναστὰς καὶ θόρυβος ἦν, ἀνέστρεφον δὲ καὶ οἱ συνωμόται καὶ ἀνεωθοῦντο τὴν πληθύν, λόγῳ μὲν διὰ τὸ δυσχεραίνειν τὸν Γάιον, ἔργῳ δὲ ἐπ’ ἀδείας βουλόμενοι ἐν ἐρημίᾳ τῶν ἀμυνουμένων καταστήσαντες αὐτὸν ἅπτεσθαι τῆς σφαγῆς. προεξῄεσαν δὲ Κλαύδιος μὲν ὁ πάτρως αὐτοῦ καὶ Μᾶρκος Βινίκιος ὁ τῆς ἀδελφῆς ἀνὴρ ἔτι δὲ Οὐαλέριος Ἀσιατικός, οὓς οὐδὲ βουλομένοις διακλεῖσαι δύναμις ἦν αἰδοῖ τῆς ἀξιώσεως, εἵπετο δ’ αὐτὸς σὺν Παύλῳ Ἀρουντίῳ. ἐπεὶ δ’ ἐντὸς ἦν τοῦ βασιλείου, τὰς μὲν ἐπ’ εὐθείας ὁδοὺς λείπει, καθ’ ἃς διεστήκεσαν τῶν δούλων οἱ θεραπεύοντες αὐτὸν καὶ προῄεσαν οἱ περὶ τὸν Κλαύδιον· τρέπεται δὲ κατὰ στενωπὸν ἠρεμηκότα καὶ ἐπὶ τόπον πρὸς λουτροῖς γενησόμενος ἅμα καὶ παῖδας οἳ ἥκεσαν ἐκ τῆς Ἀσίας κατανοήσων, πομπῆς αὐτῶν ἐκεῖθεν γενομένης ἐπὶ ὕμνοις μυστηρίων ἃ ἐπετέλει, ἔνιοι δὲ κατὰ πυρριχισμούς, οἳ ἐν τοῖς θεάτροις ἔσοιντο. ὑπαντιάζει δ’ αὐτὸν Χαιρέας καὶ ᾔτησεν σημεῖον. τοῦ δὲ τῶν εἰς χλεύην ἀνακειμένων εἰπόντος οὐδὲν ἐνδοιάσας λοιδορίαις τε ἐχρᾶτο κατὰ τοῦ Γαΐου καὶ σπασάμενος τὸ ξίφος ἐπάγει πληγὴν σφοδράν· οὐ μήν γε ἦν καίριος. καίτοι γέ φασίν τινες προνοίᾳ τοῦ Χαιρέου γενέσθαι τοῦ μὴ μιᾷ πληγῇ διεργάσασθαι τὸν Γάιον, ἀλλὰ τιμωρεῖσθαι μειζόνως πλήθει τραυμάτων. οὐ μὴν ἐμοὶ πιθανὸς οὗτος ὁ λόγος διὰ τὸ μὴ ἐπιχωρεῖν ἐν ταῖσδε ταῖς πράξεσιν λογισμῷ χρῆσθαι τὸν φόβον, Χαιρέαν δέ, εἴπερ οὕτως ἐφρόνει, πάντων ἥγημαι μωρίᾳ διαφέρειν ἡδονὴν τῇ ὀργῇ χαριζόμενον μᾶλλον ἢ ἐκ τοῦ ὀξέος ἀπαλλαγὴν αὑτῷ τε καὶ τοῖς συνωμόταις κινδύνων χαριζόμενον, διὰ τὸ πολλὰς ἂν μηχανὰς ἔτι γενέσθαι βοηθειῶν Γαΐῳ μὴ φθάντι τὴν ψυχὴν ἀφεῖναι κἀνταῦθα Χαιρέᾳ λόγον ἂν γενέσθαι οὐ περὶ τῆς Γαΐου τιμωρίας, ἀλλὰ τῆς αὐτοῦ καὶ τῶν φίλων, ὅπου γε καὶ πράξαντι καλῶς ἂν εἶχε σιγῇ χρωμένῳ διαδιδράσκειν τὰς ὀργὰς τῶν ἀμυνομένων, οὐχ ὅπως ἄδηλον εἰ τύχοι κατορθῶν ἐπ’ ἀλόγοις χρῄζειν αὐτόν τε ἀπολέσαι καὶ τὸν καιρόν. καὶ τάδε μὲν εἰκάζειν παρέστω τοῖς βουλομένοις ᾗ καὶ θέλοιεν. ὁ δὲ Γάιος ἀλγηδόνι τῆς πληγῆς περιφερόμενος, μεσσηγὺς γὰρ τοῦ τε ὤμου καὶ τοῦ τραχήλου φερόμενον τὸ ξίφος ἐπέσχεν ἡ κλεὶς προσωτέρω χωρεῖν, οὔτε ἀνεβόησεν ὑπ’ ἐκπλήξεως οὔτε ἐπεκαλέσατό τινας τῶν φίλων εἴτε ἀπιστίᾳ εἴτε καὶ ἄλλως ἀφρονήσει, στόνῳ δὲ χρησάμενος πρὸς τῆς ἀλγηδόνος τὸ περιὸν εἰς τὸ πρόσθεν ἵετο φυγῇ. καὶ δεξάμενος αὐτὸν Κορνήλιος Σαβῖνος τὴν διάνοιαν ἤδη προκατειργασμένον ὠθεῖ καὶ κλιθέντα ἐπὶ γόνυ πολλοὶ περιστάντες ἀφ’ ἑνὸς ἐγκελεύσματος ἔκοπτον τοῖς ξίφεσιν, παρακελευσμός τε τὰ πρὸς ἀλλήλους καὶ πρὸς ἔρις αὐτοῖς ἦν. τελευταῖα δὲ Ἀκύλας, ὁμολογεῖται δὲ ὑπὸ πάντων πληγὴν ἐπαγαγών, μεθίστησιν αὐτὸν ἀκριβῶς. ἀναθείη δ’ ἄν τις τὴν πρᾶξιν Χαιρέᾳ· καὶ γὰρ εἰ σὺν πολλοῖς ἐπράχθη τὸ ἔργον αὐτῷ, ἀλλ’ οὖν πρῶτός τε ἐνεθυμήθη εἶναι μέντοι αὐτῷ ὃς προλαβὼν πολὺ τῶν ἁπάντων, καὶ πρῶτος μὲν τολμηρῶς ἐξεῖπεν τοῖς λοιποῖς, δεχομένων δὲ τὸν ἐπὶ τῷ φόνῳ λόγον σποράδας τε ἤθροισεν καὶ τὰ πάντα φρονίμως συγκροτήσας ἔνθα γνωμῶν εἰσηγήσεως ἐχρῆν πολὺ κρείσσων ἐγίγνετο καὶ λόγοις καθωμίλησεν χρηστοῖς ὡς οὐ τολμῶντας ἠνάγκασέν τε τοὺς ἅπαντας, ἐπεί τε καιρὸς ἐλάμβανεν χειρὶ χρήσασθαι, φαίνεται κἀνταῦθα πρῶτός τε ὁρμήσας καὶ ἁψάμενος ἀρετῇ τοῦ φόνου καὶ τοῖς ἄλλοις εὐεπίβατον παρασχὼν καὶ προτεθνεῶτα Γάιον, ὥστ’ ἂν δικαίως καὶ ὁπόσα τοῖς λοιποῖς εἴη πεπραγμένα τῇ Χαιρέου γνώμῃ τε καὶ ἀρετῇ προστίθεσθαι καὶ πόνῳ τῶν χειρῶν.", "st": "19.1.14"}, {"sp": "N", "t": "Καὶ Γάιος μὲν τοιούτῳ τρόπῳ χρησάμενος τῆς τελευτῆς ὑπὸ τοῦ πολλοῦ τῶν τραυμάτων ἀποψυχθεὶς ἔκειτο. οἱ δὲ περὶ τὸν Χαιρέαν ἐπειδὴ κατείργαστο αὐτοῖς ἤδη Γάιος, ὁδοὺς μὲν τὰς αὐτὰς ἰόντες σώζειν αὑτοὺς ἀμήχανον ἑώρων, ὄκνῳ τε τῶν γεγονότων, οὐ γὰρ μικρὸν ἦν τὸν αὐτοκράτορα ἀνῃρηκόσι τὸ κινδύνευμα ὑπό τε ἀνοίας τοῦ δήμου τιμώμενον καὶ ὄντα προσφιλῆ καὶ τῶν στρατιωτῶν μὴ ἀναιμωτὶ ποιησομένων τὴν ζήτησιν αὐτοῦ, ἄλλως τε στενῶν οὐσῶν τῶν ὁδῶν, καθ’ ἃς ἔπραξαν τὸ ἔργον, καὶ μεγάλου πλήθους ἐμφράξαντος αὐτὰς τῆς τε θεραπείας καὶ ὁπόσοι τῶν στρατιωτῶν ἐπὶ φυλακῇ τοῦ αὐτοκράτορος ἐκείνην παρῆσαν τὴν ἡμέραν, ὁδούς τε ἑτέρας χωροῦντες παρῆσαν εἰς τὴν Γερμανικοῦ μὲν οἰκίαν τοῦ Γαΐου πατρός, ὃν τότε ἀνῃρήκεσαν, συνημμένη δὲ ἐκείνη, διὰ τὸ ἓν τὸ βασίλειον ὂν ἐπ’ οἰκοδομίαις ἑκάστου τῶν ἐν τῇ ἡγεμονίᾳ γεγονότων ἀσκηθὲν ἀπὸ μέρους ὀνόματι τῶν οἰκοδομηθησομένων ἢ καί τι τῶν ἡμερῶν οἰκήσεις ἀρξάντων τὴν ἐπωνυμίαν παρασχέσθαι. καὶ διεκπεσόμενοι ἐκ τοῦ πλήθους τὴν ἔφοδον ἐν ἀδείᾳ τὸ παρὸν ἦσαν λανθάνοντος ἀκμὴν κακοῦ τοῦ τὸν αὐτοκράτορα παρειληφότος. πρώτους δὲ εἰς τοὺς Γερμανοὺς ἡ αἴσθησις ἀφίκετο τῆς Γαΐου τελευτῆς. δορυφόροι δ’ ἦσαν οὗτοι ὁμώνυμοι τῷ ἔθνει ἀφ’ οὗ κατειλέχατο Κελτικοῦ τάγμα παρεχόμενοι τὸ αὐτῶν. θυμῷ δὲ χρῆσθαι πάτριόν ἐστιν αὐτοῖς, ὥσπερ σπάνιον εἴ τισιν ἑτέροις βαρβάρων διὰ τὸ ἡσσόνως λογισμὸν ἐπιδέχεσθαι τῶν ποιουμένων, ῥωμαλέοι τε τοῖς σώμασι καὶ τῇ πρώτῃ ὁρμῇ συνιόντες τοῖς πολεμίοις, οὓς ἂν νομίσωσι, μεγάλα κατορθοῦντες. οὗτοι οὖν πυθόμενοι τοῦ Γαΐου τὴν σφαγὴν καὶ περιαλγήσαντες διὰ τὸ μὴ ἀρετῇ κρίνειν ἐπὶ τοῖς ὅλοις, ἀλλὰ συμφέροντι τῷ αὐτῶν, μάλιστα δὲ αὐτοῖς προσφιλὴς ἦν Γάιος δόσεσι χρημάτων τὸ εὔνουν αὑτῷ κτώμενος, σπασάμενοι τὰ ξίφη, προειστήκει δ’ αὐτῶν Σαβῖνος χιλιαρχῶν οὐ δι’ ἀρετὴν καὶ γενναιότητα προγόνων, μονομάχος γὰρ ἦν, ἰσχύι δὲ σώματος τὴν ἐπὶ τοιούτοις κτησάμενος ἄθροισιν ἀρετήν, διεξῄεσαν τῆς οἰκίας ἀνερευνώμενοι τοὺς σφαγέας τοῦ Καίσαρος. Ἀσπρήναν τε κρεουργήσασιν αὐτοῖς διὰ τὸ πρώτῳ περιπεσεῖν, οὗ τὴν στολὴν μιᾶναν τὸ αἷμα τῶν θυμάτων, ὥς μοι λέλεκται πρότερον, οὐκ ἐπ’ ἀγαθῷ τὴν συντυχίαν ἀπεσήμαινε τοῦ γεγονότος δεύτερος, Νωρβανὸς ὑπηντίαζεν ἐν τοῖς γενναιοτάτοις τῶν πολιτῶν καὶ πολλοὺς αὐτοκράτορας παρεχόμενος τῶν προπατόρων. καὶ μηδὲν αἰδουμένων αὐτοῦ τὴν ἀξίωσιν ἰσχύι προύχων ἀφαιρεῖται τὸ ξίφος τῷ πρώτῳ τῶν ἐπιόντων συμπλακεὶς φανερός τε ἦν οὐκ ἀπραγμόνως τεθνηξόμενος, μέχρι δὴ περισχεθεὶς πολλοῖς τῶν ἐπιφερομένων ἔπεσεν ὑπὸ πλήθους τραυμάτων. τρίτος δὲ Ἀντήιος τῶν ἐκ τῆς βουλῆς σὺν ὀλίγοις, οὐ τυχαίως τοῖς Γερμανοῖς καθάπερ οἱ πρότερον περιπεσών, ὑπὸ δὲ φιλοθεαμοσύνης καὶ ἡδονῆς τοῦ αὐτόπτης γενόμενος Γαΐου κειμένου μῖσος εὐφρᾶναι τὸ πρὸς αὐτόν· τὸν γὰρ πατέρα τοῦ Ἀντηίου καὶ ὁμώνυμον φυγάδα ἐλάσας καὶ μὴ ἀρκεσθεὶς κτείνει στρατιώτας ἀποπέμψας. καὶ παρῆν μὲν διὰ τάδε εὐφρανούμενος θεωρίᾳ τοῦ νεκροῦ, θορυβουμένης δὲ τῆς οἰκίας κρύπτειν αὑτὸν ἐνθυμησάμενος οὐ διαφυγγάνει τῶν Γερμανῶν τό τε εἰς τὴν ἔρευναν ἀκριβὲς κἀπὶ τοῖς φόνοις ὁμοίως τῶν τε αἰτίων καὶ μὴ ἐξαγριωσάντων. καὶ οἵδε μὲν ταύτῃ τεθνήκεσαν.", "st": "19.1.15"}, {"sp": "N", "t": "Εἰς δὲ τὸ θέατρον ἐπεὶ ἀφίκετο ὁ λόγος περὶ τῆς Γαΐου τελευτῆς, ἔκπληξίς τε καὶ ἀπιστία ἦν· οἱ μὲν γὰρ καὶ πάνυ ἡδονῇ δεχόμενοι τὸν ὄλεθρον αὐτοῦ κἂν πρὸ πολλοῦ ἡγησάμενοι σφίσιν ἀγαθὸν συνελθεῖν ὑπὸ δέους ἐν ἀπιστίᾳ ἦσαν. εἰσὶ δ’ οἷς καὶ πάνυ ἀπ’ ἐλπίδων ἦν διὰ τὸ μὴ ἐθέλειν τι τοιόνδε περὶ τῷ Γαΐῳ γεγονέναι μηδὲ ἀληθείᾳ προστίθεσθαι διὰ τὸ μὴ οἷόν τε ἀνθρώπῳ εἶναι τοιᾷδε ἀρετῇ χρῆσθαι. γύναια δ’ ἦν ταῦτα καὶ παῖδες ὁπόσοι τε δοῦλοι καί τινες τοῦ στρατιωτικοῦ, οἱ μὲν διὰ τὸ μισθοφορεῖν καὶ οὐδὲν ἀλλ’ ἢ συντυραννοῦντες καὶ διακονίᾳ τῆς κατ’ ἐκεῖνον ὕβρεως ἐπανασειόμενοι τοῖς κρατίστοις τῶν πολιτῶν τιμῆς τε ἅμα καὶ ὠφελειῶν τυγχάνειν, ἡ δὲ αὖ γυναικωνῖτις καὶ τὸ νεώτερον, ὅπερ ὄχλος φιλεῖ, θεωρίαις τε καὶ μονομαχιῶν δόσεσιν καί τινων κρεανομιῶν ἡδοναῖς ἀνειλημμένοι, ἃ ἐπράσσετο λόγῳ μὲν ἐπὶ θεραπείᾳ τῆς πληθύος, τὸ δ’ ἀληθὲς ἐκπιμπλάντα τῆς μανίας Γαΐου τὴν ὠμότητα· οἱ δὲ δοῦλοι διὰ τὸ ἐν προσηγορίᾳ τε εἶναι καὶ καταφρονήματι τῶν δεσποτῶν, ἀποστροφῆς τῷ ὑβρίζοντι αὐτὴν οὔσης τῆς κατ’ ἐκεῖνον ἐπικουρίας· ῥᾴδιον γὰρ ψευσαμένοις τε κατὰ τῶν κυρίων πεπιστεῦσθαι καὶ τὰ χρήματα ἐνδείξασιν αὐτῶν ἅμα ἐλευθέροις τε εἶναι καὶ πλουσίοις μισθῷ τῶν κατηγοριῶν διὰ τὸ ἆθλα αὐτοῖς προκεῖσθαι τὰς ὀγδόας τῶν οὐσιῶν. τῶν δὲ εὐπατριδῶν εἰ καί τισιν πιστὸς ὁ λόγος φανείη, τοῖς μὲν ἐκ τοῦ προειδέναι τὴν ἐπιβουλήν, τοῖς δ’ ὑπὸ τοῦ θέλειν εὐκτὸν ἡγουμένοις, σιγῇ παρεδίδοτο οὐ μόνον ἡ ἐπὶ τοῖς ἠγγελμένοις χαρά, ἀλλὰ καὶ ἡ δόξα τῆς ἀκροάσεως, οἱ μὲν δεδιότες, μὴ καὶ ψευσθεῖσιν ἐλπίδος τιμωρίᾳ συνέλθοιεν ὡς προεξορμήσασιν ἀποφήνασθαι τὴν διάνοιαν ἑαυτῶν, οἱ δ’ ἐξεπιστάμενοι διὰ τὸ τῆς ἐπιβουλῆς μετασχεῖν μειζόνως ἔκρυπτον ἀλλήλων ἀγνοίᾳ καὶ δεδιότες, μὴ πρός τινα εἰπόντες, οἷς ἡ τυραννὶς ἑστῶσα ὠφέλιμος ἦν, ζῶντος Γαΐου κολασθεῖεν ἐνδείξεως γενομένης. ἐπεὶ καὶ ἕτερος ἐπεφοιτήκει λόγος ὡμιληκέναι μὲν τραύμασιν, οὐ μὴν ἀποθανεῖν, ἀλλὰ ζῶντα ἐν θεραπείαις ὑπὸ τῶν ἰατρῶν εἶναι. ἦν τε πιστὸς οὐθεὶς οὐδενί, ᾧ κἂν θαρσήσας γνώμην ἀποφαίνοιτο τὴν αὐτοῦ· ἢ γὰρ φίλος ὢν ὕποπτος ἐγίνετο εὐνοίᾳ τῆς τυραννίδος ἢ καὶ μίσει πρὸς ἐκεῖνον χρώμενος τῷ πρὸς αὐτὸν οὐδαμόθεν εὐνοίᾳ χρωμένῳ διαφθείρειν τὴν ἐπὶ τοῖς λεγομένοις πίστιν. ἐλέγετο δὲ ὑπό τινων, οἳ καὶ μάλιστα τοῖς εὐπατρίδαις ἠφάνιζον τὸ εὐθυμοῦν τῆς ἐλπίδος, ἐν ἀμελείᾳ κινδύνων γεγονότα καὶ ἄφροντιν κομιδῇ τῶν τραυμάτων, ὥσπερ εἶχεν ᾑματωμένον ἐπὶ τῆς ἀγορᾶς διεκπεσεῖν κἀν δημηγορίαις εἶναι. καὶ τάδε μὲν εἰκάζετο βουλήσει τῇ ἀλογίστῳ τῶν θροεῖν προθεμένων καὶ ἐπ’ ἀμφότερα δόξῃ τῶν ἀκουόντων λαμβανόμενα· οὐ μὴν τήν γ’ ἐνέδραν ἐξέλιπον δεδιότες τὴν ἐπενεχθησομένην προεξιοῦσιν αἰτίαν· οὐ γὰρ ἐφ’ ἧς ἀξιοῖεν διανοίας γενήσεσθαι περὶ αὐτοῖς τὴν κρίσιν, ἀλλ’ ἀφ’ ἧς εἰκάζειν ἐθελήσειαν τούς τε κατηγορήσοντας καὶ τοὺς δικάζοντας.", "st": "19.1.16"}, {"sp": "N", "t": "Ἐπεὶ δὲ καὶ πλῆθος τῶν Γερμανῶν περιέσχε τὸ θέατρον ἐσπασμένων τὰ ξίφη, πᾶσι τοῖς θεωροῖς ἐλπὶς ἦν ἀπολεῖσθαι, καὶ πρὸς πᾶσαν οὗτινος εἴσοδον πτοία εἶχεν αὐτούς, ὡς αὐτίκα μάλα συγκοπήσοιντο, ἐν ἀμηχάνοις τε ἦσαν οὔτ’ ἀπιέναι θάρσος εἰσφερόμενοι οὔτε ἀκίνδυνον τὴν διατριβὴν τὴν ἐπὶ τοῦ θεάτρου πεπιστευκότες. εἰσπιπτόντων τε ἤδη βοὴ τοῦ θεάτρου ῥήγνυται καθ’ ἱκετείαν τρεπομένου τῶν στρατιωτῶν, ὡς πάντων ἀγνοίας αὐτῇ γενομένης καὶ τῶν βουλευθέντων τοῖς ἐπαναστᾶσιν, εἰ δή τις καὶ γέγονεν ἐπανάστασις, καὶ τῶν γεγονότων. φείδεσθαι οὖν καὶ μὴ τόλμης ἀλλοτρίας παρὰ τῶν οὐδ’ ἐν αἰτίᾳ γενομένων ἀπολαμβάνειν τιμωρίαν, παρέντας ἐρεύνην τῶν πεπραχότων ὅ τι καὶ πεπραγμένον εἴη καταστῆναι. καὶ οἱ μὲν ταῦτά τε καὶ περαιτέρω μετὰ δακρύων καὶ τύψεως προσώπων ἐπιθειάζοντες καὶ ποτνιώμενοι ὁπόσα ἀνεδίδασκεν αὐτοὺς ὁ κίνδυνος ἑστὼς πλησίον, καὶ ὡς ἄν τις ἀγωνιζόμενος περὶ τῆς ψυχῆς εἴποι τι, ἔλεγον. θραύεται δὲ τῶν στρατιωτῶν πρὸς ταῦτα ἡ ὀργὴ καὶ μεταμελῆσαν αὐτοῖς τοῦ ἐπὶ τοῖς θεωροῖς βουλεύματος, ὠμόν τε γὰρ ἦν τοῦτο καὶ ἐκείνοις καίπερ ἐξηγριωκόσιν ἐδόκει, τὰς κεφαλὰς τῶν περὶ τὸν Ἀσπρήναν ἐπὶ τὸν βωμὸν ἀπερεισαμένοις. πρὸς ἃς μειζόνως ἔπαθον οἱ θεωροὶ λογισμῷ τε ἀξιώσεως τῶν ἀνδρῶν καὶ ἐλέῳ τοῦ πάθους, ὥστε παρ’ ὀλίγον καὶ αὐτοῖς οὐδὲν ἐλλιπεστέρως τὰ τῶν κινδύνων ὁμιλήσαντα ἐπανασεσεῖσθαι, ὧν ἄδηλον εἶναι τὴν συμφορὰν εἴπερ εἰς τέλος φευχθῆναι δύναιτ’ ἄν. ὥστε κἂν εἴ τινες τῶν προθύμως μισούντων καὶ μετὰ δίκης τὸν Γάιον ἀφαιρεῖσθαι τῶν ἐπ’ αὐτῷ εὐφροσυνῶν τῆς χώρας, διὰ τὸ ἐν ῥοπῇ μὲν τοῦ συναπολουμένου γεγονέναι, τὸ δὲ πιστὸν τοῦ περιεῖναι μηδέπω καὶ τότε ἐχέγγυον συνελθεῖν.", "st": "19.1.17"}, {"sp": "N", "t": "Ἦν δὲ Εὐάρεστος Ἀρούντιος τῶν κηρυσσόντων τὰ πωλούμενα καὶ δι’ αὐτὸ φωνῆς τε μεγέθει χρώμενος καὶ χρήματα περιβεβλημένος ὅμοια τοῖς Ῥωμαίων πλουσιωτάτοις, δύναμίς τε αὐτῷ ἦν ἐφ’ οἷς ἐθελήσειε πράσσειν κατὰ τὴν πόλιν ἔν τε τῷ τότε κἀν τοῖς ὕστερον. οὗτος διαθεὶς αὑτὸν ὡς ἐνῆν πενθιμώτατον, καίτοι μίσει καὶ παρ’ ὁντινοῦν ἐχρῆτο πρὸς Γάιον, ἀλλὰ μὴν κρείσσων ἡ διδασκαλία τοῦ φόβου καὶ στρατηγία περὶ τοῦ κερδησομένου τὴν σωτηρίαν τῆς εἰς τὸ παρὸν ἡδονῆς, πάντα κόσμον ἐπιτηδεύσας ὡς ἄν τις ἐπὶ τοῖς τιμιωτάτοις παρεσκεύαστο ἀπολωλόσιν, ἀποσημαίνει τοῦ Γαΐου τὸν θάνατον ἐπὶ τὸ θέατρον παρελθὼν καὶ ἔπαυσεν τοὺς ἀνθρώπους ἐπὶ πλέον ἀγνοίᾳ συμπεριφέρεσθαι τοῦ γεγονότος. ἤδη δὲ καὶ Στήλας Ἀρούντιος παρῆν ἀνακαλῶν τοὺς Γερμανοὺς καὶ οἱ χιλίαρχοι σὺν αὐτῷ κελεύοντες κατατίθεσθαι τὸν σίδηρον καὶ διασαφοῦντες Γαΐου τὴν τελευτήν. τοῦτο καὶ σαφέστατα ἔσωσεν τοὺς ἐν τῷ θεάτρῳ συνειλεγμένους καὶ πάντας, οἳ καὶ ὁπωσοῦν τοῖς Γερμανοῖς περιτύχοιεν· ἐλπίδος γὰρ αὐτοῖς παραγενομένης ἔμπνουν κεῖσθαι τὸν Γάιον οὐκ ἔσθ’ οὗτινος κακῶν ἂν ἀπέσχοντο. τοσόνδε ἐπερίσσευσεν αὐτοῖς εὐνοίας τῆς πρὸς αὐτόν, ὡς κἂν μετὰ τοῦ καθ’ αὑτοὺς ἀπολουμένου τῆς ψυχῆς κτήσασθαι τὸ ἀνεπιβούλευτον αὐτῷ καὶ τοσαύτῃ δυστυχίᾳ συνεσόμενον. παύονται δὲ τοῦ ὠργηκότος εἰς τὴν τιμωρίαν μαθήσεως σαφοῦς παραγενομένης αὐτοῖς ἐπὶ τῇ τελευτῇ, διά τε τὸ εἰς ἀχρεῖον ἐπιδείξεσθαι τὸ πρόθυμον τῆς εὐνοίας, ὃς ἀμείψαιτο αὐτοὺς ἀπολωλότος, καὶ δέει, μὴ καὶ περαιτέρω τῇ ὕβρει χρωμένων ἐπιστροφὴ γένοιτο ὑπὸ τῆς βουλῆς, εἴπερ εἰς ἐκείνην περισταίη τὸ κράτος, ἢ ὑπὸ τοῦ ἐπικαταστάντος ἄρχοντος. καὶ Γερμανοὶ εἰ καὶ μόλις, ἀλλ’ οὖν ἐπαύσαντο λύσσης τῆς ἐπὶ Γαΐου τῷ θανάτῳ καταλαμβανομένης αὐτούς.", "st": "19.1.18"}, {"sp": "N", "t": "Χαιρέας δέ, σφόδρα γὰρ περὶ Μινουκιανῷ ἔδεισε, μὴ διαφθαρείη μανίᾳ τῶν Γερμανῶν περιπεσών, ἕκαστόν τε τῶν στρατιωτῶν μετῄει προμηθεῖσθαι τῆς σωτηρίας αὐτοῦ δεόμενος καὶ μὴ ἀπολώλοι πολλὴν ἐξέτασιν ποιούμενος. καὶ Μινουκιανὸν μὲν Κλήμης, ἀνάγεται γὰρ ἐπὶ τοῦτον, μεθίησιν πολλῶν μετ’ ἄλλων συγκλητικῶν δικαιοσύνην τῇ πράξει συμμαρτυρῶν καὶ ἀρετὴν τοῖς ἐντεθυμημένοις καὶ πράσσειν μὴ ἀποδεδειλιακόσι· τυραννίδα γὰρ εἰς ὀλίγον μὲν ἐλθεῖν ἡδονῇ τοῦ ὑβρίζειν ἐπαρθεῖσαν, εὐτυχεῖς δὲ οὐκ ἄρα ποιεῖσθαι τὰς ἀπαλλαγὰς τοῦ βίου μίσει τῆς ἀρετῆς πρὸς αὐτὸν χρωμένης, ἀλλὰ μετὰ τοιαύτης δυστυχίας, ὁποίᾳ δὴ Γάιον συνελθεῖν πρὸ τῶν ἐπαναστάντων καὶ συνθέντων τὴν ἐπίθεσιν αὐτὸν ἐπίβουλον αὐτῷ γενόμενον καὶ διδάξαντα οἷς ὑβρίζων ἀφόρητος ἦν ἀφανίζων τοῦ νόμου τὴν πρόνοιαν πολέμῳ πρὸς αὐτὸν χρῆσθαι τοὺς φιλτάτους, καὶ νῦν λόγῳ μὲν εἶναι τούτους οἳ ἀνῃρήκασι Γάιον, ἔργῳ δὲ αὐτὸν ὑφ’ ἑαυτοῦ κεῖσθαι διολωλότα.", "st": "19.1.19"}, {"sp": "N", "t": "Ἤδη δὲ καὶ τὸ θέατρον ἐξανίστατο τῶν φυλακῶν αἳ τὸ κατ’ ἀρχὰς πάνυ πικραὶ ἐγένοντο ὑπανίσως. αἰτία δ’ ἦν τοῦ προθύμως καὶ διαφευξομένου τῶν θεωρῶν Ἀλκύων ὁ ἰατρός, συναρπασθεὶς μὲν ὡς ἐπὶ θεραπείᾳ τινῶν τραυματιῶν, ἐκπέμψας δὲ τοὺς συνόντας λόγῳ μὲν ὡς καὶ μετελευσομένους ὁπόσα εἰς τὴν ἴασιν τοῖς τραυματίαις πρόσφορα, τὸ δ’ ἀληθὲς ὡς πείσοιντο κινδύνου τοῦ κατειληφότος. ἐν τούτῳ δὲ βουλῆς τε γίνεται σύνοδος καὶ ὁ δῆμος ᾗπερ καὶ εἰώθασιν ἐκκλησιάζειν ἐπὶ τῆς ἀγορᾶς καταστὰς ἐν ζητήσει τῶν σφαγέων τῶν Γαΐου ἦσαν, ὁ μὲν δῆμος καὶ πάνυ ἐκθύμως, δοκεῖν δὲ καὶ ἡ βουλή. καὶ ἦν γὰρ Ἀσιατικὸς Οὐαλέριος ὑπατικὸς ἀνήρ, οὗτος ἐπὶ τὸν δῆμον καταστάς, θορυβούντων καὶ δεινὸν τιθεμένων τὸ ἔτι λανθάνον τῶν τὸν αὐτοκράτορα ἀπεκτονότων, ἐπεὶ προθύμως πάντες αὐτὸν ἤροντο, τίς ὁ πράξας τυγχάνει, εἴθε γὰρ ἔγωγε φησί. καὶ προύθεσαν δὲ καὶ οἱ ὕπατοι διάγραμμα Γαΐου μὲν κατηγορίας ποιούμενοι, κελεύοντες δὲ τῷ τε δήμῳ καὶ τοῖς στρατιώταις ἐπὶ τὰ αὐτῶν ἀπιέναι, τῷ μὲν δήμῳ πολλὴν ἀνέσεως ἐπαγγελλόμενοι ἐλπίδα, τῷ στρατιωτικῷ δὲ τιμῶν, εἰ ἐν κόσμῳ μείνειαν τῷ εἰωθότι μηδὲν ὑβρίζειν ἐξαγόμενοι· δέος γὰρ ἦν, μὴ ἐξαγριωσάντων ἀπολαύσειεν τοῦ κακοῦ ἡ πόλις καθ’ ἁρπαγὰς αὐτῶν καὶ συλήσεις τῶν ἱερῶν τρεπομένων. ἐφθάκει δὲ ἤδη τῶν βουλευτῶν τὸ πᾶν πλῆθος συνειλεγμένον καὶ μάλιστα οἱ εἰς τοῦ Γαΐου συνελθόντες τὸν φόνον θράσει τε ἤδη χρώμενοι κἀν καταφρονήματι μεγάλῳ ὄντες ὡς εἰς αὐτοὺς ἀνακειμένων δὴ τῶν πραγμάτων.", "st": "19.1.20"}, {"sp": "N", "t": "Ἐν τούτῳ δὴ ὄντων τῶν πραγμάτων αἰφνίδιον ἀρπάζεται Κλαύδιος ἐκ τῆς οἰκίας· οἱ γὰρ στρατιῶται συνόδου γενομένης αὐτοῖς, ἀλλήλοις καὶ αὑτοῖς λόγον δόντες περὶ τοῖς ποιητέοις ἑώρων δημοκρατίαν ἀδύνατόν τε ὂν ἐν κράτει τοσῶνδε ἄν ποτε γενέσθαι πραγμάτων ἐξικομένην τε οὐκ ἐπ’ ἀγαθῷ τῷ αὐτῶν κτήσασθαι τὴν ἀρχήν, εἴ τέ τις τῶν κατὰ ἕνα σχήσοι τὴν ἡγεμονίαν, εἰς πάντα λυπηρὸν αὐτοῖς εἶναι μὴ οὐ συνεργοῖς τῆς ἀρχῆς καταστᾶσιν. καλῶς οὖν ἔχειν ἀκρίτων ἔτι ὄντων τῶν πραγμάτων ἡγεμόνα αἱρεῖσθαι Κλαύδιον, πάτρωά τε ὄντα τοῦ τεθνεῶτος καὶ τῶν εἰς τὴν βουλὴν συλλεγομένων οὐδενὸς οὗτινος οὐκ ἀξιολογώτερον προγόνων τε ἀρετῇ καὶ τῷ κατ’ αὐτὸν παιδείαν μεμελετηκότι, καὶ σταθέντα αὐτοκράτορα τιμήσειν τε τὰ εἰκότα καὶ ἀμείψεσθαι δωρεαῖς. ταῦτα διανοοῦνταί τε καὶ ἔπραξαν ἐκ τοῦ παραχρῆμα. ἥρπαστο μὲν δὴ Κλαύδιος ὑπὸ τοῦ στρατιωτικοῦ. Ναῖος δὲ Σέντιος Σατορνῖνος καίτοι πεπυσμένος τὴν Κλαυδίου ἁρπαγήν, καὶ ὡς ἐπιδικάζοιτο τῆς ἀρχῆς ἄκων μὲν δοκεῖν, τὸ δὲ ἀληθὲς καὶ βουλήσει τῇ αὐτοῦ, καταστὰς ἐπὶ τῆς συγκλήτου καὶ μηδὲν ἐκπλαγεὶς ἐλευθέροις τε καὶ γενναίοις ἀνδράσι πρεπόντως ποιεῖται παραίνεσιν τάδε λέγων.", "st": "19.2.1"}, {"sp": "N", "t": "Εἰ καὶ ἄπιστον, ὦ Ῥωμαῖοι, διὰ τὸ χρόνῳ πολλῷ ἥκειν ἀνέλπιστον οὖσαν ἡμῖν, ἀλλ’ οὖν ἔχομεν τοῦ ἐλευθέρου τὴν ἀξίωσιν, ἄδηλον μὲν ἐφ’ ὁπόσον παρατείνουσαν καὶ γνώμῃ θεῶν οἳ ἐχαρίσαντο αὐτὴν κειμένην, εὐφραίνειν δὲ ἀρκοῦσαν καὶ εἴπερ ἀφαιρεθείημεν αὐτῆς εὐδαιμονίᾳ συνάγουσαν· ἱκανὴ γὰρ καὶ μία ὥρα τοῖς ἀρετῆς αἰσθανομένοις καὶ μετ’ αὐτοτελοῦς τῆς διανοίας ἐν αὐτοδίκῳ τῇ πατρίδι καὶ μετὰ νόμων, οἷς ποτε ἤνθησε, διαιτωμένῃ βιωθεῖσα. ἐμοὶ δὲ τῆς μὲν πρότερον ἐλευθερίας ἀμνημονεῖν ἔστι διὰ τὸ κατόπιν αὐτῆς γεγονέναι, τῆς δὲ νῦν ἀπλήστως πιμπλαμένῳ μακαριστούς τε ἡγεῖσθαι τοὺς ἐγγενηθέντας καὶ ἐντραφέντας αὐτῇ καὶ τῶν θεῶν οὐδὲν μειόνως ἀξίους τιμῆς τούσδε τοὺς ἄνδρας, οἳ ὀψὲ γοῦν κἀν τούτῳ τῆς ἡλικίας ἡμᾶς γεύσαντας αὐτῆς. καὶ εἴη μὲν εἰς πᾶν τοῦ αἰῶνος τὸ ἐπιὸν παραμεῖναι τὴν ἄδειαν αὐτῆς, ἀρκοῦσα δ’ ἂν γένοιτο καὶ ἥδε ἡ ἡμέρα τοῖς τε νεωτέροις ἡμῶν καὶ ὅσοι γεγηράκαμεν αἰὼν ὑπείληπται, τοῖς πρεσβυτέροις δόντων ἀγαθῶν αὐτῆς ἐν ὁμιλίᾳ γεγονότες μετασταῖεν, τοῖς δὲ νεωτέροις παίδευμα ἀρετῆς καταστάσεως ἀγαθὸν ἀνδράσι τοῖσδε ἀφ’ ὧν γεγόναμεν, νῦν δὲ ἤδη καὶ ἡμῖν διὰ τὴν ἄρτι ὥραν οὐδὲν προυργιαίτερον εἴη τοῦ ζῆν μετὰ ἀρετῆς, ἣ μόνη ἐκφροντίζει τῷ ἀνθρωπείῳ τὸ ἐλεύθερον· ἐγὼ γὰρ τὰ παλαιὰ οἶδα ἀκοῇ παραλαβών, οἷς δὲ ὄψει ὁμιλήσας ᾐσθόμην, οἵων κακῶν τὰς πολιτείας ἀναπιμπλᾶσιν αἱ τυραννίδες, κωλύουσαι μὲν πᾶσαν ἀρετὴν καὶ τοῦ μεγαλόφρονος ἀφαιρούμεναι τὸ ἐλεύθερον, κολακείας δὲ καὶ φόβου διδάσκαλοι καθιστάμεναι διὰ τὸ μὴ ἐπὶ σοφίᾳ τῶν νόμων, ἀλλ’ ἐπὶ τῇ ὀργῇ τῶν ἐφεστηκότων καταλιπεῖν τὰ πράγματα. ἀφ’ οὗ γὰρ Ἰούλιος Καῖσαρ φρονήσας ἐπὶ καταλύσει τῆς δημοκρατίας καὶ διαβιασάμενος τὸν κόσμον τῶν νόμων τὴν πολιτείαν συνετάραξεν, κρείσσων μὲν τοῦ δικαίου γενόμενος, ἥσσων δὲ τοῦ κατ’ ἰδίαν ἡδονὴν αὐτῷ κομιοῦντος, οὐκ ἔστιν ὅ τι τῶν κακῶν οὐ διέτριψεν τὴν πόλιν, φιλοτιμηθέντων πρὸς ἀλλήλους ἁπάντων, οἳ ἐκείνῳ διάδοχοι τῆς ἀρχῆς κατέστησαν, ἐπ’ ἀφανισμῷ τοῦ πατρίου καὶ ὡς ἂν μάλιστα τῶν πολιτῶν ἐρημίαν τοῦ γενναίου καταλείποιεν, διὰ τὸ οἴεσθαι πρὸς ἀσφαλείας εἶναι τῆς αὐτῶν τὸ κιβδήλοις ἀνδράσιν ὁμιλεῖν καὶ τῶν ἀρετῇ προύχειν πεπιστευμένων οὐ μόνον ὑφαιρεῖν τι τοῦ αὐχήματος, ἀλλ’ εἰς τὸ πᾶν ἐπιφημίζειν αὐτῷ τοῖς ὀλέθροις τῶν ἁπάντων ἀριθμῷ τε πολλῶν ὄντων καὶ βαρύτητα ἀνύποιστον ἐπιδειξαμένων καθ’ ἃ ἕκαστος ἦρξεν εἷς ὢν ὁ Γάιος ὁ σήμερον τεθνεὼς πλέω τε τῶν πάντων δεινὰ ἀπεδείξατο οὐ μόνον εἰς τοὺς συμπολίτας, ἀλλὰ καὶ εἰς τοὺς συγγενεῖς καὶ φίλους ἀπαίδευτον τὴν ὀργὴν ἐπαφιείς, ὁμοίως τοῖς ἅπασι καὶ μείζω κακὰ ἐντριβόμενος ἀδίκως τὴν τιμωρίαν εἰσπράσσεσθαι, ὠργικότων ὁμοίως εἴς τε ἀνθρώπους ἐξαγριώσας καὶ τοὺς θεούς. τυραννίδι γὰρ οὐ κερδαίνεται τὸ ἡδὺ οὐδὲ μεθ’ ὕβρεως ἀποχρῆται, οὐκ εἰς τὰ χρήματα λελυπῆσθαι καὶ γαμετάς, ἀλλὰ τὸ πᾶν κέρδος ἐκ τοῦ πανοικεσίᾳ διοχλουμένου τῶν ἐχθρῶν. ἐχθρὸν δὲ τυραννίδι πᾶν τὸ ἐλεύθερον, εἰς εὔνοιάν τε ἐκκαλεῖσθαι αὐτὴν καὶ τοῖς ἐν ὀλίγῳ τιθεμένοις ὁπόσα πεπόνθοιεν οὐκ ἔστιν. ἐξεπιστάμενοι γὰρ ὧν ἀναπλήσειαν κακῶν ἔστιν οὓς κἀκεῖνοι μεγαλοφρόνως καταφρονημάτων τε πρὸς τὴν τύχην, αὐτοὶ λανθάνειν αὐτοὺς ὧν πράξειαν μὴ δυνάμενοι μόνως πιστεύουσιν κτήσεσθαι τοῦ ὑπόπτου τὸ ἀδεές, εἰ παντελὲς αἱρεῖσθαι δυνηθεῖεν αὐτούς. τοιούτων δὴ κακῶν ἀπογεγονότες καὶ ὑποτελεῖς ἀλλήλοις καταστάντες, αἵπερ πολιτειῶν ἐχεγγυώταται πρός τε τὸ παρὸν εὔνουν καὶ τὸ αὖθις ἀνεπιβούλευτον καὶ τὸ δόξαν οἰκείαν τῷ ὀρθουμένῳ τῆς πόλεως δικαιοί τε προνοῆσαι διὰ τὸ εἰς κοινὸν αὐτοῦ τὴν ὠφέλειαν ἀπαντᾶν καὶ ἀνταποφήνασθαι γνώμην, οἷς μὴ ἀρέσκοιτο τὰ προεισηγημένα, οὐδαμῶς εἰς κίνδυνον φέρον, διὰ τὸ μὴ δεσπότην εἶναι τὸν ἐφεστηκότα, ᾧ ἀνεύθυνόν τε βλάπτοντι τὴν πόλιν καὶ αὐτοκράτορι μεταστήσασθαι τοὺς εἰρηκότας. καὶ τέτροφε τὴν τυραννίδα οὐδὲν νεώτερον πλὴν ἥ τε ἀργία καὶ τὸ πρὸς οὐδὲν τῶν ἐκείνῃ θελομένων ἀντιλογίᾳ χρώμενον· τῆς γὰρ εἰρήνης τοῦ τερπνοῦ ἡσσώμενοι καὶ μεμαθηκότες ἀνδραπόδων ἐν τρόπῳ ζῆν ὁπόσοι τε ἐπαΐομεν συμφορὰς ἀνηκέστους κακοῖς τε τοῖς πέλας ἐπείδομεν φόβῳ τοῦ μετ’ ἀρετῆς τελευτᾶν μετὰ αἰσχύνης τῆς ὑστάτης ὑπομένοντες τὰς τελευτάς. πρῶτον δὲ τοῖς ἀραμένοις τὸν τύραννον τιμὰς αἵτινες μέγισται ταύτας εἰσενεγκεῖν, μάλιστα δὲ Χαιρέᾳ τῷ Κασσίῳ· σὺν γὰρ τοῖς θεοῖς εἷς ἀνὴρ οὗτος ποριστὴς ἡμῖν καὶ γνώμῃ καὶ χερσὶ τῆς ἐλευθερίας πέφηνεν. οὗ καλὸν μὴ ἀμνημονεῖν, ἀλλ’ ἐπὶ τῆς τυραννίδος ὑπὲρ ἐλευθερίας τῆς ἡμετέρας προβεβουλευκότος τε ἅμα καὶ προκεκινδυνευκότος, ἐπὶ τῆς ἐλευθερίας ψηφίσασθαι τὰς τιμὰς πρῶτόν τε ἀνεπιτάκτους τοῦτο ἂν ἀποφήνασθαι. ἔργον δὲ κάλλιστον καὶ ἐλευθέροις ἀνδράσι πρέπον ἀμείβεσθαι τοὺς εὐεργέτας, οἷος δὴ καὶ ἀνὴρ οὗτος περὶ ἡμᾶς πάντας γέγονεν οὐδὲν παραπλήσιος Κασσίῳ καὶ Βρούτῳ τοῖς Γάιον Ἰούλιον ἀνῃρηκόσιν, ἐπεί γε οἱ μὲν στάσεως καὶ πολέμων ἐμφυλίων ἀρχὰς ἐπανερρίπισαν τῇ πόλει, οὗτος δὲ μετὰ τῆς τυραννοκτονίας καὶ τῶν ἐντεῦθεν δεινῶν ἀπήλλαξεν τὴν πόλιν.", "st": "19.2.2"}, {"sp": "N", "t": "Σέντιος μὲν τοιούτοις ἐχρῆτο τοῖς λόγοις καὶ τῶν βουλευτῶν ἡδονῇ δεχομένων καὶ ὁπόσοι τῶν ἱππέων παρῆσαν. ἀναπηδήσας δέ τις Τρεβέλλιος Μάξιμος περιαιρεῖται τὸν δακτύλιον τοῦ Σεντίου, λίθος δὲ εἰκόνα Γαΐου ἐγγεγλυμμένος ἐδεσμεύετο αὐτῷ, καὶ σπουδῇ τῶν λεγομένων καὶ ὧν ἐπενόει πράξειν, ὅπερ ᾤετο, ἐν λήθῃ γεγονότι καὶ ἡ μὲν γλυφὴ κατάγνυται. προεληλύθει δὲ ἡ νὺξ ἐπὶ μέγα, καὶ Χαιρέας δὲ σημεῖον ᾔτει τοὺς ὑπάτους, οἱ δὲ ἐλευθερίαν ἔδοσαν. ἐν θαύματι δὲ ἦν αὐτοῖς καὶ ὅμοια ἀπιστίᾳ τὰ δρώμενα· ἔτει γὰρ ἑκατοστῷ, μεθ’ ὃ τὴν δημοκρατίαν τὸ πρῶτον ἀφῃρέθησαν, ἐπὶ τοὺς ὑπάτους σημείου ἡ παράδοσις· οὗτοι γὰρ πρότερον ἢ τυραννηθῆναι τὴν πόλιν κύριοι τῶν στρατιωτικῶν ἦσαν. Χαιρέας δὲ τὸ σημεῖον λαβὼν παρεδίδου τῶν στρατιωτῶν τοῖς πρὸς τὴν σύγκλητον συνεστηκόσιν. ἦσαν δὲ εἰς σπείρας τέσσαρας, οἷς τὸ ἀβασίλευτον τιμιώτερον τῆς τυραννίδος προύκειτο. καὶ οἵδε μὲν ἀπῄεσαν μετὰ τῶν χιλιάρχων, ἀνεχώρει δὲ ἤδη καὶ ὁ δῆμος περιχαρὴς καὶ ἐλπίδος καὶ φρονήματος ἐπὶ τῷ κτησαμένῳ τὴν ἡγεμονίαν αὐτοῖς, οὐκέτι ἐπὶ τῷ ἐφεστηκότι. καὶ τὰ πάντα ἦν ὁ Χαιρέας αὐτοῖς.", "st": "19.2.3"}, {"sp": "N", "t": "Χαιρέας δὲ ἐν δεινῷ τιθέμενος περιεῖναι τὴν θυγατέρα Γαΐου καὶ τὴν γυναῖκα, ἀλλὰ μὴ πανοικὶ τὸν ὄλεθρον αὐτῷ συντυχεῖν, ἐπεὶ καὶ πᾶν ὅ τι ὑπολείποιτο αὐτῶν ἐπ’ ὀλέθρῳ τῆς πόλεως λειφθήσεσθαι καὶ τῶν νόμων, ἄλλως τε πρόθεσιν ἐσπουδακὼς τελειώσασθαι τὴν αὐτοῦ καὶ πάνυ εὐφρᾶναι μῖσος τὸ πρὸς Γάιον, Ἰούλιον ἐκπέμπει Λοῦππον ἕνα τῶν χιλιάρχων κτενοῦντα τήν τε γυναῖκα Γαΐου καὶ τὴν θυγατέρα. Κλήμεντος δ’ ὄντι συγγενεῖ τῷ Λούππῳ τὴν ἐπὶ τοιοῖσδε προύθεσαν λειτουργίαν, ὅπως μετασχὼν κἂν ἐπὶ τοιούτοις τῆς τυραννοκτονίας ἀγάλλοιτο ἀρετῇ πρὸς τῶν πολιτικῶν, ὡς καὶ τοῦ παντὸς ἐπιβουλεύματος δόξειε κοινωνεῖν τὸ πρῶτον συνθεμένων. ἐνίοις δὲ τῶν συνωμοτῶν καὶ ὠμὸν ἐδόκει τὸ ἐπὶ τῇ γυναικὶ θράσει χρησόμενον αὐτῷ διὰ τὸ Γάιον φύσει τῇ αὐτοῦ χρώμενον ἢ συμβουλῇ τῇ ἐκείνης τὰ πάντα πρᾶξαι, ἐξ ὧν ἥ τε πόλις ἀπηγορεύκει τοῖς κατειληφόσι κακοῖς καὶ τῶν πολιτῶν ὅ τι καὶ ἄνθος ἦν ἀπώλετο. οἱ δὲ καὶ τῶν μὲν ἐπὶ τοιούτοις ἐνεκάλουν αὐτῇ γνώμην τὸ δὲ πᾶν καὶ τῶν ὑπὸ Γαΐου πεπραγμένων κακῶν ἐκείνῃ τὴν αἰτίαν ἐπέφερον φάρμακον τῷ Γαΐῳ δοῦσαν ἐννοιῶν δούλωσιν καὶ ἐρώτων ἐπαγωγὰς αὐτῇ ψηφιούμενον, εἰς μανίαν μεταστάντος τὰ πάντα αὐτὴν εἶναι τὴν νεναυπηγημένην ἐπὶ ταῖς Ῥωμαίων τύχαις καὶ τῆς ὑποτελούσης αὐτοῖς οἰκουμένης. καὶ πέρας κυρωθὲν ὥστε αὐτὴν τελευτᾶν, οὐδὲν γὰρ οἱ ἀποσπεύδοντες οἷοί τε ὠφελεῖν ἦσαν, ἐστέλλετο ὁ Λοῦππος· ἐβραδύνετο δὲ οὐδὲν μελλήσει τῇ κατ’ αὐτόν, ὥστε μὴ οὐκ εἰς καιρὸν δεδιακονῆσθαι τοῖς ἀπεσταλκόσιν, θέλων ἐπ’ οὐδαμοῖς μεμπτὸς εἶναι τῶν ἐπ’ ὠφελείᾳ τοῦ δήμου πεποιημένων. παρελθὼν δὲ ἐπὶ τοῦ βασιλείου λαμβάνει τὴν Καισωνίαν, γυνὴ δ’ ἦν τοῦ Γαΐου, παρακατακειμένην τῷ σώματι τοῦ ἀνδρὸς χαμαιπετεῖ καὶ πάντων ἐν ἀτυχίᾳ ὧν χαρίζοιτ’ ἂν ὁ νόμος τοῖς μεταστᾶσιν, αἵματί τε ἀναπεφυρμένην ἐκ τῶν τραυμάτων καὶ πολλῇ τῇ ταλαιπωρίᾳ συμφερομένην τῆς θυγατρὸς παρερριμμένης· ἠκούετό τε ἐν τοῖς τοιοῖσδε οὐδὲν ἕτερον ἢ κατάμεμψις τοῦ Γαΐου, ὡς πιθανὴν οὐ σχόντος πολλάκις προηγορευκυῖαν αὐτήν. ἐπ’ ἀμφότερα δὲ οὗτος ὁ λόγος καὶ τότε εἰκάζετο καὶ νῦν ἐφ’ ὁμοίοις πρόκειται τῇ διανοίᾳ τῶν ἀκροατῶν πρὸς ὅ τι θελήσειαν ῥοπὰς τὰς αὐτοῦ προστιθέμενοι. οἱ μὲν γὰρ ἀποσημαίνειν ἔφασαν τὸν λόγον, ὡς συμβουλευομένης ἀποστάντα μανιῶν καὶ τοῦ εἰς τοὺς πολίτας ὠμοῦ μετρίως καὶ μετ’ ἀρετῆς ἐξηγεῖσθαι τῶν πραγμάτων, καὶ παρ’ αὐτὸν ἀπολέσθαι τρόπῳ τῷ αὐτοῦ χρώμενον. οἱ δέ, ὡς λόγου τοῦ περὶ τῶν συνωμοτῶν ἐπιφοιτήσαντος Γαΐῳ κελεύσειεν μηδὲν εἰς ἀναβολὰς ἀλλ’ ἐκ τοῦ ὀξέος πάντας μεταχειρισάμενον αὐτούς, κἂν εἰ μηδὲν ἀδικοῖεν, ἐν ἀδεεῖ κινδύνων καταστῆναι, καὶ τοῦτ’ εἶναι τὸ ἐπονειδιζόμενον, ὡς προηγορευκυίας διαπράξασθαι μαλακῷ γεγονότι. καὶ τὰ μὲν λεχθέντα ὑπὸ τῆς Καισωνίας καὶ ὁποῖα οἱ ἄνθρωποι περὶ αὐτῆς ἐφρόνουν ταῦτα ἦν. ἡ δὲ ἐπεὶ θεᾶται τὴν πρόσοδον τοῦ Λούππου τό τε σῶμα τοῦ Γαΐου προυδείκνυεν καὶ ἆσσον ἰέναι παρεκάλει μετ’ ὀλοφυρμοῦ καὶ δακρύων. ἐπεὶ δὲ τῇ διανοίᾳ συνεστηκότα ἑώρα τὸν Λοῦππον, καὶ μηδὲν προσιόντα ὡς ἐπὶ πρᾶξιν οὐκ αὐτῷ κεχαρισμένην, γνωρίσασα ἐφ’ ὅ τι ἐχώρει τήν τε σφαγὴν ἐγύμνου καὶ πάνυ προθύμως ποτνιωμένη ὁποῖα εἰκὸς τοὺς οὕτω σαφῶς ἐν ἀπογνώσει τοῦ ζῆν γεγονότας καὶ κελεύουσα μὴ μέλλειν ἐπὶ τελειώσει τοῦ δράματος οὗ ἐπ’ αὐτοῖς συνέθεσαν. καὶ ἥδε μὲν εὐψύχως ταύτῃ τελευτᾷ ὑπὸ τοῦ Λούππου καὶ ἐπ’ αὐτῇ τὸ θυγάτριον. καὶ Λοῦππος ταῦτα προαπαγγέλλων ἔσπευδεν τοῖς περὶ τὸν Χαιρέαν.", "st": "19.2.4"}, {"sp": "N", "t": "Γάιος μὲν δὴ τέταρτον ἐνιαυτὸν ἡγεμονεύσας Ῥωμαίων λείποντα τεσσάρων μηνῶν οὕτως τελευτᾷ, ἀνὴρ καὶ πρότερον ἢ τῇ ἀρχῇ συνῆλθεν σκαιός τε καὶ κακοτροπίας εἰς τὸ ἄκρον ἀφιγμένος, ἡδονῇ τε ἡσσώμενος καὶ φίλος διαβολῇ, καὶ τὰ μὲν φοβερὰ καταπεπληγμένος καὶ διὰ τοῦτο ἐφ’ οἷς θαρσήσειε φονικώτατος, τῆς τε ἐξουσίας ἐφ’ ἑνὶ μόνῳ πιμπλάμενος τῷ ὑβρίζειν, εἰς οὓς ἥκιστα ἐχρῆν ἀλόγῳ μεγαλοψυχίᾳ χρώμενος καὶ ποριστὴς ἐκ τοῦ κτείνειν καὶ παρανομεῖν. καὶ τοῦ μὲν θείου καὶ νομίμου μείζων ἐσπουδακὼς εἶναί τε καὶ δοκεῖν, ἡσσώμενος δὲ ἐπαίνων τῆς πληθύος καὶ πάντα, ὁπόσα αἰσχρὰ κρίνας ὁ νόμος ἐπιτιμᾷ τιμωρίαν, ἐνόμισεν ἀρετῆς. καὶ φιλίας ἀμνήμων, εἰ καὶ πλείστη τε καὶ διὰ μεγίστων γένοιτο, οἷς τότε ὀργισθείη ἐκπλήξει κολάσεως καὶ ἐλαχίσταις, πολέμιον δὲ ἡγούμενος πᾶν τὸ ἀρετῇ συνερχόμενον, ἀναντίλεκτον ἐπὶ πᾶσιν οἷς κελεύσειε τὴν ἐπιθυμίαν λαμβάνων· ὅθεν καὶ ἀδελφῇ γνησίᾳ συνῆν, ἐξ οὗ καὶ μάλιστα αὐτῷ φύεσθαι παρὰ τοῖς πολίταις ἤρξατο σφοδρότερον τὸ μῖσος διὰ τὸ πολλοῦ χρόνου μὴ ἱστορημένον εἴς τε ἀπιστίαν καὶ ἔχθραν τὴν πρὸς τὸν πράξαντα παρακαλεῖν. ἔργον δὲ μέγα ἢ βασίλειον οὐδὲν αὐτῷ πεπραγμένον εἴποι ἄν τις ἢ ἐπ’ ὠφελείᾳ τῶν συνόντων καὶ αὖθις ἀνθρώπων ἐσομένων, πλήν γε τοῦ περὶ Ῥήγιον καὶ Σικελίαν ἐπινοηθέντος ἐν ὑποδοχῇ τῶν ἀπ’ Αἰγύπτου σιτηγῶν πλοίων· τοῦτο δὲ ὁμολογουμένως μέγιστόν τε καὶ ὠφελιμώτατον τοῖς πλέουσιν· οὐ μὴν ἐπὶ τέλος γε ἀφίκετο, ἀλλ’ ἡμίεργον ὑπὸ τοῦ ἀμβλυτέρως αὐτῷ ἐπιπονεῖν κατελείφθη. αἴτιον δ’ ἦν ἡ περὶ τὰ ἀχρεῖα σπουδὴ καὶ τὸ δαπανῶντα εἰς ἡδονάς, αἳ καταμόνας ἔμελλον ὠφελεῖν, αὐτῷ ὑφαιρεῖν τῆς ἐπὶ τοῖς κρείσσοσιν ἀνωμολογημένοις φιλοτιμίας. ἄλλως δὲ ῥήτωρ τε ἄριστος καὶ γλώσσῃ τῇ Ἑλλάδι καὶ τῇ Ῥωμαίοις πατρίῳ σφόδρα ἠσκημένος συνίει τ’ ἐκ τοῦ παραχρῆμα καὶ τοῖς ὑφ’ ἑτέρων συντεθεῖσίν τε καὶ ἐκ πλείονος προσυγκειμένοις ἀντειπὼν ἐκ τοῦ ὀξέος φανῆναι πιθανώτερος ἐν μεγίστῳ πράγματι παρ’ ὁντινοῦν γενόμενος, εὐκολίᾳ τε εἰς αὐτὸ τῆς φύσεως καὶ τῷ εἰς ἰσχὺν αὐτῇ προσλαβεῖν μελέτην τοῦ ἐπιπονεῖν. ἀδελφοῦ γὰρ παιδὸς υἱεῖ γεγονότι Τιβερίου, οὗ καὶ διάδοχος γίνεται, μέγα ἀνάγκασμα παιδείας ἀντέχεσθαι διὰ τὸ καὶ αὐτὸς εἰς τὰ πρῶτα ἐν αὐτῇ κατορθῶν διαπρέπειν, καὶ συνεφιλοκάλει Γάιος συγγενοῦς τε ἀνδρὸς καὶ ἡγεμόνος εἴκων ἐπιστολαῖς ἐπρώτευσέν τε τῶν κατ’ αὐτὸν πολιτῶν. οὐ μὴν ἀντισχεῖν οἷά τε ἐγένετο αὐτῷ τὰ ἐκ τῆς παιδείας συλλεγέντα ἀγαθὰ πρὸς τὸν ἐπελθόντα ὄλεθρον αὐτῷ ὑπὸ τῆς ἐξουσίας· οὕτως ἄρα δυσπόριστον ἡ ἀρετὴ τοῦ σωφρονεῖν, οἷς ἀνυπεύθυνον τὸ πράσσειν ῥᾳστώνῃ πάρεστιν. φίλοις μὲν κεχρῆσθαι καὶ πάντα ἀξιολόγοις ὑποσπουδασθεὶς τὸ κατ’ ἀρχὰς ὑπό τε παιδείας καὶ δόξης ζήλου τῶν κρειττόνων, μέχρι δὴ τῷ περιόντι τοῦ ὑβρίζειν ἀπαμφίασις εὐνοίᾳ τῇ πρὸς αὐτὸν ἐχρήσαντο μίσους ὑποφυέντος ὑπ’ αὐτῶν ἐπιβουλευθεὶς τελευτᾷ.", "st": "19.2.5"}, {"sp": "N", "t": "Κλαύδιος δέ, καθάπερ ἀνώτερον ἔφην, ἀπορρήξεως αὐτῷ τῶν Γαΐου ὁδῶν γενομένης καὶ τοῦ οἴκου θορυβηθέντος πάθει τῆς Καίσαρος τελευτῆς, ἐν ἀμηχάνοις ὢν περὶ τῆς σωτηρίας ἔν τινι στενωπῷ κατειλημμένος ἔκρυπτεν ἑαυτὸν οὐδεμίαν κινδύνων αἰτίαν πλὴν τῆς γενναιότητος ὑφορώμενος· μέτριον γὰρ ἰδιώτης ὢν ἦγεν αὑτὸν καὶ τοῖς πᾶσιν ἀρκῶν ἦν, παιδείᾳ τε συνιὼν καὶ μάλιστα τῇ Ἑλληνίδι καὶ παντὸς τοῦ εἰς θόρυβον ἀνακειμένου παντοίως ἀπαλλάσσων αὑτόν. τότε δὲ πτοίας κατειληφυίας τὸν ὄχλον καὶ τοῦ βασιλείου παντὸς στρατιωτικῆς μανίας ἀνάπλεω γεγονότος καὶ δειλίας καὶ ἀταξίας ἰδιωτῶν οἷον ἀπειληφότων σωματοφυλάκων, οἱ περὶ τὸ στρατηγικὸν καλούμενον, ὅπερ ἐστὶ τῆς στρατιᾶς καθαρώτατον, ἐν βουλῇ περὶ τοῖς πρακτέοις ἦσαν, ὅσοι δὲ καὶ παρετύγχανον, τὴν μὲν Γαΐου τιμωρίαν ἐν ὀλίγῳ τιθέμενοι διὰ τὸ κατὰ δίκην αὐτῷ τὰς τύχας συνελθεῖν, τὰ δὲ περὶ αὐτοὺς ἀνεσκοποῦντο μᾶλλον ὃν τρόπον σχήσοι καλῶς καὶ τῶν Γερμανῶν τε ἐν τιμωρίαις τῶν σφαγέων ὄντων ὠμότητος χάριτι τῆς ἑαυτῶν μᾶλλον ἢ τοῦ συμφέροντος τοῖς πᾶσιν. ὑφ’ ὧν ἁπάντων ὁ Κλαύδιος ἐθορυβεῖτο δεδιὼς περὶ τῆς σωτηρίας, ἄλλως τ’ ἐπειδὴ καὶ τῶν περὶ τὸν Ἀσπρήναν ἐτεθέατο τὰς κεφαλὰς παραφερομένας· εἱστήκει δὲ κατά τι προσβατὸν ὀλίγαις βαθμῖσι χωρίον ὑπεσταλκὼς τῷ κατ’ αὐτὸ σκότῳ. καὶ Γρᾶτος τῶν περὶ τὸ βασίλειόν τις στρατιωτῶν θεασάμενος καὶ τοῦ μὲν ἀκριβωσομένου τὴν ὄψιν ἀμαθὴς ὢν διὰ τὸν σκότον, τοῦ δὲ ἄνθρωπον εἶναι τὸν ὑπολοχῶντα κριτὴς εἶναι μὴ ἀπηλλαγμένος, προσῄει τε ἐγγύτερον καὶ ὑποχωρεῖν ἠξιωκότος ἐπέκειτο καὶ καταλαβὼν ἐπιγνωρίζει Γερμανικὸς μὲν οὗτος, φησὶν πρὸς τοὺς ἑπομένους, καὶ στησώμεθα τοῦτον ἡγεμόνα φερόμενοι. Κλαύδιος δὲ ἐφ’ ἁρπαγῇ παρεσκευασμένους ὁρῶν καὶ δείσας, μὴ κατὰ φωνὴν ἀποθάνοι τὴν Γαΐου, φειδὼ σχεῖν ἠξίου τοῦ κατ’ αὐτὸν ἀνεπαχθοῦς ἀνάμνησιν αὐτοῖς ὑποτιθεὶς καὶ τοῦ ἀπρομηθοῦς τῶν γεγονότων. καὶ ὁ Γρᾶτος μειδιάσας ἐπισπᾶται τῆς δεξιᾶς, καί παῦσαι, φησίν, μικρολογούμενος περὶ τῆς σωτηρίας δέον σε μεγαλοφρονεῖσθαι περὶ τῆς ἡγεμονίας, ἣν οἱ θεοὶ Γάιον ἀφῃρημένοι τῇ σῇ συνεχώρησαν ἀρετῇ πρόνοιαν τῆς οἰκουμένης λαβόντες. ἀλλ’ ἴθι καὶ τῶν προγόνων ἀπολάμβανε τὸν θρόνον. ἀνεβάσταζέν τε αὐτὸν οὐ πάνυ τοῖς ποσὶ βαίνειν δυνάμενον ὑπό τε φόβου καὶ χάρματος τῶν εἰρημένων.", "st": "19.3.1"}, {"sp": "N", "t": "Συνεστρέφοντο δὲ περὶ τὸν Γρᾶτον ἤδη καὶ πλείους τῶν σωματοφυλάκων καὶ θεωροῦντες τὸν Κλαύδιον ἀγόμενον δόξῃ τοῦ ἐπὶ κόλασιν ἕλκεσθαι τῶν ἐπὶ τοιοῖσδε ζημιῶν ὡς ἄνδρα ἀπράγμονα διὰ βίου τοῦ παντὸς καὶ κινδύνοις οὔτι μετρίως ἐπὶ τῆς Γαΐου ἀρχῆς ὡμιληκότα, τινὲς δὲ καὶ αὐτῶν τοῖς ὑπάτοις ἐντρέπειν κρίσιν ἠξίουν τὴν περὶ αὐτόν. καὶ πλειόνων τοῦ στρατιωτικοῦ συστρεφομένων φυγαί τε ἦσαν τοῦ ὁμίλου καὶ προόδων ἀπορία τῷ Κλαυδίῳ δι’ ἀσθένειαν τοῦ σώματος, ἐπεὶ καὶ οἱ τὸ φορεῖον αὐτοῦ φέροντες περὶ τὴν ἁρπαγὴν αὐτοῦ παραγενομένης φυγῆς ἔσωζον αὑτοὺς ἀπ’ ἐλπίδος θέμενοι τὴν σωτηρίαν τοῦ δεσπότου. ἐν εὐρυχωρίᾳ δὲ τοῦ Παλατίου γενομένοις, πρῶτον δὲ οἰκηθῆναι τῆς Ῥωμαίων πόλεως τοῦτο παραδίδωσιν ὁ περὶ αὐτῆς λόγος, καὶ ἤδη τοῦ δημοσίου ἀντιλαμβανομένοις πολὺ πλείων ἡ ἐπιφοίτησις ἦν τῶν στρατιωτῶν χαρᾷ τὴν ὄψιν δεχομένοις τοῦ Κλαυδίου, περὶ πλείστου τε ἦν αὐτοῖς αὐτοκράτορα στήσασθαι τὸν ἄνθρωπον εὐνοίᾳ τε τῇ Γερμανικοῦ, ἀδελφὸς δὲ ἦν αὐτοῦ ἐπὶ μέγα πᾶσιν τοῖς ὡμιληκόσιν καταλελοιπὼς κλέος τὸ αὐτοῦ. ἀναλογισμός τε αὐτοὺς εἰσῄει τῆς τε πλεονεξίας τῶν ἐν τῇ συγκλήτῳ δυναστευόντων καὶ ὁπόσα ἐπὶ τῆς πρὶν ἀρχῆς ἡμάρτητο αὐτῇ. πρὸς δὲ καὶ τὸ ἀμήχανον τοῦ πράγματος κατενόουν, καὶ πάλιν εἰς ἑνὸς ἀρχὴν μεθισταμένων τῶν ὅλων κινδύνους αὐτοῖς φέρειν δι’ ἑνὸς κτησαμένου τὴν ἀρχὴν [μεθισταμένων τῶν ὅλων] παρ’ ὃν ἐπιχωρήσει καὶ εὐνοίᾳ τῇ αὐτῶν λαβόντα Κλαύδιον μνημονεύσεις τε χάριτος αὐτοῖς ἀποδιδόντα τιμήν, ἣ ἐπὶ τοιούτοις γένοιτ’ ἂν ἀρκοῦσα.", "st": "19.3.2"}, {"sp": "N", "t": "Ταῦτα πρός τε ἀλλήλους καὶ δι’ ἑαυτοὺς διεξῄεσαν καὶ τοῖς ἀεὶ προσπίπτουσιν διηγοῦντο. οἱ δὲ πυνθανόμενοι προθύμως ἐδέχοντο τὴν πρόκλησιν, συμφράξαντές τε καὶ περικλάσαντες ἦγον ἐπὶ τοῦ στρατοπέδου φοράδην ἀναβαστάσαντες, ὡς μὴ ἐμποδίζοιτο αὐτοῖς ἡ ἔπειξις. διειστήκεσαν δὲ αἱ γνῶμαι τοῦ δήμου καὶ τῶν ἐκ τῆς βουλῆς· οἱ μὲν ἀξιώματός τε τοῦ πρότερον ὀρεγόμενοι καὶ δουλείαν ἔπακτον αὐτοῖς ὕβρει τῶν τυράννων γενομένην φιλοτιμούμενοι διαδιδράσκειν χρόνῳ παρασχόν, ὁ δὲ δῆμος φθόνῳ τε πρὸς ἐκείνην καθιστάμενος καὶ τῶν πλεονεξιῶν αὐτῆς ἐπιστόμισμα τοὺς αὐτοκράτορας εἰδὼς καὶ αὐτοῦ καταφυγὴν ἔχαιρεν Κλαυδίου τῇ ἁρπαγῇ στάσιν τε ἔμφυλον, ὁποία καὶ ἐπὶ Πομπηίου γένοιτο, ἀπαλλάξειν αὐτῶν ὑπελάμβανον τοῦτον αὐτοκράτορα καθισταμένου. γνοῦσα δ’ ἡ βουλὴ τὸν Κλαύδιον ὑπὸ τῶν στρατιωτῶν ἀφιγμένον εἰς τὸ στρατόπεδον πέμπει πρὸς ἐκεῖνον ἄνδρας ἀρετῇ τοὺς ἐξ αὐτῶν, οἳ διδάξειαν μὴ δεῖν ἐπὶ καθέξει τῆς ἀρχῆς βιάζεσθαι, παραχωρεῖν δὲ τῇ συγκλήτῳ τοσῶνδε ἀνδρῶν ἕνα ὄντα ἡσσώμενον καὶ τῷ νόμῳ παραχωροῦντα τοῦ ἐπὶ τοῖς κοινοῖς κόσμου τὴν πρόνοιαν, μνημονεύοντα ὧν οἱ πρότεροι τύραννοι κακώσειαν τὴν πόλιν καὶ ὧν ὑπὸ Γαΐου καὶ αὐτὸς κινδυνεύσειεν σὺν αὐτοῖς, μηδὲ μισήσαντα τὴν βαρύτητα τῆς τυραννίδος ὑφ’ ἑτέρων πρασσομένης τῆς ὕβρεως αὐτὸν ἐθελουσίως ἐπὶ παροινίᾳ θαρσεῖν τῆς πατρίδος. καὶ πειθομένῳ μὲν τοῦ πρότερον ἀπράγμονος τὴν ἀρετὴν ἐπιδεικνυμένῳ βέβαιον τιμάς τε ὑπάρξειν, αἳ ὑπὸ ἐλευθέρων ψηφισθεῖεν τῶν πολιτῶν, καὶ ἐπιχωρήσει τοῦ νόμου τὸ μέρος ἄρχοντά τε καὶ ἀρχόμενον κερδανεῖν ἔπαινον ἀρετῆς. εἰ δὲ ἀπονοοῖτο μηδὲν ἐκ τῆς Γαΐου τελευτῆς σωφρονιζόμενος οὔτι γε αὐτοὶ ἐπιτρέψειν τῆς τε γὰρ στρατιᾶς πολὺ εἶναι τὸ συνεστηκὸς αὐτοῖς ὅπλων τε εὐπορίαν καὶ πληθὺν οἰκετῶν, οἳ χρήσαιντο αὐτοῖς. μέγα δὲ μέρος τήν τε ἐλπίδα εἶναι καὶ τὴν τύχην, τούς τε θεοὺς οὐκ ἄλλοις συμμαχεῖν, ἀλλὰ τοῖς μετ’ ἀρετῆς καὶ τοῦ καλοῦ τοὺς ἀγῶνας ποιουμένοις. εἶναι δὲ τούτους, οἳ ἂν περὶ ἐλευθερίας μάχωνται τῆς πατρίδος.", "st": "19.3.3"}, {"sp": "N", "t": "Καὶ οἱ μὲν πρεσβευταὶ Οὐηράνιός τε καὶ Βρόγχος, δήμαρχοι δὲ ἦσαν ἀμφότεροι, τοῖσδε ἐχρῶντο τοῖς λόγοις καὶ καθικέτευον τοῖς γόνασιν αὐτοῦ προσπεσόντες μηδαμῶς πολέμοις καὶ κακοῖς ἐμβαλεῖν τὴν πόλιν, θεωροῦντες στρατιᾶς πληθύι τὸν Κλαύδιον πεφραγμένον καὶ τὸ μηδὲν τοὺς ὑπάτους ὄντας συγκρίσει τῇ πρὸς αὐτόν. εἴ τε τῆς ἀρχῆς ὀρέγοιτο, παρὰ τῆς βουλῆς δέχεσθαι διδομένην· αἰσιώτερον γὰρ καὶ εὐδαιμονέστερον χρῆσθαι τὸν μὴ μετὰ ὕβρεως ἀλλ’ εὐνοίᾳ τῶν διδόντων παραλαμβάνοντα.", "st": "19.3.4"}, {"sp": "N", "t": "Κλαύδιος δέ, ἠπίστατο γὰρ μεθ’ οἵας αὐθαδείας ἀποσταλεῖεν, καὶ πρὸς τὸ παρὸν γνώμῃ τῇ αὐτῶν ἐπὶ τὸ μετριώτερον τρεπόμενος, οὐ μὴν ἀλλὰ καὶ τῷ περὶ αὐτοὺς φόβῳ διαναστὰς ἅμα μὲν θάρσει τῶν στρατιωτῶν ἅμα δὲ Ἀγρίππου τοῦ βασιλέως κελεύοντος μὴ προέσθαι τῶν χειρῶν τηλικαύτην ἀρχὴν ἥκουσαν αὐτόματον. πράξας μὲν καὶ περὶ Γάιον οἷον εἰκὸς ἄνδρα ὑπ’ αὐτοῦ διὰ τιμῆς ἠγμένον, καὶ γὰρ τὸν νεκρὸν περιέσπεν τοῦ Γαΐου καὶ ἀναθέμενος ἐπὶ κλίνης καὶ περιστείλας ἐκ τῶν ἐνδεχομένων εἰς τοὺς σωματοφύλακας ὑπεχώρει, ζῆν μὲν τὸν Γάιον ἀπαγγέλλων κακοπαθοῦντί γε ὑπὸ τραυμάτων ἰατροὺς μετέσεσθαι λέγων· πυθόμενος δὲ τοῦ Κλαυδίου τὴν ὑπὸ τῶν στρατιωτῶν ἁρπαγὴν ὠθεῖτο πρὸς αὐτὸν καὶ καταλαβὼν τεταραγμένον καὶ οἷόν τε ἐκχωρεῖν τῇ συγκλήτῳ ἀνήγειρεν ἀντιλαμβάνεσθαι κελεύων τῆς ἡγεμονίας. ταῦτα δὲ πρὸς τὸν Κλαύδιον εἰπὼν προσεχώρει πρὸς αὐτόν, καὶ μετακαλούσης αὐτὸν τῆς βουλῆς χρισάμενος μύροις τὴν κεφαλὴν ὡς ἀπὸ συνουσίας γινομένης ἀναλύσεως αὐτῷ παρῆν καὶ ἤρετο τοὺς βουλευτάς, τί πέπραχε Κλαύδιος. τῶν δὲ τὰ ὄντα φαμένων καὶ προσανερομένων, ἥντινα γνώμην ἔχοι περὶ τοῖς ὅλοις, τελευτᾶν μὲν ὑπὲρ τοῦ κατ’ ἐκείνην εὐκλεοῦς ἕτοιμος ἦν τοῖς λόγοις, σκοπεῖν δὲ ἐκέλευε περὶ τῷ συμφέροντι πᾶν ὅ τι καὶ εἰς ἡδονὴν φέροι ὑπεξελομένους· χρείαν γὰρ εἶναι τοῖς ἀρχῆς μεταποιουμένοις καὶ ὅπλων καὶ στρατιωτῶν, οἳ φράξαιντο αὐτοῖς, μὴ καὶ ἀπαράσκευοι καταστάντες εἰς τάδε σφαλεῖεν. ἀποκριναμένης δὲ τῆς βουλῆς ὅπλων τε εὐπορίαν καὶ χρήματα εἰσοίσειν, καὶ στρατιᾶς τὸ μέν τι αὐτοῖς εἶναι συνεστηκός, τὸ δὲ συγκροτήσειν ἐλευθερώσεως δούλων γενομένης. εἴη μέν, ὦ βουλή, φησὶν ὁ Ἀγρίππας ὑποτυχών, πράσσειν ὁπόσα θυμὸς ὑμῖν, λεκτέον δὲ οὐδὲν ἐνδοιάσαντί μοι διὰ τὸ ἐπὶ σωτηρίᾳ φέρειν τὸν λόγον. ἴστε μὴν στρατόν, ὃς ὑπὲρ Κλαυδίου μαχεῖται, πλήθει χρόνου ὁπλιτεύειν μεμελετηκότα, τὰ δ’ ἡμέτερα, συγκλύδων ἀνθρώπων πλῆθος δ’ ἔσται καὶ τῶν παρὰ δόξαν τῆς δουλείας ἀπηλλαγμένων, δυσκράτητα. πρὸς δὲ τεχνίτας μαχούμεθα προαγαγόντες ἄνδρας μηδ’ ὅπως σπάσαι τὰ ξίφη εἰδότας. ὥστε μοι δοκεῖ πέμπειν ὡς Κλαύδιον πείσοντας κατατίθεσθαι τὴν ἀρχήν, πρεσβεύειν τε ἕτοιμός εἰμι.", "st": "19.4.1"}, {"sp": "N", "t": "Καὶ ὁ μὲν ταῦτα εἶπεν, καὶ συγκαταθεμένων πεμφθεὶς σὺν ἑτέροις τήν τε ταραχὴν τῆς βουλῆς διηγεῖται καταμόνας πρὸς τὸν Κλαύδιον ἐδίδασκέν τε ἡγεμονικώτερον ἀποκρίνασθαι καὶ τῷ ἀξιώματι τῆς ἐξουσίας χρώμενον. ἔλεγεν οὖν Κλαύδιος, οὐ θαυμάζειν τὴν βουλὴν ἡδονῇ μὴ φέρουσαν ἄρχεσθαι διὰ τὸ ὠμότητι τετρῦσθαι τῶν πρότερον ἐπὶ τὸ ἡγεμονεύειν καταστάντων, γεύσειν τε αὐτοὺς ἐπιεικείᾳ τῇ καθ’ αὑτὸν μετρίων καιρῶν, ὀνόματι μὲν μόνῳ τῆς ἀρχῆς ἐσομένης, ἔργῳ δὲ κοινῆς πᾶσι προκεισομένης εἰς μέσον. διὰ πολλῶν δὲ καὶ ποικίλων ὡδευκότι πραγμάτων ἐν ὄψει τῇ ἐκείνων καλῶς ἔχειν μὴ ἀπιστεῖν. καὶ οἱ μὲν πρέσβεις τοιούτων ἀκροάσει λόγων καθομιληθέντες ἐξεπέμποντο. Κλαύδιος δὲ τῷ στρατῷ συλλεχθέντι διελέγετο ὅρκους λαμβάνων ἦ μὴν ἐμμενεῖν πίστει τῇ πρὸς αὐτόν, δωρεῖται τοὺς σωματοφύλακας πεντακισχιλίαις δραχμαῖς κατὰ ἕκαστον ἄνδρα, τοῖς τε ἡγεμόσιν αὐτῶν ἀνάλογον τοῦ ἀριθμοῦ καὶ τοῖς ὅποι ποτὲ στρατοπέδοις ὑπισχνεῖτο τὰ ὅμοια.", "st": "19.4.2"}, {"sp": "N", "t": "Συνεκάλουν δὲ οἱ ὕπατοι τὴν βουλὴν εἰς τὸ ἱερὸν τοῦ νικηφόρου Διός· ἔτι δὲ νὺξ ἦν. τῶν δὲ οἱ μὲν ἐν τῇ πόλει κλέπτοντες ἑαυτοὺς ἐνεδοίαζον πρὸς τὴν ἀκρόασιν, τοῖς δὲ ἐπὶ τῶν ἰδίων ἀγρῶν ἐγεγόνεισαν ἔξοδοι προορωμένοις ᾗ χωρήσει τὸ πᾶν ἐν ἀπογνώσει τοῦ ἐλευθέρου γεγονότος, καὶ πολὺ κρεῖττον ἐν ἀκινδύνῳ τοῦ δουλεύειν ὑπειληφότες διαβιοῦν ἀργίᾳ τοῦ πονεῖν ἢ κτώμενοι τὸ ἀξίωμα τῶν πατέρων περὶ τῆς σωτηρίας ἀμφίβολοι καταστῆναι. συνελέγησαν δ’ ὅμως ἑκατὸν οὐ πλείους, καὶ διαβουλευομένων περὶ τῶν ἐν χερσὶν αἰφνίδιον αἴρεται βοὴ τοῦ συνεστηκότος αὐτοῖς στρατιωτικοῦ στρατηγὸν αὐτοκράτορα κελευόντων τὴν βουλὴν ἑλέσθαι καὶ μὴ φθείρειν πολυαρχίᾳ τὴν ἡγεμονίαν. καὶ τὸ μὲν καθ’ ἑαυτοὺς ἀπεφαίνοντο περὶ τοῦ μὴ πᾶσιν, ἀλλ’ ἑνὶ τὴν ἀρχὴν ἐφέσιμον εἶναι, ὁρᾶν δὲ ἐκείνοις ἐπιτρέπειν, ὅστις τοσαύτης προστασίας ἄξιος. ὥστε ἐν ἀνίᾳ τὰ τῶν συγκλητικῶν ἦν πολὺ πλέον δι’ ἁμαρτίαν μὲν τοῦ κατὰ τὴν ἐλευθερίαν αὐχήματος, φόβῳ δὲ τοῦ Κλαυδίου. οὐ μὴν ἀλλ’ ἦσαν οἱ ἐφιέμενοι γένους τε ἀξιώματι καὶ οἰκειότησιν γάμου· καὶ γὰρ Μινουκιανὸς Μᾶρκον καὶ τὸ καθ’ αὑτὸν γενναιότητι ἀξιόλογον ὄντα καὶ δὴ ἀδελφὴν Γαΐου γεγαμηκότα Ἰουλίαν, πρόθυμός τε ἦν ἀντιποιεῖσθαι τῶν πραγμάτων, κατεῖχον δὲ οἱ ὕπατοι πρόφασιν ἐκ προφάσεως ἀναρτῶντες. Οὐαλέριον δὲ Ἀσιατικὸν Μινουκιανὸς ἐκ τῶν Γαΐου σφαγέων ἀνεῖχε τοιούτων διανοιῶν. ἐγεγόνει δ’ ἂν φόνος οὔ τινος ἐλάσσων ἐπιχωρηθέντων τῶν ἐπιθυμούντων τῆς ἡγεμονίας, ὥστε ἀντιτάξασθαι Κλαυδίῳ, ἄλλως τε καὶ οἱ μονομάχοι, πλῆθος δ’ ἦν αὐτῶν ἀξιόλογον, καὶ τῶν στρατιωτῶν οἱ νυκτοφυλακοῦντες ἐπὶ τῆς πόλεως ἐρέται τε ὁπόσοι συνέρρεον εἰς τὸ στρατόπεδον, ὥστε τῶν μετιόντων τὴν ἀρχὴν οἱ μὲν φειδοῖ τῆς πόλεως, οἱ δὲ καὶ φόβῳ τῷ ὑπὲρ αὐτῶν ἀπέστησαν.", "st": "19.4.3"}, {"sp": "N", "t": "Ὑπὸ δὲ πρώτην ἀρχὴν τῆς ἡμέρας καὶ Χαιρέας καὶ οἱ σὺν αὐτῷ παρελθόντες ἐν ἐπιχειρήσει λόγων ἦσαν πρὸς τοὺς στρατιώτας. τῶν δὲ τὸ πλῆθος ὡς ὁρᾷ παύοντας αὐτοὺς ταῖς χερσὶ καὶ τοῦ εἰπεῖν οἵους τε ἄρχεσθαι, ἀνεθορύβησεν μὴ ἐφιέναι ὥστε εἰπεῖν διὰ τὸ ὡρμῆσθαι πάντας ἐπὶ τῷ μοναρχεῖσθαι, τὸν δὲ ἡγησόμενον ἐκάλουν ὡς οὐκ ἀνεξόμενοι τὰς τριβάς. τῇ συγκλήτῳ δὲ ἀπορία ἄρχειν τε καὶ ὃν ἀρχθεῖεν ἂν τρόπον οὔτε δεχομένων αὐτοὺς τῶν στρατιωτῶν καὶ τῶν Γαΐου σφαγέων συγχωρεῖν τοῖς στρατιώταις οὐκ ἐφιέντων. ἐν τοιούτοις δὲ ὄντων Χαιρέας τὴν ὀργὴν οὐκ ἀνασχόμενος πρὸς τὴν αἴτησιν τοῦ αὐτοκράτορος δώσειν ἐπηγγέλλετο στρατηγόν, εἴ τις αὐτῷ σημεῖον παρὰ Εὐτύχου κομίσειεν. ἦν δὲ ὁ Εὔτυχος οὗτος ἡνίοχος τοῦ καλουμένου πρασίνου περισπούδαστος Γαΐῳ, καὶ περὶ τὰς οἰκοδομὰς τῶν στάσεων τοῦ περὶ ἐκεῖνον ἱππικοῦ τὸ στρατιωτικὸν ἐτρίβετο ἀτίμοις ἐργασίαις ἐπικείμενον. εἰς ἅπερ ὁ Χαιρέας ὠνείδιζεν αὐτοὺς καὶ ἕτερα πολλὰ τοιαῦτα, τήν τε κεφαλὴν κομιεῖν τοῦ Κλαυδίου· δεινὸν γάρ, εἰ μετὰ μανίαν παραφροσύνῃ δώσουσι τὴν ἡγεμονίαν. οὐ μὴν διετράπησάν γε ὑπὸ τῶν λόγων, ἀλλὰ σπασάμενοι τὰς μαχαίρας καὶ τὰ σημεῖα ἀράμενοι ᾤχοντο ὡς τὸν Κλαύδιον κοινωνήσοντες τοῖς ὀμνύουσιν αὐτῷ. κατελείπετο δὲ ἥ τε σύγκλητος ἐπ’ ἐρημίας τῶν ἀμυνούντων καὶ οἱ ὕπατοι μηδὲν ἰδιωτῶν διαφέροντες. ἔκπληξίς τε καὶ κατήφεια ἦν, οὐδ’ ὅτι χρήσαιντο αὐτοῖς τῶν ἀνθρώπων εἰδότων διὰ τὸ ἀνηρεθίσθαι τὸν Κλαύδιον ἐπ’ αὐτοῖς, ἀλλήλοις τε ἐλοιδοροῦντο, καὶ μετάμελος ἦν αὐτοῖς. καὶ Σαβῖνος εἷς τῶν Γαΐου σφαγέων σφάζειν πρότερον αὑτὸν ἠπείλει παρελθὼν εἰς μέσους ἢ Κλαύδιον ἄρχοντα στήσεσθαι καὶ δουλοκρατίαν ἐπόψεσθαι καταλαβοῦσαν, τόν τε Χαιρέαν εἰς φιλοψυχίαν ἐπέπλησσεν, εἰ καταφρονήσας Γαΐου πρῶτος ἀγαθὸν ὑπολαμβάνοι τὸ ζῆν τῆς ἐλευθερίας οὐδ’ οὕτως ἀποδοθῆναι δυναμένης τῇ πατρίδι. Χαιρέας δὲ περὶ μὲν τοῦ θνήσκειν ἐνδοιαστὸν οὐδὲν φρονεῖν ἔλεγεν, βούλεσθαι μέντοι διακωδωνίζειν διάνοιαν τὴν Κλαυδίου.", "st": "19.4.4"}, {"sp": "N", "t": "Καὶ οἱ μὲν ἐν τοῖσδε ἦσαν. ἐπὶ δὲ τοῦ στρατοπέδου πανταχόθεν ὠθεῖτο κατὰ θεραπείαν. καὶ τῶν ὑπάτων ὁ ἕτερος Κόιντος Πομπώνιος δι’ αἰτίας ἦν τῷ στρατιωτικῷ μᾶλλον ὡς ἐπ’ ἐλευθερίᾳ τὴν σύγκλητον παρακαλῶν, ὥρμησάν τε σπασάμενοι τὰ ξίφη, κἂν ἐπέπρακτο αὐτοῖς μὴ Κλαυδίου διακεκωλυκότος. παρακαθίζεται δὲ αὐτῷ τὸν ὕπατον ἐξαρπάσας τοῦ κινδύνου, τῶν δὲ συγκλητικῶν ὅσον ἦν σὺν τῷ Κοΐντῳ οὐ μεθ’ ὁμοίας ἐδέχετο τιμῆς· τινὲς δὲ καὶ πληγὰς ἔλαβον αὐτῶν ἀνωθούμενοι τῆς πρὸς αὐτὸν ἐντεύξεως, Ἀπώνιος δὲ τραυματίας ἀνεχώρει, ἦν τε κίνδυνος περὶ πάντας αὐτούς. καὶ Ἀγρίππας ὁ βασιλεὺς προσελθὼν τῷ Κλαυδίῳ ἀξιοῖ τοῖς συγκλητικοῖς ἠπιώτερον καταστῆναι· γενομένου γάρ τινος κακοῦ περὶ τὴν βουλὴν οὐχ ἕξειν ὧν ἄρξειεν ἑτέρων. πείθεται δὲ Κλαύδιος καὶ συγκαλεῖ τὴν βουλὴν ἐπὶ τοῦ Παλατίου διὰ τῆς πόλεως φερόμενος παραπέμποντος αὐτὸν τοῦ στρατιωτικοῦ σὺν πολλῇ πάνυ κακώσει τῆς πληθύος. προεξῄεσαν δὲ τῶν Γαΐου σφαγέων εἰς τὸ φανερώτερον Χαιρέας καὶ Σαβῖνος εἰργόμενοι προόδων κατ’ ἐπιστολὰς Πολλίωνος, ὃν μικρῷ πρότερον Κλαύδιος στρατηγὸν ᾕρητο τῶν σωματοφυλάκων. Κλαύδιος δέ, ἐπείπερ εἰς τὸ Παλάτιον ἀφικνεῖται συναγαγὼν τοὺς ἑταίρους ψῆφον ἀνεδίδου περὶ Χαιρέου. τοῖς δὲ τὸ μὲν ἔργον λαμπρὸν ἐδόκει, ἀπιστίαν δ’ ἐπεκάλουν τῷ πεπραχότι καὶ αὐτῷ τιμωρίαν ἐπιβάλλειν δίκαιον ἡγοῦντο ἐπ’ ἀποτροπῇ τοῦ μέλλοντος χρόνου. ἀπήγετο οὖν τὴν ἐπὶ θανάτῳ καὶ σὺν αὐτῷ Λοῦππός τε καὶ Ῥωμαίων πλείους. λέγεται δὲ Χαιρέας μεγαλοφρόνως ἐνεγκεῖν τὴν συμφορὰν οὐ μόνον τῷ κατ’ αὐτὸν ἀμεταπτώτῳ τοῦ σχήματος, ἀλλὰ καὶ οἷς ὀνειδίσειεν Λοῦππον εἰς δάκρυα ἐκτετραμμένον. ἀποτιθεμένου γέ τοι τὴν στολὴν τοῦ Λούππου καὶ τὸ ῥῖγος αἰτιωμένου φησίν, ὡς οὐκ ἂν ἐναντία τοῦ Λούππου ποιήσαιτο πώποτε ῥῖγος. πλήθους τε ἀνθρώπων ἑπομένου κατὰ θέαν, ὡς ἧκεν ἐπὶ τὸ χωρίον, ἤρετο τὸν στρατιώτην, εἰ διὰ μελέτης αὐτῷ γεγόνοιεν αἱ σφαγαὶ ἢ εἰ πρῶτον ἔχοι τὸ ξίφος ἐκέλευε κομίζειν ᾧ Γάιον μεταχειρίσαιτο αὐτός· θνήσκει δὲ εὐδαιμόνως μιᾶς πληγῆς αὐτῷ γενομένης. Λοῦππος δὲ οὐ πάνυ δεξιῶς ὑπεξῆλθεν ἀθυμίᾳ καὶ πληγῶν πλειόνων γενομένων διὰ τὸ μαλακῶς τὸν τράχηλον παρασχεῖν.", "st": "19.4.5"}, {"sp": "N", "t": "Ὀλίγαις δὲ ὕστερον ἡμέραις ἐναγισμῶν ἐνεστηκότων Ῥωμαίων τὸ πλῆθος τοῖς αὐτῶν ἐπιφέροντες καὶ Χαιρέαν μοίραις ἐτίμησαν εἰς τὸ πῦρ τιθεμέναις, ἵλεων καὶ ἄμηνιν εἶναι τῆς εἰς αὐτὸν ἀχαριστίας παρακαλοῦντες. καὶ Χαιρέᾳ μὲν τοιαύτη τελευτὴ τοῦ βίου συνέτυχεν. Σαβῖνος δὲ Κλαυδίου μὴ μόνον τῆς αἰτίας παραλύοντος αὐτὸν ἀλλὰ καὶ τὴν ἀρχὴν ἣν εἶχεν ἐφιέντος, ἄδικον ἡγεῖτο τὴν ἐκλειπίαν τῆς πρὸς τοὺς συνωμότας πίστεως, σφάζει ἑαυτὸν περιπεσὼν τῷ ξίφει μέχρι δὴ καὶ τὴν κώπην τῷ τραύματι συνελθεῖν.", "st": "19.4.6"}, {"sp": "N", "t": "Κλαύδιος δὲ τοῦ στρατιωτικοῦ πᾶν ὅ τι ἦν ὕποπτον ἐκ τοῦ ὀξέος ἀποσκευασάμενος διάγραμμα προυτίθει τήν τε ἀρχὴν Ἀγρίππα βεβαιῶν, ἣν ὁ Γάιος παρέσχε, καὶ δι’ ἐγκωμίων ἄγων τὸν βασιλέα. προσθήκην τε αὐτῷ ποιεῖται πᾶσαν τὴν ὑπὸ Ἡρώδου βασιλευθεῖσαν, ὃς ἦν πάππος αὐτοῦ, Ἰουδαίαν καὶ Σαμάρειαν. καὶ ταῦτα μὲν ὡς ὀφειλόμενα τῇ οἰκειότητι τοῦ γένους ἀπεδίδου· Ἄβιλαν δὲ τὴν Λυσανίου καὶ ὁπόσα ἐν τῷ Λιβάνῳ ὄρει ἐκ τῶν αὐτοῦ προσετίθει, ὅρκιά τε αὐτῷ τέμνεται πρὸς τὸν Ἀγρίππαν ἐπὶ τῆς ἀγορᾶς μέσης ἐν τῇ Ῥωμαίων πόλει. Ἀντίοχον δὲ ἣν εἶχεν βασιλείαν ἀφελόμενος Κιλικίας μέρει τινὶ καὶ Κομμαγηνῇ δωρεῖται. λύει δὲ καὶ Ἀλέξανδρον τὸν ἀλαβάρχην φίλον ἀρχαῖον αὐτῷ γεγονότα καὶ Ἀντωνίαν αὐτοῦ ἐπιτροπεύσαντα τὴν μητέρα ὀργῇ τῇ Γαΐου δεδεμένον, καὶ αὐτοῦ υἱὸς Βερενίκην τὴν Ἀγρίππου γαμεῖ θυγατέρα. καὶ ταύτην μέν, τελευτᾷ γὰρ Μᾶρκος ὁ τοῦ Ἀλεξάνδρου υἱὸς παρθένον λαβών, ἀδελφῷ τῷ αὐτοῦ Ἀγρίππας Ἡρώδῃ δίδωσιν Χαλκίδος αὐτῷ τὴν βασιλείαν εἶναι αἰτησάμενος παρὰ Κλαυδίου.", "st": "19.5.1"}, {"sp": "N", "t": "Στασιάζεται δὲ κατ’ αὐτὸν τὸν χρόνον Ἰουδαίων τὰ πρὸς Ἕλληνας ἐπὶ τῆς Ἀλεξανδρέων πόλεως. τελευτήσαντος γὰρ τοῦ Γαΐου τὸ Ἰουδαίων ἔθνος ἐπὶ ἀρχῆς τῆς ἐκείνου τεταπεινωμένον καὶ δεινῶς ὑπὸ τῶν Ἀλεξανδρέων ὑβρισμένον ἀνεθάρσησέ τε καὶ ἐν ὅπλοις εὐθέως ἦν. καὶ Κλαύδιος ἐπιστέλλει τῷ ἐπαρχοῦντι κατὰ τὴν Αἴγυπτον ὥστε τὴν στάσιν καταστεῖλαι, πέμπει δὲ καὶ διάγραμμα παρακεκληκότων αὐτὸν Ἀγρίππου τε καὶ Ἡρώδου τῶν βασιλέων εἴς τε τὴν Ἀλεξάνδρειαν καὶ Συρίαν γεγραμμένον τοῦτον τὸν τρόπον· Τιβέριος Κλαύδιος Καῖσαρ Σεβαστὸς Γερμανικὸς δημαρχικῆς ἐξουσίας λέγει. ἐπιγνοὺς ἀνέκαθεν τοὺς ἐν Ἀλεξανδρείᾳ Ἰουδαίους Ἀλεξανδρεῖς λεγομένους συγκατοικισθέντας τοῖς πρώτοις εὐθὺ καιροῖς Ἀλεξανδρεῦσι καὶ ἴσης πολιτείας παρὰ τῶν βασιλέων τετευχότας, καθὼς φανερὸν ἐγένετο ἐκ τῶν γραμμάτων τῶν παρ’ αὐτοῖς καὶ τῶν διαταγμάτων, καὶ μετὰ τὸ τῇ ἡμετέρᾳ ἡγεμονίᾳ Ἀλεξάνδρειαν ὑπὸ τοῦ Σεβαστοῦ ὑποταχθῆναι πεφυλάχθαι αὐτοῖς τὰ δίκαια ὑπὸ τῶν πεμφθέντων ἐπάρχων κατὰ διαφόρους χρόνους μηδεμίαν τε ἀμφισβήτησιν περὶ τούτων γενομένην τῶν δικαίων αὐτοῖς, ἅμα καὶ καθ’ ὃν καιρὸν Ἀκύλας ἦν ἐν Ἀλεξανδρείᾳ τελευτήσαντος τοῦ τῶν Ἰουδαίων ἐθνάρχου τὸν Σεβαστὸν μὴ κεκωλυκέναι ἐθνάρχας γίγνεσθαι βουλόμενον ὑποτετάχθαι ἑκάστους ἐμμένοντας τοῖς ἰδίοις ἔθεσιν καὶ μὴ παραβαίνειν ἀναγκαζομένους τὴν πάτριον θρησκείαν, Ἀλεξανδρεῖς δὲ ἐπαρθῆναι κατὰ τῶν παρ’ αὐτοῖς Ἰουδαίων ἐπὶ τῶν Γαΐου Καίσαρος χρόνων τοῦ διὰ τὴν πολλὴν ἀπόνοιαν καὶ παραφροσύνην, ὅτι μὴ παραβῆναι ἠθέλησεν τὸ Ἰουδαίων ἔθνος τὴν πάτριον θρησκείαν καὶ θεὸν προσαγορεύειν αὐτόν, ταπεινώσαντος αὐτούς· βούλομαι μηδὲν διὰ τὴν Γαΐου παραφροσύνην τῶν δικαίων τῷ Ἰουδαίων ἔθνει παραπεπτωκέναι, φυλάσσεσθαι δ’ αὐτοῖς καὶ τὰ πρότερον δικαιώματα ἐμμένουσι τοῖς ἰδίοις ἔθεσιν, ἀμφοτέροις τε διακελεύομαι τοῖς μέρεσι πλείστην ποιήσασθαι πρόνοιαν, ὅπως μηδεμία ταραχὴ γένηται μετὰ τὸ προτεθῆναί μου τὸ διάταγμα.", "st": "19.5.2"}, {"sp": "N", "t": "Τὸ μὲν οὖν εἰς Ἀλεξάνδρειαν ὑπὲρ τῶν Ἰουδαίων διάταγμα τοῦτον ἦν τὸν τρόπον γεγραμμένον· τὸ δ’ εἰς τὴν ἄλλην οἰκουμένην εἶχεν οὕτως· Τιβέριος Κλαύδιος Καῖσαρ Σεβαστὸς Γερμανικὸς ἀρχιερεὺς μέγιστος δημαρχικῆς ἐξουσίας ὕπατος χειροτονηθεὶς τὸ δεύτερον λέγει. αἰτησαμένων με βασιλέως Ἀγρίππα καὶ Ἡρώδου τῶν φιλτάτων μοι, ὅπως συγχωρήσαιμι τὰ αὐτὰ δίκαια καὶ τοῖς ἐν πάσῃ τῇ ὑπὸ Ῥωμαίοις ἡγεμονίᾳ Ἰουδαίοις φυλάσσεσθαι, καθὰ καὶ τοῖς ἐν Ἀλεξανδρείᾳ, ἥδιστα συνεχώρησα οὐ μόνον τοῦτο τοῖς αἰτησαμένοις με χαριζόμενος, ἀλλὰ καὶ αὐτοὺς ὑπὲρ ὧν παρεκλήθην ἀξίους κρίνας διὰ τὴν πρὸς Ῥωμαίους πίστιν καὶ φιλίαν, μάλιστα δὲ δίκαιον κρίνων μηδεμίαν μηδὲ Ἑλληνίδα πόλιν τῶν δικαίων τούτων ἀποτυγχάνειν, ἐπειδὴ καὶ ἐπὶ τοῦ θείου Σεβαστοῦ αὐταῖς ἦν τετηρημένα. καλῶς οὖν ἔχειν καὶ Ἰουδαίους τοὺς ἐν παντὶ τῷ ὑφ’ ἡμᾶς κόσμῳ τὰ πάτρια ἔθη ἀνεπικωλύτως φυλάσσειν, οἷς καὶ αὐτοῖς ἤδη νῦν παραγγέλλω μου ταύτῃ τῇ φιλανθρωπίᾳ ἐπιεικέστερον χρῆσθαι καὶ μὴ τὰς τῶν ἄλλων ἐθνῶν δεισιδαιμονίας ἐξουθενίζειν, τοὺς ἰδίους δὲ νόμους φυλάσσειν. τοῦτό μου τὸ διάταγμα τοὺς ἄρχοντας τῶν πόλεων καὶ τῶν κολωνιῶν καὶ μουνικιπίων τῶν ἐν τῇ Ἰταλίᾳ καὶ τῶν ἐκτός, βασιλεῖς τε καὶ δυνάστας διὰ τῶν ἰδίων πρεσβευτῶν ἐγγράψασθαι βούλομαι ἐκκείμενόν τε ἔχειν οὐκ ἔλαττον ἡμερῶν τριάκοντα ὅθεν ἐξ ἐπιπέδου καλῶς ἀναγνωσθῆναι δύναται.", "st": "19.5.3"}, {"sp": "N", "t": "Τούτοις μὲν δὴ τοῖς διατάγμασιν εἰς Ἀλεξάνδρειάν τε καὶ τὴν οἰκουμένην πᾶσαν ἀποσταλεῖσιν ἐδήλωσεν ἣν περὶ Ἰουδαίων ἔχοι γνώμην Κλαύδιος Καῖσαρ· αὐτίκα δὲ Ἀγρίππαν κομιούμενον τὴν βασιλείαν ἐπὶ τιμαῖς λαμπροτέραις ἐξέπεμψε τοῖς ἐπὶ τῶν ἐπαρχιῶν ἡγεμόσιν καὶ τοῖς ἐπιτρόποις διὰ γραμμάτων ἐπιστείλας ἐράσμιον ἄγειν αὐτόν. ὁ δ’, ὡς εἰκὸς ἦν τὸν ἐπὶ κρείττοσιν τύχαις ἀνερχόμενον, μετὰ τάχους ὑπέστρεψεν, εἰς Ἱεροσόλυμα δ’ ἐλθὼν χαριστηρίους ἐξεπλήρωσε θυσίας οὐδὲν τῶν κατὰ νόμον παραλιπών. διὸ καὶ ναζιραίων ξυρᾶσθαι διέταξε μάλα συχνούς, τὴν δὲ χρυσῆν ἅλυσιν τὴν δοθεῖσαν αὐτῷ ὑπὸ Γαΐου ἰσόσταθμον τῇ σιδηρᾷ, ᾗ τὰς ἡγεμονίδας χεῖρας ἐδέθη, τῆς στυγνῆς εἶναι τύχης ὑπόμνημα καὶ τῆς ἐπὶ τὰ κρείττω μαρτυρίαν μεταβολῆς τῶν ἱερῶν ἐντὸς ἀνεκρέμασεν περιβόλων ὑπὲρ τὸ γαζοφυλάκιον, ἵν’ ᾖ δεῖγμα καὶ τοῦ τὰ μεγάλα δύνασθαί ποτε πεσεῖν καὶ τοῦ τὸν θεὸν ἐγείρειν τὰ πεπτωκότα· πᾶσι γὰρ τοῦτ’ ἐνεφάνιζεν ἡ τῆς ἁλύσεως ἀνάθεσις, ὅτι βασιλεὺς Ἀγρίππας ἀπὸ μικρᾶς αἰτίας εἰς δεσμώτην ἀπέδυ τὸ πρὶν ἀξίωμα καὶ μετ’ ὀλίγον τῆς πέδης ἐκβὰς εἰς βασιλέα τοῦ πάλαι λαμπρότερον ἠγέρθη. διὰ τοῦτ’ οὖν ἐννοεῖσθαι, ὅτι τῆς ἀνθρωπίνης φύσεως καὶ [πεσεῖν] ὀλισθάνειν τὰ μεγέθη καὶ τὰ κλιθέντα δύναται περιφανὲς λαβεῖν πάλιν ὕψος.", "st": "19.6.1"}, {"sp": "N", "t": "Ἐντελῶς δ’ οὖν θρησκεύσας τὸν θεὸν Ἀγρίππας Θεόφιλον μὲν τὸν Ἀνάνου τῆς ἀρχιερωσύνης μετέστησεν, τῷ δὲ Βοηθοῦ Σίμωνι, τούτῳ Κανθηρᾶς ἐπίκλησις ἦν, τὴν ἐκείνου προσένειμε τιμήν. δύο δ’ ἦσαν ἀδελφοὶ τῷ Σίμωνι καὶ πατὴρ Βοηθός, οὗ τῇ θυγατρὶ βασιλεὺς συνῴκησεν Ἡρώδης, ὡς ἀνωτέρω δεδήλωται. σὺν τοῖς ἀδελφοῖς οὖν τὴν ἱερωσύνην ἔσχεν ὁ Σίμων καὶ σὺν τῷ πατρί, καθὰ καὶ πρότερον ἔσχον οἱ Σίμωνος τοῦ Ὀνία παῖδες τρεῖς ὄντες ἐπὶ τῆς τῶν Μακεδόνων ἀρχῆς, ὅπερ ἐν ταῖς προαγούσαις γραφαῖς παρέδομεν.", "st": "19.6.2"}, {"sp": "N", "t": "Καταστησάμενος δὲ τὰ περὶ τοὺς ἀρχιερεῖς οὕτως ὁ βασιλεὺς τοὺς Ἱεροσολυμίτας ἠμείψατο τῆς εἰς αὐτὸν εὐνοίας· ἀνῆκε γοῦν αὐτοῖς τὰ ὑπὲρ ἑκάστης οἰκίας, ἐν καλῷ τιθέμενος ἀντιδοῦναι τοῖς ἠγαπηκόσιν στοργήν. ἔπαρχον δὲ ἀπέδειξεν παντὸς τοῦ στρατεύματος Σίλαν ἄνδρα πολλῶν αὐτῷ πόνων συμμετασχόντα. παντάπασιν δὲ ὀλίγου χρόνου διελθόντος Δωρῖται νεανίσκοι τῆς ὁσιότητος προτιθέμενοι τόλμαν καὶ πεφυκότες εἶναι παραβόλως θρασεῖς Καίσαρος ἀνδριάντα κομίσαντες εἰς τὴν τῶν Ἰουδαίων συναγωγὴν ἀνέστησαν. σφόδρα τοῦτο Ἀγρίππαν παρώξυνεν· κατάλυσιν γὰρ τῶν πατρίων αὐτοῦ νόμων ἐδύνατο. ἀμελλητὶ δὲ πρὸς Πούπλιον Πετρώνιον, ἡγεμὼν δὲ τῆς Συρίας οὗτος ἦν, παραγίνεται καὶ καταλέγει τῶν Δωριτῶν. ὁ δ’ οὐχ ἧττον ἐπὶ τῷ πραχθέντι χαλεπήνας, καὶ γὰρ αὐτὸς ἔκρινεν ἀσέβειαν τὴν τῶν ἐννόμων παράβασιν, τοῖς ἀποστᾶσι τῶν Δωριτῶν σὺν ὀργῇ ταῦτ’ ἔγραψεν· Πούπλιος Πετρώνιος πρεσβευτὴς Τιβερίου Κλαυδίου Καίσαρος Σεβαστοῦ Γερμανικοῦ Δωριέων τοῖς πρώτοις λέγει. ἐπειδὴ τοσαύτῃ τόλμῃ ἀπονοίας τινὲς ἐχρήσαντο ἐξ ὑμῶν, ὥστε μηδὲ διὰ τὸ προτεθῆναι διάταγμα Κλαυδίου Καίσαρος Σεβαστοῦ Γερμανικοῦ περὶ τοῦ ἐφίεσθαι Ἰουδαίους φυλάσσειν τὰ πάτρια πεισθῆναι ὑμᾶς αὐτῷ, τἀναντία δὲ πάντα πρᾶξαι, συναγωγὴν Ἰουδαίων κωλύοντας εἶναι διὰ τὸ μεταθεῖναι ἐν αὐτῇ τὸν Καίσαρος ἀνδριάντα, παρανομοῦντας οὐκ εἰς μόνους Ἰουδαίους, ἀλλὰ καὶ εἰς τὸν αὐτοκράτορα, οὗ ὁ ἀνδριὰς βέλτιον ἐν τῷ ἰδίῳ ναῷ ἢ ἐν ἀλλοτρίῳ ἐτίθετο καὶ ταῦτα ἐν τῷ τῆς συναγωγῆς τόπῳ, τοῦ φύσει δικαιοῦντος ἕνα ἕκαστον τῶν ἰδίων τόπων κυριεύειν κατὰ τὸ Καίσαρος ἐπίκριμα· τοῦ γὰρ ἐμοῦ ἐπικρίματος μιμνήσκεσθαι γελοῖόν ἐστιν μετὰ τὸ τοῦ αὐτοκράτορος διάταγμα τοῦ ἐπιτρέψαντος Ἰουδαίοις τοῖς ἰδίοις ἔθεσι χρῆσθαι, ἔτι μέντοι γε καὶ συμπολιτεύεσθαι τοῖς Ἕλλησιν κεκελευκότος· τοὺς μὲν παρὰ τὸ διάταγμα τοῦ Σεβαστοῦ τοιαῦτα τετολμηκότας, ἐφ’ ᾧ καὶ αὐτοὶ ἠγανάκτησαν οἱ δοκοῦντες αὐτῶν ἐξέχειν οὐ τῇ ἰδίᾳ προαιρέσει γεγενῆσθαι λέγοντες ἀλλὰ τῇ τοῦ πλήθους ὁρμῇ, ὑπὸ ἑκατοντάρχου Πρόκλου Οὐιτελλίου ἐκέλευσα ἐπ’ ἐμὲ ἀναχθῆναι τῶν πεπραγμένων λόγον ἀποδώσοντας, τοῖς δὲ πρώτοις ἄρχουσι παραινῶ, εἰ μὴ βούλονται δοκεῖν κατὰ τὴν αὐτῶν προαίρεσιν γεγενῆσθαι τὸ ἀδίκημα, ἐπιδεῖξαι τοὺς αἰτίους τῷ ἑκατοντάρχῃ μηδεμιᾶς στάσεως μηδὲ μάχης ἐῶντας ἀφορμὴν γενέσθαι, ἥνπερ δοκοῦσίν μοι θηρεύεσθαι διὰ τῶν τοιούτων ἔργων, κἀμοῦ καὶ τοῦ τιμιωτάτου μοι βασιλέως Ἀγρίππου οὐδενὸς μᾶλλον προνοουμένων, ἢ ἵνα μὴ ἀφορμῆς δραξάμενοι τὸ τῶν Ἰουδαίων ἔθνος ὑπὸ τῆς ἀμύνης προφάσει συναθροισθὲν εἰς ἀπόνοιαν χωρῇ. ἵνα δὲ γνωριμώτερον ᾖ, τί καὶ ὁ Σεβαστὸς περὶ ὅλου τοῦ πράγματος ἐφρόνησε, τὰ ἐν Ἀλεξανδρείᾳ αὐτοῦ διατάγματα προτεθέντα προσέθηκα, ἅπερ εἰ καὶ γνώριμα πᾶσιν εἶναι δοκεῖ, τότε καὶ ἐπὶ τοῦ βήματος ἀνέγνω ὁ τιμιώτατός μοι βασιλεὺς Ἀγρίππας δικαιολογησάμενος περὶ τοῦ μὴ δεῖν αὐτοὺς ἀφαιρεθῆναι τῆς τοῦ Σεβαστοῦ δωρεᾶς. εἴς τε οὖν τὸ λοιπὸν παραγγέλλω μηδεμίαν πρόφασιν στάσεως μηδὲ ταραχῆς ζητεῖν, ἀλλ’ ἑκάστους τὰ ἴδια ἔθη θρησκεύειν.", "st": "19.6.3"}, {"sp": "N", "t": "Πετρώνιος μὲν οὖν οὕτω προυνόησε διορθώσεως μὲν τὸ παρανομηθὲν ἤδη τυχεῖν, γενέσθαι δὲ παραπλήσιον μηδὲν εἰς αὐτούς. Ἀγρίππας δὲ ὁ βασιλεὺς ἀφείλετο μὲν τὴν ἀρχιερωσύνην τὸν Κανθηρᾶν Σίμωνα, Ἰωνάθην δὲ πάλιν ἐπ’ αὐτὴν ἦγεν τὸν Ἀνάνου τοῦτον ἀξιώτερον τῆς τιμῆς ὁμολογῶν εἶναι. τῷ δὲ οὐκ ἀσμενιστὸν ἐφάνη τὴν τοσαύτην ἀπολαβεῖν τιμήν, παρῃτεῖτο δ’ οὖν ταῦτα λέγων· σοὶ μέν, ὦ βασιλεῦ, τετιμημένος χαίρω διὰ ψυχῆς ἔχων τοῦθ’ ὅ μοι γέρας δίδωσιν ἡ σὴ βουλὴ, καὶ πρὸς οὐδέν με τῆς ἀρχιερωσύνης ἄξιον ἔκρινεν ὁ θεός. ἅπαξ δ’ ἐνδὺς στολισμὸν ἱερὸν ἀρκοῦμαι· τότε γὰρ αὐτὸν ἠμφιασάμην ὁσιώτερον ἢ νῦν ἀπολήψομαι. σὺ δ’, εἰ βούλει τὸν ἀξιώτερον ἐμοῦ νῦν τὸ γέρας λαβεῖν, διδάχθητι· πάσης καὶ πρὸς τὸν θεὸν ἁμαρτίας καὶ πρὸς σέ, βασιλεῦ, καθαρὸς ἀδελφὸς ἔστι μοι· πρέποντα τῇ τιμῇ τοῦτον συνίστημι. τούτοις ὁ βασιλεὺς ἡσθεὶς τοῖς λόγοις τὸν Ἰωνάθην μὲν ἠγάσατο τῆς γνώμης, τἀδελφῷ δὲ αὐτοῦ Ματθίᾳ τὴν ἱερωσύνην ἔδωκε. καὶ μετ’ οὐ πολὺ Πετρώνιον μὲν Μάρσος διεδέξατο καὶ διεῖπε Συρίαν.", "st": "19.6.4"}, {"sp": "N", "t": "Σίλας δ’ ὁ τοῦ βασιλέως ἔπαρχος ἐπεὶ διὰ πάσης αὐτῷ τύχης ἐγεγόνει πιστὸς οὐδένα κίνδυνόν ποτε κοινωνεῖν ἀνηνάμενος, ἀλλὰ καὶ τοὺς σφαλερωτάτους ὑποδὺς πολλάκις πόνους, πεποιθήσεως ἦν ἀνάπλεως, προσήκειν ὑπολαμβάνων ἰσοτιμίαν βεβαιότητι φιλίας. οὐδαμῆ τοίνυν ὑποκατεκλίνετο βασιλεῖ, παρρησίαν δὲ διὰ πάσης ὁμιλίας ἦγεν, κἀν ταῖς φιλοφρονήσεσιν ἐγίνετο φορτικὸς σεμνύνων ἑαυτὸν ἀμέτρως καὶ πολλάκις τῷ βασιλεῖ τὰ στυγνὰ τῆς τύχης ἄγων εἰς ἀνάμνησιν, ἵνα τὴν ἑαυτοῦ τότε σπουδὴν παραδεικνύῃ, συνεχῶς δ’ ἦν, ὡς ὑπὲρ αὐτοῦ κάμοι, πολλὰ διεξιών. τούτων οὖν τὸ πλεονάζον ὀνειδισμὸς ἐδόκει· διὸ προσάντως ὁ βασιλεὺς ἐδέχετο τὴν ἀταμίευτον παρρησίαν τἀνδρός· οὐχ ἡδεῖαι γὰρ αἱ τῶν ἀδόξων χρόνων ἀναμνήσεις, εὐήθης δὲ ὁ διηνεκῶς ἅ ποτε ὠφέλησεν προφέρων. τέλος γοῦν ἀνηρέθισε σφόδρα ὁ Σίλας τοῦ βασιλέως τὸν θυμὸν κἀκεῖνος ὀργῇ πλέον ἢ λογισμῷ διδοὺς οὐ τῆς ἐπαρχίας μόνον μετέστησε τὸν Σίλαν, ἀλλὰ καὶ παρέδωκεν δεθησόμενον εἰς τὴν ἐκείνου πατρίδα πέμψας. χρόνῳ δὲ τὸν θυμὸν ἠμβλύνθη καὶ λογισμοῖς εἰλικρινέσι τὴν περὶ τἀνδρὸς κρίσιν ἐφῆκεν ἐν νῷ λαμβάνων ὅσους ὑπὲρ ἐκείνου πόνους ἐκεῖνος ἀνέτλη. ἡμέραν οὖν ἑορτάζων αὐτοῦ γενέθλιον, ὅτε πᾶσιν ὧν ἦρχεν εὐφροσύνη ᾗ καθίσταντο θαλίαι, τὸν Σίλαν ἀνεκάλει παραυτίκα συνέστιον αὐτῷ γενησόμενον. τῷ δέ, τρόπος γὰρ ἐλευθέριος ἦν, ἐδόκει προσειληφέναι δικαίαν αἰτίαν ὀργῆς, ἣν οὐκ ἀπεκρύπτετο πρὸς τοὺς μετιόντας αὐτὸν λέγων· ἐπὶ ποίαν ὁ βασιλεὺς τιμὴν ἀνακαλεῖ με τὴν μετὰ μικρὸν ἀπολουμένην; οὐδὲ γὰρ τὰ πρῶτά μοι γέρα τῆς εἰς αὐτὸν εὐνοίας ἐτήρησεν, ἀπεσύλησεν δ’ ὑβρίσας. ἢ πεπαῦσθαι νενόμικέ με τῆς παρρησίας, ἣν ἀπὸ ποίου συνειδότος ἔχων βοήσομαι μᾶλλον, ὅσων αὐτὸν ἐξελυσάμην δεινῶν, ὅσους ἤνεγκα πόνους ἐκείνῳ ποριζόμενος σωτηρίαν τε καὶ τιμήν, ὧν γέρας ἠνεγκάμην δεσμὰ καὶ σκότιον εἱρκτήν. οὐκ ἐγώ ποτε τούτων λήσομαι· τάχα μοι τὴν τῆς ἀριστείας συνεποίσεται μνήμην καὶ μεταστᾶσα τῆς σαρκὸς ἡ ψυχή. ταῦτα ἀνεβόα καὶ διετάττετο τῷ βασιλεῖ λέγειν. ὁ δ’ ὡς ἀνιάτως ἑώρα διακείμενον, πάλιν εἴασεν ἐν φρουρᾷ.", "st": "19.7.1"}, {"sp": "N", "t": "Τὰ δὲ τῶν Ἱεροσολύμων τείχη τὰ πρὸς τὴν καινὴν νεύοντα πόλιν δημοσίαις ὠχύρου δαπάναις, τῇ μὲν εὐρύνων εἰς πλάτος τῇ δὲ εἰς ὕψος ἐξαίρων, κἂν ἐξειργάσατο ταῦτα πάσης ἀνθρωπίνης κρείττονα βίας, εἰ μὴ Μάρσος ὁ τῆς Συρίας ἡγεμὼν Κλαυδίῳ Καίσαρι διὰ γραμμάτων ἐδήλωσε τὸ πραττόμενον. καὶ νεωτερισμόν τινα Κλαύδιος ὑποπτεύσας ἐπέστειλεν Ἀγρίππᾳ μετὰ σπουδῆς παύσασθαι τῆς τῶν τειχῶν ἐξοικοδομήσεως· ὁ δ’ ἀπειθεῖν οὐκ ἔκρινεν.", "st": "19.7.2"}, {"sp": "N", "t": "Ἐπεφύκει δ’ ὁ βασιλεὺς οὗτος εὐεργετικὸς εἶναι ἐν δωρεαῖς καὶ μεγαλοφρονῆσαι ἔθνη φιλότιμος καὶ πολλοῖς ἀθρόως δαπανήμασιν ἀνιστὰς αὑτὸν εἰς ἐπιφάνειαν ἡδόμενος τῷ χαρίζεσθαι καὶ τῷ βιοῦν ἐν εὐφημίᾳ χαίρων, κατ’ οὐδὲν Ἡρώδῃ τῷ πρὸ ἑαυτοῦ βασιλεῖ τὸν τρόπον συμφερόμενος· ἐκείνῳ γὰρ πονηρὸν ἦν ἦθος ἐπὶ τιμωρίαν ἀπότομον καὶ κατὰ τῶν ἀπηχθημένων ἀταμίευτον, Ἕλλησι πλέον ἢ Ἰουδαίοις οἰκείως ἔχειν ὁμολογούμενος· ἀλλοφύλων γέ τοι πόλεις ἐσέμνυνεν δόσει χρημάτων βαλανείων θεάτρων τε ἄλλοτε κατασκευαῖς, ἔστιν αἷς ναοὺς ἀνέστησε, στοὰς ἄλλαις, ἀλλὰ Ἰουδαίων οὐδεμίαν πόλιν οὐδ’ ὀλίγης ἐπισκευῆς ἠξίωσεν οὐδὲ δόσεως ἀξίας μνημονευθῆναι. πραῢς δ’ ὁ τρόπος Ἀγρίππᾳ καὶ πρὸς πάντας τὸ εὐεργετικὸν ὅμοιον. τοῖς ἀλλοεθνέσιν ἦν φιλάνθρωπος κἀκείνοις ἐνδεικνύμενος τὸ φιλόδωρον τοῖς ὁμοφύλοις ἀναλόγως χρηστὸς καὶ συμπαθὴς μᾶλλον. ἡδεῖα γοῦν αὐτῷ δίαιτα καὶ συνεχὴς ἐν τοῖς Ἱεροσολύμοις ἦν καὶ τὰ πάτρια καθαρῶς ἐτήρει. διὰ πάσης γοῦν αὑτὸν ἦγεν ἁγνείας οὐδ’ ἡμέρα τις παρώδευεν αὐτῷ τὰ νόμιμα χηρεύουσα θυσίας.", "st": "19.7.3"}, {"sp": "N", "t": "Καὶ δή τις ἐν τοῖς Ἱεροσολύμοις ἀνὴρ ἐπιχώριος ἐξακριβάζειν δοκῶν τὰ νόμιμα, Σίμων ἦν ὄνομα τούτῳ, πλῆθος εἰς ἐκκλησίαν ἁλίσας τηνικάδε τοῦ βασιλέως εἰς Καισάρειαν ἐκδεδημηκότος ἐτόλμησεν αὐτοῦ κατειπεῖν, ὡς οὐχ ὅσιος εἴη, δικαίως δ’ ἂν εἴργοιτο τοῦ ναοῦ τῆς εἰσόδου προσηκούσης τοῖς ἐγγενέσιν. δηλοῦται μὲν δὴ διὰ γραμμάτων ὑπὸ τοῦ στρατηγοῦ τῆς πόλεως τῷ βασιλεῖ δημηγορήσας Σίμων ταῦτα, μεταπέμπεται δὲ αὐτὸν ὁ βασιλεὺς καί, καθέζετο γὰρ ἐν τῷ θεάτρῳ τότε, καθεσθῆναι παρ’ αὐτὸν ἐκέλευσεν. ἠρέμα τε καὶ πρᾴως εἰπέ μοι, φησίν, τί τῶν ἐνθάδε γινομένων ἐστὶ παράνομον; ὁ δὲ εἰπεῖν ἔχων οὐδὲν τυχεῖν ἐδεῖτο συγγνώμης. ἀλλὰ ὁ βασιλεὺς αὐτῷ ἢ προσεδόκησέν τις διηλλάττετο τὴν πρᾳότητα κρίνων βασιλικωτέραν ὀργῆς καὶ πρέπειν εἰδὼς τοῖς μεγέθεσι θυμοῦ πλέον ἐπιείκειαν. τὸν Σίμωνα γοῦν καὶ δωρεᾶς τινος ἀξιώσας ἀπεπέμπετο.", "st": "19.7.4"}, {"sp": "N", "t": "Πολλοῖς δὲ κατασκευάσας πολλὰ Βηρυτίους ἐξαιρέτως ἐτίμησεν· θέατρον γὰρ αὐτοῖς κατεσκεύασε πολυτελείᾳ τε καὶ κάλλει πολλῶν διαφέρον ἀμφιθέατρόν τε πολλῶν ἀναλωμάτων βαλανεῖα πρὸς τούτοις καὶ στοάς, ἐν οὐδενὶ τῶν ἔργων στενότητι δαπανημάτων ἢ τὸ κάλλος ἀδικήσας ἢ τὸ μέγεθος. ἐπεδαψιλεύσατο δ’ αὐτῶν τὴν καθιέρωσιν μεγαλοπρεπῶς, ἐν τῷ θεάτρῳ μὲν θεωρίας ἐπιτελῶν πάνθ’ ὅσα μουσικῆς ἔργα παράγων καὶ ποικίλης ποιητικὰ τέρψεως, ἐν δὲ τῷ ἀμφιθεάτρῳ πλήθει μονομάχων τὴν αὐτοῦ δεικνὺς μεγαλόνοιαν. ἔνθα καὶ τὴν κατὰ πλῆθος ἀντίταξιν βουληθεὶς γενέσθαι τῶν θεωμένων τέρψιν ἑπτακοσίους ἄνδρας ἑπτακοσίοις μαχησομένους εἰσέπεμψεν κακούργους ὅσους εἶχεν ἀποτάξας εἰς τήνδε τὴν πρᾶξιν, ἵν’ οἱ μὲν κολασθῶσιν, τὸ πολέμου δ’ ἔργον γένηται τέρψις εἰρήνης. τούτους μὲν οὖν πασσυδὶ διέφθειρεν.", "st": "19.7.5"}, {"sp": "N", "t": "Ἐν Βηρυτῷ δὲ τελέσας τὰ προειρημένα μετῆλθεν εἰς Τιβεριάδα πόλιν τῆς Γαλιλαίας. ἦν δὲ ἄρα τοῖς ἄλλοις βασιλεῦσιν περίβλεπτος. ἧκε γοῦν παρ’ αὐτὸν Κομμαγηνῆς μὲν βασιλεὺς Ἀντίοχος, Ἐμεσῶν δὲ Σαμψιγέραμος καὶ Κότυς, τῆς μικρᾶς Ἀρμενίας οὗτος ἐβασίλευσεν, καὶ Πολέμων τὴν Πόντου κεκτημένος δυναστείαν Ἡρώδης τε· οὗτος ἀδελφὸς ἦν αὐτοῦ, ἦρχεν δὲ τῆς Χαλκίδος. ὡμίλησε δὲ πᾶσιν κατά τε τὰς ὑποδοχὰς καὶ φιλοφρονήσεις ὡς μάλιστα διαδείξας φρονήσεως ὕψος καὶ διὰ τοῦτό γε δοκεῖν δικαίως τῇ τοῦ βασιλέως παρουσίᾳ τετιμῆσθαι. ἀλλὰ γὰρ τούτων διατριβόντων ἔτι παρ’ αὐτῷ Μάρσος ὁ τῆς Συρίας ἡγεμὼν παρεγένετο. πρὸς Ῥωμαίους οὖν τιμητικὸν τηρῶν ὑπαντησόμενος αὐτῷ τῆς πόλεως ἀπωτέρω σταδίους ἑπτὰ προῆλθεν ὁ βασιλεύς. τοῦτο δὲ ἄρα ἔμελλεν τῆς πρὸς Μάρσον ἀρχὴ γενήσεσθαι διαφορᾶς· συγκαθεζόμενος γὰρ ἐπὶ τῆς ἀπήνης ἐπήγετο τοὺς ἄλλους βασιλέας, Μάρσῳ δ’ ἡ τούτων ὁμόνοια καὶ μέχρι τοσοῦδε φιλία πρὸς ἀλλήλους ὑπωπτεύθη συμφέρειν οὐχ ὑπολαμβάνοντι Ῥωμαίοις δυναστῶν τοσούτων συμφρόνησιν. εὐθὺς οὖν ἑκάστῳ τῶν ἐπιτηδείων τινὰς πέμπων ἐπέστελλεν ἐπὶ τὰ ἑαυτοῦ δίχα μελλήσεως ἀπέρχεσθαι. ταῦτα Ἀγρίππας ἀνιαρῶς ἐξεδέχετο· καὶ Μάρσῳ μὲν ἐκ τούτου διαφόρως ἔσχεν, τὴν ἀρχιερωσύνην δὲ Ματθίαν ἀφελόμενος ἀντ’ αὐτοῦ κατέστησεν ἀρχιερέα Ἐλιωναῖον τὸν τοῦ Κιθαίρου παῖδα.", "st": "19.8.1"}, {"sp": "N", "t": "Τρίτον δὲ ἔτος αὐτῷ βασιλεύοντι τῆς ὅλης Ἰουδαίας πεπλήρωτο, καὶ παρῆν εἰς πόλιν Καισάρειαν, ἣ τὸ πρότερον Στράτωνος πύργος ἐκαλεῖτο. συνετέλει δ’ ἐνταῦθα θεωρίας εἰς τὴν Καίσαρος τιμὴν ὑπὲρ τῆς ἐκείνου σωτηρίας ἑορτήν τινα ταύτην ἐπιστάμενος, καὶ παρ’ αὐτὴν ἤθροιστο τῶν κατὰ τὴν ἐπαρχίαν ἐν τέλει καὶ προβεβηκότων εἰς ἀξίαν πλῆθος. δευτέρᾳ δὴ τῶν θεωριῶν ἡμέρᾳ στολὴν ἐνδὺς ἐξ ἀργύρου πεποιημένην πᾶσαν, ὡς θαυμάσιον ὑφὴν εἶναι, παρῆλθεν εἰς τὸ θέατρον ἀρχομένης ἡμέρας. ἔνθα ταῖς πρώταις τῶν ἡλιακῶν ἀκτίνων ἐπιβολαῖς ὁ ἄργυρος καταυγασθεὶς θαυμασίως ἀπέστιλβε μαρμαίρων τι φοβερὸν καὶ τοῖς εἰς αὐτὸν ἀτενίζουσι φρικῶδες. εὐθὺς δὲ οἱ κόλακες τὰς οὐδὲ ἐκείνῳ πρὸς ἀγαθοῦ ἄλλος ἄλλοθεν φωνὰς ἀνεβόων, θεὸν προσαγορεύοντες εὐμενής τε εἴης ἐπιλέγοντες, εἰ καὶ μέχρι νῦν ὡς ἄνθρωπον ἐφοβήθημεν, ἀλλὰ τοὐντεῦθεν κρείττονά σε θνητῆς φύσεως ὁμολογοῦμεν. οὐκ ἐπέπληξεν τούτοις ὁ βασιλεὺς οὐδὲ τὴν κολακείαν ἀσεβοῦσαν ἀπετρίψατο. ἀνακύψας δ’ οὖν μετ’ ὀλίγον τὸν βουβῶνα τῆς ἑαυτοῦ κεφαλῆς ὑπερκαθιζόμενον εἶδεν ἐπὶ σχοινίου τινός. ἄγγελον τοῦτον εὐθὺς ἐνόησεν κακῶν εἶναι τὸν καί ποτε τῶν ἀγαθῶν γενόμενον, καὶ διακάρδιον ἔσχεν ὀδύνην, ἄθρουν δ’ αὐτῷ τῆς κοιλίας προσέφυσεν ἄλγημα μετὰ σφοδρότητος ἀρξάμενον. ἀναθορὼν οὖν πρὸς τοὺς φίλους, ὁ θεὸς ὑμῖν ἐγώ, φησίν, ἤδη καταστρέφειν ἐπιτάττομαι τὸν βίον, παραχρῆμα τῆς εἱμαρμένης τὰς ἄρτι μου κατεψευσμένας φωνὰς ἐλεγχούσης· ὁ κληθεὶς ἀθάνατος ὑφ’ ὑμῶν ἤδη θανεῖν ἀπάγομαι. δεκτέον δὲ τὴν πεπρωμένην, ᾗ θεὸς βεβούληται· καὶ γὰρ βεβιώκαμεν οὐδαμῇ φαύλως, ἀλλ’ ἐπὶ τῆς μακαριζομένης λαμπρότητος. ταῦθ’ ἅμα λέγων ἐπιτάσει τῆς ὀδύνης κατεπονεῖτο· μετὰ σπουδῆς οὖν εἰς τὸ βασίλειον ἐκομίσθη καὶ διῇξε λόγος εἰς πάντας, ὡς ἔχοι τοῦ τεθνάναι παντάπασι μετ’ ὀλίγον. ἡ πληθὺς δ’ αὐτίκα σὺν γυναιξὶν καὶ παισὶν ἐπὶ σάκκων καθεσθεῖσα τῷ πατρίῳ νόμῳ τὸν θεὸν ἱκέτευεν ὑπὲρ τοῦ βασιλέως, οἰμωγῆς δὲ πάντ’ ἦν ἀνάπλεα καὶ θρήνων. ἐν ὑψηλῷ δ’ ὁ βασιλεὺς δωματίῳ κατακείμενος καὶ κάτω βλέπων αὐτοὺς πρηνεῖς καταπίπτοντας ἄδακρυς οὐδ’ αὐτὸς διέμενεν. συνεχεῖς δ’ ἐφ’ ἡμέρας πέντε τῷ τῆς γαστρὸς ἀλγήματι διεργασθεὶς τὸν βίον κατέστρεψεν, ἀπὸ γενέσεως ἄγων πεντηκοστὸν ἔτος καὶ τέταρτον, τῆς βασιλείας δ’ ἕβδομον. τέτταρας μὲν οὖν ἐπὶ Γαΐου Καίσαρος ἐβασίλευσεν ἐνιαυτοὺς τῆς Φιλίππου μὲν τετραρχίας εἰς τριετίαν ἄρξας, τῷ τετάρτῳ δὲ καὶ τὴν Ἡρώδου προσειληφώς, τρεῖς δ’ ἐπιλαβὼν τῆς Κλαυδίου Καίσαρος αὐτοκρατορίας, ἐν οἷς τῶν τε προειρημένων ἐβασίλευσεν καὶ τὴν Ἰουδαίαν προσέλαβεν Σαμάρειάν τε καὶ Καισάρειαν. προσωδεύσατο δ’ ὅτι πλείστας αὐτῶν προσφορὰς διακοσίας ἐπὶ χιλίαις μυριάδας, πολλὰ μέντοι προσεδανείσατο· τῷ γὰρ φιλόδωρος εἶναι δαψιλέστερα τῶν προσιόντων ἀνήλισκεν, ἦν δὲ ἀφειδὲς αὐτοῦ τὸ φιλότιμον.", "st": "19.8.2"}, {"sp": "N", "t": "Ἀγνοουμένης γε μὴν τοῖς πλήθεσιν τῆς ἐκπνοῆς αὐτοῦ συμφρονήσαντες Ἡρώδης τε ὁ τῆς Χαλκίδος δυναστεύων καὶ Ἑλκίας ὁ ἔπαρχος καὶ φίλος τοῦ βασιλέως Ἀρίστωνα ἔπεμψαν τῶν ὑπηρετῶν τὸν ἐπιτήδειον καὶ Σίλαν, ἐχθρὸς γὰρ ἦν αὐτοῖς, ἀπέσφαξαν ὡς δὴ τοῦ βασιλέως κελεύσαντος.", "st": "19.8.3"}, {"sp": "N", "t": "Ἀγρίππας μὲν οὖν ὁ βασιλεὺς τρόπῳ τοιούτῳ κατέστρεψεν τὸν βίον, γένει δὲ αὐτῷ κατελέλειπτο υἱὸς μὲν Ἀγρίππας ἄγων ἔτος ἑπτακαιδέκατον, τρεῖς δὲ θυγατέρες, ὧν ἡ μὲν Ἡρώδῃ τοῦ πατρὸς ἀδελφῷ γεγάμητο Βερενίκη τὸ ἑκκαιδέκατον ἔτος γεγονυῖα, παρθένοι δ’ ἦσαν αἱ δύο Μαριάμμη τε καὶ Δρούσιλλα, δεκαετὴς μὲν ἡ ἑτέρα, ἑξαετὴς δὲ Δρούσιλλα· καθωμολόγηντο δ’ ὑπὸ τοῦ πατρὸς πρὸς γάμον Ἰουλίῳ μὲν Ἀρχελάῳ τοῦ Χελκίου παιδὶ Μαριάμμη, Δρούσιλλα δὲ Ἐπιφανεῖ, τοῦ δὲ τῆς Κομμαγηνῆς βασιλέως Ἀντιόχου υἱὸς ἦν οὗτος. ἀλλὰ γὰρ ὅτε ἐγνώσθη τὸν βίον ἐκλιπὼν Ἀγρίππας, Καισαρεῖς καὶ Σεβαστηνοὶ τῶν εὐποιιῶν αὐτοῦ λαθόμενοι τὰ τῶν δυσμενεστάτων ἐποίησαν· βλασφημίας τε γὰρ ἀπερρίπτουν εἰς τὸν κατοιχόμενον ἀπρεπεῖς λέγεσθαι καὶ ὅσοι στρατευόμενοι τότε ἔτυχον, συχνοὶ δ’ ἦσαν, οἴκαδε ἀπῆλθον καὶ τοὺς ἀνδριάντας τῶν τοῦ βασιλέως θυγατέρων ἁρπάσαντες ὁμοθυμαδὸν ἐκόμισαν εἰς τὰ πορνεῖα καὶ στήσαντες ἐπὶ τῶν τεγῶν ὡς δυνατὸν ἦν ἀφύβριζον ἀσχημονέστερα διηγήσεως δρῶντες, ἐπί τε τοῖς δημοσίοις κατακλινόμενοι τόποις πανδήμους ἑστιάσεις ἐπετέλουν στεφανούμενοι καὶ μυριζόμενοι καὶ σπένδοντες τῷ Χάρωνι προπόσεις τῆς τοῦ βασιλέως ἐκπνοῆς ἀλλήλοις ἀνταποδιδόντες. ἀμνήμονες δ’ ἦσαν οὐκ Ἀγρίππα μόνον χρησαμένου πολλαῖς εἰς αὐτοὺς φιλοτιμίαις, καὶ τοῦ πάππου δὲ Ἡρώδου· τὰς πόλεις ἐκεῖνος αὐτοῖς ἔκτισεν λιμένας τε καὶ ναοὺς κατεσκεύασεν λαμπροῖς δαπανήμασιν.", "st": "19.9.1"}, {"sp": "N", "t": "Ὁ δὲ τοῦ τεθνεῶτος υἱὸς Ἀγρίππας ἐπὶ Ῥώμης ἦν ἐν τῷ χρόνῳ τούτῳ τρεφόμενος παρὰ Κλαυδίῳ Καίσαρι. πυθόμενός γε μὴν Καῖσαρ, ὅτι τέθνηκεν Ἀγρίππας, Σεβαστηνοὶ δὲ καὶ Καισαρεῖς ὑβρίκασιν εἰς αὐτόν, ἐπ’ ἐκείνῳ μὲν ἤλγησεν, ἐπὶ δὲ τοὺς ἀχαριστήσαντας ὠργίσθη. πέμπειν οὖν εὐθέως ὥρμητο τὸν νεώτερον Ἀγρίππαν τὴν βασιλείαν διαδεξόμενον ἅμα βουλόμενος ἐμπεδοῦν τοὺς ὀμωμοσμένους ὅρκους, ἀλλὰ τῶν ἐξελευθέρων καὶ φίλων οἱ πολὺ παρ’ αὐτῷ δυνάμενοι ἀπέτρεψαν, σφαλερὸν εἶναι λέγοντες κομιδῇ νέῳ μηδὲ τοὺς παιδὸς ἐκβεβηκότι χρόνους ἐπιτρέπειν βασιλείας τηλικοῦτον μέγεθος, ᾧ μὴ δυνατὸν τὰς τῆς διοικήσεως φροντίδας ἐνεγκεῖν, καὶ τελείῳ δ’ οὖν εἶναι βαρὺ βάσταγμα βασιλείαν. ἔδοξεν οὖν αὐτοὺς εἰκότα λέγειν ὁ Καῖσαρ. ἔπαρχον οὖν τῆς Ἰουδαίας καὶ τῆς ἁπάσης βασιλείας ἀπέστειλεν Κούσπιον Φᾶδον τῷ κατοιχομένῳ διδοὺς τιμὴν τὸ μὴ Μάρσον ἐπαγαγεῖν εἰς βασιλείαν αὐτῷ διάφορον. ἐγνώκει δὲ πρὸ πάντων ἐπιστεῖλαι τῷ Φάδῳ Καισαρεῦσιν καὶ Σεβαστηνοῖς ἐπιπλῆξαι τῆς εἰς τὸν κατοιχόμενον ὕβρεως καὶ παροινίας εἰς τὰς ἔτι ζώσας, τὴν ἴλην δὲ τῶν Καισαρέων καὶ τῶν Σεβαστηνῶν καὶ τὰς πέντε σπείρας εἰς Πόντον μεταγαγεῖν, ἵν’ ἐκεῖ στρατεύοιντο, τῶν δ’ ἐν Συρίᾳ Ῥωμαϊκῶν ταγμάτων ἐπιλέξαι στρατιώτας κατ’ ἀριθμοὺς καὶ τὸν ἐκείνων ἀναπληρῶσαι τόπον. οὐ μὴν οἱ κελευσθέντες μετέστησαν· πρεσβευσάμενοι γὰρ Κλαύδιον ἀπεμειλίξαντο καὶ μένειν ἐπὶ τῆς Ἰουδαίας ἐπέτυχον, οἳ καὶ τοῖς ἐπιοῦσι χρόνοις τῶν μεγίστων Ἰουδαίοις ἐγένοντο συμφορῶν ἀρχὴ τοῦ κατὰ Φλῶρον πολέμου σπέρματα βαλόντες. ὅθεν Οὐεσπασιανὸς κρατήσας, ὡς μετ’ ὀλίγον ἐροῦμεν, ἐξήγαγεν αὐτοὺς τῆς ἐπαρχίας.", "st": "19.9.2"}, {"sp": "HDR", "t": "Βιβλίον Κʹ", "st": "20"}, {"sp": "N", "t": "Τελευτήσαντος δὲ τοῦ βασιλέως Ἀγρίππα, καθὼς ἐν τῇ πρὸ ταύτης ἀπηγγέλκαμεν βίβλῳ, πέμπει Μάρσῳ διάδοχον Κλαύδιος Καῖσαρ Κάσσιον Λογγῖνον, μνήμῃ τῇ τοῦ βασιλέως τοῦτο χαριζόμενος, πολλὰ διὰ γραμμάτων ὑπ’ αὐτοῦ περιόντος ἀξιωθεὶς μηκέτι Μάρσον τῶν κατὰ τὴν Συρίαν πραγμάτων προΐστασθαι. Φᾶδος δὲ ὡς εἰς τὴν Ἰουδαίαν ἐπίτροπος ἀφίκετο, καταλαμβάνει στασιάσαντας τοὺς τὴν Περαίαν κατοικοῦντας Ἰουδαίους πρὸς Φιλαδελφηνοὺς περὶ ὅρων κώμης μιᾶς λεγομένης πολεμίων ἀνδρῶν ἀνάπλεω· καὶ δὴ οἱ τῆς Περαίας χωρὶς γνώμης τῆς τῶν πρώτων παρ’ αὐτοῖς ἀναλαβόντες τὰ ὅπλα πολλοὺς τῶν Φιλαδελφηνῶν διαφθείρουσιν. ταῦτα πυθόμενον τὸν Φᾶδον σφόδρα παρώξυνεν, ὅτι μὴ τὴν κρίσιν αὐτῷ παραλίποιεν, εἴπερ ὑπὸ τῶν Φιλαδελφηνῶν ἐνόμιζον ἀδικεῖσθαι, ἀλλ’ ἐφ’ ὅπλα χωρήσειαν. λαβὼν οὖν τρεῖς τοὺς πρώτους αὐτῶν τοὺς καὶ τῆς στάσεως αἰτίους δῆσαι προσέταξεν, εἶτα τὸν μὲν αὐτῶν ἀνεῖλεν, Ἀννίβας δ’ ἦν ὄνομα τούτῳ, Ἀμαράμῳ δὲ καὶ Ἐλεαζάρῳ τοῖς δυσὶ φυγὴν ἐπέβαλεν. ἀναιρεῖται δὲ καὶ Θολομαῖος ὁ ἀρχιλῃστὴς μετ’ οὐ πολὺν χρόνον ἀχθεὶς ἐπ’ αὐτὸν διατεθεικὼς μέγιστα κακὰ τὴν Ἰδουμαίαν καὶ τοὺς Ἄραβας, ἐκαθάρθη τε λῃστηρίων ἅπασα τοὐντεῦθεν Ἰουδαία προνοίᾳ καὶ φροντίδι τῇ Φάδου· ὃς δὴ καὶ τότε μεταπεμψάμενος τοὺς ἀρχιερεῖς καὶ τοὺς πρώτους τῶν Ἱεροσολυμιτῶν παρῄνεσεν αὐτοῖς τὸν ποδήρη χιτῶνα καὶ τὴν ἱερὰν στολήν, ἣν φορεῖν μόνος ὁ ἀρχιερεὺς ἔθος ἔχει, εἰς τὴν Ἀντωνίαν, ἥπερ ἐστὶ φρούριον, καταθέσθαι κεισομένην ὑπὸ τῇ Ῥωμαίων ἐξουσίᾳ, καθὰ δὴ καὶ πρότερον ἦν. οἱ δὲ ἀντιλέγειν μὲν οὐκ ἐτόλμων, παρεκάλουν δ’ ὅμως τόν τε Φᾶδον καὶ τὸν Λογγῖνον, ἀφίκετο γὰρ καὶ αὐτὸς εἰς τὰ Ἱεροσόλυμα πολλὴν ἐπαγόμενος δύναμιν φόβῳ τοῦ μὴ τὰ προστάγματα Φάδου τὸ πλῆθος τῶν Ἰουδαίων νεωτερίζειν ἀναγκάσῃ, πρῶτον μὲν αὐτοῖς ἐπιτρέψαι πρέσβεις ὡς Καίσαρα πέμψαι τοὺς αἰτησομένους παρ’ αὐτοῦ τὴν ἱερὰν στολὴν ὑπὸ τὴν αὐτῶν ἐξουσίαν ἔχειν, εἶτα δὲ περιμεῖναι μέχρις ἂν γνῶσιν, τί πρὸς ταῦτα Κλαύδιος ἀποκρίναιτο. οἱ δὲ ἐπιτρέψειν αὐτοῖς ἔφασαν ἀποστεῖλαι τοὺς πρέσβεις, εἰ λάβοιεν τοὺς παῖδας ὁμηρεύσοντας. ὑπακουσάντων δ’ ἑτοίμως ἐκείνων καὶ δόντων ἐξεπέμφθησαν οἱ πρέσβεις. παραγενομένων δὲ εἰς τὴν Ῥώμην αὐτῶν γνοὺς ὁ νεώτερος Ἀγρίππας ὁ τοῦ τετελευτηκότος παῖς, καθ’ ἣν ἥκουσιν αἰτίαν, ἐτύγχανεν δὲ ὢν παρὰ Κλαυδίῳ Καίσαρι, καθὼς καὶ πρότερον εἴπομεν, παρακαλεῖ τὸν Καίσαρα συγχωρῆσαι τοῖς Ἰουδαίοις ἅπερ ἠξίουν περὶ τῆς ἱερᾶς στολῆς καὶ Φάδῳ περὶ τούτων ἐπιστεῖλαι.", "st": "20.1.1"}, {"sp": "N", "t": "Καλέσας δὲ Κλαύδιος τοὺς πρέσβεις ἔφη ταῦτα συγχωρεῖν καὶ ἐκέλευεν αὐτοὺς Ἀγρίππᾳ χάριν εἰδέναι, ταῦτα γὰρ ἐκείνου ποιεῖν ἀξιώσαντος, ἐπί τε ταῖς ἀποκρίσεσιν τοιαύτην ἐπιστολὴν ἔδωκεν· Κλαύδιος Καῖσαρ Γερμανικὸς δημαρχικῆς ἐξουσίας τὸ πέμπτον ὕπατος ἀποδεδειγμένος τὸ τέταρτον αὐτοκράτωρ τὸ δέκατον πατὴρ πατρίδος Ἱεροσολυμιτῶν ἄρχουσι βουλῇ δήμῳ Ἰουδαίων παντὶ ἔθνει χαίρειν. Ἀγρίππα τοῦ ἐμοῦ, ὃν ἐγὼ ἔθρεψα καὶ ἔχω σὺν ἐμαυτῷ εὐσεβέστατον ὄντα, προσαγαγόντος μοι τοὺς ὑμετέρους πρέσβεις εὐχαριστοῦντας ἐφ’ ᾗ πεποίημαι τοῦ ἔθνους ὑμῶν κηδεμονίᾳ, καὶ αἰτησαμένων σπουδαίως καὶ φιλοτίμως τὴν ἱερὰν ἐσθῆτα καὶ τὸν στέφανον ὑπὸ τὴν ἐξουσίαν ὑμῶν εἶναι, συγχωρῶ καθὼς ὁ κράτιστος καί μοι τιμιώτατος Οὐιτέλλιος ἐποίησεν. συγκατεθέμην δὲ τῇ γνώμῃ ταύτῃ πρῶτον διὰ τὸ ἐμαυτοῦ εὐσεβὲς καὶ τὸ βούλεσθαι ἑκάστους κατὰ τὰ πάτρια θρησκεύειν, ἔπειτα δὲ εἰδώς, ὅτι καὶ αὐτῷ βασιλεῖ Ἡρώδῃ καὶ Ἀριστοβούλῳ τῷ νεωτέρῳ, ὧν τὴν πρὸς ἐμαυτὸν εὐσέβειαν καὶ τὴν περὶ ὑμᾶς γινώσκω σπουδήν ταῦτα ποιήσας, πρὸς οὓς ἔστι μοι πλεῖστα δίκαια φιλίας κρατίστους ὄντας κἀμοὶ τιμίους. ἔγραψα δὲ περὶ τούτων καὶ Κουσπίῳ Φάδῳ τῷ ’μῷ ἐπιτρόπῳ. οἱ τὰ γράμματα κομίζοντες Κορνήλιος Κέρωνος Τρύφων Θευδίωνος Δωρόθεος Ναθαναήλου Ἰωάννης Ἰωάννου. ἐγράφη πρὸ τεσσάρων καλανδῶν ἐπὶ ὑπάτων Ῥούφου καὶ Πομπηίου Σιλουανοῦ.", "st": "20.1.2"}, {"sp": "N", "t": "Ἠιτήσατο δὲ καὶ Ἡρώδης, ὁ ἀδελφὸς μὲν Ἀγρίππα τοῦ τετελευτηκότος, Χαλκίδος δὲ τὴν ἀρχὴν κατὰ τὸν χρόνον ἐκεῖνον πεπιστευμένος, Κλαύδιον Καίσαρα τὴν ἐξουσίαν τοῦ νεὼ καὶ τῶν ἱερῶν χρημάτων καὶ τὴν τῶν ἀρχιερέων χειροτονίαν, πάντων τε ἐπέτυχεν. ἐξ ἐκείνου τε πᾶσι τοῖς ἀπογόνοις αὐτοῦ παρέμεινεν ἡ ἐξουσία μέχρι τῆς τοῦ πολέμου τελευτῆς. καὶ δὴ ὁ Ἡρώδης μεθίστησιν τῆς ἀρχιερωσύνης τὸν ἐπικαλούμενον Κανθήραν Ἰωσήπῳ τῷ Καμεὶ ἀντ’ ἐκείνου τὴν διαδοχὴν τῆς τιμῆς παρασχόμενος.", "st": "20.1.3"}, {"sp": "N", "t": "Κατὰ τοῦτον δὲ τὸν καιρὸν τῶν Ἀδιαβηνῶν βασιλὶς Ἑλένη καὶ ὁ παῖς αὐτῆς Ἰζάτης εἰς τὰ Ἰουδαίων ἔθη τὸν βίον μετέβαλον διὰ τοιαύτην αἰτίαν· Μονόβαζος ὁ τῶν Ἀδιαβηνῶν βασιλεύς, ᾧ καὶ Βαζαῖος ἐπίκλησις ἦν, τῆς ἀδελφῆς Ἑλένης ἁλοὺς ἔρωτι τῇ πρὸς γάμου κοινωνίᾳ ἄγεται καὶ κατέστησεν ἐγκύμονα. συγκαθεύδων δέ ποτε τῇ γαστρὶ τῆς γυναικὸς τὴν χεῖρα προσαναπαύσας ἡνίκα καθύπνωσεν, φωνῆς τινος ἔδοξεν ὑπακούειν κελευούσης αἴρειν ἀπὸ τῆς νηδύος τὴν χεῖρα καὶ μὴ θλίβειν τὸ ἐν αὐτῇ βρέφος θεοῦ προνοίᾳ καὶ ἀρχῆς τυχὸν καὶ τέλους εὐτυχοῦς τευξόμενον. ταραχθεὶς οὖν ὑπὸ τῆς φωνῆς εὐθὺς διεγερθεὶς ἔφραζε τῇ γυναικὶ ταῦτα, καί γε τὸν υἱὸν Ἰζάτην ἐπεκάλεσεν. ἦν δὲ αὐτῷ Μονόβαζος τούτου πρεσβύτερος ἐκ τῆς Ἑλένης γενόμενος ἄλλοι τε παῖδες ἐξ ἑτέρων γυναικῶν. τὴν μέντοι πᾶσαν εὔνοιαν ὡς εἰς μονογενῆ τὸν Ἰζάτην ἔχων φανερὸς ἦν. φθόνος δὲ τοὐντεῦθεν τῷ παιδὶ παρὰ τῶν ὁμοπατρίων ἀδελφῶν ἐφύετο κἀκ τούτου μῖσος ηὔξετο λυπουμένων ἁπάντων, ὅτι τὸν Ἰζάτην αὐτῶν ὁ πατὴρ προτιμῴη. ταῦτα δὲ καίπερ σαφῶς αἰσθανόμενος ὁ πατὴρ ἐκείνοις μὲν συνεγίνωσκεν ὡς μὴ διὰ κακίαν αὐτὸ πάσχουσιν ἀλλ’ ἤτοι παρὰ τοῦ πατρὸς αὐτῶν ἕκαστον ἀξιῶν εὐνοίας τυγχάνειν, τὸν δὲ νεανίαν, σφόδρα γὰρ ἐδεδοίκει περὶ αὐτοῦ, μὴ μισούμενος ὑπὸ τῶν ἀδελφῶν πάθοι τι, πολλὰ δωρησάμενος πρὸς Ἀβεννήριγον ἐκπέμπει τὸν Σπασίνου χάρακος βασιλέα, παρακατατιθέμενος ἐκείνῳ τὴν τοῦ παιδὸς σωτηρίαν. ὁ δὲ Ἀβεννήριγος ἄσμενός τε δέχεται τὸν νεανίαν καὶ διὰ πολλῆς εὐνοίας ἄγων γυναῖκα μὲν αὐτῷ τὴν θυγατέρα, Σαμαχὼς δ’ ἦν ὄνομα ταύτῃ, δίδωσι· δωρεῖται δὲ χώραν, ἐξ ἧς μεγάλας λήψοιτο προσόδους.", "st": "20.2.1"}, {"sp": "N", "t": "Μονόβαζος δὲ ἤδη γηραιὸς ὢν καὶ τοῦ ζῆν ὀλίγον αὐτῷ τὸν λοιπὸν ὁρῶν χρόνον ἠθέλησεν εἰς ὄψιν ἀφικέσθαι τῷ παιδὶ πρὸ τοῦ τελευτῆσαι. μεταπεμψάμενος οὖν αὐτὸν ἀσπάζεται φιλοφρονέστατα, καὶ χώραν δίδωσιν Καρρῶν λεγομένην. φέρειν δ’ ἡ γῆ πλεῖστον τὸ ἄμωμον ἀγαθή· ἔστι δ’ ἐν αὐτῇ καὶ τὰ λείψανα τῆς λάρνακος, ᾗ Νῶχον ἐκ τῆς ἐπομβρίας διασεσῶσθαι λόγος ἔχει, καὶ μέχρι νῦν ταῦτα τοῖς ἰδεῖν βουλομένοις ἐπιδείκνυται. διέτριβεν οὖν ὁ Ἰζάτης ἐν τῇ χώρᾳ ταύτῃ μέχρι τῆς τελευτῆς τοῦ πατρός. ᾗ δ’ ἐξέλιπεν ἡμέρᾳ τὸν βίον ὁ Μονόβαζος ἡ βασιλὶς Ἑλένη μεταπέμπεται πάντας τοὺς μεγιστᾶνας καὶ τῆς βασιλείας σατράπας καὶ τοὺς τὰς δυνάμεις πεπιστευμένους. οἷς ἀφικομένοις, ὅτι μὲν ὁ ἐμὸς ἀνήρ, εἶπε, τῆς βασιλείας αὐτῷ διάδοχον Ἰζάτην ηὔξατο γενέσθαι καὶ τοῦτον ἄξιον ἔκρινεν, οὐδ’ ὑμᾶς λεληθέναι δοκῶ, περιμένω δὲ ὅμως καὶ τὴν ὑμετέραν κρίσιν· μακάριος γὰρ οὐχ ὁ παρ’ ἑνός, ἀλλὰ πλειόνων καὶ θελόντων τὴν ἀρχὴν λαμβάνων. ἡ μὲν ταῦτ’ εἶπεν ἐπὶ πείρᾳ τοῦ τί φρονοῖεν οἱ συγκληθέντες· οἱ δὲ ἀκούσαντες πρῶτον μὲν προσεκύνησαν τὴν βασιλίδα, καθὼς ἔθος ἐστὶν αὐτοῖς, εἶτ’ ἔφασαν τὴν τοῦ βασιλέως γνώμην βεβαιοῦν καὶ ὑπακούσεσθαι χαίροντες Ἰζάτῃ δικαίως ὑπὸ τοῦ πατρὸς προκριθέντι τῶν ἀδελφῶν κατὰ τὰς εὐχὰς τὰς ἁπάντων. βούλεσθαί τ’ ἔφασαν προαποκτεῖναι πρῶτον αὐτοῦ τοὺς ἀδελφοὺς καὶ συγγενεῖς ὑπὲρ τοῦ τὴν ἀρχὴν Ἰζάτην μετ’ ἀσφαλείας κατασχεῖν· φθαρέντων γὰρ ἐκείνων καθαιρεθήσεσθαι πάντα τὸν φόβον τὸν ὑπὸ μίσους τοῦ παρ’ αὐτῶν καὶ φθόνου γινόμενον. πρὸς ταῦτα ἡ Ἑλένη χάριν μὲν αὐτοῖς ὡμολόγει τῆς πρὸς αὐτὴν καὶ τὸν Ἰζάτην εὐνοίας ἔχειν, παρεκάλει δ’ ὅμως ἐπισχεῖν τὴν περὶ τῆς ἀναιρέσεως τῶν ἀδελφῶν γνώμην μέχρι ἂν Ἰζάτης παραγενόμενος συνδοκιμάσῃ. οἱ δ’ ἐπεὶ ἀνελεῖν συμβουλεύσαντες οὐκ ἔπεισαν, ἀλλὰ φυλάσσειν αὐτοὺς δεσμίους παρῄνουν μέχρι τῆς ἐκείνου παρουσίας ὑπὲρ ἀσφαλείας τῆς ἑαυτῶν. συνεβούλευον δ’ αὐτῇ μεταξὺ προστήσασθαί τινα τῆς ἀρχῆς ἐπίτροπον, ᾧ μάλιστα πιστεύει. πείθεται τούτοις ἡ Ἑλένη, καὶ καθίστησι τὸν πρεσβύτατον παῖδα Μονόβαζον βασιλέα περιθεῖσα τὸ διάδημα καὶ δοῦσα τὸν σημαντῆρα τοῦ πατρὸς δακτύλιον τήν τε σαμψηρὰν ὀνομαζομένην παρ’ αὐτοῖς, διοικεῖν τε τὴν βασιλείαν παρῄνεσεν μέχρι τῆς τοῦ ἀδελφοῦ παρουσίας. ἧκε δ’ οὗτος ταχέως ἀκούσας τὴν τοῦ πατρὸς τελευτὴν καὶ διαδέχεται τὸν ἀδελφὸν Μονόβαζον ὑπεκστάντος τῆς ἀρχῆς αὐτῷ.", "st": "20.2.2"}, {"sp": "N", "t": "Καθ’ ὃν δὲ χρόνον ὁ Ἰζάτης ἐν τῷ Σπασίνου χάρακι διέτριβεν Ἰουδαῖός τις ἔμπορος Ἀνανίας ὄνομα πρὸς τὰς γυναῖκας εἰσιὼν τοῦ βασιλέως ἐδίδασκεν αὐτὰς τὸν θεὸν σέβειν, ὡς Ἰουδαίοις πάτριον ἦν, καὶ δὴ δι’ αὐτῶν εἰς γνῶσιν ἀφικόμενος τῷ Ἰζάτῃ κἀκεῖνον ὁμοίως συνανέπεισεν μετακληθέντι τε ὑπὸ τοῦ πατρὸς εἰς τὴν Ἀδιαβηνὴν συνεξῆλθεν κατὰ πολλὴν ὑπακούσας δέησιν· συνεβεβήκει δὲ καὶ τὴν Ἑλένην ὁμοίως ὑφ’ ἑτέρου τινὸς Ἰουδαίου διδαχθεῖσαν εἰς τοὺς ἐκείνων μετακεκομίσθαι νόμους. ὁ δ’ Ἰζάτης ὡς παρέλαβεν τὴν βασιλείαν, ἀφικόμενος εἰς τὴν Ἀδιαβηνὴν καὶ θεασάμενος τούς τε ἀδελφοὺς καὶ τοὺς ἄλλους συγγενεῖς δεδεμένους ἐδυσχέρανεν τῷ γεγονότι. καὶ τὸ μὲν ἀνελεῖν ἢ φυλάττειν δεδεμένους ἀσεβὲς ἡγούμενος, τὸ δὲ μνησικακοῦντας ἔχειν σὺν αὐτῷ μὴ δεδεμένους σφαλερὸν εἶναι νομίζων, τοὺς μὲν ὁμηρεύσοντας μετὰ τέκνων εἰς τὴν Ῥώμην ἐξέπεμψε Κλαυδίῳ Καίσαρι, τοὺς δὲ πρὸς Ἀρταβάνην τὸν Πάρθον ἐφ’ ὁμοίαις προφάσεσιν ἀπέστειλεν.", "st": "20.2.3"}, {"sp": "N", "t": "Πυθόμενος δὲ πάνυ τοῖς Ἰουδαίων ἔθεσιν χαίρειν τὴν μητέρα τὴν ἑαυτοῦ ἔσπευσε καὶ αὐτὸς εἰς ἐκεῖνα μεταθέσθαι, νομίζων τε μὴ ἂν εἶναι βεβαίως Ἰουδαῖος, εἰ μὴ περιτέμνοιτο, πράττειν ἦν ἕτοιμος. μαθοῦσα δ’ ἡ μήτηρ κωλύειν ἐπειρᾶτο ἐπιφέρειν αὐτῷ κίνδυνον λέγουσα· βασιλέα γὰρ εἶναι, καὶ καταστήσειν εἰς πολλὴν δυσμένειαν τοὺς ὑπηκόους μαθόντας, ὅτι ξένων ἐπιθυμήσειεν καὶ ἀλλοτρίων αὐτοῖς ἐθῶν, οὐκ ἀνέξεσθαί τε βασιλεύοντος αὐτῶν Ἰουδαίου. καὶ ἡ μὲν ταῦτ’ ἔλεγεν καὶ παντοίως ἐκώλυεν. ὁ δ’ εἰς τὸν Ἀνανίαν τοὺς λόγους ἀνέφερεν. τοῦ δὲ τῇ μητρὶ συμφάσκοντος καὶ συναπειλήσαντος ὡς εἰ μὴ πείθοι καταλιπὼν ἄπεισιν· δεδοικέναι γὰρ ἔλεγεν, μὴ τοῦ πράγματος ἐκδήλου πᾶσιν γενομένου κινδυνεύσειε τιμωρίαν ὑποσχεῖν ὡς αὐτὸς αἴτιος τούτων καὶ διδάσκαλος τῷ βασιλεῖ ἀπρεπῶν ἔργων γενόμενος, δυνάμενον δ’ αὐτὸν ἔφη καὶ χωρὶς τῆς περιτομῆς τὸ θεῖον σέβειν, εἴγε πάντως κέκρικε ζηλοῦν τὰ πάτρια τῶν Ἰουδαίων· τοῦτ’ εἶναι κυριώτερον τοῦ περιτέμνεσθαι· συγγνώμην δ’ ἕξειν αὐτῷ καὶ τὸν θεὸν φήσαντος μὴ πράξαντι τὸ ἔργον δι’ ἀνάγκην καὶ τὸν ἐκ τῶν ὑπηκόων φόβον, ἐπείσθη μὲν τότε τοῖς λόγοις ὁ βασιλεύς. μετὰ ταῦτα δέ, τὴν γὰρ ἐπιθυμίαν οὐκ ἐξεβεβλήκει παντάπασιν, Ἰουδαῖός τις ἕτερος ἐκ τῆς Γαλιλαίας ἀφικόμενος Ἐλεάζαρος ὄνομα πάνυ περὶ τὰ πάτρια δοκῶν ἀκριβὴς εἶναι προετρέψατο πρᾶξαι τοὖργον. ἐπεὶ γὰρ εἰσῆλθεν ἀσπασόμενος αὐτὸν καὶ κατέλαβε τὸν Μωυσέος νόμον ἀναγινώσκοντα, λανθάνεις, εἶπεν, ὦ βασιλεῦ, τὰ μέγιστα τοὺς νόμους καὶ δι’ αὐτῶν τὸν θεὸν ἀδικῶν· οὐ γὰρ ἀναγινώσκειν σε δεῖ μόνον αὐτούς, ἀλλὰ καὶ πρότερον τὰ προστασσόμενα ποιεῖν ὑπ’ αὐτῶν. μέχρι τίνος ἀπερίτμητος μενεῖς; ἀλλ’ εἰ μήπω τὸν περὶ τούτου νόμον ἀνέγνως, ἵν’ εἰδῇς τίς ἐστιν ἡ ἀσέβεια, νῦν ἀνάγνωθι. ταῦτα ἀκούσας ὁ βασιλεὺς οὐχ ὑπερεβάλετο τὴν πρᾶξιν, μεταστὰς δ’ εἰς ἕτερον οἴκημα καὶ τὸν ἰατρὸν εἰσκαλεσάμενος τὸ προσταχθὲν ἐτέλει καὶ μεταπεμψάμενος τήν τε μητέρα καὶ τὸν διδάσκαλον Ἀνανίαν ἐσήμαινεν αὐτὸν πεπραχέναι τοὖργον. τοὺς δ’ ἔκπληξις εὐθὺς ἔλαβεν καὶ φόβος οὔτι μέτριος, μὴ τῆς πράξεως εἰς ἔλεγχον ἐλθούσης κινδυνεύσειεν μὲν ὁ βασιλεὺς τὴν ἀρχὴν ἀποβαλεῖν οὐκ ἀνασχομένων τῶν ὑπηκόων ἄρχειν αὐτῶν ἄνδρα τῶν παρ’ ἑτέροις ζηλωτὴν ἐθῶν, κινδυνεύσειαν δὲ καὶ αὐτοὶ τῆς αἰτίας ἐπ’ αὐτοῖς ἐνεχθείσης. θεὸς δ’ ἦν ὁ κωλύσων ἄρα τοὺς ἐκείνων φόβους ἐλθεῖν ἐπὶ τέλος· πολλοῖς γὰρ αὐτόν τε τὸν Ἰζάτην περιπεσόντα κινδύνοις καὶ παῖδας τοὺς ἐκείνου διέσωσεν ἐξ ἀμηχάνων πόρον εἰς σωτηρίαν παρασχών, ἐπιδεικνὺς ὅτι τοῖς εἰς αὐτὸν ἀποβλέπουσιν καὶ μόνῳ πεπιστευκόσιν ὁ καρπὸς οὐκ ἀπόλλυται ὁ τῆς εὐσεβείας. ἀλλὰ ταῦτα μὲν ὕστερον ἀπαγγελοῦμεν.", "st": "20.2.4"}, {"sp": "N", "t": "Ἑλένη δὲ ἡ τοῦ βασιλέως μήτηρ ὁρῶσα τὰ μὲν κατὰ τὴν βασιλείαν εἰρηνευόμενα, τὸν δὲ υἱὸν αὐτῆς μακάριον καὶ παρὰ πᾶσι ζηλωτὸν καὶ τοῖς ἀλλοεθνέσι διὰ τὴν ἐκ τοῦ θεοῦ πρόνοιαν, ἐπιθυμίαν ἔσχεν εἰς τὴν Ἱεροσολυμιτῶν πόλιν ἀφικομένη τὸ πᾶσιν ἀνθρώποις περιβόητον ἱερὸν τοῦ θεοῦ προσκυνῆσαι καὶ χαριστηρίους θυσίας προσενεγκεῖν, ἐδεῖτό τε τοῦ παιδὸς ἐπιτρέψαι. τοῦ δὲ πάνυ προθύμως τῇ μητρὶ παρακαλούσῃ κατανεύσαντος καὶ πολλὴν παρασκευὴν τῶν εἰς τὴν ἀποστολὴν ἑτοιμασαμένου καὶ χρήματα πλεῖστα δόντος, καταβαίνει εἰς τὴν Ἱεροσολυμιτῶν πόλιν προπέμποντος ἐπὶ πολὺ τοῦ παιδός. γίνεται δὲ αὐτῆς ἡ ἄφιξις πάνυ συμφέρουσα τοῖς Ἱεροσολυμίταις· λιμοῦ γὰρ αὐτῶν τὴν πόλιν κατὰ τὸν καιρὸν ἐκεῖνον πιεζοῦντος καὶ πολλῶν ὑπ’ ἐνδείας ἀναλωμάτων φθειρομένων ἡ βασιλὶς Ἑλένη πέμπει τινὰς τῶν ἑαυτῆς, τοὺς μὲν εἰς τὴν Ἀλεξάνδρειαν πολλῶν σῖτον ὠνησομένους χρημάτων, τοὺς δ’ εἰς Κύπρον ἰσχάδων φόρτον οἴσοντας. ὡς δ’ ἐπανῆλθον ταχέως κομίζοντες τοῖς ἀπορουμένοις διένειμε τροφὴν καὶ μεγίστην αὐτῆς μνήμην τῆς εὐποιίας ταύτης εἰς τὸ πᾶν ἡμῶν ἔθνος καταλέλοιπε. πυθόμενος δὲ καὶ ὁ παῖς αὐτῆς Ἰζάτης τὰ περὶ τὸν λιμὸν ἔπεμψε πολλὰ χρήματα τοῖς πρώτοις τῶν Ἱεροσολυμιτῶν. ἀλλὰ γὰρ ἃ τοῖς βασιλεῦσιν εἰς τὴν πόλιν ἡμῶν ἀγαθὰ πέπρακται μετὰ ταῦτα δηλώσομεν.", "st": "20.2.5"}, {"sp": "N", "t": "Ὁ δὲ τῶν Πάρθων βασιλεὺς Ἀρταβάνης αἰσθόμενος τοὺς σατράπας ἐπιβουλὴν ἐπ’ αὐτὸν συντεθεικότας, μένειν παρ’ αὐτοῖς ἀσφαλὲς οὐχ ὁρῶν ἔγνω πρὸς Ἰζάτην ἀπαίρειν, πόρον παρ’ αὐτοῦ βουλόμενος σωτηρίας εὑρέσθαι καὶ κάθοδον εἰς τὴν ἀρχήν, εἰ δυνηθείη. καὶ δὴ ἀφικνεῖται συγγενῶν τε καὶ οἰκετῶν περὶ χιλίους τὸν ἀριθμὸν ἐπαγόμενος συντυγχάνει τε τῷ Ἰζάτῃ καθ’ ὁδόν. αὐτός τε σαφῶς ἐκεῖνον ἐπιστάμενος, ὑπ’ Ἰζάτου δὲ οὐ γινωσκόμενος, πλησίον καταστὰς πρῶτον μὲν κατὰ τὸ πάτριον προσεκύνησεν αὐτόν, εἶτα βασιλεῦ, φησίν, μὴ περιίδῃς με τὸν σὸν ἱκέτην μηδ’ ὑπερηφανήσῃς δεομένου· ταπεινὸς γὰρ ἐκ μεταβολῆς γενόμενος καὶ ἐκ βασιλέως ἰδιώτης τῆς σῆς ἐπικουρίας χρῄζω. βλέψον οὖν εἰς τὸ τῆς τύχης ἄστατον καὶ κοινὴν εἶναι νόμισον καὶ ὑπὲρ σαυτοῦ πρόνοιαν· ἐμοῦ γὰρ ἀνεκδικήτου περιοφθέντος ἔσονται θρασύτεροι πολλοὶ καὶ κατὰ τῶν ἄλλων βασιλέων. ὁ μὲν ταῦτ’ ἔλεγεν δακρύων καὶ τῇ κεφαλῇ κάτω νεύων, ὁ δὲ Ἰζάτης ὡς ἤκουσε τοὔνομα καὶ εἶδεν ἱκέτην αὐτῷ παρεστῶτα τὸν Ἀρταβάνην, κατεπήδησεν ἀπὸ τοῦ ἵππου καί θάρσησον, εἶπεν, ὦ βασιλεῦ, μηδέ σε συγχείτω τὸ παρὸν ὡς ἀνήκεστον· ταχεῖα γὰρ ἔσται τῆς λύπης ἡ μεταβολή. φίλον δέ με καὶ σύμμαχον εὑρήσεις κρείττω τῆς ἐλπίδος· ἢ γὰρ εἰς τὴν Πάρθων σε καταστήσω βασιλείαν πάλιν ἢ τῆς ἐμῆς ἐκστήσομαι.", "st": "20.3.1"}, {"sp": "N", "t": "Ταῦτα εἰπὼν ἀνεβίβαζεν τὸν Ἀρταβάνην ἐπὶ τὸν ἵππον, παρείπετο δ’ αὐτὸς πεζὸς τιμὴν ἀπονέμων ταυτηνὶ ὡς ἂν μείζονι βασιλεῖ. θεασάμενος δ’ Ἀρταβάνης βαρέως ἤνεγκεν καὶ τὴν ἐφεστῶσαν αὐτῷ τύχην καὶ τιμὴν ἐπωμόσατο καταβήσεσθαι μὴ ’κείνου πάλιν ἀναβάντος καὶ προηγουμένου. ὁ δὲ πεισθεὶς ἐπὶ τὸν ἵππον ἥλατο καὶ ἀγαγὼν αὐτὸν εἰς τὴν βασιλείαν πᾶσαν τιμὴν ἀπένειμεν ἔν τε συνεδρίαις καὶ ταῖς περὶ τὰς ἑστιάσεις προκατακλίσεσιν, οὐκ εἰς τὸ παρὸν αὐτοῦ τῆς τύχης ἀποβλέπων, ἀλλ’ εἰς τὸ πρότερον ἀξίωμα, καί τι καὶ λογισμῷ διδούς, ὡς κοιναὶ τοῖς ἀνθρώποις αἱ μεταβολαὶ τῆς τύχης. γράφει τε πρὸς τοὺς Πάρθους πείθων αὐτοὺς τὸν Ἀρταβάνην ὑποδέξασθαι, πίστιν προτείνων τῆς τῶν πεπραγμένων ἀμνηστίας δεξιὰν καὶ ὅρκους καὶ μεσιτείαν τὴν αὐτοῦ. τῶν δὲ Πάρθων δέξασθαι μὲν αὐτὸν θέλειν οὐκ ἀρνουμένων, μὴ δύνασθαι δὲ λεγόντων διὰ τὸ τὴν ἀρχὴν ἑτέρῳ πεπιστευκέναι, Κίνναμος δ’ ἦν ὄνομα τῷ παρειληφότι, καὶ δεδοικέναι, μὴ στάσις αὐτοὺς ἐκ τούτου καταλάβῃ, μαθὼν τὴν προαίρεσιν αὐτῶν ὁ Κίνναμος ταύτην αὐτὸς γράφει τῷ Ἀρταβάνῃ, τέθραπτο γὰρ ὑπ’ αὐτοῦ καὶ φύσει δ’ ἦν καλὸς καὶ ἀγαθός, παρακαλῶν αὐτῷ πιστεύσαντα παραγενέσθαι τὴν ἀρχὴν ἀποληψόμενον τὴν αὐτοῦ. καὶ ὁ Ἀρταβάνης πιστεύσας παρῆν. ὑπαντᾷ δ’ αὐτῷ ὁ Κίνναμος καὶ προσκυνήσας βασιλέα τε προσαγορεύσας περιτίθησιν αὐτοῦ τῇ κεφαλῇ τὸ διάδημα ἀφελὼν τῆς ἑαυτοῦ.", "st": "20.3.2"}, {"sp": "N", "t": "Καὶ Ἀρταβάνης οὕτω διὰ Ἰζάτου πάλιν εἰς τὴν ἀρχὴν καθίσταται πρότερον αὐτῆς ἐκπεσὼν διὰ τοὺς μεγιστᾶνας. οὐκ ἐγένετο μὴν ἀμνήμων τῶν εἰς αὐτὸν εὐεργεσιῶν, ἀλλ’ ἀντιδωρεῖται τὸν Ἰζάτην ταῖς μεγίσταις τιμαῖς παρ’ αὐτοῖς· τήν τε γὰρ τιάραν ὀρθὴν ἐπέτρεψεν αὐτῷ φορεῖν καὶ ἐπὶ κλίνης χρυσῆς καθεύδειν, ἅπερ μόνων ἐστὶ γέρα καὶ σημεῖα τῶν Πάρθων βασιλέων. ἔδωκεν δὲ καὶ χώραν πολλὴν αὐτῷ κἀγαθὴν τοῦ τῶν Ἀρμενίων βασιλέως ἀποτεμόμενος, Νίσιβις δέ ἐστιν ὄνομα τῇ γῇ, καὶ ἐν αὐτῇ πρότερον Μακεδόνες ἐκτίσαντο πόλιν Ἀντιόχειαν, ἣν Ἐπιμυγδονίαν προσηγόρευσαν. ταύταις μὲν δὴ ταῖς τιμαῖς ὁ Ἰζάτης ὑπὸ τοῦ τῶν Πάρθων βασιλέως ἐτιμήθη.", "st": "20.3.3"}, {"sp": "N", "t": "Μετ’ οὐ πολὺν δὲ χρόνον Ἀρταβάνης τελευτᾷ τὴν βασιλείαν τῷ παιδὶ Οὐαρδάνῃ καταλιπών. οὗτος δὴ πρὸς τὸν Ἰζάτην ἀφικόμενος ἔπειθεν αὐτὸν μέλλων πρὸς Ῥωμαίους πόλεμον ἐκφέρειν συστρατεύεσθαι καὶ συμμαχίαν ἑτοιμάζειν. οὐ μὴν ἔπειθεν· ὁ γὰρ Ἰζάτης τὴν Ῥωμαίων δύναμίν τε καὶ τύχην ἐπιστάμενος ἀδυνάτοις αὐτὸν ἐνόμιζεν ἐπιχειρεῖν. ἔτι τε πεπομφὼς πέντε μὲν τὸν ἀριθμὸν υἱοὺς τὴν ἡλικίαν νέους γλῶτταν τὴν παρ’ ἡμῖν πάτριον καὶ παιδείαν ἀκριβῶς μαθησομένους, τὴν δὲ μητέρα προσκυνήσουσαν τὸ ἱερόν, ὡς προεῖπον, ὀκνηρότερος ἦν καὶ τὸν Οὐαρδάνην ἐκώλυεν συνεχῶς διηγούμενος τὰς Ῥωμαίων δυνάμεις τε καὶ πράξεις, διὰ τούτων οἰόμενος αὐτὸν φοβήσειν καὶ παύσειν ἐπιθυμοῦντα τῆς ἐπ’ αὐτοὺς στρατείας. παροξυνθεὶς δ’ ἐπὶ τούτοις ὁ Πάρθος πόλεμον εὐθὺς πρὸς Ἰζάτην κατήγγειλεν. οὐ μὴν ἔλαβεν οὐδὲ τῆς ἐπὶ τούτῳ στρατείας ὄνησιν τοῦ θεοῦ τὰς ἐλπίδας αὐτοῦ πάσας ὑποτεμόντος· μαθόντες γὰρ οἱ Πάρθοι τὴν διάνοιαν τοῦ Οὐαρδάνου καὶ ὡς ἐπὶ Ῥωμαίους στρατεύειν ἔκρινεν, αὐτὸν μὲν ἀναιροῦσιν, τὴν ἀρχὴν δὲ τῷ ἀδελφῷ Κοτάρδῃ παρέδοσαν. καὶ τοῦτον δὲ μετ’ οὐ πολὺν χρόνον ἐξ ἐπιβουλῆς τελευτήσαντα διαδέχεται Οὐολογέσης ὁ ἀδελφός, ὃς δὴ καὶ τοῖς ὁμοπατρίοις δυσὶν ἀδελφοῖς δυναστείας ἐπίστευσεν, Πακόρῳ μὲν τῷ καὶ πρεσβυτέρῳ τὴν Μήδων, Τιριδάτῃ δὲ τῷ νεωτέρῳ τὴν Ἀρμενίαν.", "st": "20.3.4"}, {"sp": "N", "t": "Ὁ δὲ τοῦ βασιλέως ἀδελφὸς Μονόβαζος καὶ οἱ συγγενεῖς θεωροῦντες τὸν Ἰζάτην διὰ τὴν πρὸς τὸν θεὸν εὐσέβειαν ζηλωτὸν παρὰ πᾶσιν ἀνθρώποις γεγενημένον ἔσχον ἐπιθυμίαν καὶ αὐτοὶ τὰ πάτρια καταλιπόντες ἔθεσι χρῆσθαι τοῖς Ἰουδαίων. γίνεται δ’ ἡ πρᾶξις αὐτῶν κατάφωρος τοῖς ὑπηκόοις, κἀπὶ τούτῳ χαλεπήναντες οἱ μεγιστᾶνες οὐκ ἐφανέρουν μὲν τὴν ὀργήν, κατὰ νοῦν δὲ ἔχοντες καιρὸν ἐπιτήδειον ἐζήτουν δίκην εἰσπράξασθαι σπεύδοντες παρ’ αὐτῶν. καὶ δὴ γράφουσιν πρὸς Ἀβίαν τὸν Ἀράβων βασιλέα χρήματα πολλὰ δώσειν ὑπισχνούμενοι στρατεύσασθαι θελήσαντι κατὰ τοῦ παρ’ αὐτοῖς βασιλέως, ἐπηγγέλλοντο δὲ καὶ περὶ τὴν πρώτην συμβολὴν ἐγκαταλείψειν τὸν βασιλέα· θέλειν γὰρ αὐτὸν τιμωρήσασθαι μισήσαντα τὰ παρ’ αὐτοῖς ἔθη· καὶ ὅρκοις τὴν πρὸς ἀλλήλους ἐνδησάμενοι πίστιν σπεύδειν παρεκάλουν. πείθεται δὲ ὁ Ἄραψ, καὶ πολλὴν ἐπαγόμενος δύναμιν ἧκεν ἐπὶ τὸν Ἰζάτην. μελλούσης δὲ τῆς πρώτης συμβολῆς πρὶν εἰς χεῖρας ἐλθεῖν καταλείπουσιν τὸν Ἰζάτην ἐκ συνθήματος πάντες ὡς πανικῷ δείματι κατασχεθέντες, καὶ τὰ νῶτα τοῖς πολεμίοις ἐντρέψαντες ἔφευγον. οὐ μὴν ὁ Ἰζάτης κατεπλάγη, νοήσας δὲ προδοσίαν ὑπὸ τῶν μεγιστάνων γεγενῆσθαι καὶ αὐτὸς εἰς τὸ στρατόπεδον ὑπεχώρησεν, καὶ τὴν αἰτίαν ζητήσας ὡς ἔμαθεν συντεταγμένους πρὸς τὸν Ἄραβα, τοὺς μὲν αἰτίους ἀναιρεῖ, τῇ δ’ ἐπιούσῃ συμβαλὼν πλείστους μὲν ἀπέκτεινε, πάντας δὲ φυγεῖν ἠνάγκασεν, αὐτὸν δὲ τὸν βασιλέα διώκων εἴς τι φρούριον συνήλασεν Ἄρσαμον καλούμενον, καὶ προσμαχεσάμενος καρτερῶς εἷλε τὸ φρούριον διαρπάσας τε τὴν ἐν αὐτῷ λείαν πᾶσαν, πολλὴ δὲ ἦν, ὑπέστρεψεν εἰς τὴν Ἀδιαβηνὴν τὸν Ἀβίαν οὐ καταλαβὼν ζῶντα· περικαταλαμβανόμενος γὰρ ἑαυτὸν ἀνεῖλεν.", "st": "20.4.1"}, {"sp": "N", "t": "Ἀποτυχόντες δὲ οἱ τῶν Ἀδιαβηνῶν μεγιστᾶνες τῆς πρώτης ἐπιχειρήσεως παραδόντος αὐτοὺς τοῦ θεοῦ τῷ βασιλεῖ οὐδ’ ὣς ἠρέμουν, ἀλλὰ γράφουσιν πάλιν Οὐολογέσῃ, βασιλεὺς δὲ Πάρθων οὗτος ἦν, παρακαλοῦντες ἀποκτεῖναι μὲν τὸν Ἰζάτην, καταστῆσαι δ’ αὐτοῖς ἕτερον δυνάστην καὶ τῷ γένει Πάρθον· μισεῖν γὰρ ἔλεγον τὸν ἑαυτῶν βασιλέα καταλύσαντα μὲν τὰ πάτρια, ξένων δ’ ἐραστὴν ἐθῶν γενόμενον. ταῦτα ἀκούσας ὁ Πάρθος ἐπήρθη πρὸς τὸν πόλεμον, καὶ προφάσεως δικαίας μηδεμίαν ἀφορμὴν ἔχων τὰς ὑπὸ τοῦ πατρὸς αὐτῷ δοθείσας τιμὰς ἔπεμψεν ἀπαιτῶν, ἀπειθήσαντι δὲ πόλεμον κατήγγελλεν. ταράσσεται δὲ τὴν ψυχὴν οὐχὶ μετρίως ὁ Ἰζάτης, ὡς ἤκουσεν ταῦτα, κατάγνωσιν μὲν φέρειν αὐτῷ νομίσας τὸ τῶν δωρεῶν ἐξίστασθαι δοκεῖν διὰ φόβον τοῦτο πράξας. εἰδὼς δέ, ὅτι καὶ ἀπολαβὼν ὁ Πάρθος τὰς τιμὰς οὐκ ἂν ἠρεμήσειεν, ἔκρινεν ἐπιτρέψαι τῷ κηδεμόνι θεῷ τὸν ὑπὲρ τῆς ψυχῆς κίνδυνον, καὶ τοῦτον μέγιστον ἡγησάμενος ἔχειν σύμμαχον κατατίθεται μὲν τὰ τέκνα καὶ τὰς γυναῖκας εἰς τὰ τῶν φρουρίων ἀσφαλέστατα, τὸν σῖτον δὲ πάντα μὲν τὸν εἰς τὰς βάρεις ἐμπίπρησιν τόν τε χόρτον καὶ τὰς νομάς, ταῦτά τε προευτρεπισάμενος ἐξεδέχετο τοὺς πολεμίους. παραγενομένου δὲ τοῦ Πάρθου μετὰ πολλῆς δυνάμεως πεζῶν τε καὶ ἱππέων θᾶττον ἐλπίδος, ὥδευσε γὰρ συντόνως, βαλλομένου τε χάρακα πρὸς τῷ ποταμῷ τῷ τὴν Ἀδιαβηνὴν καὶ τὴν Μηδίαν ὁρίζοντι, τίθησι καὶ ὁ Ἰζάτης τὸ στρατόπεδον οὐκ ἄπωθεν ἔχων περὶ αὐτὸν ἱππεῖς τὸν ἀριθμὸν ἑξακισχιλίους. ἀφικνεῖται δὲ πρὸς τὸν Ἰζάτην ἄγγελος παρὰ τοῦ Πάρθου πεμφθείς, ὃς τὴν Πάρθων δύναμιν ὅση τίς ἐστιν ἤγγελλεν ἀπὸ Εὐφράτου ποταμοῦ μέχρι Βάκτρων τοὺς ὅρους αὐτῆς τιθέμενος καὶ τοὺς ὑπηκόους αὐτῆς βασιλέας καταλέγων. ἠπείλει δὲ δώσειν αὐτὸν δίκας ἀχάριστον περὶ δεσπότας τοὺς ἑαυτοῦ γενόμενον, καὶ ῥύεσθαι τῶν βασιλέως αὐτὸν χειρῶν οὐδὲ τὸν θεὸν ὃν σέβει δυνήσεσθαι. ταῦτα τοῦ ἀγγέλου φράσαντος ὁ Ἰζάτης εἰδέναι μὲν τὴν Πάρθων δύναμιν ἔφη πολὺ τῆς αὐτοῦ διαφέρουσαν, γινώσκειν δ’ οὖν ἔτι μᾶλλον πάντων ἀνθρώπων ἔλεγεν κρείσσω τὸν θεόν. καὶ τοιαύτην δοὺς τὴν ἀπόκρισιν ἐπὶ τὴν ἱκετείαν ἐτρέπετο τοῦ θεοῦ, χαμαί τε ῥίψας αὑτὸν καὶ σποδῷ τὴν κεφαλὴν καταισχύνας μετὰ γυναικὸς καὶ τέκνων ἐνήστευεν ἀνακαλῶν τὸν θεὸν καὶ λέγων, εἰ μὴ μάτην, ὦ δέσποτα κύριε, τῆς σῆς ἐγενόμην χρηστότητος, τῶν πάντων δὲ δικαίως μόνον καὶ πρῶτον ἥγημαι κύριον, ἐλθὲ σύμμαχος οὐχ ὑπὲρ ἐμοῦ μόνον ἀμυνούμενος τοὺς πολεμίους, ἀλλ’ ὅτι καὶ τῆς σῆς δυνάμεως κατατετολμήκασιν. ὁ μὲν ταῦτ’ ἐποτνιᾶτο δακρύων καὶ ὀδυρόμενος, ἐπήκοος δὲ ὁ θεὸς ἐγίνετο, καὶ κατ’ ἐκείνην εὐθὺς τὴν νύκτα δεξάμενος Οὐολογέσης ἐπιστολάς, ἐν αἷς ἐγέγραπτο Δαῶν καὶ Σακῶν χεῖρα μεγάλην καταφρονήσασαν αὐτοῦ τῆς ἀποδημίας ἐπιστρατευσαμένην διαρπάζειν τὴν Παρθυηνῶν, ἄπρακτος ἀνέζευξεν εἰς τοὐπίσω. καὶ Ἰζάτης οὕτω κατὰ θεοῦ πρόνοιαν τὰς ἀπειλὰς τοῦ Πάρθου διαφεύγει.", "st": "20.4.2"}, {"sp": "N", "t": "Μετ’ οὐ πολὺν δὲ χρόνον πεντηκοστὸν μὲν καὶ πέμπτον ἀπὸ γενεᾶς πληρώσας ἔτος τέταρτον δὲ πρὸς εἰκοστῷ δυναστεύσας, καταλιπὼν παῖδας ἄρρενας εἰκοσιτέσσαρας καὶ θυγατέρας εἰκοσιτέσσαρας καταστρέφει τὸν βίον. τὴν μέντοι διαδοχὴν τῆς ἀρχῆς τὸν ἀδελφὸν Μονόβαζον ἐκέλευεν παραλαβεῖν, ἀμειβόμενος αὐτὸν ὅτι κατὰ τὴν ἀποδημίαν αὐτοῦ μετὰ τὸν τοῦ πατρὸς θάνατον πιστῶς φυλάξειεν αὐτῷ τὴν δυναστείαν. ἡ δὲ μήτηρ Ἑλένη τὸν τοῦ παιδὸς θάνατον ἀκούσασα βαρέως μὲν ἤνεγκεν ὡς εἰκὸς μητέρα στερομένην εὐσεβεστάτου παιδός, παραμυθίαν δ’ ὅμως εἶχεν τὴν διαδοχὴν ἀκούσασα εἰς τὸν πρεσβύτερον αὐτῆς υἱὸν ἥκουσαν, καὶ πρὸς αὐτὸν ἔσπευδεν. παραγενομένη δὲ εἰς τὴν Ἀδιαβηνὴν οὐ πολὺν Ἰζάτῃ τῷ παιδὶ χρόνον ἐπεβίωσεν. ὁ δὲ Μονόβαζος τά τε ἐκείνης ὀστᾶ καὶ τὰ τοῦ ἀδελφοῦ πέμψας εἰς Ἱεροσόλυμα θάψαι προσέταξεν ἐν ταῖς πυραμίσιν, ἃς ἡ μήτηρ κατεσκευάκει τρεῖς τὸν ἀριθμὸν τρία στάδια τῆς Ἱεροσολυμιτῶν πόλεως ἀπεχούσας. ἀλλὰ Μονόβαζος μὲν ὁ βασιλεὺς ὅσα κατὰ τὸν τῆς ζωῆς χρόνον ἔπραξεν, ὕστερον ἀπαγγελοῦμεν.", "st": "20.4.3"}, {"sp": "N", "t": "Φάδου δὲ τῆς Ἰουδαίας ἐπιτροπεύοντος γόης τις ἀνὴρ Θευδᾶς ὀνόματι πείθει τὸν πλεῖστον ὄχλον ἀναλαβόντα τὰς κτήσεις ἕπεσθαι πρὸς τὸν Ἰορδάνην ποταμὸν αὐτῷ· προφήτης γὰρ ἔλεγεν εἶναι, καὶ προστάγματι τὸν ποταμὸν σχίσας δίοδον ἔχειν ἔφη παρέξειν αὐτοῖς ῥᾳδίαν. καὶ ταῦτα λέγων πολλοὺς ἠπάτησεν. οὐ μὴν εἴασεν αὐτοὺς τῆς ἀφροσύνης ὄνασθαι Φᾶδος, ἀλλ’ ἐξέπεμψεν ἴλην ἱππέων ἐπ’ αὐτούς, ἥτις ἀπροσδόκητος ἐπιπεσοῦσα πολλοὺς μὲν ἀνεῖλεν, πολλοὺς δὲ ζῶντας ἔλαβεν, αὐτὸν δὲ τὸν Θευδᾶν ζωγρήσαντες ἀποτέμνουσι τὴν κεφαλὴν καὶ κομίζουσιν εἰς Ἱεροσόλυμα. τὰ μὲν οὖν συμβάντα τοῖς Ἰουδαίοις κατὰ τοὺς Κουσπίου Φάδου τῆς ἐπιτροπῆς χρόνους ταῦτ’ ἐγένετο.", "st": "20.5.1"}, {"sp": "N", "t": "Ἦλθε δὲ Φάδῳ διάδοχος Τιβέριος Ἀλέξανδρος Ἀλεξάνδρου παῖς τοῦ καὶ ἀλαβαρχήσαντος ἐν Ἀλεξανδρείᾳ γένει τε καὶ πλούτῳ πρωτεύσαντος τῶν ἐκεῖ καθ’ αὑτόν. διήνεγκε καὶ τῇ πρὸς τὸν θεὸν εὐσεβείᾳ τοῦ παιδὸς Ἀλεξάνδρου· τοῖς γὰρ πατρίοις οὐκ ἐνέμεινεν οὗτος ἔθεσιν. ἐπὶ τούτου δὲ καὶ τὸν μέγαν λιμὸν κατὰ τὴν Ἰουδαίαν συνέβη γενέσθαι, καθ’ ὃν καὶ ἡ βασίλισσα Ἑλένη πολλῶν χρημάτων ὠνησαμένη σῖτον ἀπὸ τῆς Αἰγύπτου διένειμεν τοῖς ἀπορουμένοις, ὡς προεῖπον. πρὸς τούτοις δὲ καὶ οἱ παῖδες Ἰούδα τοῦ Γαλιλαίου ἀνήχθησαν τοῦ τὸν λαὸν ἀπὸ Ῥωμαίων ἀποστήσαντος Κυρινίου τῆς Ἰουδαίας τιμητεύοντος, ὡς ἐν τοῖς πρὸ τούτων δεδηλώκαμεν, Ἰάκωβος καὶ Σίμων, οὓς ἀνασταυρῶσαι προσέταξεν Ἀλέξανδρος. ὁ δὲ τῆς Χαλκίδος βασιλεὺς Ἡρώδης μεταστήσας τῆς ἀρχιερωσύνης Ἰώσηπον τὸν τοῦ Καμοιδὶ τὴν διαδοχὴν τῆς τιμῆς Ἀνανίᾳ τῷ τοῦ Νεβεδαίου δίδωσιν. Τιβερίῳ δὲ Ἀλεξάνδρῳ Κουμανὸς ἀφίκετο διάδοχος. καὶ τελευτᾷ τὸν βίον Ἡρώδης ὁ τοῦ μεγάλου βασιλέως Ἀγρίππα ἀδελφὸς ὀγδόῳ τῆς Κλαυδίου Καίσαρος ἀρχῆς ἔτει, καταλιπὼν τρεῖς υἱοὺς Ἀριστόβουλον μὲν ὑπὸ τῆς πρώτης αὐτῷ τεχθέντα γυναικός, ἐκ Βερενίκης δὲ τῆς τἀδελφοῦ θυγατρὸς Βερενικιανὸν καὶ Ὑρκανόν. τὴν δ’ ἀρχὴν αὐτοῦ Καῖσαρ Κλαύδιος Ἀγρίππᾳ τῷ νεωτέρῳ δίδωσιν.", "st": "20.5.2"}, {"sp": "N", "t": "Στάσεως δ’ ἐμπεσούσης τῇ τῶν Ἱεροσολυμιτῶν πόλει Κουμανοῦ τὰ κατὰ τὴν Ἰουδαίαν πράγματα διοικοῦντος ἐφθάρησαν ὑπὸ ταύτης πολλοὶ τῶν Ἰουδαίων. καὶ πρότερον ἀφηγήσομαι τὴν αἰτίαν, δι’ ἣν ταῦτα συνέβη· τῆς πάσχα προσαγορευομένης ἑορτῆς ἐνστάσης, καθ’ ἣν ἔθος ἐστὶν ἡμῖν ἄζυμα προσφέρεσθαι, πολλοῦ καὶ πανταχόθεν πλήθους συναχθέντος ἐπὶ τὴν ἑορτὴν δείσας ὁ Κουμανός, μὴ νεώτερόν τι παρὰ τούτων προσπέσῃ, κελεύει τῶν στρατιωτῶν μίαν τάξιν ἀναλαβοῦσαν τὰ ὅπλα ἐπὶ τῶν τοῦ ἱεροῦ στοῶν ἑστάναι καταστελοῦντας τὸν νεωτερισμόν, εἰ ἄρα τις γένοιτο. τοῦτο δὲ καὶ οἱ πρὸ αὐτοῦ τῆς Ἰουδαίας ἐπιτροπεύσαντες ἐν ταῖς ἑορταῖς ἔπραττον. τετάρτῃ δὲ ἡμέρᾳ τῆς ἑορτῆς στρατιώτης τις ἀνακαλύψας ἐπεδείκνυε τῷ πλήθει τὰ αἰδοῖα, καὶ πρὸς τοῦτο θεασαμένων ὀργὴ καὶ θυμὸς ἦν οὐχ ἑαυτοὺς ὑβρίσθαι λεγόντων, ἀλλὰ τὸν θεὸν ἠσεβῆσθαι· τινὲς δὲ τῶν θρασυτέρων τὸν Κουμανὸν ἐβλασφήμουν ὑπ’ αὐτοῦ τὸν στρατιώτην καθεῖσθαι λέγοντες. Κουμανὸς δ’ ἀκούσας καὶ αὐτὸς οὐ μετρίως ἐρεθίζεται πρὸς τὰς βλασφημίας, παρῄνει μέντοι παύσασθαι νεωτέρων ἐπιθυμοῦντας πραγμάτων μηδὲ στάσεις ἐξάπτειν ἐν ἑορτῇ. μὴ πείθων δέ, μᾶλλον γὰρ ἐπέκειντο βλασφημοῦντες, κελεύει τὸ στράτευμα πᾶν τὰς πανοπλίας ἀναλαβὸν ἥκειν εἰς τὴν Ἀντωνίαν, φρούριον δ’ ἦν τοῦτο, καθάπερ καὶ πρότερον εἴπομεν, ἐπικείμενον τῷ ἱερῷ. παραγενομένους δὲ τοὺς στρατιώτας θεασάμενον τὸ πλῆθος καὶ φοβηθὲν φεύγειν ὥρμησεν, τῶν δ’ ἐξόδων στενῶν οὐσῶν διώκεσθαι νομίζοντες ὑπὸ τῶν πολεμίων καὶ συνωθούμενοι κατὰ τὴν φυγὴν πολλοὺς ἀλλήλοις ἐν τοῖς στενοῖς θλιβόμενοι διέφθειρον. δύο γοῦν μυριάδες ἐξηριθμήθησαν τῶν κατὰ τὴν στάσιν ἐκείνην φθαρέντων. πένθος δ’ ἦν τὸ λοιπὸν ἀντὶ τῆς ἑορτῆς, καὶ πάντες ἐκλαθόμενοι τῶν εὐχῶν καὶ τῶν θυσιῶν ἐπὶ θρήνους καὶ κλαυθμοὺς ἐτράποντο. τοιαῦτα μὲν ἑνὸς ἀσέλγεια στρατιώτου παθήματα γενέσθαι παρεσκεύασεν.", "st": "20.5.3"}, {"sp": "N", "t": "Οὔπω δ’ αὐτῶν τὸ πρῶτον πένθος ἐπέπαυτο καὶ κακὸν ἄλλο προσέπιπτεν· τῶν γὰρ ἀφεστώτων ἐπὶ νεωτερισμῷ τινες κατὰ τὴν δημοσίαν ὁδὸν ὡς ἑκατὸν σταδίων ἄπωθεν τῆς πόλεως Στέφανον Καίσαρος δοῦλον ὁδοιποροῦντα λῃστεύσαντες ἅπασαν αὐτοῦ τὴν κτῆσιν διαρπάζουσιν. ἀκούσας δὲ τὸ πραχθὲν ὁ Κουμανὸς εὐθὺς πέμπει στρατιώτας, κελεύσας αὐτοῖς τὰς πλησίον κώμας διαρπάσαι, τοὺς δ’ ἐπιφανεστάτους αὐτῶν δήσαντας ἐπ’ αὐτὸν ἄγειν. τῆς δὲ πορθήσεως γενομένης τῶν στρατιωτῶν τις τοὺς Μωυσέως νόμους ἔν τινι κώμῃ λαβὼν κειμένους προκομίσας εἰς τὴν πάντων ὄψιν διέσχισεν ἐπιβλασφημῶν καὶ πολλὰ κατακερτομῶν. Ἰουδαῖοι δὲ ταῦτα ἀκούσαντες καὶ πολλοὶ συνδραμόντες καταβαίνουσιν εἰς Καισάρειαν, ἐκεῖ γὰρ ἐτύγχανεν ὁ Κουμανὸς ὤν, ἱκετεύοντες μὴ αὐτοὺς ἀλλὰ τὸν θεὸν οὗπερ οἱ νόμοι καθυβρίσθησαν ἐκδικῆσαι· ζῆν γὰρ οὐχ ὑπομένειν τῶν πατρίων αὐτοῖς οὕτως περιυβρισμένων. καὶ Κουμανὸς δείσας, μὴ πάλιν νεωτερίσειεν τὸ πλῆθος, συμβουλευσάντων καὶ τῶν φίλων τὸν ἐνυβρίσαντα τοῖς νόμοις στρατιώτην πελεκίσας ἔπαυσεν τὴν στάσιν ἐκ δευτέρου μέλλουσαν ἐξάπτεσθαι.", "st": "20.5.4"}, {"sp": "N", "t": "Γίνεται δὲ καὶ Σαμαρείταις πρὸς Ἰουδαίους ἔχθρα δι’ αἰτίαν τοιαύτην· ἔθος ἦν τοῖς Γαλιλαίοις ἐν ταῖς ἑορταῖς εἰς τὴν ἱερὰν πόλιν παραγινομένοις ὁδεύειν διὰ τῆς Σαμαρέων χώρας. καὶ τότε καθ’ ὁδὸν αὐτοῖς κώμης Γιναῆς λεγομένης τῆς ἐν μεθορίῳ κειμένης Σαμαρείας τε καὶ τοῦ μεγάλου πεδίου τινὲς συνάψαντες μάχην πολλοὺς αὐτῶν ἀναιροῦσιν. πυθόμενοι δὲ τὰ πραχθέντα τῶν Γαλιλαίων οἱ πρῶτοι πρὸς Κουμανὸν ἀφίκοντο καὶ παρεκάλουν αὐτὸν μετιέναι τῶν ἀνῃρημένων τὸν φόνον. ὁ δὲ χρήμασι πεισθεὶς ὑπὸ τῶν Σαμαρέων ὠλιγώρησεν. ἀγανακτήσαντες δὲ ἐπὶ τούτῳ Γαλιλαῖοι τὸ πλῆθος τῶν Ἰουδαίων ἔπειθον ἐφ’ ὅπλα χωρῆσαι καὶ τῆς ἐλευθερίας ἀντέχεσθαι· δουλείαν γὰρ καὶ καθ’ αὑτὴν μὲν πικρὰν ἔλεγον εἶναι, τὴν ἐφ’ ὕβρει δὲ παντάπασιν ἀφόρητον. τῶν δ’ ἐν τέλει καταπραΰνειν αὐτοὺς πειρωμένων καὶ πείσειν τὸν Κουμανὸν ἐπαγγελλομένων δίκας εἰσπράξασθαι παρὰ τῶν ἀνῃρηκότων, ἐκείνοις μὲν οὐ προσέσχον, ἀναλαβόντες δὲ τὰ ὅπλα καὶ βοηθεῖν Ἐλεάζαρον τὸν τοῦ Δειναίου παρακαλέσαντες, λῃστὴς δ’ οὗτος ἦν ἔτη πολλὰ τὴν διατριβὴν ἐν ὄρει πεποιημένος, κώμας τινὰς τῶν Σαμαρέων ἐμπρήσαντες διαρπάζουσι. Κουμανὸς δὲ τῆς πράξεως εἰς αὐτὸν ἀφικομένης ἀναλαβὼν τὴν τῶν Σεβαστηνῶν ἴλην καὶ πεζῶν τέσσαρα τάγματα τούς τε Σαμαρεῖς καθοπλίσας ἐξῆλθεν ἐπὶ τοὺς Ἰουδαίους, καὶ συμβαλὼν πολλοὺς μὲν αὐτῶν ἀπέκτεινεν πλείους δὲ ζῶντας ἔλαβεν. οἱ δὲ πρῶτοι κατὰ τιμὴν καὶ γένος τῶν Ἱεροσολυμιτῶν, ὡς εἶδον εἰς οἷον κακῶν μέγεθος ἥκουσιν, μετενδυσάμενοι σάκκους καὶ σποδοῦ τὰς κεφαλὰς ἀναπλήσαντες παντοῖοι τοὺς ἀφεστῶτας παρακαλοῦντες ἦσαν καὶ πείθοντες πρὸ ὀφθαλμῶν θεμένους κατασκαφησομένην μὲν αὐτῶν τὴν πατρίδα, τὸ δὲ ἱερὸν πυρποληθησόμενον, αὐτῶν δὲ καὶ γυναικῶν σὺν τέκνοις ἀνδραποδισμοὺς ἐσομένους, μεταθέσθαι τὸν λογισμὸν καὶ τὰ ὅπλα ῥίψαντας ἠρεμεῖν εἰς τὸ λοιπὸν ἀποχωρήσαντας εἰς τὰ αὑτῶν. ταῦτα δὲ εἰπόντες ἔπεισαν. καὶ οἱ μὲν διελύθησαν, οἱ λῃσταὶ δὲ ἐπὶ τοὺς ἐχυροὺς τόπους πάλιν ἀπῆλθον. ἐξ ἐκείνου τε ἡ σύμπασα Ἰουδαία λῃστηρίων ἐπληρώθη.", "st": "20.6.1"}, {"sp": "N", "t": "Σαμαρέων δὲ οἱ πρῶτοι πρὸς Οὐμμίδιον Κοδρᾶτον τῆς Συρίας προεστηκότα κατὰ τὸν καιρὸν ἐκεῖνον ἐν Τύρῳ τυγχάνοντα παραγενόμενοι κατηγόρουν τῶν Ἰουδαίων, ὡς τὰς κώμας αὐτῶν ἐμπρήσειαν καὶ διαρπάσειαν, καὶ περὶ μὲν ὧν αὐτοὶ πεπόνθασιν οὐχ οὕτως ἀγανακτεῖν ἔφασκον, ὡς ὅτι Ῥωμαίων καταφρονήσειαν, ἐφ’ οὓς κριτὰς ἐχρῆν αὐτοὺς εἴπερ ἠδίκουν παραγενέσθαι, ἢ νῦν ὡς οὐκ ἐχόντων ἡγεμόνας Ῥωμαίους καταδραμεῖν· ἥκειν οὖν ἐπ’ αὐτὸν ἐκδικίας τευξόμενοι. ταῦτα μὲν οὖν οἱ Σαμαρεῖς κατηγόρουν. Ἰουδαῖοι δὲ καὶ τῆς στάσεως καὶ τῆς μάχης αἰτίους γεγονέναι Σαμαρεῖς ἔφασαν, πρὸ πάντων δὲ Κουμανὸν δώροις ὑπ’ αὐτῶν φθαρέντα καὶ παρασιωπήσαντα τὸν τῶν ἀνῃρημένων φόνον. καὶ Κουαδρᾶτος ἀκούσας ὑπερτίθεται τὴν κρίσιν, εἰπὼν ἀποφανεῖσθαι, ἐπειδὰν εἰς τὴν Ἰουδαίαν παραγενόμενος ἀκριβέστερον ἐπιγνῷ τὴν ἀλήθειαν. καὶ οἱ μὲν ἀπῄεσαν ἄπρακτοι. μετ’ οὐ πολὺν δὲ χρόνον ὁ Κουαδρᾶτος ἧκεν εἰς Σαμάρειαν, ἔνθα διακούσας αἰτίους τῆς ταραχῆς ὑπέλαβε γεγονέναι τοὺς Σαμαρεῖς. Σαμαρέων δὲ καὶ Ἰουδαίων οὕστινας νεωτερίσαντας ἔμαθεν ἀνεσταύρωσεν οὓς Κουμανὸς ἔλαβεν αἰχμαλώτους. κἀκεῖθεν εἰς κώμην τινὰ παραγενόμενος Λύδδαν πόλεως τὸ μέγεθος οὐκ ἀποδέουσαν καθίσας ἐπὶ βήματος κἀκ δευτέρου τῶν Σαμαρέων διακούσας διδάσκεται παρά τινος Σαμαρέως, ὅτι τῶν Ἰουδαίων τις πρῶτος ὄνομα Δόητος καί τινες σὺν αὐτῷ νεωτερισταὶ τέσσαρες τὸν ἀριθμὸν πείσειαν τὸν ὄχλον ἐπὶ τῇ Ῥωμαίων ἀποστάσει. κἀκείνους μὲν ὁ Κουαδρᾶτος ἀνελεῖν προσέταξεν, τοὺς δὲ περὶ Ἀνανίαν τὸν ἀρχιερέα καὶ τὸν στρατηγὸν Ἄνανον δήσας εἰς Ῥώμην ἀνέπεμψεν περὶ τῶν πεπραγμένων λόγον ὑφέξοντας Κλαυδίῳ Καίσαρι. κελεύει δὲ καὶ τοῖς τῶν Σαμαρέων πρώτοις καὶ τοῖς Ἰουδαίοις Κουμανῷ τε τῷ ἐπιτρόπῳ καὶ Κέλερι, χιλίαρχος δ’ ἦν οὗτος, ἐπ’ Ἰταλίας ἀπιέναι πρὸς τὸν αὐτοκράτορα κριθησομένους ἐπ’ αὐτοῦ περὶ τῶν πρὸς ἀλλήλους ζητήσεων. αὐτὸς δὲ δείσας, μὴ τὸ πλῆθος πάλιν τῶν Ἰουδαίων νεωτερίσειεν, εἰς τὴν τῶν Ἱεροσολυμιτῶν πόλιν ἀφικνεῖται· καταλαμβάνει δ’ αὐτὴν εἰρηνευομένην καὶ πάτριον ἑορτὴν τῷ θεῷ τελοῦσαν. πιστεύσας οὖν μηδένα νεωτερισμὸν παρ’ αὐτῶν γενήσεσθαι καταλιπὼν ἑορτάζοντας ὑπέστρεψεν εἰς Ἀντιόχειαν.", "st": "20.6.2"}, {"sp": "N", "t": "Οἱ περὶ Κουμανὸν δὲ καὶ τοὺς πρώτους τῶν Σαμαρέων ἀναπεμφθέντες εἰς Ῥώμην λαμβάνουσι παρὰ τοῦ αὐτοκράτορος ἡμέραν, καθ’ ἣν περὶ τῶν πρὸς ἀλλήλους ἀμφισβητήσεων λέγειν ἔμελλον. σπουδὴ δὲ μεγίστη τῷ Κουμανῷ καὶ τοῖς Σαμαρεῦσιν ἦν παρὰ τῶν Καίσαρος ἀπελευθέρων καὶ φίλων, κἂν περιεγένοντο τῶν Ἰουδαίων, εἰ μή περ Ἀγρίππας ὁ νεώτερος ἐν τῇ Ῥώμῃ τυγχάνων κατασπευδομένους ἰδὼν τοὺς τῶν Ἰουδαίων πρώτους ἐδεήθη πολλὰ τῆς τοῦ αὐτοκράτορος γυναικὸς Ἀγριππίνης πεῖσαι τὸν ἄνδρα διακούσαντα πρεπόντως τῇ ἑαυτοῦ δικαιοσύνῃ τιμωρήσασθαι τοὺς αἰτίους τῆς ἀποστάσεως. καὶ Κλαύδιος τῇ δεήσει ταύτῃ προευτρεπισθεὶς καὶ διακούσας, ὡς εὗρε τῶν κακῶν ἀρχηγοὺς τοὺς Σαμαρείτας γενομένους, τοὺς μὲν ἀναβάντας πρὸς αὐτὸν ἐκέλευσεν ἀναιρεθῆναι, τῷ Κουμανῷ δὲ φυγὴν ἐπέβαλεν, Κέλερα δὲ τὸν χιλίαρχον ἐκέλευσεν ἀγαγόντας εἰς τὰ Ἱεροσόλυμα πάντων ὁρώντων ἐπὶ τὴν πόλιν πᾶσαν σύραντας οὕτως ἀποκτεῖναι.", "st": "20.6.3"}, {"sp": "N", "t": "Πέμπει δὲ καὶ Κλαύδιον Φήλικα Πάλλαντος ἀδελφὸν τῶν κατὰ τὴν Ἰουδαίαν προστησόμενον πραγμάτων. τῆς δ’ ἀρχῆς δωδέκατον ἔτος ἤδη πεπληρωκὼς δωρεῖται τὸν Ἀγρίππαν τῇ Φιλίππου τετραρχίᾳ καὶ Βαταναίᾳ προσθεὶς αὐτῷ τὴν Τραχωνῖτιν σὺν Ἀβέλλᾳ· Λυσανία δ’ αὕτη γεγόνει τετραρχία· τὴν Χαλκίδα δ’ αὐτὸν ἀφαιρεῖται δυναστεύσαντα ταύτης ἔτη τέσσαρα. λαβὼν δὲ τὴν δωρεὰν παρὰ τοῦ Καίσαρος Ἀγρίππας ἐκδίδωσι πρὸς γάμον Ἀζίζῳ τῷ Ἐμεσῶν βασιλεῖ περιτέμνεσθαι θελήσαντι Δρούσιλλαν τὴν ἀδελφήν· Ἐπιφανὴς γὰρ ὁ Ἀντιόχου τοῦ βασιλέως παῖς παρῃτήσατο τὸν γάμον μὴ βουληθεὶς τὰ Ἰουδαίων ἔθη μεταλαβεῖν καίπερ τοῦτο ποιήσειν προϋπεσχημένος αὐτῆς τῷ πατρί. καὶ Μαριάμμην δ’ ἐξέδωκεν Ἀρχελάῳ τῷ Ἑλκίου παιδὶ πρότερον ὑπὸ Ἀγρίππα τοῦ πατρὸς ἁρμοσθεῖσαν αὐτῷ, καὶ γίνεται θυγάτηρ αὐτοῖς ὄνομα Βερενίκη.", "st": "20.7.1"}, {"sp": "N", "t": "Διαλύονται δὲ τῇ Δρουσίλλῃ πρὸς τὸν Ἄζιζον οἱ γάμοι μετ’ οὐ πολὺν χρόνον τοιαύτης ἐμπεσούσης αἰτίας· καθ’ ὃν χρόνον τῆς Ἰουδαίας ἐπετρόπευε Φῆλιξ θεασάμενος ταύτην, καὶ γὰρ ἦν κάλλει πασῶν διαφέρουσα, λαμβάνει τῆς γυναικὸς ἐπιθυμίαν, καὶ Ἄτομον ὀνόματι τῶν ἑαυτοῦ φίλων Ἰουδαῖον, Κύπριον δὲ τὸ γένος, μάγον εἶναι σκηπτόμενον πέμπων πρὸς αὐτὴν ἔπειθεν τὸν ἄνδρα καταλιποῦσαν αὐτῷ γήμασθαι, μακαρίαν ποιήσειν ἐπαγγελλόμενος μὴ ὑπερηφανήσασαν αὐτόν. ἡ δὲ κακῶς πράττουσα καὶ φυγεῖν τὸν ἐκ τῆς ἀδελφῆς Βερενίκης βουλομένη φθόνον αὑτῇ διὰ τὸ κάλλος παρεκάλει παρ’ ἐκείνης οἰόμενος οὐκ ἐν ὀλίγοις ἔβλαπτεν, παραβῆναί τε τὰ πάτρια νόμιμα πείθεται καὶ τῷ Φήλικι γήμασθαι. τεκοῦσα δ’ ἐξ αὐτοῦ παῖδα προσηγόρευσεν Ἀγρίππαν. ἀλλ’ ὃν μὲν τρόπον ὁ νεανίας οὗτος σὺν τῇ γυναικὶ κατὰ τὴν ἐκπύρωσιν τοῦ Βεσβίου ὄρους ἐπὶ τῶν Τίτου Καίσαρος χρόνων ἠφανίσθη, μετὰ ταῦτα δηλώσω.", "st": "20.7.2"}, {"sp": "N", "t": "Βερενίκη δὲ μετὰ τὴν Ἡρώδου τελευτήν, ὃς αὐτῆς ἀνὴρ καὶ θεῖος ἐγεγόνει, πολὺν χρόνον ἐπιχηρεύσασα, φήμης ἐπισχούσης, ὅτι τἀδελφῷ συνείη, πείθει Πολέμωνα, Κιλικίας δὲ ἦν οὗτος βασιλεύς, περιτεμόμενον ἀγαγέσθαι πρὸς γάμον αὐτήν· οὕτως γὰρ ἐλέγξειν ᾤετο ψευδεῖς τὰς διαβολάς. καὶ ὁ Πολέμων ἐπείσθη μάλιστα διὰ τὸν πλοῦτον αὐτῆς· οὐ μὴν ἐπὶ πολὺ συνέμεινεν ὁ γάμος, ἀλλ’ ἡ Βερενίκη δι’ ἀκολασίαν, ὡς ἔφασαν, καταλείπει τὸν Πολέμωνα. ὁ δ’ ἅμα τοῦ τε γάμου καὶ τοῦ τοῖς ἔθεσι τῶν Ἰουδαίων ἐμμένειν ἀπήλλακτο. τῷ αὐτῷ δὲ καιρῷ καὶ Μαριάμμη παραιτησαμένη τὸν Ἀρχέλαον συνῴκησε Δημητρίῳ τῶν ἐν Ἀλεξανδρείᾳ Ἰουδαίων πρωτεύοντι γένει τε καὶ πλούτῳ· τότε δὴ καὶ τὴν ἀλαβαρχίαν αὐτὸς εἶχεν. γενόμενον δ’ αὐτῇ παιδίον ἐξ ἐκείνου Ἀγριππῖνον προσηγόρευσεν. ἀλλὰ περὶ μὲν ἑκάστου τούτων μετὰ ἀκριβείας ὕστερον ἀπαγγελοῦμεν.", "st": "20.7.3"}, {"sp": "N", "t": "Τελευτᾷ δὲ Κλαύδιος Καῖσαρ βασιλεύσας ἔτη δεκατρία καὶ μῆνας ὀκτὼ πρὸς ἡμέραις εἴκοσι, καὶ λόγος ἦν παρά τινων, ὡς ὑπὸ τῆς γυναικὸς Ἀγριππίνης φαρμάκοις ἀνῄρητο. ταύτης πατὴρ μὲν ἦν Γερμανικὸς ὁ Καίσαρος ἀδελφός, ἀνὴρ δὲ γενόμενος Δομέτιος Ἠνόβαρβος ὁ τῶν ἐπισήμων κατὰ τὴν Ῥωμαίων πόλιν. οὗ τελευτήσαντος χηρεύουσαν αὐτὴν ἐπὶ πολὺν χρόνον Κλαύδιος ἄγεται πρὸς γάμον ἐπαγομένην καὶ παῖδα Δομέτιον ὁμώνυμον τῷ πατρί. προανῃρήκει δὲ τὴν γυναῖκα Μεσσαλῖναν διὰ ζηλοτυπίαν, ἐξ ἧς αὐτῷ καὶ παῖδες ἐγεγόνεσαν Βρεττανικός τε καὶ Ὀκταουία. ἦν γὰρ Ἀντωνιανὴ καὶ πρεσβυτάτη τῶν ἀδελφῶν, ἣν ἐκ Πετίνης τῆς πρώτης γυναικὸς εἶχεν. καὶ δὴ τὴν Ὀκταουίαν ἥρμοσεν τῷ Νέρωνι· τοῦτο γὰρ ὕστερον αὐτὸν ἐκάλεσεν εἰσποιησάμενος υἱὸν ὁ Καῖσαρ.", "st": "20.8.1"}, {"sp": "N", "t": "Δεδοικυῖα δ’ ἡ Ἀγριππῖνα, μὴ ὁ Βρεττανικὸς ἀνδρωθεὶς αὐτὸς παρὰ τοῦ πατρὸς τὴν ἀρχὴν παραλάβοι, τῷ δὲ αὐτῆς παιδὶ προαρπάσαι βουλομένη τὴν ἡγεμονίαν τά τε περὶ τὸν θάνατον τοῦ Κλαυδίου, καθάπερ ἦν λόγος, διεπράξατο, καὶ παραχρῆμα πέμπει τὸν τῶν στρατευμάτων ἔπαρχον Βοῦρρον καὶ σὺν αὐτῷ τοὺς χιλιάρχους τῶν τε ἀπελευθέρων τοὺς πλεῖστον δυναμένους ἀπάξοντας εἰς τὴν παρεμβολὴν τὸν Νέρωνα καὶ προσαγορεύσοντας αὐτὸν αὐτοκράτορα. Νέρων δὲ τὴν ἀρχὴν οὕτως παραλαβὼν Βρεττανικὸν μὲν ἀδήλως τοῖς πολλοῖς ἀναιρεῖ διὰ φαρμάκων, φανερῶς δ’ οὐκ εἰς μακρὰν τὴν μητέρα τὴν ἑαυτοῦ φονεύει, ταύτην ἀμοιβὴν ἀποτίσας αὐτῇ οὐ μόνον τῆς γενέσεως ἀλλὰ καὶ τοῦ ταῖς ἐκείνης μηχαναῖς τὴν Ῥωμαίων ἡγεμονίαν παραλαβεῖν. κτείνει δὲ καὶ τὴν Ὀκταουίαν, ᾗ συνῴκει, πολλούς τε ἐπιφανεῖς ἄνδρας ὡς ἐπ’ αὐτὸν ἐπιβουλὰς συντιθέντας.", "st": "20.8.2"}, {"sp": "N", "t": "Ἀλλὰ περὶ μὲν τούτων ἐῶ πλείω γράφειν· πολλοὶ γὰρ τὴν περὶ Νέρωνα συντετάχασιν ἱστορίαν, ὧν οἱ μὲν διὰ χάριν εὖ πεπονθότες ὑπ’ αὐτοῦ τῆς ἀληθείας ἠμέλησαν, οἱ δὲ διὰ μῖσος καὶ τὴν πρὸς αὐτὸν ἀπέχθειαν οὕτως ἀναιδῶς ἐνεπαρῴνησαν τοῖς ψεύσμασιν, ὡς ἀξίους αὐτοὺς εἶναι καταγνώσεως. καὶ θαυμάζειν οὐκ ἔπεισί μοι τοὺς περὶ Νέρωνος ψευσαμένους, ὅπου μηδὲ τῶν πρὸ αὐτοῦ γενομένων γράφοντες τὴν ἀλήθειαν τῆς ἱστορίας τετηρήκασιν, καίτοι πρὸς ἐκείνους αὐτοῖς οὐδὲν μῖσος ἦν ἅτε μετ’ αὐτοὺς πολλῷ χρόνῳ γενομένοις. ἀλλὰ γὰρ τοῖς μὲν οὐ προνοουμένοις τῆς ἀληθείας ἐξέστω γράφειν ὡς θέλουσιν, τούτῳ γὰρ χαίρειν ἐοίκασιν, ἡμεῖς δὲ σκοπὸν προθέμενοι τὴν ἀλήθειαν τὰ μὲν ἀπηρτημένα τῆς προκειμένης ἡμῖν πραγματείας ἐπ’ ὀλίγον μνήμης ἀξιοῦμεν, τὰ δ’ ἡμῖν τοῖς Ἰουδαίοις συμπεσόντα δηλοῦμεν οὐ παρέργως μήτε τὰς συμφορὰς μήτε τὰς ἁμαρτίας διασαφεῖν ὀκνοῦντες. ἐπανήξω τοίνυν ἐπὶ τὴν τῶν οἰκείων πραγμάτων διήγησιν.", "st": "20.8.3"}, {"sp": "N", "t": "Τῷ γὰρ πρώτῳ τῆς Νέρωνος ἀρχῆς ἔτει τελευτήσαντος τοῦ Ἐμέσων δυνάστου Ἀζίζου Σόεμος ἀδελφὸς τὴν ἀρχὴν διαδέχεται. τὴν δὲ τῆς μικρᾶς Ἀρμενίας προστασίαν Ἀριστόβουλος Ἡρώδου τῆς Χαλκίδος βασιλέως παῖς ὑπὸ Νέρωνος ἐγχειρίζεται. καὶ τὸν Ἀγρίππαν δὲ δωρεῖται μοίρᾳ τινὶ τῆς Γαλιλαίας ὁ Καῖσαρ Τιβεριάδα καὶ Ταριχέας ὑπακούειν αὐτῷ κελεύσας, δίδωσι δὲ καὶ Ἰουλιάδα πόλιν τῆς Περαίας καὶ κώμας τὰς περὶ αὐτὴν δεκατέσσαρας.", "st": "20.8.4"}, {"sp": "N", "t": "Τὰ δὲ κατὰ τὴν Ἰουδαίαν πράγματα πρὸς τὸ χεῖρον ἀεὶ τὴν ἐπίδοσιν ἐλάμβανεν· λῃστηρίων γὰρ ἡ χώρα πάλιν ἀνεπλήσθη καὶ γοήτων ἀνθρώπων, οἳ τὸν ὄχλον ἠπάτων. ἀλλὰ τούτους μὲν ὁ Φῆλιξ πολλοὺς καθ’ ἑκάστην ἡμέραν σὺν τοῖς λῃσταῖς λαμβάνων ἀνῄρει, καὶ Ἐλεάζαρον δὲ τὸν Διναίου παῖδα τὸν συστησάμενον τῶν λῃστῶν τὸ σύνταγμα δι’ ἐνέδρας εἷλεν ζῶντα· πίστιν γὰρ αὐτῷ προτείνας ὑπὲρ τοῦ μηδὲν πείσεσθαι κακὸν πείθει πρὸς αὐτὸν ἀφικέσθαι καὶ δήσας ἀνέπεμψεν εἰς Ῥώμην. ἔχων δὲ καὶ ἀπεχθῶς πρὸς τὸν ἀρχιερέα Ἰωνάθην ὁ Φῆλιξ διὰ τὸ πολλάκις ὑπ’ αὐτοῦ νουθετεῖσθαι περὶ τοῦ κρειττόνως προΐστασθαι τῶν κατὰ τὴν Ἰουδαίαν πραγμάτων, μὴ καὶ μέμψιν αὐτὸς ὀφλοίη παρὰ τοῖς πλήθεσιν αἰτησάμενος ἐκεῖνον παρὰ τοῦ Καίσαρος πεμφθῆναι τῆς Ἰουδαίας ἐπίτροπον, πρόφασιν ἐπενόει δι’ ἧς μεταστήσεται τὸν συνεχῶς ὀχληρὸν αὐτῷ γινόμενον· βαρὺ γὰρ τοῖς ἀδικεῖν θέλουσιν τὸ συνεχῶς νουθετοῦν. καὶ δὴ διὰ τοιαύτης αἰτίας ὁ Φῆλιξ τὸν πιστότατον τῶν Ἰωνάθου φίλων Ἱεροσολυμίτην τὸ γένος Δωρᾶν ὀνόματι πείθει πολλὰ χρήματα δώσειν ὑπισχνούμενος ἐπαγαγεῖν τῷ Ἰωνάθῃ τοὺς [λῃστὰς] ἀναιρήσοντας, κἀκεῖνος ὑπακούσας ἐμηχανήσατο διὰ τῶν λῃστῶν πραχθῆναι τοιούτῳ τρόπῳ τὸν φόνον· ἀνέβησάν τινες αὐτῶν εἰς τὴν πόλιν ὡς προσκυνήσοντες τὸν θεὸν ὑπὸ τὰς ἐσθῆτας ἔχοντες ξιφίδια καὶ συναναμιγέντες τῷ Ἰωνάθῃ κτείνουσιν αὐτόν. ἀνεκδικήτου δὲ τούτου τοῦ φόνου μεμενηκότος μετὰ πάσης τὸ λοιπὸν ἀδείας ἀναβαίνοντες ἐν ταῖς ἑορταῖς οἱ λῃσταὶ καὶ τὸν σίδηρον ὁμοίως κεκρυμμένον ἔχοντες συναναμιγνύμενοι τοῖς πλήθεσιν ἀνῄρουν μέν τινας ἑαυτῶν ἐχθρούς, οὓς δ’ ἐπὶ χρήμασιν ἄλλοις ὑπηρετοῦντες, οὐ μόνον κατὰ τὴν ἄλλην πόλιν ἀλλὰ καὶ κατὰ τὸ ἱερὸν ἐνίους· καὶ γὰρ ἐκεῖ σφάττειν ἐτόλμων, οὐδ’ ἐν τούτῳ δοκοῦντες ἀσεβεῖν. διὰ τοῦτ’ οἶμαι καὶ τὸν θεὸν μισήσαντα τὴν ἀσέβειαν αὐτῶν ἀποστραφῆναι μὲν ἡμῶν τὴν πόλιν, τὸ δὲ ἱερὸν οὐκέτι καθαρὸν οἰκητήριον αὐτῷ κρίναντα Ῥωμαίους ἐπαγαγεῖν ἡμῖν καὶ τῇ πόλει καθάρσιον πῦρ καὶ δουλείαν ἐπιβαλεῖν σὺν γυναιξὶν καὶ τέκνοις σωφρονίσαι ταῖς συμφοραῖς βουλόμενον ἡμᾶς.", "st": "20.8.5"}, {"sp": "N", "t": "Τὰ μὲν οὖν τῶν λῃστῶν ἔργα τοιαύτης ἀνοσιότητος ἐπλήρου τὴν πόλιν, οἱ δὲ γόητες καὶ ἀπατεῶνες ἄνθρωποι τὸν ὄχλον ἔπειθον αὐτοῖς εἰς τὴν ἐρημίαν ἕπεσθαι· δείξειν γὰρ ἔφασαν ἐναργῆ τέρατα καὶ σημεῖα κατὰ τὴν τοῦ θεοῦ πρόνοιαν γινόμενα. καὶ πολλοὶ πεισθέντες τῆς ἀφροσύνης τιμωρίας ὑπέσχον· ἀναχθέντας γὰρ αὐτοὺς Φῆλιξ ἐκόλασεν. ἀφικνεῖται δέ τις ἐξ Αἰγύπτου κατὰ τοῦτον τὸν καιρὸν εἰς Ἱεροσόλυμα προφήτης εἶναι λέγων καὶ συμβουλεύων τῷ δημοτικῷ πλήθει σὺν αὐτῷ πρὸς ὄρος τὸ προσαγορευόμενον ἐλαιῶν, ὃ τῆς πόλεως ἄντικρυς κείμενον ἀπέχει στάδια πέντε· θέλειν γὰρ ἔφασκεν αὐτοῖς ἐκεῖθεν ἐπιδεῖξαι, ὡς κελεύσαντος αὐτοῦ πίπτοι τὰ τῶν Ἱεροσολυμιτῶν τείχη, δι’ ὧν καὶ τὴν εἴσοδον αὐτοῖς παρέξειν ἐπηγγέλλετο. Φῆλιξ δ’ ὡς ἐπύθετο ταῦτα, κελεύει τοὺς στρατιώτας ἀναλαβεῖν τὰ ὅπλα καὶ μετὰ πολλῶν ἱππέων τε καὶ πεζῶν ὁρμήσας ἀπὸ τῶν Ἱεροσολύμων προσβάλλει τοῖς περὶ τὸν Αἰγύπτιον, καὶ τετρακοσίους μὲν αὐτῶν ἀνεῖλεν, διακοσίους δὲ ζῶντας ἔλαβεν. ὁ δ’ Αἰγύπτιος αὐτὸς διαδρὰς ἐκ τῆς μάχης ἀφανὴς ἐγένετο. πάλιν δ’ οἱ λῃσταὶ τὸν δῆμον εἰς τὸν πρὸς Ῥωμαίους πόλεμον ἠρέθιζον μηδὲν ὑπακούειν αὐτοῖς λέγοντες, καὶ τὰς τῶν ἀπειθούντων κώμας ἐμπιπράντες διήρπαζον.", "st": "20.8.6"}, {"sp": "N", "t": "Γίνεται δὲ καὶ τῶν Καισάρειαν οἰκούντων Ἰουδαίων στάσις πρὸς τοὺς ἐν αὐτῇ Σύρους περὶ ἰσοπολιτείας· οἱ μὲν γὰρ Ἰουδαῖοι πρωτεύειν ἠξίουν διὰ τὸ τὸν κτίστην τῆς Καισαρείας Ἡρώδην αὐτῶν βασιλέα γεγονέναι τὸ γένος Ἰουδαῖον, Σύροι δὲ τὰ μὲν περὶ τὸν Ἡρώδην ὡμολόγουν, ἔφασκον δὲ τὴν Καισάρειαν Στράτωνος πύργον τὸ πρότερον καλεῖσθαι καὶ τότε μηδένα γεγονέναι τῆς πόλεως αὐτῶν Ἰουδαῖον οἰκήτορα. ταῦτα ἀκούσαντες οἱ τῆς χώρας ἔπαρχοι λαβόντες ἀμφοτέρωθεν τοὺς αἰτίους τῆς στάσεως πληγαῖς ᾐκίσαντο καὶ τὴν ταραχὴν οὕτω κατέστειλαν πρὸς ὀλίγον. πάλιν γὰρ οἱ κατὰ τὴν πόλιν Ἰουδαῖοι τῷ πλούτῳ θαρροῦντες καὶ διὰ τοῦτο καταφρονοῦντες τῶν Σύρων ἐβλασφήμουν εἰς αὐτοὺς ἐρεθίσειν προσδοκῶντες. οἱ δὲ χρήμασιν μὲν ἡττώμενοι, μέγα δὲ φρονοῦντες ἐπὶ τῷ τοὺς πλείστους τῶν ὑπὸ Ῥωμαίοις ἐκεῖ στρατευομένων Καισαρεῖς εἶναι καὶ Σεβαστηνοὺς μέχρι μέν τινος καὶ αὐτοὶ τοὺς Ἰουδαίους λόγῳ ὕβριζον, εἶτα λίθοις ἀλλήλους ἔβαλλον, ἕως πολλοὺς παρ’ ἀμφότερα τρωθῆναί τε καὶ πεσεῖν συνέβη· νικῶσί γε μὴν Ἰουδαῖοι. Φῆλιξ δ’ ὡς ἐθεάσατο φιλονεικίαν ἐν πολέμου τρόπῳ γενομένην προπηδήσας παύεσθαι τοὺς Ἰουδαίους παρεκάλει, μὴ πειθομένοις δὲ τοὺς στρατιώτας ὁπλίσας ἐπαφίησι καὶ πολλοὺς μὲν αὐτῶν ἀνεῖλεν, πλείους δὲ ζῶντας ἔλαβεν, οἰκίας δέ τινας τῶν ἐν τῇ πόλει πολλῶν πάνυ χρημάτων γεμούσας διαρπάζειν ἐφῆκεν. οἱ δὲ τῶν Ἰουδαίων ἐπιεικέστεροι καὶ προύχοντες κατὰ τὴν ἀξίωσιν δείσαντες περὶ ἑαυτῶν παρεκάλουν τὸν Φήλικα τοὺς στρατιώτας ἀνακαλέσασθαι τῇ σάλπιγγι καὶ φείσασθαι τὸ λοιπὸν αὐτῶν δοῦναί τε μετάνοιαν ἐπὶ τοῖς πεπραγμένοις. καὶ Φῆλιξ ἐπείσθη.", "st": "20.8.7"}, {"sp": "N", "t": "Κατὰ τοῦτον τὸν καιρὸν ὁ βασιλεὺς Ἀγρίππας δίδωσιν τὴν ἀρχιερωσύνην Ἰσμαήλῳ· Φαβεῖ παῖς οὗτος ἦν. ἐξάπτεται δὲ καὶ τοῖς ἀρχιερεῦσι στάσις πρὸς τοὺς ἱερεῖς καὶ τοὺς πρώτους τοῦ πλήθους τῶν Ἱεροσολυμιτῶν, ἕκαστός τε αὐτῶν στῖφος ἀνθρώπων τῶν θρασυτάτων καὶ νεωτεριστῶν ἑαυτῷ ποιήσας ἡγεμὼν ἦν, καὶ συρράσσοντες ἐκακολόγουν τε ἀλλήλους καὶ λίθοις ἔβαλλον. ὁ δ’ ἐπιπλήξων ἦν οὐδὲ εἷς, ἀλλ’ ὡς ἐν ἀπροστατήτῳ πόλει ταῦτ’ ἐπράσσετο μετ’ ἐξουσίας. τοσαύτη δὲ τοὺς ἀρχιερεῖς κατέλαβεν ἀναίδεια καὶ τόλμα, ὥστε καὶ πέμπειν δούλους ἐτόλμων ἐπὶ τὰς ἅλωνας τοὺς ληψομένους τὰς τοῖς ἱερεῦσιν ὀφειλομένας δεκάτας, καὶ συνέβαινεν τοὺς ἀπορουμένους τῶν ἱερέων ὑπ’ ἐνδείας τελευτᾶν. οὕτως ἐκράτει τοῦ δικαίου παντὸς ἡ τῶν στασιαζόντων βία.", "st": "20.8.8"}, {"sp": "N", "t": "Πορκίου δὲ Φήστου διαδόχου Φήλικι πεμφθέντος ὑπὸ Νέρωνος οἱ πρωτεύοντες τῶν τὴν Καισάρειαν κατοικούντων Ἰουδαίων εἰς τὴν Ῥώμην ἀναβαίνουσιν Φήλικος κατηγοροῦντες, καὶ πάντως ἂν ἐδεδώκει τιμωρίαν τῶν εἰς Ἰουδαίους ἀδικημάτων, εἰ μὴ πολλὰ αὐτὸν ὁ Νέρων τἀδελφῷ Πάλλαντι παρακαλέσαντι συνεχώρησεν μάλιστα δὴ τότε διὰ τιμῆς ἄγων ἐκεῖνον. καὶ τῶν ἐν Καισαρείᾳ δὲ οἱ πρῶτοι Σύρων Βήρυλλον, παιδαγωγὸς δ’ ἦν οὗτος τοῦ Νέρωνος τάξιν τὴν ἐπὶ τῶν Ἑλληνικῶν ἐπιστολῶν πεπιστευμένος, πείθουσι πολλοῖς χρήμασιν αἰτήσασθαι παρὰ τοῦ Νέρωνος αὐτοῖς ἐπιστολὴν ἀκυροῦσαν τὴν Ἰουδαίων πρὸς αὐτοὺς ἰσοπολιτείαν. καὶ Βήρυλλος τὸν αὐτοκράτορα παρακαλέσας ἐπέτυχε γραφῆναι τὴν ἐπιστολήν. αὕτη τῷ ἔθνει ἡμῶν τῶν μετὰ ταῦτα κακῶν τὰς αἰτίας παρέσχεν· πυθόμενοι γὰρ οἱ κατὰ τὴν Καισάρειαν Ἰουδαῖοι τὰ γραφέντα τῆς πρὸς τοὺς Σύρους στάσεως μᾶλλον εἴχοντο μέχρι δὴ τὸν πόλεμον ἐξῆψαν.", "st": "20.8.9"}, {"sp": "N", "t": "Ἀφικομένου δὲ εἰς τὴν Ἰουδαίαν Φήστου συνέβαινεν τὴν Ἰουδαίαν ὑπὸ τῶν λῃστῶν κακοῦσθαι τῶν κωμῶν ἁπασῶν ἐμπιπραμένων τε καὶ διαρπαζομένων. καὶ οἱ σικάριοι δὲ καλούμενοι, λῃσταὶ δέ εἰσιν οὗτοι, τότε μάλιστα ἐπλήθυον χρώμενοι ξιφιδίοις παραπλησίοις μὲν τὸ μέγεθος τοῖς τῶν Περσῶν ἀκινάκαις, ἐπικαμπέσι δὲ καὶ ὁμοίαις ταῖς ὑπὸ Ῥωμαίων σίκαις καλουμέναις, ἀφ’ ὧν καὶ τὴν προσηγορίαν οἱ λῃστεύοντες ἔλαβον πολλοὺς ἀναιροῦντες. ἀναμιγνύμενοι γὰρ ἐν ταῖς ἑορταῖς, καθὼς καὶ πρότερον εἴπομεν, τῷ πλήθει τῶν πανταχόθεν εἰς τὴν πόλιν ἐπὶ τὴν εὐσέβειαν συρρεόντων οὓς βουληθεῖεν ῥᾳδίως ἀπέσφαττον, πολλάκις δὲ καὶ μεθ’ ὅπλων ἐπὶ τὰς κώμας τῶν ἐχθρῶν ἀφικόμενοι διήρπαζον καὶ ἐνεπίμπρασαν. πέμπει δὲ Φῆστος δύναμιν ἱππικήν τε καὶ πεζικὴν ἐπὶ τοὺς ἀπατηθέντας ὑπό τινος ἀνθρώπου γόητος σωτηρίαν αὐτοῖς ἐπαγγελλομένου καὶ παῦλαν κακῶν, εἰ βουληθεῖεν ἕπεσθαι μέχρι τῆς ἐρημίας αὐτῷ, καὶ αὐτόν τε ἐκεῖνον τὸν ἀπατήσαντα καὶ τοὺς ἀκολουθήσαντας διέφθειραν οἱ πεμφθέντες.", "st": "20.8.10"}, {"sp": "N", "t": "Κατὰ δὲ τὸν καιρὸν τοῦτον ὁ βασιλεὺς Ἀγρίππας ᾠκοδομήσατο μεγέθει διαφέρον οἴκημα ἐν τῷ βασιλείῳ ἐν Ἱεροσολύμοις πλησίον τοῦ ξυστοῦ. τὸ δὲ βασίλειον ἐγεγόνει πάλαι ὑπὸ τῶν Ἀσαμωναίου παίδων, ἐφ’ ὑψηλοῦ δὲ τόπου κείμενον τοῖς κατοπτεύειν ἀπ’ αὐτοῦ βουλομένοις τὴν πόλιν ἐπιτερπεστάτην παρεῖχεν τὴν θέαν, ἧς ἐφιέμενος ὁ βασιλεὺς ἐκεῖθεν ἀφεώρα κατακείμενος τὰ κατὰ τὸ ἱερὸν πρασσόμενα. ταῦτα δὲ θεασάμενοι τῶν Ἱεροσολυμιτῶν οἱ προύχοντες δεινῶς ἐχαλέπαινον· οὐ γὰρ ἦν πάτριον τὰ κατὰ τὸ ἱερὸν δρώμενα κατοπτεύεσθαι καὶ μάλιστα τὰς ἱερουργίας. τοῖχον οὖν ἐγείρουσιν ἐπὶ τῆς ἐξέδρας ὑψηλόν, ἥτις ἦν ἐν τῷ ἔσωθεν ἱερῷ τετραμμένη πρὸς δύσιν. οὐ μόνον δὲ τοῦ βασιλικοῦ τρικλίνου τὴν ἄποψιν οὗτος οἰκοδομηθεὶς ἀπετέμνετο, ἀλλὰ καὶ τῆς δυτικῆς στοᾶς τῆς κατὰ τὸ ἔξωθεν ἱερὸν οὔσης, ἔνθα τὰς φυλακὰς οἱ Ῥωμαῖοι ταῖς ἑορταῖς ἐποιοῦντο διὰ τὸ ἱερόν. ἐπὶ τούτοις ἠγανάκτησεν ὅ τε βασιλεὺς Ἀγρίππας, μάλιστα δὲ Φῆστος ὁ ἔπαρχος, καὶ προσέταξεν αὐτοῖς καθελεῖν. οἱ δὲ παρεκάλεσαν ἐξουσίαν αὐτοῖς δοῦναι πρεσβεῦσαι περὶ τούτου πρὸς Νέρωνα· ζῆν γὰρ οὐχ ὑπομένειν καθαιρεθέντος τινὸς μέρους τοῦ ἱεροῦ. συγχωρήσαντος δὲ τοῦ Φήστου πέμπουσιν ἐξ αὑτῶν πρὸς Νέρωνα τοὺς πρώτους δέκα καὶ Ἰσμάηλον τὸν ἀρχιερέα καὶ Ἑλκίαν τὸν γαζοφύλακα. Νέρων δὲ διακούσας αὐτῶν οὐ μόνον συνέγνω περὶ τοῦ πραχθέντος, ἀλλὰ καὶ συνεχώρησεν ἐᾶν οὕτως τὴν οἰκοδομίαν, τῇ γυναικὶ Ποππαίᾳ, θεοσεβὴς γὰρ ἦν, ὑπὲρ τῶν Ἰουδαίων δεηθείσῃ χαριζόμενος, ἣ τοῖς μὲν δέκα προσέταξεν ἀπιέναι, τὸν δ’ Ἑλκίαν καὶ τὸν Ἰσμάηλον ὁμηρεύσοντας παρ’ ἑαυτῇ κατέσχεν. ὁ δὲ βασιλεὺς ταῦθ’ ὡς ἐπύθετο δίδωσιν τὴν ἀρχιερωσύνην Ἰωσήπῳ τῷ Σίμωνος παιδὶ ἀρχιερέως ἐπικαλουμένῳ δὲ Καβί.", "st": "20.8.11"}, {"sp": "N", "t": "Πέμπει δὲ Καῖσαρ Ἀλβῖνον εἰς τὴν Ἰουδαίαν ἔπαρχον Φήστου τὴν τελευτὴν πυθόμενος. ὁ δὲ βασιλεὺς ἀφείλετο μὲν τὸν Ἰώσηπον τὴν ἱερωσύνην, τῷ δὲ Ἀνάνου παιδὶ καὶ αὐτῷ Ἀνάνῳ λεγομένῳ τὴν διαδοχὴν τῆς ἀρχῆς ἔδωκεν. τοῦτον δέ φασι τὸν πρεσβύτατον Ἄνανον εὐτυχέστατον γενέσθαι· πέντε γὰρ ἔσχε παῖδας καὶ τούτους πάντας συνέβη ἀρχιερατεῦσαι τῷ θεῷ, αὐτὸς πρότερος τῆς τιμῆς ἐπὶ πλεῖστον ἀπολαύσας, ὅπερ οὐδενὶ συνέβη τῶν παρ’ ἡμῖν ἀρχιερέων. ὁ δὲ νεώτερος Ἄνανος, ὃν τὴν ἀρχιερωσύνην ἔφαμεν εἰληφέναι, θρασὺς ἦν τὸν τρόπον καὶ τολμητὴς διαφερόντως, αἵρεσιν δὲ μετῄει τὴν Σαδδουκαίων, οἵπερ εἰσὶ περὶ τὰς κρίσεις ὠμοὶ παρὰ πάντας τοὺς Ἰουδαίους, καθὼς ἤδη δεδηλώκαμεν. ἅτε δὴ οὖν τοιοῦτος ὢν ὁ Ἄνανος, νομίσας ἔχειν καιρὸν ἐπιτήδειον διὰ τὸ τεθνάναι μὲν Φῆστον, Ἀλβῖνον δ’ ἔτι κατὰ τὴν ὁδὸν ὑπάρχειν, καθίζει συνέδριον κριτῶν καὶ παραγαγὼν εἰς αὐτὸ τὸν ἀδελφὸν Ἰησοῦ τοῦ λεγομένου Χριστοῦ, Ἰάκωβος ὄνομα αὐτῷ, καί τινας ἑτέρους, ὡς παρανομησάντων κατηγορίαν ποιησάμενος παρέδωκε λευσθησομένους. ὅσοι δὲ ἐδόκουν ἐπιεικέστατοι τῶν κατὰ τὴν πόλιν εἶναι καὶ περὶ τοὺς νόμους ἀκριβεῖς βαρέως ἤνεγκαν ἐπὶ τούτῳ καὶ πέμπουσιν πρὸς τὸν βασιλέα κρύφα παρακαλοῦντες αὐτὸν ἐπιστεῖλαι τῷ Ἀνάνῳ μηκέτι τοιαῦτα πράσσειν· μηδὲ γὰρ τὸ πρῶτον ὀρθῶς αὐτὸν πεποιηκέναι. τινὲς δ’ αὐτῶν καὶ τὸν Ἀλβῖνον ὑπαντιάζουσιν ἀπὸ τῆς Ἀλεξανδρείας ὁδοιποροῦντα καὶ διδάσκουσιν, ὡς οὐκ ἐξὸν ἦν Ἀνάνῳ χωρὶς τῆς ἐκείνου γνώμης καθίσαι συνέδριον. Ἀλβῖνος δὲ πεισθεὶς τοῖς λεγομένοις γράφει μετ’ ὀργῆς τῷ Ἀνάνῳ λήψεσθαι παρ’ αὐτοῦ δίκας ἀπειλῶν. καὶ ὁ βασιλεὺς Ἀγρίππας διὰ τοῦτο τὴν Ἀρχιερωσύνην ἀφελόμενος αὐτὸν ἄρξαντα μῆνας τρεῖς Ἰησοῦν τὸν τοῦ Δαμναίου κατέστησεν.", "st": "20.9.1"}, {"sp": "N", "t": "Ἐπεὶ δ’ ἧκεν ὁ Ἀλβῖνος εἰς τὴν τῶν Ἱεροσολυμιτῶν πόλιν, πᾶσαν εἰσηνέγκατο σπουδὴν καὶ πρόνοιαν ὑπὲρ τοῦ τὴν χώραν εἰρηνεύεσθαι τοὺς πολλοὺς τῶν σικαρίων διαφθείρας. ὁ δὲ ἀρχιερεὺς Ἀνανίας καθ’ ἑκάστην ἡμέραν ἐπὶ μέγα προύκοπτε δόξης καὶ τῆς παρὰ τῶν πολιτῶν εὐνοίας τε καὶ τιμῆς ἠξιοῦτο λαμπρῶς· ἦν γὰρ χρημάτων ποριστικός· καθ’ ἡμέραν γοῦν τὸν Ἀλβῖνον καὶ τὸν ἀρχιερέα δώροις ἐθεράπευεν. εἶχεν δ’ οἰκέτας πάνυ μοχθηρούς, οἳ συναναστρεφόμενοι τοῖς θρασυτάτοις ἐπὶ τὰς ἅλωνας πορευόμενοι τὰς τῶν ἱερέων δεκάτας ἐλάμβανον βιαζόμενοι καὶ τοὺς μὴ διδόντας οὐκ ἀπείχοντο τύπτειν, οἵ τε ἀρχιερεῖς ὅμοια τοῖς ἐκείνου δούλοις ἔπρασσον μηδενὸς κωλύειν δυναμένου. καὶ τῶν ἱερέων τοὺς πάλαι ταῖς δεκάταις τρεφομένους τότε συνέβαινε θνήσκειν τροφῆς ἀπορίᾳ.", "st": "20.9.2"}, {"sp": "N", "t": "Πάλιν δ’ οἱ σικάριοι κατὰ τὴν ἑορτήν, ἐνειστήκει γὰρ αὕτη, διὰ νυκτὸς εἰς τὴν πόλιν παρελθόντες συλλαμβάνουσι ζῶντα τὸν γραμματέα τοῦ στρατηγοῦντος Ἐλεαζάρου, παῖς δ’ ἦν οὗτος Ἀνανίου τοῦ ἀρχιερέως, καὶ δήσαντες ἐξήγαγον. εἶτα πέμψαντες πρὸς τὸν Ἀνανίαν ἀπολύσειν ἔφασαν τὸν γραμματέα πρὸς αὐτόν, εἰ πείσειεν τὸν Ἀλβῖνον δέκα δεσμώτας τοὺς ἐξ αὐτῶν ληφθέντας ἀπολῦσαι. καὶ ὁ Ἀνανίας διὰ τὴν ἀνάγκην πείσας τὸν Ἀλβῖνον τῆς ἀξιώσεως ἐπέτυχεν. τοῦτο μειζόνων κακῶν ἦρξεν· οἱ γὰρ λῃσταὶ παντοίως ἐπεμηχανῶντο τῶν Ἀνανίου τινὰς συλλαμβάνειν οἰκείων καὶ συνεχῶς ζωγροῦντες οὐκ ἀπέλυον πρὶν ἤ τινας τῶν σικαρίων ἀπολάβοιεν γενόμενοί τε πάλιν ἀριθμὸς οὐκ ὀλίγος ἀναθαρρήσαντες τὴν χώραν ἅπασαν ἐκάκουν.", "st": "20.9.3"}, {"sp": "N", "t": "Κατὰ τοῦτον δὲ τὸν καιρὸν ὁ βασιλεὺς Ἀγρίππας μείζονα τὴν Φιλίππου καλουμένην Καισάρειαν κατασκευάσας εἰς τιμὴν τοῦ Νέρωνος Νερωνιάδα προσηγόρευσεν, καὶ Βηρυτίοις δὲ θέατρον ἀπὸ πολλῶν χρημάτων κατεσκευασμένον ταῖς κατ’ ἔτος θέαις ἐδωρεῖτο πολλὰς εἰς τοῦτο μυριάδας ἀναλίσκων· σῖτον γὰρ ἐδίδου τῷ δήμῳ καὶ ἔλαιον διένεμεν καὶ τὴν πᾶσαν δὲ πόλιν ἀνδριάντων ἀναθέσεσιν καὶ ταῖς τῶν ἀρχαίων ἀποτύποις εἰκόσιν ἐκόσμει καὶ μικροῦ δεῖν πάντα τὸν τῆς βασιλείας κόσμον ἐκεῖ μετήνεγκεν. μῖσος οὖν αὐτῷ παρὰ τῶν ὑπηκόων ηὔξετο διὰ τὸ περιαιρούμενον τὰ ἐκείνων εἰς ξένην πόλιν κοσμεῖν. λαμβάνει δὲ καὶ Ἰησοῦς ὁ τοῦ Γαμαλιήλου τὴν διαδοχὴν τῆς ἀρχιερωσύνης παρὰ τοῦ βασιλέως Ἰησοῦν ἀφελομένου τὸν τοῦ Δαμναίου, καὶ διὰ τοῦτο στάσις αὐτῶν πρὸς ἀλλήλους ἐγένετο· σύστημα γὰρ τῶν θρασυτάτων ποιησάμενοι πολλάκις μέχρι λίθων βολῆς ἀπὸ τῶν βλασφημιῶν ἐξέπιπτον. ὑπερεῖχεν δὲ Ἀνανίας τῷ πλούτῳ προσαγόμενος τοὺς λαμβάνειν ἑτοίμους. Κοστόβαρος δὲ καὶ Σαοῦλος αὐτοὶ καθ’ αὑτοὺς μοχθηρὰ πλήθη συνῆγον γένους μὲν ὄντες βασιλικοῦ καὶ διὰ τὴν πρὸς Ἀγρίππαν συγγένειαν εὐνοίας τυγχάνοντες, βίαιοι δὲ καὶ ἁρπάζειν τὰ τῶν ἀσθενεστέρων ἕτοιμοι. ἐξ ἐκείνου μάλιστα τοῦ καιροῦ συνέβη τὴν πόλιν ἡμῶν νοσεῖν προκοπτόντων πάντων ἐπὶ τὸ χεῖρον.", "st": "20.9.4"}, {"sp": "N", "t": "Ὡς δ’ ἤκουσεν Ἀλβῖνος διάδοχον αὐτῷ Γέσσιον Φλῶρον ἀφικνεῖσθαι, βουλόμενος δοκεῖν τι τοῖς Ἱεροσολυμίταις παρεσχῆσθαι προαγαγὼν τοὺς δεσμώτας, ὅσοι ἦσαν αὐτῶν προδήλως θανεῖν ἄξιοι, τούτους προσέταξεν ἀναιρεθῆναι, τοὺς δ’ ἐκ μικρᾶς καὶ τῆς τυχούσης αἰτίας εἰς τὴν εἱρκτὴν κατατεθέντας χρήματα λαμβάνων αὐτὸς ἀπέλυεν. καὶ οὕτως ἡ μὲν φυλακὴ τῶν δεσμωτῶν ἐκαθάρθη, ἡ χώρα δὲ λῃστῶν ἐπληρώθη.", "st": "20.9.5"}, {"sp": "N", "t": "Τῶν δὲ Λευιτῶν, φυλὴ δ’ ἐστὶν αὕτη, ὅσοιπερ ἦσαν ὑμνῳδοὶ πείθουσι τὸν βασιλέα καθίσαντα συνέδριον φορεῖν αὐτοῖς ἐπίσης τοῖς ἱερεῦσιν ἐπιτρέψαι λινῆν στολήν· πρέπειν γὰρ αὐτοῦ τοῖς τῆς ἀρχῆς χρόνοις ἔφασκον ἀφ’ ὧν μνημονευθήσεται καινοποιεῖν. καὶ τῆς ἀξιώσεως οὐ διήμαρτον· ὁ γὰρ βασιλεὺς μετὰ γνώμης τῶν εἰς τὸ συνέδριον ἐποιχομένων συνεχώρησεν τοῖς ὑμνῳδοῖς ἀποθεμένους τὴν προτέραν ἐσθῆτα φορεῖν λινῆν οἵαν ἠθέλησαν. μέρους δέ τινος τῆς φυλῆς λειτουργοῦντος κατὰ τὸ ἱερὸν καὶ τούτοις ἐπέτρεψεν τοὺς ὕμνους ἐκμαθεῖν, ὡς παρεκάλουν. πάντα δ’ ἦν ἐναντία ταῦτα τοῖς πατρίοις νόμοις, ὧν παραβαθέντων οὐκ ἐνῆν μὴ οὐχὶ δίκας ὑποσχεῖν.", "st": "20.9.6"}, {"sp": "N", "t": "Ἤδη δὲ τότε καὶ τὸ ἱερὸν ἐτετέλεστο. βλέπων οὖν ὁ δῆμος ἀργήσαντας τοὺς τεχνίτας ὑπὲρ μυρίους καὶ ὀκτακισχιλίους ὄντας καὶ μισθοφορίας ἐνδεεῖς ἐσομένους διὰ τὸ τὴν τροφὴν ἐκ τῆς κατὰ τὸ ἱερὸν ἐργασίας πορίζεσθαι, καὶ χρήματα μὲν ἀπόθετα διὰ τὸν ἐκ Ῥωμαίων φόβον ἔχειν οὐ θέλων, προνοούμενος δὲ τῶν τεχνιτῶν καὶ εἰς τούτους ἀναλοῦν τοὺς θησαυροὺς βουλόμενος, καὶ γὰρ εἰ μίαν τις ὥραν τῆς ἡμέρας ἐργάσαιτο, τὸν μισθὸν ὑπὲρ ταύτης εὐθέως ἐλάμβανεν, ἔπειθον τὸν βασιλέα τὴν ἀνατολικὴν στοὰν ἀνεγεῖραι. ἦν δὲ ἡ στοὰ τοῦ μὲν ἔξωθεν ἱεροῦ, κειμένη δ’ ἐν φάραγγι βαθείᾳ τετρακοσίων πηχῶν τοὺς τοίχους ἔχουσα ἐκ λίθου τετραγώνου κατεσκεύαστο καὶ λευκοῦ πάνυ, τὸ μὲν μῆκος ἑκάστου λίθου πήχεις εἴκοσι, τὸ δὲ ὕψος ἕξ, ἔργον Σολόμωνος τοῦ βασιλέως πρώτου δειμαμένου τὸ σύμπαν ἱερόν. ὁ βασιλεὺς δ’, ἐπεπίστευτο γὰρ ὑπὸ Κλαυδίου Καίσαρος τὴν ἐπιμέλειαν τοῦ ἱεροῦ, λογισάμενος παντὸς μὲν ἔργου τὴν καθαίρεσιν εἶναι ῥᾳδίαν δυσχερῆ δὲ τὴν κατασκευήν, ἐπὶ δὲ τῆς στοᾶς ταύτης καὶ μᾶλλον, χρόνου τε γὰρ καὶ πολλῶν χρημάτων εἰς τοὖργον δεήσειν, ἠρνήσατο μὲν περὶ τούτου δεομένοις, καταστορέσαι δὲ λευκῷ λίθῳ τὴν πόλιν οὐκ ἐκώλυσεν. Ἰησοῦν δὲ τὸν τοῦ Γαμαλιήλου τὴν ἀρχιερωσύνην ἀφελόμενος ἔδωκεν αὐτὴν Ματθίᾳ τῷ Θεοφίλου, καθ’ ὃν καὶ ὁ πρὸς Ῥωμαίους πόλεμος Ἰουδαίοις ἔλαβε τὴν ἀρχήν.", "st": "20.9.7"}, {"sp": "N", "t": "Ἀναγκαῖον δ’ εἶναι νομίζω καὶ τῇ ἱστορίᾳ ταύτῃ προσῆκον διηγήσασθαι περὶ τῶν ἀρχιερέων, πῶς ἀρξάμενοι καὶ τίσιν ἔξεστι τῆς τιμῆς ταύτης μεταλαμβάνειν καὶ πόσοι γεγόνασιν μέχρι τῆς τοῦ πολέμου τελευτῆς. πρῶτον μὲν οὖν πάντων λέγουσιν Ἀαρῶνα τὸν Μωυσέως ἀδελφὸν ἀρχιερατεῦσαι τῷ θεῷ, τελευτήσαντος δὲ ἐκείνου διαδέξασθαι τοὺς παῖδας εὐθὺς κἀπ’ ἐκείνων τοῖς ἐγγόνοις αὐτῶν διαμεῖναι τὴν τιμὴν ἅπασιν. ὅθεν καὶ πάτριόν ἐστι μηδένα τοῦ θεοῦ τὴν ἀρχιερωσύνην λαμβάνειν ἢ τὸν ἐξ αἵματος τοῦ Ἀαρῶνος, ἑτέρου δὲ γένους οὐδ’ ἂν βασιλεὺς ὢν τύχῃ τεύξεται τῆς ἀρχιερωσύνης. ἐγένοντο οὖν πάντες τὸν ἀριθμὸν ἀπὸ Ἀαρῶνος, ὡς ἔφαμεν, τοῦ πρώτου γενομένου μέχρι Φανάσου τοῦ κατὰ τὸν πόλεμον ὑπὸ τῶν στασιαστῶν ἀρχιερέως ἀναδειχθέντος ὀγδοήκοντα τρεῖς. ἐκ τούτων κατὰ τὴν ἔρημον ἐπὶ τῶν Μωυσέως χρόνων τῆς σκηνῆς ἑστώσης, ἣν Μωυσῆς τῷ θεῷ κατεσκεύασεν, μέχρι τῆς εἰς Ἰουδαίαν ἀφίξεως, ἔνθα Σολόμων ὁ βασιλεὺς τῷ θεῷ τὸν ναὸν ἤγειρεν, ἀρχιεράτευσαν δεκατρεῖς. τὸ γὰρ πρῶτον ἕως τοῦ βίου τελευτῆς τὰς ἀρχιερωσύνας εἶχον, ὕστερον δὲ καὶ παρὰ ζώντων διεδέχοντο. οἱ τοίνυν δεκατρεῖς οὗτοι τῶν δύο παίδων Ἀαρῶνος ὄντες ἔγγονοι κατὰ διαδοχὴν τὴν τιμὴν παρελάμβανον. ἐγένετο δὲ αὐτῶν ἀριστοκρατικὴ μὲν ἡ πρώτη πολιτεία, μετὰ ταύτην δὲ μοναρχία, βασιλέων δὲ τρίτη. γίνεται δὲ τῶν ἐτῶν ἀριθμὸς ὧν ἦρξαν οἱ δεκατρεῖς ἀφ’ ἧς ἡμέρας οἱ πατέρες ἡμῶν ἐξέλιπον Αἴγυπτον Μωυσέως ἄγοντος μέχρι τῆς τοῦ ναοῦ κατασκευῆς, ὃν Σολόμων ὁ βασιλεὺς ἐν Ἱεροσολύμοις ἀνήγειρεν, ἔτη δώδεκα πρὸς τοῖς ἑξακοσίοις.", "st": "20.10.1"}, {"sp": "N", "t": "Μετὰ δὲ τοὺς δεκατρεῖς ἀρχιερέας ἐκείνους οἱ δέκα καὶ ὀκτὼ τὴν ἀρχιερωσύνην ἔσχον ἀπὸ Σολόμωνος βασιλέως ἐν Ἱεροσολύμοις αὐτὴν διαδεξάμενοι, μέχρι οὗ Ναβουχοδονόσορος ὁ τῶν Βαβυλωνίων βασιλεὺς ἐπιστρατεύσας τῇ πόλει τὸν μὲν ναὸν ἐνέπρησεν, τὸ δὲ ἔθνος ἡμῶν εἰς Βαβυλῶνα μετήνεγκεν καὶ τὸν ἀρχιερέα Ἰωσαδάκην αἰχμάλωτον ἔλαβεν. τούτων χρόνος τῆς ἱερωσύνης τετρακοσίων ἑξηκονταὲξ ἐτῶν ἐστι μηνῶν ἓξ ἡμερῶν δέκα ἤδη βασιλευομένων Ἰουδαίων. μετὰ δὲ χρόνον ἐτῶν ἁλώσεως ἑβδομήκοντα τῆς ὑπὸ Βαβυλωνίων γενομένης Κῦρος ὁ Περσῶν βασιλεὺς ἀπέλυσεν τοὺς ἐκ Βαβυλῶνος Ἰουδαίους ἐπὶ τὴν οἰκείαν γῆν πάλιν καὶ συνεχώρησεν τὸν ναὸν ἀνεγεῖραι. τότε δὴ τῶν ὑποστρεψάντων αἰχμαλώτων Ἰησοῦς ὁ τοῦ Ἰωσεδὲκ εἷς ὢν τὴν ἀρχιερωσύνην λαμβάνει. λαμβάνει δ’ οὗτος αὐτὸς καὶ οἱ ἔγγονοι αὐτοῦ πεντεκαίδεκα συνάπαντες μέχρι βασιλέως Ἀντιόχου τοῦ Εὐπάτορος, ἐπολιτεύοντο δὲ δημοκρατικῶς ἔτη τετρακόσια δεκατέσσαρα.", "st": "20.10.2"}, {"sp": "N", "t": "Πρῶτος δ’ Ἀντίοχος ὁ προειρημένος καὶ ὁ στρατηγὸς αὐτοῦ Λυσίας τὸν Ὀνίαν, ᾧ Μενέλαος ἐπίκλην, παύουσι τῆς ἀρχιερωσύνης ἀνελόντες αὐτὸν ἐν Βεροίᾳ καὶ καθιστᾶσιν Ἰάκιμον ἀρχιερέα, γένους μὲν τοῦ Ἀαρῶνος, οὐκ ὄντα δὲ τῆς οἰκίας ταύτης. διὰ τοῦτο καὶ Ὀνίας ὁ τοῦ τετελευτηκότος Ὀνίου ἐξάδελφος ὁμώνυμος τῷ πατρὶ παραγενόμενος εἰς Αἴγυπτον καὶ διὰ φιλίας ἀφικόμενος Πτολεμαίῳ τῷ Φιλομήτορι καὶ Κλεοπάτρᾳ τῇ γυναικὶ αὐτοῦ, πείθει τούτους κατὰ τὸν Ἡλιοπολίτην νομὸν δειμαμένους τῷ θεῷ ναὸν παραπλήσιον τῷ ἐν Ἱεροσολύμοις αὐτὸν ἀρχιερέα καταστῆσαι. ἀλλὰ περὶ μὲν τοῦ ἱεροῦ τοῦ κατασκευασθέντος ἐν Αἰγύπτῳ πολλάκις ἐδηλώσαμεν. ὁ δὲ Ἰάκιμος ἔτη τρία τὴν ἀρχιερωσύνην κατασχὼν ἐτελεύτησεν. διεδέξατο δ’ αὐτὸν οὐδείς, ἀλλὰ διετέλεσεν ἡ πόλις ἐνιαυτοὺς ἑπτὰ χωρὶς ἀρχιερέως οὖσα. πάλιν δὲ οἱ τῶν Ἀσαμωναίου παίδων ἔγγονοι τὴν προστασίαν τοῦ ἔθνους πιστευθέντες καὶ πολεμήσαντες Μακεδόσιν Ἰωνάθην ἀρχιερέα καθιστᾶσιν, ὃς ἦρξεν ἐνιαυτοὺς ἑπτά. τελευτήσαντος δὲ ἐξ ἐπιβουλῆς αὐτοῦ καὶ ἐνέδρας τῆς ὑπὸ Τρύφωνος μηχανηθείσης, ὡς ἀνωτέρω που προειρήκαμεν, λαμβάνει τὴν ἀρχιερωσύνην Σίμων ἀδελφὸς αὐτοῦ. καὶ τοῦτον δὲ δόλῳ παρὰ συμπόσιον ὑπὸ τοῦ γαμβροῦ διαφθαρέντα διεδέξατο παῖς Ὑρκανὸς ὄνομα ὃν κατασχόντα τὴν ἱερωσύνην πλείονα τἀδελφοῦ χρόνον ἐνιαυτῷ, τριακονταὲν ἔτη τῆς τιμῆς Ὑρκανὸς ἀπολαύσας τελευτᾷ γηραιὸς Ἰούδᾳ τῷ καὶ Ἀριστοβούλῳ κληθέντι τὴν διαδοχὴν καταλιπών. κληρονομεῖ δὲ καὶ τοῦτον ἀδελφὸς Ἀλέξανδρος, ὑπὸ νόσου μὲν τελευτήσαντα, τὴν ἱερωσύνην δὲ κατασχόντα μετὰ βασιλείας, καὶ γὰρ διάδημα πρῶτος περιέθετο ὁ Ἰούδας, ἐνιαυτὸν ἕνα.", "st": "20.10.3"}, {"sp": "N", "t": "Βασιλεύσας δὲ ὁ Ἀλέξανδρος καὶ ἱερατεύσας ἔτη εἰκοσιεπτὰ καταστρέφει τὸν βίον Ἀλεξάνδρᾳ τῇ γυναικὶ καταστῆσαι τὸν ἀρχιερατευσόμενον ἐπιτρέψας. ἡ δὲ τὴν μὲν ἀρχιερωσύνην Ὑρκανῷ δίδωσιν, αὐτὴ δὲ τὴν βασιλείαν ἔτη ἐννέα κατασχοῦσα τελευτᾷ τὸν βίον· τὸν ἴσον δὲ χρόνον τὴν ἀρχιερωσύνην ὁ παῖς αὐτῆς Ὑρκανὸς ἔσχεν· μετὰ γὰρ τὸν θάνατον αὐτῆς πολεμήσας πρὸς αὐτὸν ὁ ἀδελφὸς Ἀριστόβουλος καὶ νικήσας ἀφαιρεῖται μὲν ἐκεῖνον τὴν ἀρχήν, αὐτὸς δ’ ἐβασίλευέ τε καὶ ἀρχιεράτευεν τοῦ ἔθνους. ἔτει δὲ τρίτῳ τῆς βασιλείας καὶ πρὸς μησὶν τοῖς ἴσοις Πομπήιος ἐλθὼν καὶ τὴν τῶν Ἱεροσολυμιτῶν πόλιν κατὰ κράτος ἑλὼν αὐτὸν μὲν εἰς Ῥώμην μετὰ τῶν τέκνων δήσας ἔπεμψεν, τῷ δ’ Ὑρκανῷ πάλιν τὴν ἀρχιερωσύνην ἀποδοὺς τὴν μὲν τοῦ ἔθνους προστασίαν ἐπέτρεψεν, διάδημα δὲ φορεῖν ἐκώλυσεν. ἦρξεν δὲ πρὸς τοῖς ἐννέα τοῖς πρώτοις ὁ Ὑρκανὸς τέσσαρα καὶ εἴκοσιν. Βαζαφράνης δὲ καὶ Πάκορος οἱ τῆς Παρθυηνῆς δυνάσται διαβάντες τὸν Εὐφράτην καὶ πολεμήσαντες Ὑρκανῷ αὐτὸν μὲν ζωγρίᾳ συνέλαβον, τὸν Ἀριστοβούλου δὲ υἱὸν Ἀντίγονον κατέστησαν βασιλέα. τρία δ’ ἔτη καὶ τρεῖς μῆνας ἄρξαντα τοῦτον Σόσσιός τε καὶ Ἡρώδης ἐξεπολιόρκησαν, Ἀντώνιος δ’ ἀνεῖλεν εἰς τὴν Ἀντιόχειαν ἀναχθέντα.", "st": "20.10.4"}, {"sp": "N", "t": "Τὴν δὲ βασιλείαν Ἡρώδης παρὰ Ῥωμαίων ἐγχειρισθεὶς οὐκέτι τοὺς ἐκ τοῦ Ἀσαμωναίου γένους καθίστησιν ἀρχιερεῖς, ἀλλά τισιν ἀσήμοις καὶ μόνον ἐξ ἱερέων οὖσιν πλὴν ἑνὸς Ἀριστοβούλου τὴν τιμὴν ἀπένεμεν. τὸν δ’ Ἀριστόβουλον Ὑρκανοῦ τοῦ ὑπὸ Πάρθων ληφθέντος υἱωνὸν ὄντα καταστήσας ἀρχιερέα τῇ ἀδελφῇ αὐτοῦ συνῴκησεν Μαριάμμῃ, τὴν τοῦ πλήθους πρὸς ἑαυτὸν θηρώμενος εὔνοιαν διὰ τὴν Ὑρκανοῦ μνήμην. εἶτα φοβηθείς, μὴ πρὸς τὸν Ἀριστόβουλον πάντες ἀποκλίνωσιν, ἀνεῖλεν αὐτὸν ἐν Ἱεριχοῖ πνιγῆναι μηχανησάμενος κολυμβῶντα, καθὼς ἤδη δεδηλώκαμεν. μετὰ τοῦτον οὐκέτι τοῖς ἐγγόνοις τῶν Ἀσαμωναίου παίδων τὴν ἀρχιερωσύνην ἐπίστευσεν. ἔπραξεν δὲ ὅμοια τῷ Ἡρώδῃ περὶ τῆς καταστάσεως τῶν ἱερέων Ἀρχέλαός τε ὁ παῖς αὐτοῦ καὶ μετὰ τοῦτον τὴν ἀρχὴν Ῥωμαῖοι τῶν Ἰουδαίων παραλαβόντες. εἰσὶν οὖν οἱ ἀπὸ τῶν Ἡρώδου χρόνων ἀρχιερατεύσαντες μέχρι τῆς ἡμέρας, ἧς τὸν ναὸν καὶ τὴν πόλιν Τίτος ἑλὼν ἐπυρπόλησεν, οἱ πάντες εἴκοσι καὶ ὀκτώ, χρόνος δὲ τούτων ἔτη πρὸς τοῖς ἑκατὸν ἑπτά. καὶ τινὲς μὲν αὐτῶν ἐπολιτεύσαντο ἐπί τε Ἡρώδου βασιλεύοντος καὶ ἐπὶ Ἀρχελάου τοῦ παιδὸς αὐτοῦ, μετὰ δὲ τὴν τούτων τελευτὴν ἀριστοκρατία μὲν ἦν ἡ πολιτεία, τὴν δὲ προστασίαν τοῦ ἔθνους οἱ ἀρχιερεῖς ἐπεπίστευντο. περὶ μὲν οὖν τῶν ἀρχιερέων ἱκανὰ ταῦτα.", "st": "20.10.5"}, {"sp": "N", "t": "Γέσσιος δὲ Φλῶρος ὁ πεμφθεὶς Ἀλβίνου διάδοχος ὑπὸ Νέρωνος πολλῶν ἐνέπλησε κακῶν Ἰουδαίους. Κλαζομένιος μὲν ἦν τὸ γένος οὗτος, ἐπήγετο δὲ γυναῖκα Κλεοπάτραν, δι’ ἣν φίλην οὖσαν Ποππαίας τῆς Νέρωνος γυναικὸς καὶ πονηρίᾳ μηδὲν αὐτοῦ διαφέρουσαν τῆς ἀρχῆς ἐπέτυχεν. οὕτω δὲ περὶ τὴν ἐξουσίαν ἐγένετο κακὸς καὶ βίαιος, ὥστε διὰ τὴν ὑπερβολὴν τῶν κακῶν Ἀλβῖνον ἐπῄνουν ὡς εὐεργέτην Ἰουδαῖοι· ἐκεῖνος μὲν γὰρ ἐπεκρύπτετο τὴν πονηρίαν καὶ τοῦ μὴ παντάπασιν κατάφωρος εἶναι προυνόει, Γέσσιος δὲ Φλῶρος καθάπερ εἰς ἐπίδειξιν πονηρίας πεμφθεὶς τὰς εἰς τὸ ἔθνος ἡμῶν παρανομίας ἐπόμπευεν, μήτε ἁρπαγῆς παραλιπὼν μηδένα τρόπον μήτε ἀδίκου κολάσεως· ἦν γὰρ ἄτεγκτος μὲν πρὸς ἔλεον, παντὸς δὲ κέρδους ἄπληστος, ᾧ γε μηδὲ τὰ πλεῖστα τῶν ὀλίγων διέφερεν, ἀλλὰ καὶ λῃσταῖς ἐκοινώνησεν· ἀδεῶς γὰρ οἱ πολλοὶ τοῦτ’ ἔπραττον ἐχέγγυον παρ’ ἐκείνου τὴν σωτηρίαν ἐπὶ τοῖς μέρεσιν ἔχειν πεπιστευκότες. καὶ τοῦτο μέτριον οὐκ ἦν. ἀλλ’ οἱ δυστυχεῖς Ἰουδαῖοι μὴ δυνάμενοι τὰς ὑπὸ τῶν λῃστῶν γινομένας πορθήσεις ὑπομένειν ἠναγκάζοντο τῶν ἰδίων ἠθῶν ἐξανιστάμενοι φεύγειν ἅπαντες, ὡς κρεῖττον ὁπουδήποτε παρὰ τοῖς ἀλλοφύλοις κατοικήσοντες. καὶ τί δεῖ πλείω λέγειν; τὸν γὰρ πρὸς Ῥωμαίους πόλεμον ὁ καταναγκάσας ἡμᾶς ἄρασθαι Φλῶρος ἦν κρεῖττον ἡγουμένους ἀθρόως ἢ κατ’ ὀλίγον ἀπολέσθαι. καὶ δὴ τὴν ἀρχὴν ἔλαβεν ὁ πόλεμος δευτέρῳ μὲν ἔτει τῆς ἐπιτροπῆς Φλώρου, δωδεκάτῳ δὲ τῆς Νέρωνος ἀρχῆς. ἀλλ’ ὅσα μὲν δρᾶν ἠναγκάσθημεν ἢ παθεῖν ὑπεμείναμεν, ἀκριβῶς γνῶναι πάρεστιν τοῖς βουλομένοις ἐντυχεῖν ταῖς ὑπ’ ἐμοῦ περὶ τοῦ Ἰουδαϊκοῦ πολέμου βίβλοις γεγραμμέναις.", "st": "20.11.1"}, {"sp": "N", "t": "Παύσεται δ’ ἐνταῦθά μοι τὰ τῆς ἀρχαιολογίας μεθ’ ἣν καὶ τὸν πόλεμον ἠρξάμην γράφειν. περιέχει δ’ αὕτη τὴν ἀπὸ πρώτης γενέσεως ἀνθρώπου παράδοσιν μέχρι ἔτους δωδεκάτου τῆς Νέρωνος ἡγεμονίας τῶν ἡμῖν συμβεβηκότων τοῖς Ἰουδαίοις κατά τε τὴν Αἴγυπτον καὶ Συρίαν καὶ Παλαιστίνην, ὅσα τε πεπόνθαμεν ὑπὸ Ἀσσυρίων τε καὶ Βαβυλωνίων, τίνα τε Πέρσαι καὶ Μακεδόνες διατεθείκασιν ἡμᾶς, καὶ μετ’ ἐκείνους Ῥωμαῖοι· πάντα γὰρ οἶμαι μετ’ ἀκριβείας συντεταχέναι. τηρῆσαι δὲ πεπείραμαι καὶ τὴν τῶν ἀρχιερέων ἀναγραφὴν τῶν ἐν δισχιλίοις ἔτεσι γενομένων. ἀπλανῆ δὲ πεποίημαι καὶ τὴν περὶ τοὺς βασιλεῖς διαδοχὴν τὰς πράξεις αὐτῶν καὶ τὰς πολιτείας ἀπαγγέλλων μοναρχῶν τε δυναστείας, ὡς αἱ ἱεραὶ βίβλοι περὶ πάντων ἔχουσι τὴν ἀναγραφήν· τοῦτο γὰρ ποιήσειν ἐν ἀρχῇ τῆς ἱστορίας ἐπηγγειλάμην. λέγω δὴ θαρσήσας ἤδη διὰ τὴν τῶν προτεθέντων συντέλειαν, ὅτι μηδεὶς ἂν ἕτερος ἠδυνήθη θελήσας μήτε Ἰουδαῖος μήτε ἀλλόφυλος τὴν πραγματείαν ταύτην οὕτως ἀκριβῶς εἰς Ἕλληνας ἐξενεγκεῖν· ἔχω γὰρ ὁμολογούμενον παρὰ τῶν ὁμοεθνῶν πλεῖστον αὐτῶν κατὰ τὴν ἐπιχώριον παιδείαν διαφέρειν καὶ τῶν Ἑλληνικῶν δὲ γραμμάτων ἐσπούδασα μετασχεῖν τὴν γραμματικὴν ἐμπειρίαν ἀναλαβών, τὴν δὲ περὶ τὴν προφορὰν ἀκρίβειαν πάτριος ἐκώλυσεν συνήθεια. παρ’ ἡμῖν γὰρ οὐκ ἐκείνους ἀποδέχονται τοὺς πολλῶν ἐθνῶν διάλεκτον ἐκμαθόντας διὰ τὸ κοινὸν εἶναι νομίζειν τὸ ἐπιτήδευμα τοῦτο μόνον οὐκ ἐλευθέροις τοῖς τυχοῦσιν ἀλλὰ καὶ τῶν οἰκετῶν τοῖς θέλουσι, μόνοις δὲ σοφίαν μαρτυροῦσιν τοῖς τὰ νόμιμα σαφῶς ἐπισταμένοις καὶ τὴν τῶν ἱερῶν γραμμάτων δύναμιν ἑρμηνεῦσαι δυναμένοις. διὰ τοῦτο πολλῶν πονησάντων περὶ τὴν ἄσκησιν ταύτην μόλις δύο τινὲς ἢ τρεῖς κατώρθωσαν καὶ τῶν πόνων τὴν ἐπικαρπίαν εὐθὺς ἔλαβον.", "st": "20.12.1"}, {"sp": "N", "t": "ἴσως δ’ οὐκ ἂν ἐπίφθονον γένοιτο καὶ περὶ γένους τοὐμοῦ καὶ περὶ τῶν κατὰ τὸν βίον πράξεων βραχέα διεξελθεῖν ἕως ἔχω ζῶντας ἢ τοὺς ἐλέγξοντας ἢ τοὺς μαρτυρήσοντας. Ἐπὶ τούτοις δὲ καταπαύσω τὴν ἀρχαιολογίαν βιβλίοις μὲν εἴκοσι περιειλημμένην, ἓξ δὲ μυριάσι στίχων, κἂν τὸ θεῖον ἐπιτρέπῃ κατὰ περιδρομὴν ὑπομνήσω πάλιν τοῦ τε πολέμου καὶ τῶν συμβεβηκότων ἡμῖν μέχρι τῆς νῦν ἐνεστώσης ἡμέρας, ἥτις ἐστὶν τρισκαιδεκάτου μὲν ἔτους τῆς Δομετιανοῦ Καίσαρος ἀρχῆς, ἐμοὶ δ’ ἀπὸ γενέσεως πεντηκοστοῦ τε καὶ ἕκτου. προῄρημαι δὲ συγγράψαι κατὰ τὰς ἡμετέρας δόξας τῶν Ἰουδαίων ἐν τέσσαρσι βίβλοις περὶ θεοῦ καὶ τῆς οὐσίας αὐτοῦ καὶ περὶ τῶν νόμων, διὰ τί κατ’ αὐτοὺς τὰ μὲν ἔξεστιν ἡμῖν ποιεῖν, τὰ δὲ κεκώλυται.", "st": "20.12.2"}], []);})();
